  output reg  [31:0]            rdata);



  reg    [31:0]            data0;
  reg    [31:0]            data1;
  reg    [31:0]            data2;
  reg    [31:0]            data3;
  wire   [3:0]             wr_sel;



localparam  ARM_CMSDK_AHB_EG_SLAVE_PID4 = 32'h00000004; 
localparam  ARM_CMSDK_AHB_EG_SLAVE_PID5 = 32'h00000000; 
localparam  ARM_CMSDK_AHB_EG_SLAVE_PID6 = 32'h00000000; 
localparam  ARM_CMSDK_AHB_EG_SLAVE_PID7 = 32'h00000000; 
localparam  ARM_CMSDK_AHB_EG_SLAVE_PID0 = 32'h00000017; 
