localparam  ARM_CMSDK_AHB_EG_SLAVE_PID2 = 32'h0000001B; 
localparam  ARM_CMSDK_AHB_EG_SLAVE_PID3 = 32'h00000000; 
localparam  ARM_CMSDK_AHB_EG_SLAVE_CID0 = 32'h0000000D; 
localparam  ARM_CMSDK_AHB_EG_SLAVE_CID1 = 32'h000000F0; 
localparam  ARM_CMSDK_AHB_EG_SLAVE_CID2 = 32'h00000005; 
localparam  ARM_CMSDK_AHB_EG_SLAVE_CID3 = 32'h000000B1; 









  assign wr_sel[0] = ((addr[(ADDRWIDTH-1):2]==10'b0000000000)&(write_en)) ? 1'b1: 1'b0;
  assign wr_sel[1] = ((addr[(ADDRWIDTH-1):2]==10'b0000000001)&(write_en)) ? 1'b1: 1'b0;
  assign wr_sel[2] = ((addr[(ADDRWIDTH-1):2]==10'b0000000010)&(write_en)) ? 1'b1: 1'b0;
  assign wr_sel[3] = ((addr[(ADDRWIDTH-1):2]==10'b0000000011)&(write_en)) ? 1'b1: 1'b0;




  always @(posedge hclk or negedge hresetn)
    begin
    if (~hresetn)
      begin
        data0 <= {32{1'b0}}; 
      end
    else if (wr_sel[0])
      begin
        if (byte_strobe[0])
            data0[ 7: 0] <= wdata[ 7: 0];
        if (byte_strobe[1])
            data0[15: 8] <= wdata[15: 8];
        if (byte_strobe[2])
            data0[23:16] <= wdata[23:16];
        if (byte_strobe[3])
            data0[31:24] <= wdata[31:24];
      end
    end



  always @(posedge hclk or negedge hresetn)
    begin
    if (~hresetn)
      begin
        data1 <= {32{1'b0}}; 
      end
    else if (wr_sel[1])
      begin
        if (byte_strobe[0])
            data1[ 7: 0] <= wdata[ 7: 0];
        if (byte_strobe[1])
            data1[15: 8] <= wdata[15: 8];
        if (byte_strobe[2])
            data1[23:16] <= wdata[23:16];
        if (byte_strobe[3])
            data1[31:24] <= wdata[31:24];
      end
    end



  always @(posedge hclk or negedge hresetn)
    begin
    if (~hresetn)
      begin
        data2 <= {32{1'b0}}; 
      end
    else if (wr_sel[2])
      begin
        if (byte_strobe[0])
            data2[ 7: 0] <= wdata[ 7: 0];
        if (byte_strobe[1])
            data2[15: 8] <= wdata[15: 8];
        if (byte_strobe[2])
            data2[23:16] <= wdata[23:16];
        if (byte_strobe[3])
            data2[31:24] <= wdata[31:24];
      end
    end



  always @(posedge hclk or negedge hresetn)
    begin
    if (~hresetn)
      begin
        data3 <= {32{1'b0}}; 
      end
    else if (wr_sel[3])
      begin
        if (byte_strobe[0])
            data3[ 7: 0] <= wdata[ 7: 0];
        if (byte_strobe[1])
            data3[15: 8] <= wdata[15: 8];
        if (byte_strobe[2])
            data3[23:16] <= wdata[23:16];
        if (byte_strobe[3])
            data3[31:24] <= wdata[31:24];
      end
    end



always @ (read_en or addr or data0 or data1 or data2 or data3 or ecorevnum)
 begin
   case (read_en)
     1'b1:
     begin
       if (addr[11:4] == 8'h00) begin
         case(addr[3:2])
           2'b00: rdata =  data0;
           2'b01: rdata =  data1;
           2'b10: rdata =  data2;
           2'b11: rdata =  data3;
           default: rdata = {32{1'bx}};
         endcase
       end
       else if (addr[11:6] == 6'h3F) begin
         case(addr[5:2])


         4'b0100: rdata = ARM_CMSDK_AHB_EG_SLAVE_PID4; 
         4'b0101: rdata = ARM_CMSDK_AHB_EG_SLAVE_PID5; 
         4'b0110: rdata = ARM_CMSDK_AHB_EG_SLAVE_PID6; 
         4'b0111: rdata = ARM_CMSDK_AHB_EG_SLAVE_PID7; 
         4'b1000: rdata = ARM_CMSDK_AHB_EG_SLAVE_PID0; 
         4'b1001: rdata = ARM_CMSDK_AHB_EG_SLAVE_PID1; 
         4'b1010: rdata = ARM_CMSDK_AHB_EG_SLAVE_PID2; 
         4'b1011: rdata = {ARM_CMSDK_AHB_EG_SLAVE_PID3[31:8], ecorevnum[3:0], 4'h0};

         4'b1100: rdata = ARM_CMSDK_AHB_EG_SLAVE_CID0; 
         4'b1101: rdata = ARM_CMSDK_AHB_EG_SLAVE_CID1; 
         4'b1110: rdata = ARM_CMSDK_AHB_EG_SLAVE_CID2; 
         4'b1111: rdata = ARM_CMSDK_AHB_EG_SLAVE_CID3; 




         4'b0000, 4'b0001,4'b0010,4'b0011: rdata = {32'h00000000}; 
         default: rdata =  {32{1'bx}};  
         endcase
       end
       else begin
         rdata = {32'h00000000}; 
       end
     end
   1'b0:
     begin
       rdata =  {32{1'b0}};
     end
   default:
     begin
       rdata =  {32{1'bx}};
     end
   endcase
 end







 endmodule

