            case(state)
            SIF:begin
                state<=SPC;
                finish<=0;
            end
            SPC:state<=SID;
            SID:begin
                case(inst)
                MFHI,MFLO,MFC0,MTC0,MTHI,MTLO:state<=SEXE_M;
                DIV,DIVU:state<=SEXE_DIV;
                MULT,MULTU:state<=SEXE_MULT;
                CLZ:state<=SWB_REG;
                J,JAL,JR,JALR:state<=SEXE_J;
                LB,LBU,LH,LHU,LW,SB,SH,SW:state<=SEXE_LS;
                BEQ,BNE,BGEZ,TEQ:state<=SEXE_B1;
                SYSCALL,ERET,BREAK:state<=SEXE_BREAK;
                default:state<=SEXE_ALU;
                endcase
            end
            SEXE_DIV:begin
                if((inst==DIV&&DIV_busy)||(inst==DIVU&&DIVU_busy)) state<=SEXE_DIV;
                else begin 
                    state<=SIF;
                    finish<=1;
                end
            end
            SEXE_LS:state<=SMEM_LS;
            SEXE_B1:begin
                if((inst==BEQ&&zero)||(inst==BNE&&~zero)||(inst==BGEZ&&~negative)) state<=SEXE_B2;
                else if(inst==TEQ&&zero) state<=SEXE_BREAK;
                else begin
                    state<=SIF;
                    finish<=1;
                end
            end
            SEXE_ALU:state<=SWB_REG;
            SEXE_B2:begin
                if(inst==TEQ)  state<=SEXE_BREAK;
                else
                begin
                    state<=SIF;
                    finish<=1;
                end
            end
            SEXE_BREAK,SWB_REG,SMEM_LS,SEXE_J,SEXE_MULT,SEXE_M:
            begin
                state<=SIF;
                finish<=1;
            end
            endcase
        end
    end

    always@(posedge clk or posedge rst)
    begin
        if(rst)
        begin
            DIV_start<=0;
            DIVU_start<=0;
            PC_ena<=0;
            IR_ena<=0;
            M_PC<=8'bxxxxxxxx;
            DM_ena<=0;
            DM_w<=0;
            RF_w<=0;
            Z_ena<=0;
            aluc<=4'bxxxx;
            HI_ena<=0;
            LO_ena<=0;
            RF_waddr<=5'bxxxxx;
            M_RF<=8'bxxxxxxxx;
            M_ALU<=8'bxxxxxxxx;
            M_HI<=8'bxxxxxxxx;
            M_LO<=8'bxxxxxxxx;
            EXT16_sign<=1'bx;
            EXT1_n_c<=1'bx;
            CBW_sign<=1'bx;
            CHW_sign<=1'bx;
            mfc0<=0;
            mtc0<=0;
            exception<=0;
            eret<=0;
            cause<=5'bxxxxx;
        end
        else
        begin
            case(state)
                SIF:begin
                    DIV_start<=0;
                    DIVU_start<=0;
                    PC_ena<=0;
                    M_PC<=8'bxxxxxxxx;
                    DM_ena<=0;
                    DM_w<=0;
                    data_type<=2'bxx;
                    RF_w<=0;
                    RF_waddr<=5'bxxxxx;
                    M_RF<=8'bxxxxxxxx;
                    EXT1_n_c<=1'bx;
                    M_ALU<=8'bxxxxxxxx;
                    Z_ena<=0;
                    aluc<=4'bxxxx;
                    HI_ena<=0;
                    LO_ena<=0;
                    M_HI<=8'bxxxxxxxx;
                    M_LO<=8'bxxxxxxxx;
                    CBW_sign<=1'bx;
                    CHW_sign<=1'bx;
                    mfc0<=0;
                    mtc0<=0;

                    IR_ena<=1;                
                end
                SPC:begin
                    IR_ena<=0;

                    PC_ena<=1;
                    M_PC<=mux_pc_NPC;
                end
                SID:begin
                    PC_ena<=0;
                    M_PC<=8'bxxxxxxxx;

                    case(inst)
                    ADDI,ADDIU,SLTI,LW,SW,LB,SB,LBU,LHU,LH,SH:begin
                        M_ALU<=mux_alu_Rs_EXT16;
                        EXT16_sign<=1;
                    end
                    ANDI,ORI,SLTIU,XORI:begin
                        M_ALU<=mux_alu_Rs_EXT16;
                        EXT16_sign<=0;
                    end
                    LUI:begin
                        M_ALU<=mux_alu_x_EXT16;
                        EXT16_sign<=0;
                    end
                    ADDU,AND,XOR,NOR,OR,SLLV,SLTU,SUBU,ADD,SUB,SLT,SRLV,SRAV:
                        M_ALU<=mux_alu_Rs_Rt;
                    BEQ,BNE,BGEZ,TEQ:begin
                        M_ALU<=mux_alu_Rs_Rt;
                        Z_ena<=1;
                        aluc<=4'b0011;
                    end
                    J,JR:;
                    JAL:begin
                        RF_w<=1;
                        RF_waddr<=5'd31;
                        M_RF<=mux_rf_PC;
                    end
                    JALR:begin
                        RF_w<=1;
                        RF_waddr<=rd;
                        M_RF<=mux_rf_PC;
                    end
                    SLL,SRA,SRL:begin
                        M_ALU<=mux_alu_ext5_Rt;
                    end
                    CLZ,MFHI,MTHI,MFLO,MTLO,MFC0,MTC0:;
                    DIV:DIV_start<=1;
                    DIVU:DIVU_start<=1;
                    MULT,MULTU:;
                    SYSCALL:begin
                        exception<=1;
                        cause<=EXC_syscall;
                    end
                    ERET:begin
                        exception<=1;
                        eret<=1;
                    end
                    BREAK:begin
                        exception<=1;
                        cause<=EXC_break;
                    end
                    endcase
                end
                SEXE_ALU:begin
                    Z_ena<=1;
                    case(inst)
                    BEQ:
                        aluc<=4'b0011;
                    ADDI,ADD:
                        aluc<=4'b001x;
                    ADDIU,ADDU:
                        aluc<=4'b0000;
                    ANDI,AND:
                        aluc<=4'b0100;
                    ORI,OR:
                        aluc<=4'b0101;
                    SLTIU,SLTU:
                        aluc<=4'b1010;
                    LUI:
                        aluc<=4'b100x;
                    XORI,XOR:
                        aluc<=4'b0110;
                    SLTI,SLT:
                        aluc<=4'b1011;
                    NOR:
                        aluc<=4'b0111;
                    SLL,SLLV:
                        aluc<=4'b111x;
                    SRA,SRAV:
                        aluc<=4'b1100;
                    SRL,SRLV:
                        aluc<=4'b1101;
                    SUBU:
                        aluc<=4'b0001;
                    SUB:
                        aluc<=4'b0011;
                    endcase
                end
                SWB_REG:begin 
                    Z_ena<=0;
                    M_ALU<=8'bxxxxxxxx;
                    EXT16_sign<=1'bx;
                    aluc<=4'bxxxx;

                    RF_w<=1;        
                    case(inst)
                    ADDI,ADDIU,ANDI,ORI,SLTIU,LUI,XORI,SLTI:
                        RF_waddr<=rt;
                    ADDU,AND,XOR,NOR,OR,SLL,SLLV,SLTU,SRA,SRL,SUBU,ADD,SUB,SLT,SRLV,SRAV,CLZ:
                        RF_waddr<=rd;
                    endcase

                    case(inst)
                    SLTIU,SLTU:begin
                        M_RF<=mux_rf_EXT1;
                        EXT1_n_c<=1;
                    end
                    SLTI,SLT:begin
                        M_RF<=mux_rf_EXT1;
                        EXT1_n_c<=0;
                    end
                    CLZ:
                        M_RF<=mux_rf_CLZ;
                    default:M_RF<=mux_rf_ALU;
                    endcase
                end
                SEXE_B1:begin
                    M_ALU<=8'bxxxxxxxx;
                    Z_ena<=0;
                    aluc<=4'bxxxx;

                    if(inst==TEQ&&zero)
                    begin
                        exception<=1;
                        cause<=EXC_teq;
                    end
                end
                SEXE_B2:begin
                    M_ALU<=mux_alu_EXT18_PC;
                    Z_ena<=1;
                    aluc<=4'b0010;
                    PC_ena<=1;
                    M_PC<=mux_pc_ALU;
                end
                SEXE_J:begin
                    case(inst)
                    J:begin
                        PC_ena<=1;
                        M_PC<=mux_pc_II;
                    end
                    JAL:begin
                        RF_w<=0;
                        RF_waddr<=5'bxxxxx;
                        M_RF<=8'bxxxxxxxx;

                        PC_ena<=1;
                        M_PC<=mux_pc_II;
                    end
                    JR:begin
                        PC_ena<=1;
                        M_PC<=mux_pc_Rs;
                    end
                    JALR:begin
                        RF_w<=0;
                        RF_waddr<=5'bxxxxx;
                        M_RF<=8'bxxxxxxxx;

                        PC_ena<=1;
                        M_PC<=mux_pc_Rs;
                    end
                    endcase        
                end
                SEXE_LS:begin
                    Z_ena<=1;
                    aluc<=4'b0010;
                end
                SMEM_LS:begin                 
                    Z_ena<=0;
                    M_ALU<=8'bxxxxxxxx;
                    EXT16_sign<=1'bx;
                    aluc<=4'bxxxx;

                    case(inst)
                    LW:begin
                        DM_ena<=1;
                        DM_w<=0;
                        data_type<=Wdata;
                        RF_w<=1;
                        RF_waddr<=rt;
                        M_RF<=mux_rf_DM_Data;
                    end
                    SW:begin
                        DM_ena<=1;
                        DM_w<=1;
                        data_type<=Wdata;
                    end
                    LB:begin
                        DM_ena<=1;
                        DM_w<=0;
                        data_type<=Bdata;
                        RF_w<=1;
                        RF_waddr<=rt;
                        M_RF<=mux_rf_CBW;
                        CBW_sign<=1;
                    end
                    SB:begin
                        DM_ena<=1;
                        DM_w<=1;
                        data_type<=Bdata;
                    end
                    LBU:begin
                        DM_ena<=1;
                        DM_w<=0;
                        data_type<=Bdata;
                        RF_w<=1;
                        RF_waddr<=rt;
                        M_RF<=mux_rf_CBW;
                        CBW_sign<=0;
                    end
                    LHU:begin
                        DM_ena<=1;
                        DM_w<=0;
                        data_type<=Hdata;
                        RF_w<=1;
                        RF_waddr<=rt;
                        M_RF<=mux_rf_CHW;
                        CHW_sign<=0;
                    end
                    LH:begin
                        DM_ena<=1;
                        DM_w<=0;
                        data_type<=Hdata;
                        RF_w<=1;
                        RF_waddr<=rt;
                        M_RF<=mux_rf_CHW;
                        CHW_sign<=1;
                    end
                    SH:begin
                        DM_ena<=1;
                        DM_w<=1;
                        data_type<=Hdata;
                    end
                    endcase
                end
                SEXE_M:begin
                    case(inst)
                    MFHI:begin
                        RF_w<=1; 
                        RF_waddr<=rd;
                        M_RF<=mux_rf_HI;
                    end
                    MTHI:begin
                        HI_ena<=1;
                        M_HI<=mux_hi_Rs;
                    end
                    MFLO:begin
                        RF_w<=1;
                        RF_waddr<=rd;
                        M_RF<=mux_rf_LO;
                    end
                    MTLO:begin
                        LO_ena<=1;
                        M_LO<=mux_lo_Rs;
                    end
                    MFC0:begin
                        mfc0<=1;
                        RF_w<=1;
                        RF_waddr<=rt;
                        M_RF<=mux_rf_CPR;
                    end
                    MTC0:begin
                        mtc0<=1;
                    end
                    endcase
                end
                SEXE_DIV:begin
                    HI_ena<=1;
                    LO_ena<=1;
                    case(inst)
                    DIV:begin DIV_start<=0;M_HI<=mux_hi_DIV;M_LO<=mux_lo_DIV;end
                    DIVU:begin DIVU_start<=0;M_HI<=mux_hi_DIVU;M_LO<=mux_lo_DIVU;end
                    endcase
                end
                SEXE_MULT:begin
                    HI_ena<=1;
                    LO_ena<=1;
                    case(inst)
                    MULT:begin M_HI<=mux_hi_MULT;M_LO<=mux_lo_MULT;end
                    MULTU:begin M_HI<=mux_hi_MULTU;M_LO<=mux_lo_MULTU;end
                    endcase
                end
                SEXE_BREAK:begin
                    exception<=0;
                    eret<=0;
                    cause<=5'bxxxxx;

                    PC_ena<=1;
                    M_PC<=mux_pc_EPC;
                end
            endcase
        end
    end
endmodule

module controller_purify(ins, clk, rst, write_r, read_r, PC_en, fetch, ac_ena, ram_ena, rom_ena,ram_write, ram_read, rom_read, ad_sel);

input clk, rst;   		
input [2:0] ins;  		


output reg write_r, read_r, PC_en, ac_ena, ram_ena, rom_ena;



output reg ram_write, ram_read, rom_read, ad_sel;

output reg [1:0] fetch;		


reg [3:0] state;		
reg [3:0] next_state; 	



parameter 	NOP=3'b000, 
			LDO=3'b001,	
			LDA=3'b010, 
			STO=3'b011, 
			PRE=3'b100, 
			ADD=3'b101, 
			LDM=3'b110, 
			HLT=3'b111; 


parameter Sidle=4'hf,
			 S0=4'd0,
			 S1=4'd1,
			 S2=4'd2,
			 S3=4'd3,
			 S4=4'd4,
			 S5=4'd5,
			 S6=4'd6,
			 S7=4'd7,
			 S8=4'd8,
			 S9=4'd9,
			 S10=4'd10,
			 S11=4'd11,
			 S12=4'd12;


always @(posedge clk or negedge rst) 
begin
	if(!rst) state<=Sidle;

	else state<=next_state;

end


always @*
begin
case(state)
S1:		begin
			if (ins==NOP) next_state=S0;
			else if (ins==HLT)  next_state=S2;
			else if (ins==PRE | ins==ADD) next_state=S9;
			else if (ins==LDM) next_state=S11;
			else next_state=S3;
		end

S4:		begin
			if (ins==LDA | ins==LDO) next_state=S5;

			else next_state=S7; 
		end
Sidle:	next_state=S0;
S0:		next_state=S1;
S2:	    next_state=S2;
S3:		next_state=S4;
S5:		next_state=S6;
S6:		next_state=S0;
S7:		next_state=S8;
S8:		next_state=S0;
S9:		next_state=S10;
S10:	next_state=S0;
S11:	next_state=S12;
S12:	next_state=S0;
default: next_state=Sidle;
endcase
end



always@*
begin 
case(state)


  Sidle: begin
		 write_r=1'b0;
		 read_r=1'b0;
		 PC_en=1'b0; 
		 ac_ena=1'b0;
		 ram_ena=1'b0;
		 rom_ena=1'b0;
		 ram_write=1'b0;
		 ram_read=1'b0;
		 rom_read=1'b0;
		 ad_sel=1'b0;
		 fetch=2'b00;
		 end
     S0: begin 
		 write_r=0;
		 read_r=0;
		 PC_en=0;
 ac_ena=0;
		 ram_ena=0;
		 rom_ena=1;
		 ram_write=0;
		 ram_read=0;
		 rom_read=1;
		 ad_sel=0;
		 fetch=2'b01;
		 end
     S1: begin
		 write_r=0;
		 read_r=0;
		 PC_en=1; 
		 ac_ena=0;
		 ram_ena=0;
		 ram_write=0;
		 ram_read=0;
		 rom_ena=1;
		 rom_read=1; 
		 ad_sel=0;
		 fetch=2'b00;
		 end
     S2: begin
		 write_r=0;
		 read_r=0;
		 PC_en=0;
		 ac_ena=0;
		 ram_ena=0;
		 rom_ena=0;
		 ram_write=0;
		 ram_read=0;
		 rom_read=0;
		 ad_sel=0;
		 fetch=2'b00;
		 end
     S3: begin 
		 write_r=0;
		 read_r=0;
		 PC_en=0;
		 ac_ena=1; 
		 ram_ena=0;
		 rom_ena=1;
		 ram_write=0;
		 ram_read=0;
		 rom_read=1;
		 ad_sel=0;
	     fetch=2'b10; 
		 end
S4: begin
		 write_r=0;
		 read_r=0;
		 PC_en=1;
		 ac_ena=1;
		 ram_ena=0;
		 ram_write=0;
		 ram_read=0;
		 rom_ena=1; 
		 rom_read=1;
		 ad_sel=0;
		 fetch=2'b10; 
		 end
     S5: begin
		 if (ins==LDO)
		 begin
		 write_r=1;
		 read_r=0;
		 PC_en=0;
		 ac_ena=1;
		 ram_ena=0;
		 ram_write=0;
		 ram_read=0;
		 rom_ena=1;
		 rom_read=1;
		 ad_sel=1;
		 fetch=2'b01; 		 
		 end
		 else 
		 begin
		 write_r=1;
		 read_r=0;
		 PC_en=0;
		 ac_ena=1;
		 ram_ena=1;
	   	 ram_write=0;
		 ram_read=1;
		 rom_ena=0;
		 rom_read=0;
		 ad_sel=1;
		 fetch=2'b01;
		 end	 
		 end
     S6: begin 

	 write_r=1'b0;
		 read_r=1'b0;
		 PC_en=1'b0; 
		 ac_ena=1'b0;
		 ram_ena=1'b0;
		 rom_ena=1'b0;
		 ram_write=1'b0;
		 ram_read=1'b0;
		 rom_read=1'b0;
		 ad_sel=1'b0;
		 fetch=2'b00;
	end

     S7: begin 
		 write_r=0;
		 read_r=1;
		 PC_en=0;
		 ac_ena=0;
		 ram_ena=0;
		 rom_ena=0;
		 ram_write=0;
		 ram_read=0;
		 rom_read=0;
		 ad_sel=0;
		 fetch=2'b00;
		 end
     S8: begin 
		 write_r=0;
		 read_r=1;
		 PC_en=0;
		 ac_ena=0;
		 rom_read=0;
		 rom_ena=0;

		 ram_ena=1;
		 ram_write=1;
		 ram_read=0;

		 ad_sel=1;
		 fetch=2'b00; 
		 end
     S9: begin 
		 if (ins==PRE) 
		 begin
		 write_r=0;
		 read_r=1;
		 PC_en=0;
		 ac_ena=1;
		 ram_ena=0;
		 rom_ena=0;
		 ram_write=0;
		 ram_read=0;
		 rom_read=0;
		 ad_sel=0;
		 fetch=2'b00;
		 end
		 else 
		 begin 
		 write_r=0;
		 read_r=1;
		 PC_en=0;
		 ac_ena=1;
		 ram_ena=0;
		 rom_ena=0;
		 ram_write=0;
		 ram_read=0;
		 rom_read=0;
		 ad_sel=0;

		 fetch=2'b00;		 
		 end 
		 end
    S10: begin
		 write_r=0;
		 read_r=1;
		 PC_en=0;
		 ac_ena=0;
		 ram_ena=0;
		 rom_ena=0;
		 ram_write=0;
		 ram_read=0;
		 rom_read=0;
		 ad_sel=0;
		 fetch=2'b00;
		 end
    S11: begin 
		 write_r=1;
		 read_r=0;
		 PC_en=0;
		 ac_ena=1;
		 ram_ena=0;

		 ram_write=0;
		 ram_read=0;
		 rom_ena=1;
		 rom_read=1;
		 ad_sel=0;
		 fetch=2'b00;

		 end
    S12: begin 
		 write_r=0;
		 read_r=0;
		 PC_en=0;
		 ac_ena=0;
		 ram_ena=0;
		 rom_ena=0;
		 ram_write=0;
		 ram_read=0;
		 rom_read=0;
		 ad_sel=0;
		 fetch=2'b00;	 
		 end
default: begin
		 write_r=0;
		 read_r=0;
		 PC_en=0;
		 ac_ena=0;
		 ram_ena=0;
		 rom_ena=0;
		 ram_write=0;
		 ram_read=0;
		 rom_read=0;
		 ad_sel=0;
		 fetch=2'b00;		 
		 end
endcase
end
endmodule

