   output reg           misr_cntl,
   output reg           sens_disb,
   output reg           sens_sel,
   output reg           xor_sync,
   output reg		padr_rfmt, 
   output reg           sclk_inv,
   output reg           ppll_enab
  );

  parameter 		PAL_WADR	= 3'h0,  
	  		PAL_DAT		= 3'h1,  
	  		PIX_MSK		= 3'h2,  
	  		PAL_RADR 	= 3'h3,  
			IDX_ADRLO	= 3'h4,  
			IDX_ADRHI 	= 3'h5,  
	  		IDX_DAT 	= 3'h6,  
			IDX_CTL		= 3'd7,	 
			MISC_CTL1	= 11'h70, 
			MISC_CTL2	= 11'h71, 
			MISC_CLK_CTL	= 11'h02, 
			SYNC_CTL	= 11'h03, 
			HSYNC_CTL	= 11'h04, 
			PWR_MNG		= 11'h05, 
			DAC_OPR		= 11'h06, 
			PAL_CTL		= 11'h07, 
			SYSCLK_CTL	= 11'h08, 
			PIX_FMT		= 11'h0A, 
			PIX_CTL8	= 8'h0B, 
			PIX_CTL16	= 8'h0C, 
			PIX_CTL32	= 8'h0E; 

  wire [13:0] 		read_address;
  wire 			sns =  blu_comp & grn_comp & red_comp;
  wire 			lsns = lblu_comp & lgrn_comp & lred_comp;

  reg [10:0] 		idx;
  reg 			idx_cntl;
  reg [2:0] 		pix_p_pll;
  reg [1:0] 		pix_c_pll;
  reg [6:0] 		pix_m_pll;
  reg [5:0] 		pix_n_pll;


  wire 			rdwr_clk;

  assign 		read_address = {cp_addr[2:0] , idx[10:0]};

  assign 		rdwr_clk = wrn & rdn;


  always @(posedge hclk or negedge hresetn)
    begin
      if (!hresetn)idx_raw[10:0] <= 11'h000;

      else if((rs == IDX_DAT) && !wrn) idx_raw <= idx;
      else if(!rdwr_clk) idx_raw <= 11'h0;
    end


  always @(posedge hclk or negedge hresetn)
    begin
      if (!hresetn) idx_inc[10:0] <= 11'h000;
      else if((rs == IDX_DAT) && !rdwr_clk) idx_inc <= idx;
      else if(!rdwr_clk) idx_inc <= 11'h0;
    end


  always @(posedge hclk or negedge hresetn)
    if (!hresetn) 	cp_addr[2:0] <= 3'b0;
    else 		cp_addr <= rs;

  always @(posedge hclk or negedge hresetn) begin
    if (!hresetn) begin
      idx[10:0]      <= 11'h000;
      pal_wradr[7:0] <= 8'h00;
      pal_data1[7:0] <= 8'h00;
      pal_data2[7:0] <= 8'h00;
      pal_data3[7:0] <= 8'h00;
      pix_mask[7:0]  <= 8'h00;
      idx_cntl       <= 1'b0;
      misr_cntl      <= 1'b0;
      padr_rfmt      <= 1'b0;
      sens_disb      <= 1'b0;
      sens_sel       <= 1'b0;
      xor_sync       <= 1'b0;
      pix_sel        <= 2'b0;
      blank_cntl     <= 1'b0;
      colres         <= 1'b0;
      vga_mode       <= 1'b0;
      sclk_inv       <= 1'b0;
      ppll_enab      <= 1'b1;
      csyn_invt      <= 1'b0;
      vsyn_invt      <= 1'b0;
      hsyn_invt      <= 1'b0;
      vsyn_cntl      <= 2'b00;
      hsyn_cntl      <= 2'b00;
      hsyn_pos       <= 4'b0;
      sclk_pwr       <= 1'b0;
      sync_pwr       <= 1'b0;
      iclk_pwr       <= 1'b0;
      dac_pwr        <= 1'b0;
      dac_op         <= 4'b0;
      sixbitlin      <= 1'b0;
      prog_mode      <= 1'b0;
      spll_enab      <= 1'b1;
      pixformat      <= 3'b0;
      b8dcol         <= 1'b0;
      b16dcol        <= 1'b0;
      ziblin         <= 1'b0;
      fsf            <= 1'b0;
      b32dcol        <= 1'b0;
      pixclksel      <= 3'b1;
      int_fs         <= 2'h0;
      pixreg20       <= 8'h07;
      pixreg21       <= 8'h15;
      pixreg22       <= 8'h10;
      pixreg23       <= 8'h2C;
      pixreg24       <= 8'h12;
      pixreg25       <= 8'h00;
      pixreg26       <= 8'h00;
      pixreg27       <= 8'h00;
      sysnctl        <= 6'h08;
      sysmctl        <= 8'h41;
      syspctl        <= 3'h0;
      syscctl        <= 2'h0;
      curctl         <= 8'h00;
      adcurctl       <= 1'b0;
      adcuratt       <= 8'h00;
      curxlow        <= 8'h00;
      curxhi         <= 8'h00; 
      curylow        <= 8'h00;
      curyhi         <= 8'h00; 
      curhotx        <= 6'h00; 
      curhoty        <= 6'h00;
      cur1red        <= 8'h00;
      cur1grn        <= 8'h00;
      cur1blu        <= 8'h00;
      cur2red        <= 8'h00;
      cur2grn        <= 8'h00;
      cur2blu        <= 8'h00;
      cur3red        <= 8'h00;
      cur3grn        <= 8'h00;
      cur3blu        <= 8'h00;
      cpu2cursor     <= 8'h00;
    end else begin

      if ((cp_addr == IDX_DAT) && (!wrn || !rdn)) idx <= idx + idx_cntl;

      if (!wrn) begin
	case (cp_addr)
	  IDX_ADRLO: idx[7:0]  <= cpu_din[7:0]; 
	  IDX_ADRHI: idx[10:8] <= cpu_din[2:0]; 
	  IDX_DAT: begin


            cpu2cursor <= cpu_din[7:0]; 
	    case (idx)
	      MISC_CTL1: begin
		misr_cntl <= cpu_din[7];
		padr_rfmt <= cpu_din[5];
		sens_disb <= cpu_din[4];
		sens_sel  <= cpu_din[3];
		xor_sync  <= cpu_din[2];
	      end
	      MISC_CTL2: begin
		pix_sel    <= cpu_din[7:6];
		blank_cntl <= cpu_din[4];
		colres     <= cpu_din[2];
		vga_mode   <= !cpu_din[0];
	      end
	      MISC_CLK_CTL: begin
		sclk_inv  <= cpu_din[4];
		ppll_enab <= cpu_din[0];
	      end
	      SYNC_CTL: begin
		csyn_invt <= cpu_din[6];
		vsyn_invt <= cpu_din[5];
		hsyn_invt <= cpu_din[4];
		vsyn_cntl <= cpu_din[3:2];
		hsyn_cntl <= cpu_din[1:0];
	      end
	      HSYNC_CTL: hsyn_pos <= cpu_din[3:0];
	      PWR_MNG: begin
		sclk_pwr  <= cpu_din[4];
		sync_pwr  <= cpu_din[2];
		iclk_pwr  <= cpu_din[1];
		dac_pwr   <= cpu_din[0];
	      end
	      DAC_OPR: dac_op <= cpu_din[3:0];
	      PAL_CTL: sixbitlin <= cpu_din[7];
	      SYSCLK_CTL: begin
		prog_mode <= cpu_din[2];
		spll_enab <= cpu_din[0];
	      end
	      PIX_FMT: pixformat <= cpu_din[2:0];
	      PIX_CTL8: b8dcol <= cpu_din[0];
	      PIX_CTL16: begin


		ziblin <= cpu_din[2];
		fsf    <= cpu_din[1];
		if (cpu_din[7:6] == 2'b11) b16dcol <= 1'b1;
		else b16dcol <= 1'b0;
	      end
	      PIX_CTL32: begin


		if (cpu_din[1:0] == 2'b11) b32dcol <= 1'b1;
		else b32dcol <= 1'b0;
	      end
	      11'h010: pixclksel <= cpu_din[2:0];
	      11'h011: int_fs   <= cpu_din[1:0];
	      11'h020: begin
		pixreg20   <= cpu_din[7:0]; 
	      end
	      11'h021: begin
		pixreg21   <= cpu_din[7:0]; 
	      end
	      11'h022: begin
		pixreg22   <= cpu_din[7:0]; 
	      end
	      11'h023: begin
		pixreg23   <= cpu_din[7:0]; 
	      end
	      11'h024: begin
		pixreg24   <= cpu_din[7:0]; 
	      end
	      11'h025: begin
		pixreg25   <= cpu_din[7:0]; 
	      end
	      11'h026: begin
		pixreg26   <= cpu_din[7:0]; 
	      end
	      11'h027: begin
		pixreg27   <= cpu_din[7:0]; 
	      end
	      11'h015: begin
		sysnctl    <= cpu_din[5:0]; 
	      end
	      11'h016: begin
		sysmctl    <= cpu_din[7:0]; 
	      end
	      11'h017: begin
		syspctl    <= cpu_din[2:0]; 
	      end
	      11'h018: begin
		syscctl    <= cpu_din[1:0]; 
	      end
	      11'h030: curctl     <= cpu_din[7:0]; 
	      11'h037: adcurctl   <= cpu_din[0];   
	      11'h038: adcuratt   <= cpu_din[7:0]; 
	      11'h031: curxlow    <= cpu_din[7:0]; 
	      11'h032: curxhi     <= {{4{cpu_din[7]}},
                                      cpu_din[3:0]};  
	      11'h033: curylow    <= cpu_din[7:0]; 
	      11'h034: curyhi     <= {{4{cpu_din[7]}},
                                      cpu_din[3:0]};
	      11'h035: curhotx    <= cpu_din[5:0]; 
	      11'h036: curhoty    <= cpu_din[5:0]; 
	      11'h040: cur1red    <= cpu_din[7:0]; 
	      11'h041: cur1grn    <= cpu_din[7:0]; 
	      11'h042: cur1blu    <= cpu_din[7:0]; 
	      11'h043: cur2red    <= cpu_din[7:0]; 
	      11'h044: cur2grn    <= cpu_din[7:0]; 
	      11'h045: cur2blu    <= cpu_din[7:0]; 
	      11'h046: cur3red    <= cpu_din[7:0]; 
	      11'h047: cur3grn    <= cpu_din[7:0]; 
	      11'h048: cur3blu    <= cpu_din[7:0]; 
	    endcase
	  end
	  PAL_WADR: begin
	    wr_mode  <=1'b1;
	    rd_mode  <=1'b0;
	    pal_wradr[7:0] <= cpu_din[7:0]; 
	  end
	  PAL_RADR: begin
            wr_mode  <=1'b0;
            rd_mode  <=1'b1;
	    pal_wradr[7:0] <= cpu_din[7:0]; 
	  end
	  PAL_DAT: begin
	    pal_data1[7:0] <= cpu_din[7:0];
	    pal_data2[7:0] <= pal_data1[7:0];
	    pal_data3[7:0] <= pal_data2[7:0];
	  end

	  PIX_MSK: pix_mask[7:0] <= cpu_din[7:0];
	  IDX_CTL: idx_cntl  <= cpu_din[0];
	endcase
      end
    end
  end


  always @*
    casex(read_address)
      14'b000xxxxxxxxxxx:    cpu_dout = paladr;
      14'b001xxxxxxxxxxx:    cpu_dout = pal2cpu;
      14'b010xxxxxxxxxxx:    cpu_dout = pix_mask;
      14'b011xxxxxxxxxxx:      begin
        if (!padr_rfmt) begin
          cpu_dout = paladr; end
        else begin
          cpu_dout = {6'h00 , rd_mode, rd_mode}; end
      end
      14'b100xxxxxxxxxxx:    cpu_dout = idx[7:0];
      14'b101xxxxxxxxxxx:    cpu_dout = {5'h00 , idx[10:8]};
      14'b111xxxxxxxxxxx:    cpu_dout = {7'h00 , idx_cntl};


      14'b11000001110000:    cpu_dout = {misr_cntl, 1'b0, padr_rfmt,
					  sens_disb, sens_sel, xor_sync, 2'h0 };



      14'b11000001110001:    cpu_dout = {pix_sel, 1'b0, blank_cntl, 1'b0,
					  colres, 1'b0, !vga_mode };


      14'b1100000000000x:    cpu_dout = 8'h99;


      14'b11000000000010:    cpu_dout = { 3'h0, sclk_inv, 3'h0, ppll_enab};


      14'b11000000000011:    cpu_dout = { 1'h0, csyn_invt, vsyn_invt,
                                           hsyn_invt, vsyn_cntl, hsyn_cntl};


      14'b11000000000100:    cpu_dout = { 4'h0, hsyn_pos};


      14'b11000000000101:    cpu_dout = { 3'h0, sclk_pwr, 1'b0, sync_pwr,
					   iclk_pwr, dac_pwr};


      14'b11000000000110:    cpu_dout = { 4'h0, dac_op };


      14'b11000000000111:    cpu_dout = { sixbitlin, 7'h00 };


      14'b11000000001000:    cpu_dout = {5'h00, prog_mode, 1'b0, spll_enab};


      14'b11000000001010:    cpu_dout = {5'h00, pixformat};

      14'b11000000001011:    cpu_dout = {7'h00, b8dcol};

      14'b11000000001100:    cpu_dout = {b16dcol, b16dcol, 3'h0, ziblin,
                                          fsf, 1'b0 };

      14'b11000000001110:    cpu_dout = {6'h00, b32dcol, b32dcol };

      14'b11000000010000:    cpu_dout = {5'h00, pixclksel};

      14'b11000000010001:    cpu_dout = {6'h00, int_fs};

      14'b11000000100000:   


        cpu_dout =  pixreg20; 

      14'b11000000100001: 



        cpu_dout =  pixreg21;

      14'b11000000100010: 


        cpu_dout =  pixreg22;

      14'b11000000100011: 


        cpu_dout =  pixreg23;

      14'b11000000100100: 



        cpu_dout =  pixreg24;

      14'b11000000100101: 



        cpu_dout =  pixreg25;

      14'b11000000100110: 


        cpu_dout =  pixreg26;

      14'b11000000100111:


        cpu_dout =  pixreg27;

      14'b11000000010101: 



        cpu_dout = {2'b0 , sysnctl[5:0]};

      14'b11000000010110: 



        cpu_dout =  sysmctl;


      14'b11000000010111: 
        cpu_dout = {5'h00, syspctl}; 



      14'b11000000011000: 
        cpu_dout = {6'h00, syscctl}; 



      14'b11000000110000:    cpu_dout = curctl;

      14'b11000000110111:    cpu_dout = {7'h00, adcurctl};

      14'b11000000111000:    cpu_dout = adcuratt;

      14'b11000000110001:    begin  if (curctl[4]) begin
        cpu_dout =  act_curxlow ; end
      else begin cpu_dout =  curxlow ; end
      end

      14'b11000000110010:    begin  if (curctl[4]) begin
        cpu_dout = {act_curxhi[7],
                     act_curxhi[7], act_curxhi[7],
                     act_curxhi[7], act_curxhi[3:0]}; end
      else begin cpu_dout = {curxhi[7],
                              curxhi[7], curxhi[7], curxhi[7],
                              curxhi[3:0]}; end end

      14'b11000000110011:    begin  if (curctl[4]) begin
        cpu_dout =  act_curylow ; end
      else begin cpu_dout =  curylow ; end
      end

      14'b11000000110100:    begin  if (curctl[4]) begin
        cpu_dout = {act_curyhi[7],
                     act_curyhi[7], act_curyhi[7],
                     act_curyhi[7], act_curyhi[3:0]}; end
      else begin cpu_dout = {curyhi[7],
                              curyhi[7], curyhi[7], curyhi[7],
                              curyhi[3:0]}; end end

      14'b11000000110101:    begin  if (curctl[2]) begin
        cpu_dout = {2'b00, curhotx}; end
      else begin
        cpu_dout = {3'h0, curhotx[4:0]}; end end

        14'b11000000110110:    begin  if (curctl[2]) begin
          cpu_dout = {2'b00, curhoty}; end
        else begin
          cpu_dout = {3'h0, curhoty[4:0]}; end end

      14'b11000001000000:    cpu_dout = cur1red;

      14'b11000001000001:    cpu_dout = cur1grn;

      14'b11000001000010:    cpu_dout = cur1blu;

      14'b11000001000011:    cpu_dout = cur2red;

      14'b11000001000100:    cpu_dout = cur2grn;

      14'b11000001000101:    cpu_dout = cur2blu;

      14'b11000001000110:    cpu_dout = cur3red;

      14'b11000001000111:    cpu_dout = cur3grn;

      14'b11000001001000:    cpu_dout = cur3blu;

      14'b11000010000010:    cpu_dout = {lsns, lblu_comp, lgrn_comp,
					  lred_comp, sns, blu_comp, grn_comp, red_comp};

      14'b11000010000011:    cpu_dout = {7'h0, misr_done};

      14'b11000010000100:    cpu_dout =  misr_red;

      14'b11000010000110:    cpu_dout = misr_grn;

      14'b11000010001000:    cpu_dout = misr_blu;

      14'b11000010001100:    cpu_dout = {5'h00 , preg[2:0]};

      14'b11000010001101:    cpu_dout = {6'h00 , creg[1:0]};

      14'b11000010001110:    cpu_dout = {1'b0 ,  mreg[6:0]};

      14'b11000010001111:    cpu_dout = {2'b00 , nreg[5:0]};

      14'b11000010010000:    cpu_dout = {5'h00 , preg[2:0]};

      14'b11000010010001:    cpu_dout = {6'h00 , creg[1:0]};
      default :   cpu_dout = cursor2cpu;
    endcase


 endmodule

module conv_layer_controller(


	clk,
	rst_n,
	enable,
	input_interface_ack,


	input_interface_cmd,
	current_state


);

parameter	WIDTH				=	32;
parameter	KERNEL_SIZE			=	3;	
parameter	IMAGE_SIZE			=	8;
parameter	ARRAY_SIZE			=	6;

parameter	ADDR_WIDTH			=	6;
parameter	ROM_DEPTH			=	64;










parameter	ACK_IDLE			=	2'd0;
parameter	ACK_PRELOAD_FIN		=	2'd1;
parameter	ACK_SHIFT_FIN		=	2'd2;
parameter	ACK_LOAD_FIN		=	2'd3;

parameter	CMD_IDLE			=	2'd0;
parameter	CMD_PRELOAD_START	=	2'd1;
parameter	CMD_SHIFT_START		=	2'd2;
parameter	CMD_LOAD_START		=	2'd3;

parameter	TOTAL_WEIGHT		=	4;
parameter	TOTAL_SHIFT			=	ARRAY_SIZE;

input					clk;
input					rst_n;
input					enable;
input	[1:0]			input_interface_ack;


output 	[1:0]			input_interface_cmd;
reg		[1:0]			input_interface_cmd;

reg		[1:0]			weight_cycle;
reg		[2:0]			shift_cycle;

output	[2:0]			current_state;
reg		[2:0]			current_state;
reg		[2:0]			next_state;

parameter	STAGE_INIT			=	3'd0;
parameter	STAGE_PRELOAD		=	3'd1;	
parameter	STAGE_SHIFT			=	3'd2;
parameter	STAGE_LOAD			=	3'd3;


always @(posedge clk, negedge rst_n) begin
	if(!rst_n) begin
		current_state	<=	STAGE_INIT;
	end
	else begin
		if (enable)
			current_state	<=	next_state;
		else
			current_state	<= 	current_state;
	end
end

always @(current_state, input_interface_ack, weight_cycle) begin
	case (current_state)
		STAGE_INIT: begin
			next_state	=	STAGE_PRELOAD;
		end

		STAGE_PRELOAD: begin
			if ( input_interface_ack == ACK_PRELOAD_FIN )
				next_state	=	STAGE_SHIFT;
			else
				next_state	=	STAGE_PRELOAD;
		end

		STAGE_SHIFT: begin
			if ( input_interface_ack == ACK_SHIFT_FIN ) begin
				if ( weight_cycle == TOTAL_WEIGHT - 1  ) begin
					if ( shift_cycle  == TOTAL_SHIFT - 1 )
						next_state	<=	STAGE_PRELOAD;
					else
						next_state	=	STAGE_LOAD;
				end
				else
					next_state	=	STAGE_SHIFT;
			end
			else
				next_state	= STAGE_SHIFT;
		end

		STAGE_LOAD: begin
			if (input_interface_ack	==	ACK_LOAD_FIN)
				next_state	=	STAGE_SHIFT;
			else
				next_state	=	STAGE_LOAD;
		end

		default:
			next_state	= current_state;
	endcase		
end

always @(posedge clk, negedge rst_n) begin
	if(!rst_n)
		input_interface_cmd	<=	CMD_IDLE;
	else begin
		case (current_state)
			STAGE_INIT:
				input_interface_cmd <=	CMD_PRELOAD_START;

			STAGE_PRELOAD:
				if ( input_interface_ack == ACK_PRELOAD_FIN )
					input_interface_cmd	<=	CMD_SHIFT_START;
				else
					input_interface_cmd	<=	CMD_IDLE;

			STAGE_SHIFT:
				if ( input_interface_ack == ACK_SHIFT_FIN) begin
					if ( weight_cycle == TOTAL_WEIGHT - 1 ) begin
						if ( shift_cycle  == TOTAL_SHIFT - 1 )
							input_interface_cmd	<=	CMD_PRELOAD_START;
						else
							input_interface_cmd	<=	CMD_LOAD_START;
					end	
					else
						input_interface_cmd	<=	CMD_SHIFT_START;
				end
				else
					input_interface_cmd	<= CMD_IDLE;

			STAGE_LOAD:
				if ( input_interface_ack == ACK_LOAD_FIN)
					input_interface_cmd	<=	CMD_SHIFT_START;
				else
					input_interface_cmd	<=	CMD_IDLE;

			default:
				input_interface_cmd	<=	CMD_IDLE;
		endcase
	end
end


always @(posedge clk, negedge rst_n) begin
	if(!rst_n) 	
		weight_cycle	<=	2'd0;
	else if ( input_interface_ack == ACK_SHIFT_FIN) begin
		if ( weight_cycle == TOTAL_WEIGHT - 1 )
			weight_cycle	<=	2'd0;
		else
			weight_cycle	<=	weight_cycle	+ 1'd1;
	end 
	else
		weight_cycle	<=	weight_cycle;	
end

always @(posedge clk, negedge rst_n) begin
	if(!rst_n) 	
		shift_cycle		<=	3'd0;
	else if (input_interface_ack == ACK_SHIFT_FIN) begin
		if ( weight_cycle == TOTAL_WEIGHT - 1)
			shift_cycle		<=	shift_cycle	+ 1'b1;
		else
			shift_cycle		<=	shift_cycle;
	end
	else if ( shift_cycle == TOTAL_SHIFT)
		shift_cycle		<=	3'd0;
end

endmodule

`timescale 1ns / 1ps





















module Ctr(
    input [5:0] opCode,
    output reg RegDst,
    output reg ALUSrc,
    output reg MemToReg,
    output reg RegWrite,
    output reg MemRead,
    output reg MemWrite,
    output reg Branch,
    output reg [1:0] ALUOp,
    output reg Jump
    );


    always @(opCode)
    begin
        case(opCode)
        6'b000000: 
        begin
            RegDst = 1;
            ALUSrc = 0;
            MemToReg = 0;
            RegWrite = 1;
            MemRead = 0;
            MemWrite = 0;
            Branch = 0;
            ALUOp = 2'b10;
            Jump = 0;
        end


