module fifo(
    output [7:0] dout,
    output indicator,  
    input [7:0] din,
    input din_valid,
    input clk,
    input reset_n
);

parameter SIZE = 20,
          INDEX_WIDTH = 8,
          MAX_INDEX = SIZE * 8 - 1;

localparam WAITING = 0,
           RECEIVING = 1,
           LEFT_PADDING = 2,
           TRANSFERING = 3,
           RIGHT_PADDING = 4;

reg [2:0] state, next_state;
reg [MAX_INDEX:0] queue, next_queue;
reg [INDEX_WIDTH - 1:0] head, next_head;  
reg [6:0] count, next_count;

always @(*) begin
    case (state)
        WAITING: begin
            if (din_valid) begin
                next_state = RECEIVING;
                next_queue = {queue[MAX_INDEX - 8:0],
                              din};
                next_head = 8;
            end else begin
                next_state = WAITING;
                next_queue = queue;
                next_head = 0;
            end
            next_count = 0;
        end

        RECEIVING: begin
            if (din_valid) begin
                next_state = RECEIVING;
                next_queue = {queue[MAX_INDEX - 8:0],
                              din};
                next_head = head + 8;
            end else begin
                next_state = LEFT_PADDING;
                next_queue = queue;
                next_head = head;
            end
            next_count = 0;
        end

        LEFT_PADDING: begin
            if (count < 79) begin
                next_state = LEFT_PADDING;
                next_count = count + 1;
            end else begin
                next_state = TRANSFERING;
                next_count = 0;
            end
            next_head = head;
            next_queue = queue;
        end

        TRANSFERING: begin
            if (count < 7) begin
                next_state = TRANSFERING;
                next_head = head;
                next_count = count + 1;
            end else begin
                if (head == 8)  
                    next_state = RIGHT_PADDING;
                else
                    next_state = TRANSFERING;
                next_head = head - 8;
                next_count = 0;
            end
            next_queue = queue;
        end

        RIGHT_PADDING: begin
            if (count < 15) begin
                next_state = RIGHT_PADDING;
                next_count = count + 1;
            end else begin
                next_state = WAITING;
                next_count = 0;
            end
            next_head = 0;
            next_queue = 0;
        end

        default: begin
            next_state = WAITING;
            next_queue = 0;
            next_head = 0;
            next_count = 0;
        end
    endcase
end


always @(posedge clk or negedge reset_n) begin
    if (~reset_n) begin
        state <= WAITING;
        queue <= 0;
        head <= 0;
        count <= 0;
    end else begin
        state <= next_state;
        queue <= next_queue;
        head <= next_head;
        count <= next_count;
    end
end

assign dout = (head == 0) ? 0 : queue[(head - 1)-:8],
       indicator = (state == RECEIVING && ~din_valid) ||
                   (state == TRANSFERING && next_state == RIGHT_PADDING);

endmodule

module gpu_gpios
(
    input         bus_rst,
    input         bus_clk,

    input         bus_eof,

    input   [5:0] reg_rd,
    input   [1:0] reg_wr,

    input   [7:0] reg_wdata,
    output  [7:0] reg_rdata,

    input   [1:0] start_n,
    input   [1:0] coin_n,
    input   [5:0] joy1_n,
    input   [5:0] joy2_n,
    input   [7:0] dip_sw_A,
    input   [7:0] dip_sw_B,

    output        cfg_scale_2x_on,
    output        cfg_scan_line_h,
    output        cfg_scan_line_v,
    output  [3:0] cfg_prom_wren
);




    reg [7:0] r_reg_C000;

    always@(posedge bus_rst or posedge bus_clk) begin : REG_C000
        if (bus_rst) begin
            r_reg_C000 <= 8'b11110111;
        end
        else begin
            r_reg_C000[0] <= start_n[0]; 
            r_reg_C000[1] <= start_n[1]; 
            r_reg_C000[2] <= 1'b1;
            r_reg_C000[3] <= bus_eof;    
            r_reg_C000[4] <= 1'b1;
            r_reg_C000[5] <= 1'b1;
            r_reg_C000[6] <= coin_n[0];  
            r_reg_C000[7] <= coin_n[1];  
        end
    end





    reg [7:0] r_reg_C001;

    always@(posedge bus_rst or posedge bus_clk) begin : REG_C001
        if (bus_rst) begin
            r_reg_C001 <= 8'b11111111;
        end
        else begin
            r_reg_C001[0] <= joy1_n[0]; 
            r_reg_C001[1] <= joy1_n[1]; 
            r_reg_C001[2] <= joy1_n[2]; 
            r_reg_C001[3] <= joy1_n[3]; 
            r_reg_C001[4] <= joy1_n[4]; 
            r_reg_C001[5] <= joy1_n[5]; 
            r_reg_C001[6] <= 1'b1;
            r_reg_C001[7] <= 1'b1;
        end
    end





    reg [7:0] r_reg_C002;

    always@(posedge bus_rst or posedge bus_clk) begin : REG_C002
        if (bus_rst) begin
            r_reg_C002 <= 8'b11111111;
        end
        else begin
            r_reg_C002[0] <= joy2_n[0]; 
            r_reg_C002[1] <= joy2_n[1]; 
            r_reg_C002[2] <= joy2_n[2]; 
            r_reg_C002[3] <= joy2_n[3]; 
            r_reg_C002[4] <= joy2_n[4]; 
            r_reg_C002[5] <= joy2_n[5]; 
            r_reg_C002[6] <= 1'b1;
            r_reg_C002[7] <= 1'b1;
        end
    end





    reg [7:0] r_reg_C003;
    reg [7:0] r_reg_C004;

    always@(posedge bus_clk) begin : REG_C003_C004
        r_reg_C003 <= dip_sw_A;
        r_reg_C004 <= dip_sw_B;
    end





    reg [7:0] r_reg_C007;
    reg [7:0] r_reg_C807;

    always@(posedge bus_rst or posedge bus_clk) begin : REG_C007_C807
        if (bus_rst) begin
            r_reg_C007 <= 8'b00000000;
            r_reg_C807 <= 8'b00000000;
        end
        else begin

            r_reg_C007[7] <=  r_reg_C807[6] &  r_reg_C807[1] & ~r_reg_C807[0]
                           |  r_reg_C807[6] &  r_reg_C807[5] &  r_reg_C807[2] &  r_reg_C807[0]
                           | ~r_reg_C807[4] &  r_reg_C807[2] &  r_reg_C807[1] &  r_reg_C807[0]
                           | ~r_reg_C807[5] &  r_reg_C807[3] & ~r_reg_C807[2] &  r_reg_C807[1]
                           | ~r_reg_C807[4] & ~r_reg_C807[3] & ~r_reg_C807[2] & ~r_reg_C807[1];
            r_reg_C007[6] <=  r_reg_C807[6] &  r_reg_C807[3] &  r_reg_C807[2]
                           |  r_reg_C807[4] & ~r_reg_C807[3] &  r_reg_C807[2]
                           |  r_reg_C807[4] & ~r_reg_C807[3] & ~r_reg_C807[1]
                           |  r_reg_C807[4] & ~r_reg_C807[3] & ~r_reg_C807[0]
                           |  r_reg_C807[6] & ~r_reg_C807[4] & ~r_reg_C807[2]
                           | ~r_reg_C807[7] &  r_reg_C807[5] &  r_reg_C807[3] & ~r_reg_C807[2];
            r_reg_C007[5] <=  r_reg_C807[7] &  r_reg_C807[4]
                           |  r_reg_C807[5] &  r_reg_C807[2] &  r_reg_C807[1]
                           | ~r_reg_C807[3] &  r_reg_C807[2] &  r_reg_C807[1]
                           | ~r_reg_C807[5] & ~r_reg_C807[2] & ~r_reg_C807[0]
                           |  r_reg_C807[5] & ~r_reg_C807[3] &  r_reg_C807[1] &  r_reg_C807[0]
                           | ~r_reg_C807[6] &  r_reg_C807[4] &  r_reg_C807[2] &  r_reg_C807[0]
                           | ~r_reg_C807[6] & ~r_reg_C807[4] & ~r_reg_C807[3] & ~r_reg_C807[2]
                           | ~r_reg_C807[4] & ~r_reg_C807[3] & ~r_reg_C807[2] & ~r_reg_C807[1];
            r_reg_C007[4] <= ~r_reg_C807[4] & ~r_reg_C807[0]
                           | ~r_reg_C807[7] &  r_reg_C807[6] &  r_reg_C807[0]
                           |  r_reg_C807[5] & ~r_reg_C807[2] &  r_reg_C807[1]
                           |  r_reg_C807[3] &  r_reg_C807[2] & ~r_reg_C807[0]
                           | ~r_reg_C807[7] &  r_reg_C807[3] & ~r_reg_C807[1];
            r_reg_C007[3] <= ~r_reg_C807[6] &  r_reg_C807[2] &  r_reg_C807[1]
                           | ~r_reg_C807[7] &  r_reg_C807[3] & ~r_reg_C807[0]
                           | ~r_reg_C807[7] & ~r_reg_C807[6] &  r_reg_C807[4] &  r_reg_C807[3]
                           | ~r_reg_C807[7] & ~r_reg_C807[6] & ~r_reg_C807[1] & ~r_reg_C807[0]
                           | ~r_reg_C807[6] & ~r_reg_C807[4] & ~r_reg_C807[3] & ~r_reg_C807[2];
            r_reg_C007[2] <=  r_reg_C807[6] &  r_reg_C807[4] &  r_reg_C807[3]
                           |  r_reg_C807[5] & ~r_reg_C807[3] &  r_reg_C807[0]
                           | ~r_reg_C807[4] & ~r_reg_C807[3] & ~r_reg_C807[2]
                           | ~r_reg_C807[7] &  r_reg_C807[5] &  r_reg_C807[4] &  r_reg_C807[2]
                           | ~r_reg_C807[7] & ~r_reg_C807[6] & ~r_reg_C807[4] & ~r_reg_C807[1];
            r_reg_C007[1] <=  r_reg_C807[2] &  r_reg_C807[1] &  r_reg_C807[0]
                           |  r_reg_C807[3] &  r_reg_C807[1] &  r_reg_C807[0]
                           | ~r_reg_C807[6] & ~r_reg_C807[5] &  r_reg_C807[2]
                           | ~r_reg_C807[6] &  r_reg_C807[3] & ~r_reg_C807[1]
                           |  r_reg_C807[6] & ~r_reg_C807[3] & ~r_reg_C807[0]
                           |  r_reg_C807[5] & ~r_reg_C807[4] & ~r_reg_C807[3] & ~r_reg_C807[2]
                           |  r_reg_C807[5] & ~r_reg_C807[2] & ~r_reg_C807[1] & ~r_reg_C807[0];
            r_reg_C007[0] <=  r_reg_C807[3] &  r_reg_C807[2] & ~r_reg_C807[1]
                           | ~r_reg_C807[6] &  r_reg_C807[4] &  r_reg_C807[2]
                           | ~r_reg_C807[6] &  r_reg_C807[2] & ~r_reg_C807[0]
                           | ~r_reg_C807[4] &  r_reg_C807[3] & ~r_reg_C807[1]
                           |  r_reg_C807[5] &  r_reg_C807[4] & ~r_reg_C807[3] &  r_reg_C807[1]
                           |  r_reg_C807[5] & ~r_reg_C807[4] & ~r_reg_C807[2] & ~r_reg_C807[1];

            if (reg_wr[0])
               r_reg_C807 <= reg_wdata;
        end
    end





    reg [7:0] r_reg_rdata;

    always@(posedge bus_clk) begin : READ_MUX
        r_reg_rdata <= r_reg_C000 & {8{reg_rd[0]}}
                     | r_reg_C001 & {8{reg_rd[1]}}
                     | r_reg_C002 & {8{reg_rd[2]}}
                     | r_reg_C003 & {8{reg_rd[3]}}
                     | r_reg_C004 & {8{reg_rd[4]}}
                     | r_reg_C007 & {8{reg_rd[5]}};
    end

    assign reg_rdata = r_reg_rdata;





    reg [1:0] r_cfg_fsm;
    reg [3:0] r_cfg_reg;
    reg [3:0] r_cfg_wren;

    always@(posedge bus_rst or posedge bus_clk) begin : REG_SPECIAL
        if (bus_rst) begin
            r_cfg_fsm  <= 2'd0;
            r_cfg_reg  <= 4'b0100;
            r_cfg_wren <= 4'd0;
        end
        else begin
            if (reg_wr[1]) begin
                case (r_cfg_fsm)
                    2'd0 : if (reg_wdata == 8'h19) r_cfg_fsm <= 2'd1;
                    2'd1 : if (reg_wdata == 8'h43) r_cfg_fsm <= 2'd2;
                    2'd2 : if (reg_wdata == 8'hFD) r_cfg_fsm <= 2'd3;
                    2'd3 : begin
                        if (reg_wdata[7])
                            r_cfg_reg[reg_wdata[1:0]] <= reg_wdata[6];
                        else
                            r_cfg_wren <= reg_wdata[3:0];
                        r_cfg_fsm <= 2'd0;
                    end
                endcase
            end
        end
    end

    assign cfg_scale_2x_on = r_cfg_reg[0];
    assign cfg_scan_line_h = r_cfg_reg[1];
    assign cfg_scan_line_v = r_cfg_reg[2];

    assign cfg_prom_wren   = r_cfg_wren;



endmodule

`default_nettype none

















































`define COMMAND  3'b000
`define ADDRESS  3'b001
`define DATA     3'b010
`define PASSTHRU 3'b101

module housekeeping_spi (reset, SCK, SDI, CSB, SDO,
	sdoenb, idata, odata, oaddr, rdstb, wrstb,
	pass_thru, pass_thru_delay,
	pass_thru_reset);

    input reset;
    input SCK;
    input SDI;
    input CSB;
    output SDO;
    output sdoenb;
    input [7:0] idata;
    output [7:0] odata;
    output [7:0] oaddr;
    output rdstb;
    output wrstb; 
    output pass_thru;
    output pass_thru_delay;
    output pass_thru_reset;

    reg  [7:0]  addr;
    reg		wrstb;
    reg		rdstb;
    reg		sdoenb;
    reg  [2:0]  state;
    reg  [2:0]  count;
    reg		writemode;
    reg		readmode;
    reg  [2:0]	fixed;
    wire [7:0]  odata;
    reg  [6:0]  predata;
    wire [7:0]  oaddr;
    reg  [7:0]  ldata;
    reg		pass_thru;
    reg		pass_thru_delay;
    reg		pre_pass_thru;
    wire	csb_reset;

    assign odata = {predata, SDI};
    assign oaddr = (state == `ADDRESS) ? {addr[6:0], SDI} : addr;
    assign SDO = ldata[7];
    assign csb_reset = CSB | reset;
    assign pass_thru_reset = pass_thru_delay | pre_pass_thru;




    always @(negedge SCK or posedge csb_reset) begin
        if (csb_reset == 1'b1) begin
            wrstb <= 1'b0;
            ldata  <= 8'b00000000;
            sdoenb <= 1'b1;
        end else begin



            if (state == `DATA) begin
            	if (readmode == 1'b1) begin
                    sdoenb <= 1'b0;
                    if (count == 3'b000) begin
                	ldata <= idata;
                    end else begin
                	ldata <= {ldata[6:0], 1'b0};	
                    end
                end else begin
                    sdoenb <= 1'b1;
                end





                if (count == 3'b111) begin
                    if (writemode == 1'b1) begin
                        wrstb <= 1'b1;
                    end
                end else begin
                    wrstb <= 1'b0;
                end
	    end else if (state == `PASSTHRU) begin
		wrstb <= 1'b0;
		sdoenb <= 1'b0;
            end else begin
                wrstb <= 1'b0;
                sdoenb <= 1'b1;
            end		
        end		
    end			

    always @(posedge SCK or posedge csb_reset) begin
        if (csb_reset == 1'b1) begin

            addr <= 8'h00;
            rdstb <= 1'b0;
            predata <= 7'b0000000;
            state  <= `COMMAND;
            count  <= 3'b000;
            readmode <= 1'b0;
            writemode <= 1'b0;
            fixed <= 3'b000;
	    pass_thru <= 1'b0;
	    pass_thru_delay <= 1'b0;
	    pre_pass_thru <= 1'b0;
        end else begin

            if (state == `COMMAND) begin
                rdstb <= 1'b0;
                count <= count + 1;
        	if (count == 3'b000) begin
	            writemode <= SDI;
	        end else if (count == 3'b001) begin
	            readmode <= SDI;
	        end else if (count < 3'b101) begin
	            fixed <= {fixed[1:0], SDI}; 
	        end else if (count == 3'b101) begin
		    pre_pass_thru <= SDI;
	        end else if (count == 3'b110) begin
		    pass_thru_delay <= pre_pass_thru;
	        end else if (count == 3'b111) begin
		    if (pre_pass_thru == 1'b1) begin
			state <= `PASSTHRU;
			pre_pass_thru <= 1'b0;
		    end else begin
	                state <= `ADDRESS;
		    end
	        end
            end else if (state == `ADDRESS) begin
	        count <= count + 1;
	        addr <= {addr[6:0], SDI};
	        if (count == 3'b111) begin
	            if (readmode == 1'b1) begin
	            	rdstb <= 1'b1;
	            end
	            state <= `DATA;
		    if (readmode == 1'b1) begin
			rdstb <= 1'b1;
		    end
	        end else begin
	            rdstb <= 1'b0;
	        end
            end else if (state == `DATA) begin
	        predata <= {predata[6:0], SDI};
	        count <= count + 1;
	        if (count == 3'b111) begin
	            if (fixed == 3'b001) begin
	                state <= `COMMAND;
	            end else if (fixed != 3'b000) begin
	                fixed <= fixed - 1;
	                addr <= addr + 1;	
	            end else begin	
	                addr <= addr + 1;	
	            end
		    if (readmode == 1'b1) begin
			rdstb <= 1'b1;
		    end
	        end else begin
	            rdstb <= 1'b0;
	        end
	    end else if (state == `PASSTHRU) begin
		pass_thru <= 1'b1;
            end		
        end		
    end			

endmodule 
`default_nettype wire

module mash_mod
    # (
        parameter WIDTH_MODULUS     = 16,
        parameter ORDER             = 3
    ) (
        input                       clk,
        input                       rst,
        input [WIDTH_MODULUS-1:0]   data_in,
        output [ORDER-1:0]          data_out
    );


    reg [WIDTH_MODULUS-1:0]         accumulator_output[ORDER-1:0];
    reg [WIDTH_MODULUS-1:0]         accumulator_delay[ORDER-1:0];
    reg [4*(ORDER-1)-1:0]           accumulator_carry[ORDER-1:0];
    reg signed [ORDER-1:0]          sum_output[ORDER-2:0];
    reg signed [ORDER-1:0]          sum_minus[ORDER-2:0];
    reg signed [ORDER-1:0]          sum_delay[ORDER-2:0];


    genvar i;
    generate
        for (i = 0; i < ORDER; i = i + 1) begin


            if (i == 0) begin
                always @(posedge rst, posedge clk) begin
                    if (rst) begin
                        accumulator_carry[i][0] <= 0;
                        accumulator_output[i] <= 0;
                        accumulator_delay[i] <= 0;
                    end
                    else begin
                        {accumulator_carry[i][0], accumulator_output[i]} <= data_in + accumulator_output[i];
                        accumulator_delay[i] <= accumulator_output[i];
                    end
                end
            end
            else begin
                always @(posedge rst, posedge clk) begin
                    if (rst) begin
                        accumulator_carry[i][0] <= 0;
                        accumulator_output[i] <= 0;
                        accumulator_delay[i] <= 0;
                    end
                    else begin
                        {accumulator_carry[i][0], accumulator_output[i]} <= accumulator_delay[i-1] + accumulator_output[i];
                        accumulator_delay[i] <= accumulator_output[i];
                    end
                end
            end


            always @(posedge rst, posedge clk) begin
                if (rst) begin
                    accumulator_carry[i][4*(ORDER-1)-1:1] <= 0;
                end
                else begin
                    accumulator_carry[i][4*(ORDER-1)-1:1] <= accumulator_carry[i][4*(ORDER-1)-2:0];
                end
            end


            if (i < ORDER-2) begin
                always @(posedge rst, posedge clk) begin
                    if (rst) begin
                        sum_delay[i] <= 0;
                        sum_minus[i] <= 0;
                        sum_output[i] <= 0;
                    end
                    else begin
                        sum_delay[i] <= sum_output[i+1];
                        sum_minus[i] <= sum_output[i+1] - sum_delay[i];
                        sum_output[i] <= sum_minus[i] + {2'b00, accumulator_carry[i][4*(ORDER-1-i)-1]};
                    end
                end
            end
            else if (i == ORDER-2) begin
                always @(posedge rst, posedge clk) begin
                    if (rst) begin
                        sum_delay[i] <= 0;
                        sum_minus[i] <= 0;
                        sum_output[i] <= 0;
                    end
                    else begin
                        sum_delay[i] <= {2'b00, accumulator_carry[ORDER-1][0]};
                        sum_minus[i] <= {2'b00, accumulator_carry[ORDER-1][0]} - sum_delay[i];
                        sum_output[i] <= sum_minus[i] + {2'b00, accumulator_carry[i][4*(ORDER-1-i)-1]};
                    end
                end
            end
        end
    endgenerate


    assign data_out = sum_output[0];

endmodule

`timescale 1ns / 1ps

module mcp3_ram512x052 (


    input              clk


  , input              wren
  , input        [8:0] wrad
  , input       [51:0] data


  , input              rden
  , input        [8:0] rdad
  , output      [51:0] q

  );

 (* ram_style = "block" *)

  reg    [51:0] ram [0:511];
  reg    [51:0] q_int;

  always @(posedge clk)
   begin
     if ( wren == 1'b1 )
        ram[wrad] <= data[51:0];

     if ( rden == 1'b1)
       begin
          if (( rdad[8:0] != wrad[8:0] ) || ( wren == 1'b0 ))
             q_int[51:0] <= ram[rdad];
          else
             q_int[51:0] <= 52'bx; 
        end
   end  

  assign q[51:0] =  q_int[51:0];

endmodule

module i2c_master( clk, resetn, i2c_baud_clk_l, i2c_baud_clk_h,
                   i2c_sda, i2c_scl, i2c_tx_on, i2c_stop, i2c_start,
                   i2c_rx_on, i2c_ack, i2c_busy, i2c_tx_reg, i2c_rx_reg);

input clk;
input resetn;
input [7:0] i2c_baud_clk_l;
input [7:0] i2c_baud_clk_h;
inout i2c_sda;
output i2c_scl;
input i2c_tx_on;
input i2c_rx_on;
input [7:0] i2c_tx_reg;
output [7:0] i2c_rx_reg;
output i2c_busy;
input i2c_start;
input i2c_stop;
output i2c_ack;

reg [15:0] i2c_clk_cntr;
reg i2c_tick;
reg [7:0] i2c_tx_buf;
reg [3:0] i2c_bit_count;
reg [7:0] i2c_rx_reg;
reg i2c_sda_reg;
reg i2c_ack;
reg i2c_scl;
reg i2c_busy;


wire [15:0] i2c_clk_reg = {i2c_baud_clk_h, i2c_baud_clk_l};

always @(posedge clk or negedge resetn)
begin
    if(~resetn) begin
       i2c_clk_cntr <= 0;
       i2c_tick <= 1'b0;
    end
    else if(i2c_clk_cntr == (i2c_clk_reg-1)) begin
       i2c_clk_cntr <= 0;
       i2c_tick <= 1'b1;
    end
    else begin
       i2c_clk_cntr <= i2c_clk_cntr + 1'b1;
       i2c_tick <= 1'b0;
    end
end

assign i2c_sda = i2c_sda_reg;


always @(posedge clk or negedge resetn)
begin
   if(~resetn) begin
      i2c_scl <= 1'b1;
      i2c_sda_reg <= 1'bz;
      i2c_bit_count <= 4'b0000;
      i2c_tx_buf <= 00;
      i2c_busy <= 1'b0;
      i2c_ack <= 1'b0;
   end
   else if(i2c_tick && i2c_busy && ~(i2c_tx_on || i2c_rx_on))begin
	   i2c_busy <= 1'b0;
      if(i2c_start)
         i2c_scl <= 1'b0;
      else
         i2c_scl <= 1'b1;
   end
   else if(i2c_start && i2c_tick) begin
      i2c_scl <= 1'b1;
      i2c_sda_reg <= 1'b0;
      i2c_busy <= 1'b1;
   end
   else if(i2c_stop && i2c_tick) begin
      i2c_scl <= 1'b1;
      i2c_sda_reg <= 1'b0;
      i2c_busy <= 1'b1;
   end
   else if(i2c_tick && i2c_tx_on && ~i2c_busy)begin  
      if(i2c_tx_reg[7])
         i2c_sda_reg <= 1'bz;
      else
         i2c_sda_reg <= 1'b0;
      i2c_tx_buf <= {i2c_tx_reg[6:0],1'b0};
      i2c_busy <= 1'b1;
      i2c_bit_count <= 4'b0000;
   end
   else if(i2c_tick && i2c_rx_on && ~i2c_busy) begin
      i2c_bit_count <= 4'b0000;
      i2c_busy <= 1'b1;
      i2c_rx_reg[0] <= i2c_sda;
   end




   else if(i2c_tick && i2c_busy ) begin 
      i2c_scl <= ~i2c_scl;
      if(i2c_scl) begin
         i2c_bit_count <= i2c_bit_count + 1'b1;
         if(i2c_bit_count == 4'b0111) begin
            if(i2c_tx_on)
               i2c_sda_reg <= 1'bz;
            else if(i2c_rx_on) 
               i2c_sda_reg <= 1'b0;
         end
         else if(i2c_bit_count == 4'b1000) begin
            i2c_busy <= 1'b0;
            if(i2c_rx_on) begin
               i2c_sda_reg <= 1'bz;

	    end
            else if(i2c_tx_on)
              i2c_ack <= ~i2c_sda;
         end
         else if(i2c_tx_on) begin
            i2c_sda_reg <= i2c_tx_buf[7];
            i2c_tx_buf <= {i2c_tx_buf[6:0],1'b0};
         end
         else if(i2c_rx_on)
         i2c_rx_reg <= {i2c_rx_reg[6:0],i2c_sda};
      end
   end  
end


endmodule

module mul(

    input           clk,
    input           rstn,

    input           ctrl_mdu_fake_gen_flag,

    input           gpr_mdu_mul_data_vld,
    input [63:0]    gpr_mdu_mul_reg1_data,
    input [63:0]    gpr_mdu_mul_reg2_data,

    input [ 2:0]    de_mdu_mul_type,

    output          mdu_wb_mul_vld,
    output[63:0]    mdu_wb_mul_wdata,
    output reg      mdu_wb_mul_fake_vld
);


localparam MUL    = 3'b001;
localparam MULH   = 3'b010;
localparam MULHU  = 3'b011;
localparam MULHSU = 3'b100;
localparam MULW   = 3'b101;


reg vld;
reg vld_1d;
reg vld_2d;
reg vld_3d;
reg vld_4d;


reg [2:0]op;
reg [2:0]op_1d;
reg [2:0]op_2d;
reg [2:0]op_3d;
reg [2:0]op_4d;

reg [63:0]a;
reg [63:0]b;

reg sig;
reg sig_1d;
reg sig_2d;
reg sig_3d;
reg sig_4d;

reg [15:0]dff1_0a;
reg [15:0]dff1_1a;
reg [15:0]dff1_2a;
reg [15:0]dff1_3a;
reg [15:0]dff1_0b;
reg [15:0]dff1_1b;
reg [15:0]dff1_2b;
reg [15:0]dff1_3b;

reg [31:0]mul_0a0b;
reg [31:0]mul_1a1b;
reg [31:0]mul_0a1b;
reg [31:0]mul_1a0b;
reg [31:0]mul_0a2b;
reg [31:0]mul_2a0b;
reg [31:0]mul_1a2b;
reg [31:0]mul_2a1b;
reg [31:0]mul_0a3b;
reg [31:0]mul_3a0b;
reg [31:0]mul_1a3b;
reg [31:0]mul_3a1b;
reg [31:0]mul_2a3b;
reg [31:0]mul_3a2b;
reg [31:0]mul_2a2b;
reg [31:0]mul_3a3b;

reg [15:0]dff2_0a0b;
reg [15:0]dff2_2a2b;
reg [47:0]dff2_ab;
reg [47:0]dff2_op;
reg [31:0]dff2_0a1b; 
reg [31:0]dff2_1a0b;
reg [31:0]dff2_0a2b;
reg [31:0]dff2_2a0b;
reg [31:0]dff2_1a2b;
reg [31:0]dff2_2a1b;
reg [31:0]dff2_0a3b;
reg [31:0]dff2_3a0b;
reg [31:0]dff2_1a3b;
reg [31:0]dff2_3a1b;
reg [31:0]dff2_2a3b;
reg [31:0]dff2_3a2b;

reg [32:0]add1_0a1b_1a0b;
reg [32:0]add1_0a2b_2a0b;
reg [32:0]add1_1a2b_2a1b;
reg [32:0]add1_0a3b_3a0b;
reg [32:0]add1_1a3b_3a1b;
reg [32:0]add1_2a3b_3a2b;

reg [47:0]add2_ab_cd;
reg [47:0]add2_mn_op;
reg [32:0]add2_ef_gh;
reg [32:0]add2_ij_kl;

reg [31:0]dff3_32_final;
reg [31:0]dff3_ab_cd;
reg [48:0]dff3_ef_gh;
reg [15:0]dff3_ij_16_low;
reg [32:0]dff3_ij_kl;
reg [63:0]dff3_mn_op;

reg [48:0]add3_x;
reg [63:0]add3_y;

reg [79:0]add4_final;

reg [127:0]dff_final; 

reg [63:0]wdata;


wire[63:0] multiplier;
wire[63:0] multiplicator;
wire[127:0]comp;











reg [127:0] mul_result ;

always@(posedge clk) begin
    if(gpr_mdu_mul_data_vld)
      mul_result <= gpr_mdu_mul_reg1_data * gpr_mdu_mul_reg2_data ;
end












assign multiplier   = gpr_mdu_mul_reg1_data;
assign multiplicator = gpr_mdu_mul_reg2_data;


always@(posedge clk or negedge rstn)begin
    if(rstn == 1'b0)begin
        mdu_wb_mul_fake_vld <= 1'b0;
    end
    else begin
        mdu_wb_mul_fake_vld <= gpr_mdu_mul_data_vld & ctrl_mdu_fake_gen_flag;
    end
end


always@(*)begin
    vld = gpr_mdu_mul_data_vld & ~ctrl_mdu_fake_gen_flag;
end

always@(posedge clk or negedge rstn)begin
    if(rstn == 1'b0)begin
        vld_1d <= 1'b0;
        vld_2d <= 1'b0;
        vld_3d <= 1'b0;
        vld_4d <= 1'b0;
    end
    else begin
        vld_1d <= vld;
        vld_2d <= vld_1d;
        vld_3d <= vld_2d;
        vld_4d <= vld_3d;
    end
end


assign mdu_wb_mul_vld = vld_4d;





always@(*)begin
    op = de_mdu_mul_type;
end

always@(posedge clk)begin
    op_1d <= op;
end

always@(posedge clk)begin
    op_2d <= op_1d;
end

always@(posedge clk)begin
    op_3d <= op_2d;
end

always@(posedge clk)begin
    op_4d <= op_3d;
end




always@(*)begin
    if(!multiplier[63] | op == MULHU)begin
        a = multiplier;
    end
    else begin
        a = ~(multiplier - 1'b1);
    end 
end

always@(*)begin
    if(!multiplicator[63] | op == MULHU | op == MULHSU)begin  
        b = multiplicator;
    end
    else begin
        b = ~(multiplicator - 1'b1);
    end
end


always@(*)begin
    if(op == MUL | op == MULH)begin
        if(multiplier[63]^multiplicator[63])begin
            sig = 1;
        end
        else begin
            sig = 0;
        end
    end
    else if(op == MULW)begin
        if(multiplier[63]^multiplicator[63])begin
            sig = 1;
        end
        else begin
            sig = 0;
        end
    end
    else if(op == MULHSU)begin
        sig = multiplier[63];
    end        
    else begin
        sig = 0;
    end
end

always@(posedge clk)begin
    sig_1d <= sig;
end

always@(posedge clk)begin
    sig_2d <= sig_1d;
end

always@(posedge clk)begin
    sig_3d <= sig_2d;
end

always@(posedge clk)begin
    sig_4d <= sig_3d;
end



always@(posedge clk)begin
     if(vld)begin
        dff1_0a <= a[15:0];
        dff1_1a <= a[31:16];
        dff1_2a <= a[47:32];
        dff1_3a <= a[63:48];
        dff1_0b <= b[15:0];
        dff1_1b <= b[31:16];
        dff1_2b <= b[47:32];
        dff1_3b <= b[63:48];
    end
end


always@(*)begin     
    mul_0a0b = dff1_0a * dff1_0b;
    mul_1a1b = dff1_1a * dff1_1b;
    mul_0a1b = dff1_0a * dff1_1b;
    mul_1a0b = dff1_1a * dff1_0b;
    mul_0a2b = dff1_0a * dff1_2b;
    mul_2a0b = dff1_2a * dff1_0b;
    mul_1a2b = dff1_1a * dff1_2b;
    mul_2a1b = dff1_2a * dff1_1b;
    mul_0a3b = dff1_0a * dff1_3b;
    mul_3a0b = dff1_3a * dff1_0b;
    mul_1a3b = dff1_1a * dff1_3b;
    mul_3a1b = dff1_3a * dff1_1b;
    mul_2a3b = dff1_2a * dff1_3b;
    mul_3a2b = dff1_3a * dff1_2b;
    mul_2a2b = dff1_2a * dff1_2b;
    mul_3a3b = dff1_3a * dff1_3b;
end


always@(posedge clk)begin
    if(vld_1d)begin
        dff2_0a0b <= mul_0a0b[15:0];
        dff2_2a2b <= mul_2a2b[15:0];
        dff2_ab <= {mul_1a1b,mul_0a0b[31:16]};
        dff2_op <= {mul_3a3b,mul_2a2b[31:16]};
        dff2_0a1b <= mul_0a1b;
        dff2_1a0b <= mul_1a0b;
        dff2_0a2b <= mul_0a2b;
        dff2_2a0b <= mul_2a0b;
        dff2_1a2b <= mul_1a2b;
        dff2_2a1b <= mul_2a1b;
        dff2_0a3b <= mul_0a3b;
        dff2_3a0b <= mul_3a0b;
        dff2_1a3b <= mul_1a3b;
        dff2_3a1b <= mul_3a1b;
        dff2_2a3b <= mul_2a3b;
        dff2_3a2b <= mul_3a2b;
    end
end


always@(*)begin
    add1_0a1b_1a0b = {1'b0,dff2_0a1b} + {1'b0,dff2_1a0b};
    add1_0a2b_2a0b = {1'b0,dff2_0a2b} + {1'b0,dff2_2a0b};
    add1_1a2b_2a1b = {1'b0,dff2_1a2b} + {1'b0,dff2_2a1b};
    add1_0a3b_3a0b = {1'b0,dff2_0a3b} + {1'b0,dff2_3a0b};
    add1_1a3b_3a1b = {1'b0,dff2_1a3b} + {1'b0,dff2_3a1b};
    add1_2a3b_3a2b = {1'b0,dff2_2a3b} + {1'b0,dff2_3a2b};
end


always@(*)begin
    add2_ab_cd = {15'b0,add1_0a1b_1a0b} + dff2_ab;
    add2_ef_gh = {16'b0,add1_0a2b_2a0b[32:16]} + add1_1a2b_2a1b;
    add2_ij_kl = {16'b0,add1_0a3b_3a0b[32:16]} + add1_1a3b_3a1b;
    add2_mn_op = {15'b0,add1_2a3b_3a2b} + dff2_op;
end


always@(posedge clk)begin
    if(vld_2d)begin
        dff3_32_final <= {add2_ab_cd[15:0],dff2_0a0b};
        dff3_ab_cd  <= add2_ab_cd[47:16];
        dff3_ef_gh  <= {add2_ef_gh,add1_0a2b_2a0b[15:0]};
        dff3_ij_16_low <= add1_0a3b_3a0b[15:0];
        dff3_ij_kl  <= add2_ij_kl;
        dff3_mn_op  <= {add2_mn_op,dff2_2a2b};
    end
end


always@(*)begin
    add3_x = dff3_ef_gh + {16'b0,dff3_ab_cd};
    add3_y = dff3_mn_op + {15'b0,dff3_ij_kl};
end



always@(*)begin
    add4_final = {add3_y,dff3_ij_16_low} + {47'b0,add3_x[48:16]};
end


always@(posedge clk)begin
    if(vld_3d)begin
        dff_final <= {add4_final,add3_x[15:0],dff3_32_final};
    end
end


assign comp = ~dff_final + 1'b1; 

always@(*)begin
    if(op_4d == MUL)begin
        if(sig_4d)begin
            wdata = comp[63:0];
        end
        else begin
            wdata = dff_final[63:0];
        end
    end
    else if(op_4d == MULH)begin
        if(sig_4d)begin
            wdata = comp[127:64];
        end
        else begin
            wdata = dff_final[127:64];
        end
    end
    else if(op_4d == MULHU)begin
        wdata = dff_final[127:64];
    end
    else if(op_4d == MULHSU)begin
        if(sig_4d)begin
            wdata = comp[127:64];
        end
        else begin
            wdata = dff_final[127:64];
        end
    end
    else if(op_4d == MULW)begin
        if(sig_4d)begin
            wdata = {{32{comp[31]}},comp[31:0]};
        end
        else begin
            wdata = {{32{dff_final[31]}},dff_final[31:0]};
        end
    end
    else begin
        if(sig_4d)begin
            wdata = {32'b1,comp[31:0]};
        end
        else begin
            wdata = {32'b0,dff_final[31:0]};
        end
    end
end







assign mdu_wb_mul_wdata = wdata;

endmodule

module mac #(
    parameter I_BW        = 8,          
    parameter O_BW        = I_BW * 3,   
    parameter BIAS_BW     = I_BW * 2,   
    parameter NUM_CLASSES = 3           
) (

    input                                           clk_i,
    input                                           rst_n_i,


    input  signed [I_BW - 1: 0]                     data0_i,
    input                                           valid0_i,
    input                                           last0_i,
    output                                          ready0_o,


    input  signed [(NUM_CLASSES * I_BW) - 1 : 0]    data1_w_i,
    input  signed [(NUM_CLASSES * BIAS_BW) - 1 : 0] data1_b_i,
    input                                           valid1_i,
    input                                           last1_i,
    output                                          ready1_o,


    output signed [(NUM_CLASSES * O_BW) - 1 : 0]    data_o,
    output                                          valid_o,
    output                                          last_o,
    input                                           ready_i
);


    genvar i;




    localparam VALID_TIMEOUT_CYCLES         = 8;  
    localparam VALID_TIMEOUT_BW             = $clog2(VALID_TIMEOUT_CYCLES + 1);




    reg valid_q, valid_q2, valid_q3;
    reg last_q, last_q2, last_q3;
    reg ready_q;





    reg signed [(NUM_CLASSES * BIAS_BW) - 1 : 0] data1_b_q, data1_b_q2;
    always @(posedge clk_i) begin
        if (!rst_n_i) begin
            data1_b_q  <= 0;
            data1_b_q2 <= 0;
        end else begin
            data1_b_q  <= data1_b_i;
            data1_b_q2 <= data1_b_q;
        end
    end





    wire signed [I_BW - 1 : 0]    weight_arr [NUM_CLASSES - 1 : 0];
    wire signed [BIAS_BW - 1 : 0] bias_arr   [NUM_CLASSES - 1 : 0];


    for (i = 0; i < NUM_CLASSES; i = i + 1) begin: unpack_inputs
        assign weight_arr[i] = data1_w_i[(i + 1) * I_BW - 1 : i * I_BW];
        assign bias_arr[i]   = data1_b_q2[(i + 1) * BIAS_BW - 1 : i * BIAS_BW];
    end





    reg signed [(I_BW * 2) - 1: 0] mult_arr [NUM_CLASSES - 1 : 0];
    for (i = 0; i < NUM_CLASSES; i = i + 1) begin: fc_multiply
        always @(posedge clk_i) begin
            if (!rst_n_i) begin
                mult_arr[i] <= 'd0;
            end else begin
                mult_arr[i] <= data0_i * weight_arr[i];
            end
        end
    end










    wire valid_timeout;
    reg [VALID_TIMEOUT_BW - 1: 0] valid_timeout_counter;
    always @(posedge clk_i) begin
        if (!rst_n_i) begin
            valid_timeout_counter <= 'd0;
        end else begin
            if (valid0_i) begin  
                valid_timeout_counter <= 'd0;
            end else if (valid_timeout_counter == VALID_TIMEOUT_CYCLES) begin
                valid_timeout_counter <= valid_timeout_counter;
            end else begin
                valid_timeout_counter <= valid_timeout_counter + 'd1;
            end
        end
    end
    assign valid_timeout = (valid_timeout_counter == VALID_TIMEOUT_CYCLES);

    reg signed [O_BW - 1: 0] acc_arr [NUM_CLASSES - 1 : 0];
    for (i = 0; i < NUM_CLASSES; i = i + 1) begin: fc_accumulate
        always @(posedge clk_i) begin
            if (!rst_n_i) begin
                acc_arr[i] <= 'd0;
            end else begin
                if (last_q2 | valid_timeout) begin
                    acc_arr[i] <= 'd0;
                end else if (valid_q) begin
                    acc_arr[i] <= mult_arr[i] + acc_arr[i];
                end else begin
                    acc_arr[i] <= acc_arr[i];
                end
            end
        end
    end




    reg signed [O_BW - 1: 0] add_arr [NUM_CLASSES - 1 : 0];
    for (i = 0; i < NUM_CLASSES; i = i + 1) begin: fc_bias
        always @(posedge clk_i) begin
            if (!rst_n_i) begin
                add_arr[i] <= 'd0;
            end else begin
                add_arr[i] <= acc_arr[i] + bias_arr[i];
            end
        end
    end




    for (i = 0; i < NUM_CLASSES; i = i + 1) begin: pack_output
        assign data_o[(i + 1) * O_BW - 1 : i * O_BW] = add_arr[i];
    end


    always @(posedge clk_i) begin
        if (!rst_n_i) begin
            valid_q  <= 'b0;
            valid_q2 <= 'b0;
            valid_q3 <= 'b0;
            last_q   <= 'b0;
            last_q2  <= 'b0;
            last_q3  <= 'b0;
            ready_q  <= 'b0;
        end else begin
            valid_q  <= valid0_i && valid1_i;
            valid_q2 <= valid_q;
            valid_q3 <= valid_q2;

            last_q   <= last1_i;
            last_q2  <= last_q;
            last_q3  <= last_q2;
            ready_q  <= ready_i;
        end
    end


    assign valid_o  = valid_q3 && last_q3;
    assign last_o   = last_q3;
    assign ready0_o = ready_q;
    assign ready1_o = ready_q;





endmodule

