module tuner(
    input clk, reset,
    input[15:0] frets,
    input e, a, d, g,
    output wire speaker);

    reg [19:0] clkCntE, clkCntA, clkCntD, clkCntG;


    always @ (frets) begin
        case(frets)    
            16'b0000000000000000 : clkCntE = 20'd606722; 
            16'b0000000000000001 : clkCntE = 20'd572672; 
            16'b0000000000000010 : clkCntE = 20'd540541; 
            16'b0000000000000100 : clkCntE = 20'd510204; 
            16'b0000000000001000 : clkCntE = 20'd481556; 
            16'b0000000000010000 : clkCntE = 20'd454545; 
            16'b0000000000100000 : clkCntE = 20'd429037; 
            16'b0000000001000000 : clkCntE = 20'd404957; 
            16'b0000000010000000 : clkCntE = 20'd382234; 
            16'b0000000100000000 : clkCntE = 20'd360776; 
            16'b0000001000000000 : clkCntE = 20'd340530; 
            16'b0000010000000000 : clkCntE = 20'd321419; 
            16'b0000100000000000 : clkCntE = 20'd303380; 
            16'b0001000000000000 : clkCntE = 20'd286352; 
            16'b0010000000000000 : clkCntE = 20'd270270; 
            16'b0100000000000000 : clkCntE = 20'd255102; 
            16'b1000000000000000 : clkCntE = 20'd240790; 
            default: clkCntE = 20'd606722; 
        endcase
    end


    always @ (frets) begin
        case(frets)   
            16'b0000000000000000 : clkCntA = 20'd454545; 
            16'b0000000000000001 : clkCntA = 20'd429037; 
            16'b0000000000000010 : clkCntA = 20'd404957; 
            16'b0000000000000100 : clkCntA = 20'd382234; 
            16'b0000000000001000 : clkCntA = 20'd360776; 
            16'b0000000000010000 : clkCntA = 20'd340530; 
            16'b0000000000100000 : clkCntA = 20'd321419; 
            16'b0000000001000000 : clkCntA = 20'd303380; 
            16'b0000000010000000 : clkCntA = 20'd286352; 
            16'b0000000100000000 : clkCntA = 20'd270270; 
            16'b0000001000000000 : clkCntA = 20'd255102; 
            16'b0000010000000000 : clkCntA = 20'd240790; 
            16'b0000100000000000 : clkCntA = 20'd227273; 
            16'b0001000000000000 : clkCntA = 20'd214519; 
            16'b0010000000000000 : clkCntA = 20'd202478; 
            16'b0100000000000000 : clkCntA = 20'd191110; 
            16'b1000000000000000 : clkCntA = 20'd180388; 
            default: clkCntA = 20'd454545; 
        endcase
    end


    always @ (frets) begin
        case(frets)   
            16'b0000000000000000 : clkCntD = 20'd340530; 
            16'b0000000000000001 : clkCntD = 20'd321419; 
            16'b0000000000000010 : clkCntD = 20'd303380; 
            16'b0000000000000100 : clkCntD = 20'd286352; 
            16'b0000000000001000 : clkCntD = 20'd270270; 
            16'b0000000000010000 : clkCntD = 20'd255102; 
            16'b0000000000100000 : clkCntD = 20'd240790; 
            16'b0000000001000000 : clkCntD = 20'd227273; 
            16'b0000000010000000 : clkCntD = 20'd214519; 
            16'b0000000100000000 : clkCntD = 20'd202478; 
            16'b0000001000000000 : clkCntD = 20'd191110; 
            16'b0000010000000000 : clkCntD = 20'd180388; 
            16'b0000100000000000 : clkCntD = 20'd170265; 
            16'b0001000000000000 : clkCntD = 20'd160705; 
            16'b0010000000000000 : clkCntD = 20'd151685; 
            16'b0100000000000000 : clkCntD = 20'd143172; 
            16'b1000000000000000 : clkCntD = 20'd135139; 
	        default: clkCntD = 20'd340530; 
        endcase
    end


    always @ (frets) begin
        case(frets)   
            16'b0000000000000000 : clkCntG = 20'd255102; 
            16'b0000000000000001 : clkCntG = 20'd240790; 
            16'b0000000000000010 : clkCntG = 20'd227273; 
            16'b0000000000000100 : clkCntG = 20'd214519; 
            16'b0000000000001000 : clkCntG = 20'd202478; 
            16'b0000000000010000 : clkCntG = 20'd191110; 
            16'b0000000000100000 : clkCntG = 20'd180388; 
            16'b0000000001000000 : clkCntG = 20'd170265; 
            16'b0000000010000000 : clkCntG = 20'd160705; 
            16'b0000000100000000 : clkCntG = 20'd151685; 
            16'b0000001000000000 : clkCntG = 20'd143172; 
            16'b0000010000000000 : clkCntG = 20'd135139; 
            16'b0000100000000000 : clkCntG = 20'd127551; 
            16'b0001000000000000 : clkCntG = 20'd120395; 
            16'b0010000000000000 : clkCntG = 20'd113636; 
            16'b0100000000000000 : clkCntG = 20'd107259; 
            16'b1000000000000000 : clkCntG = 20'd101239; 
            default: clkCntG = 20'd255102; 
        endcase
    end


    reg speakerE, speakerA, speakerD, speakerG;
    reg [19:0] counterE, counterA, counterD, counterG;


    always @ (posedge clk) begin
        if (reset == 1'b1) begin
            speakerE = 0;
            counterE = 0;
        end else begin
            if (e == 1) begin
                if (counterE >= clkCntE) begin
                    speakerE <= ~speakerE;
                    counterE <= 0;
                end else begin
                    counterE <= counterE + 1;
                end
            end else begin
                speakerE = 0;
            end
        end
    end


    always @ (posedge clk) begin
        if (reset == 1'b1) begin
            speakerA = 0;
            counterA = 0;
        end else begin
            if (a == 1) begin
                if (counterA >= clkCntA) begin
                    speakerA <= ~speakerA;
                    counterA <= 0;
                end else begin
                    counterA <= counterA + 1;
                end
            end else begin
                speakerA = 0;
            end
        end
    end


    always @ (posedge clk) begin
        if (reset == 1'b1) begin
            speakerD = 0;
            counterD = 0;
        end else begin
            if (d == 1) begin
                if (counterD >= clkCntD) begin
                    speakerD <= ~speakerD;
                    counterD <= 0;
                end else begin
                    counterD <= counterD + 1;
                end
            end else begin
                speakerD = 0;
            end
        end
    end


    always @ (posedge clk) begin
        if (reset == 1'b1) begin
            speakerG = 0;
            counterG = 0;
        end else begin
            if (g == 1) begin
                if (counterG >= clkCntG) begin
                    speakerG <= ~speakerG;
                    counterG <= 0;
                end else begin
                    counterG <= counterG + 1;
                end
            end else begin
                speakerG = 0;
            end
        end
    end


    assign speaker = speakerE + speakerA + speakerD + speakerG;

endmodule

module usb_uart_bridge_ep (
  input clk,
