  localparam PipelineOutState_WaitPipeline = 3;


  assign uart_out_data = uart_out_data_reg;
  assign uart_out_valid = uart_out_valid_reg;



  assign out_ep_req = ( out_ep_req_reg || out_ep_data_avail );

  wire out_granted_data_available;

  assign out_granted_data_available = out_ep_req && out_ep_grant;

  assign out_ep_data_get = ( uart_out_ready || ~uart_out_valid_reg ) && out_ep_data_get_reg;

  reg [7:0] out_stall_data;
  reg       out_stall_valid;


  always @(posedge clk) begin
      if ( reset ) begin
          pipeline_out_state <= PipelineOutState_Idle;
          uart_out_data_reg <= 0;
          uart_out_valid_reg <= 0;
          out_ep_req_reg <= 0;
          out_ep_data_get_reg <= 0;
          out_stall_data <= 0;
          out_stall_valid <= 0;
      end else begin
          case( pipeline_out_state )
              PipelineOutState_Idle: begin

                  if ( out_granted_data_available ) begin

                      out_ep_data_get_reg <= 1;

                      out_ep_req_reg <= 1;

                      pipeline_out_state <= PipelineOutState_WaitData;
                      uart_out_valid_reg <= 0;
                      out_stall_data <= 0;
                      out_stall_valid <= 0;
                  end
              end
              PipelineOutState_WaitData: begin


                  if ( uart_out_ready || ~uart_out_valid_reg ) begin


                      if ( out_stall_valid ) begin
                        uart_out_data_reg <= out_stall_data;
                        uart_out_valid_reg <= 1;
                        out_stall_data <= 0;
                        out_stall_valid <= 0;
                        if ( out_ep_data_avail )
                          pipeline_out_state <= PipelineOutState_PushData;
                        else begin
                          pipeline_out_state <= PipelineOutState_WaitPipeline;
                        end
                      end else begin
                          pipeline_out_state <= PipelineOutState_PushData;
                      end
                  end
              end
              PipelineOutState_PushData: begin

                  if ( uart_out_ready || ~uart_out_valid_reg ) begin

                    uart_out_data_reg <= out_ep_data;
                    uart_out_valid_reg <= 1;
                    if ( ~out_ep_data_avail ) begin

                        out_ep_data_get_reg <= 0;
                        pipeline_out_state <= PipelineOutState_WaitPipeline;
                    end
                  end else begin


                    out_stall_data <= out_ep_data;
                    out_stall_valid <= 1;
                    pipeline_out_state <= PipelineOutState_WaitData;                     
                    if ( ~out_ep_data_avail )
                        out_ep_data_get_reg <= 0;
                  end
              end
              PipelineOutState_WaitPipeline: begin

                  out_ep_req_reg <= 0;
                  if ( uart_out_ready ) begin
                      uart_out_valid_reg <= 0;
                      uart_out_data_reg <= 0;
                      pipeline_out_state <= PipelineOutState_Idle;
                  end

              end

          endcase
      end
  end


  reg       in_ep_req_reg;
  reg       in_ep_data_done_reg;


  reg [1:0] pipeline_in_state;

  localparam PipelineInState_Idle      = 0;
  localparam PipelineInState_WaitData  = 1;
  localparam PipelineInState_CycleData = 2;
  localparam PipelineInState_WaitEP    = 3;


  assign uart_in_ready = ( pipeline_in_state == PipelineInState_CycleData ) && in_ep_data_free;





  assign in_ep_req = ( uart_in_valid && in_ep_data_free) || in_ep_req_reg;


  wire in_granted_in_valid = in_ep_grant && uart_in_valid;



  assign in_ep_data_put = ( pipeline_in_state == PipelineInState_CycleData ) && uart_in_valid && in_ep_data_free;

  assign in_ep_data_done = in_ep_data_done_reg;

  assign in_ep_data = uart_in_data;




  reg [TimeoutWidth:0] in_ep_timeout;


  always @(posedge clk) begin
      if ( reset ) begin
          pipeline_in_state <= PipelineInState_Idle;
          in_ep_req_reg <= 0;
          in_ep_data_done_reg <= 0;
      end else begin
          case( pipeline_in_state )
              PipelineInState_Idle: begin
                  in_ep_data_done_reg <= 0;
                  if ( in_granted_in_valid && in_ep_data_free ) begin


                      in_ep_req_reg <= 1;
                      pipeline_in_state <= PipelineInState_CycleData;
                  end
              end
              PipelineInState_CycleData: begin
                  if  (uart_in_valid ) begin
                      if ( ~in_ep_data_free ) begin

                        pipeline_in_state <= PipelineInState_Idle;

                        in_ep_req_reg <= 0;
                      end
                  end else begin


                      in_ep_timeout <= 0;
                      pipeline_in_state <= PipelineInState_WaitData;
                 end
              end
              PipelineInState_WaitData: begin
                  in_ep_timeout <= in_ep_timeout + 1;
                  if ( uart_in_valid ) begin
                      pipeline_in_state <= PipelineInState_CycleData;                
                  end else begin

                        if ( in_ep_timeout[ TimeoutWidth ] ) begin
                            in_ep_data_done_reg <= 1;
                            pipeline_in_state <= PipelineInState_WaitEP;
                        end
                  end
              end

              PipelineInState_WaitEP: begin

                  in_ep_data_done_reg <= 0;


                  pipeline_in_state <= PipelineInState_Idle;

                  in_ep_req_reg <= 0;
              end
          endcase
      end
  end

  assign debug = { in_ep_data_free, in_ep_data_done, pipeline_in_state[ 1 ], pipeline_in_state[ 0 ] };  

endmodule

`timescale 1ns/100ps


module util_axis_tiny_fifo #(
    parameter depth = 4,
    parameter width = 8
  )
  (

    input                   aclk,
    input                   arstn,

    output [width-1:0]  m_axis_tdata,
    output              m_axis_tvalid,
    input               m_axis_tready,

    input  [width-1:0]  s_axis_tdata,
    input               s_axis_tvalid,
    output              s_axis_tready
  );


  reg [clogb2(depth):0] index;
  reg [clogb2(depth):0] index_shift;
  reg [clogb2(depth):0] index_check;


  reg [width-1:0] reg_data_buffer[depth-1:0];
  reg [depth-1:0] reg_valid_buffer;


  assign s_axis_tready = ~&reg_valid_buffer || m_axis_tready;


  assign m_axis_tdata  = reg_data_buffer[0];
  assign m_axis_tvalid = reg_valid_buffer[0];


  always @(posedge aclk) begin
    if(arstn == 1'b0) begin
      reg_valid_buffer <= 0;

      for(index = 0; index < depth; index = index + 1) begin
        reg_data_buffer[index] <= 0;
      end
    end else begin

      reg_data_buffer[depth-1]  <= (~&reg_valid_buffer || m_axis_tready ? (s_axis_tvalid ? s_axis_tdata : 0) : reg_data_buffer[depth-1]);
      reg_valid_buffer[depth-1] <= (~&reg_valid_buffer || m_axis_tready ? s_axis_tvalid : reg_valid_buffer[depth-1]);



      for(index_shift = 1; index_shift < depth; index_shift = index_shift + 1) begin
        for(index_check = 0; index_check < index_shift; index_check = index_check + 1) begin
          if((m_axis_tready == 1'b1) || (reg_valid_buffer[index_check] == 1'b0)) begin
            reg_data_buffer[index_shift-1]  <= reg_data_buffer[index_shift];
            reg_valid_buffer[index_shift-1] <= reg_valid_buffer[index_shift];
          end
        end
      end
    end
  end


  function integer clogb2;
    input [31:0] value;
    begin
        value = value - 1;
        for (clogb2 = 0; value > 0; clogb2 = clogb2 + 1) begin
            value = value >> 1;
        end
    end
  endfunction

endmodule

module xc_malu_mul (

input  wire [31:0]  rs1             ,
input  wire [31:0]  rs2             ,

input  wire [ 5:0]  count           ,
input  wire [63:0]  acc             ,
input  wire [31:0]  arg_0           ,

input  wire         carryless       ,

input  wire         pw_32           , 
input  wire         pw_16           , 
input  wire         pw_8            , 
input  wire         pw_4            , 
input  wire         pw_2            , 

input  wire         lhs_sign        ,
input  wire         rhs_sign        ,

output wire [31:0]  padd_lhs        , 
output wire [31:0]  padd_rhs        , 
output wire         padd_sub        , 
output wire         padd_cin        , 
output wire         padd_cen        , 

input  wire [32:0]  padd_cout       ,
input  wire [31:0]  padd_result     ,

output wire [63:0]  n_acc           ,
output wire [31:0]  n_arg_0         ,
output wire         ready           

);

assign ready             = count == {pw_32, pw_16, pw_8, pw_4, pw_2,1'b0};

wire          add_en     = arg_0[0];

wire          sub_last   = rs2[31] && count == 31 && rhs_sign && |rs1;

wire [32:0]   add_lhs    = {lhs_sign && acc[63], acc[63:32]};
wire [32:0]   add_rhs    = add_en ? {lhs_sign && rs1[31], rs1} : 0 ;

assign        padd_lhs   = add_lhs[31:0];
assign        padd_rhs   = add_rhs[31:0];
assign        padd_sub   = sub_last;

assign        padd_cin   = 1'b0;
assign        padd_cen   = !carryless;

wire          add_32     = carryless ? 1'b0 :
                           add_lhs[32] + 
                           add_rhs[32] +
                           sub_last    + padd_cout[31];

wire   [32:0] add_result = {add_32, padd_result};

assign n_acc             = {add_result, acc[31:1]};

assign n_arg_0           = {1'b0, arg_0[31:1]};

endmodule

