module ic_master_read_burst (
    iClk,
    iReset_n,

    iStart,
    iRead_data_valid,
    iWait_request,
    iFF_almost_full,
    HC_ff0_wait_request,
    R2Y_waitrequest,

    iStart_read_address,
    iLength,
    iRead_data,


    oRead,
    oRead_address,
    oFF_write_request,
    oBurst_length,
    oWrite_data
);

  parameter BURST_LENGTH = 8'd64;
  parameter ADDRESS_INC = 4;
  localparam BURST_ADDRESS_INC = (BURST_LENGTH * ADDRESS_INC);



  input iClk, iReset_n;

  input iStart, iRead_data_valid, iWait_request, iFF_almost_full;
  input HC_ff0_wait_request, R2Y_waitrequest;
  input [31:0] iStart_read_address, iLength;
  input [31:0] iRead_data;

  output oRead;
  output oFF_write_request;
  output [7:0] oBurst_length;
  output [31:0] oRead_address;
  output [31:0] oWrite_data;




  wire read_data_valid;




  reg oRead, oFF_write_request;
  reg [1:0] state;
  reg [7:0] burst_count;
  reg [31:0] end_read_address, oRead_address, oWrite_data;




  assign oBurst_length   = BURST_LENGTH;
  assign read_data_valid = iRead_data_valid && (oRead_address <= end_read_address);


  always @(posedge iClk) begin
    if (~iReset_n) begin
      oWrite_data <= 32'h0;
      oFF_write_request <= 1'b0;
    end else begin
      oWrite_data <= read_data_valid ? iRead_data : oWrite_data;
      oFF_write_request <= read_data_valid;
    end
  end


  always @(posedge iClk) begin
    if (~iReset_n) begin
      oRead    <= 1'b0;
      oRead_address   <= 32'h0;
      burst_count   <= 8'h0;
      end_read_address  <= 32'h0;
      state    <= 2'h0;
    end else
      case (state)

        2'h0:
        if (iStart) begin
          oRead    <= 1'b1;
          oRead_address   <= iStart_read_address;
          end_read_address  <= iStart_read_address + iLength - ADDRESS_INC;
          state    <= 2'h1;
        end



        2'h1: begin
          if (~iWait_request) begin
            oRead <= 1'b0;
            if (burst_count == BURST_LENGTH) begin
              oRead_address <= oRead_address + BURST_ADDRESS_INC;
              burst_count <= 8'h0;
              state <= 2'h2;
            end
          end
          if (iRead_data_valid) burst_count <= burst_count + 1'b1;
        end


        2'h2: begin
          if (oRead_address > end_read_address) state <= 2'h3;
          else if (~iFF_almost_full && ~(HC_ff0_wait_request || R2Y_waitrequest)) begin
            oRead <= 1'b1;
            state <= 2'h1;
          end
        end


        2'h3: begin
          oRead    <= 1'b0;
          oRead_address   <= 32'h0;
          end_read_address  <= 32'h1;
          state    <= 2'h0;
        end

        default: ;
      endcase
  end

endmodule

module JC_block (
    jmp_loc,
    pc_mux_sel,
    current_address,
    jmp_address_pm,
    op,
    flag_ex,
    interrupt,
    clk,
    reset
);

  output [15:0] jmp_loc;
  output pc_mux_sel;

  input [15:0] current_address, jmp_address_pm;
  input [5:0] op;
  input [1:0] flag_ex;
  input interrupt, clk, reset;

  wire [15:0] address_mux, jmp_address;
  wire [15:0] address_prv_temp;
  wire [1:0] flag_current, flag_mux;
  wire [1:0] flag_prv_temp;
  wire jz, jnz, jv, jnv, jmp, ret, pc_mux_sel_jz, pc_mux_sel_jnz, pc_mux_sel_jv, pc_mux_sel_jnv;
  wire int_ff1_temp, int_ff2_temp;

  reg [15:0] address_prv;
  reg [ 1:0] flag_prv;
  reg int_ff1, int_ff2;

  assign jz = (~op[5]) & (op[4]) & (op[3]) & (op[2]) & (op[1]) & (~op[0]);
  assign jnz = (~op[5]) & (op[4]) & (op[3]) & (op[2]) & (op[1]) & (op[0]);
  assign jv = (~op[5]) & (op[4]) & (op[3]) & (op[2]) & (~op[1]) & (~op[0]);
  assign jnv = (~op[5]) & (op[4]) & (op[3]) & (op[2]) & (~op[1]) & (op[0]);
  assign jmp = (~op[5]) & (op[4]) & (op[3]) & (~op[2]) & (~op[1]) & (~op[0]);
  assign ret = (~op[5]) & (op[4]) & (~op[3]) & (~op[2]) & (~op[1]) & (~op[0]);

  assign pc_mux_sel_jz = (flag_current[1]) & jz;
  assign pc_mux_sel_jnz = (~flag_current[1]) & jnz;
  assign pc_mux_sel_jv = (flag_current[0]) & jv;
  assign pc_mux_sel_jnv = (~flag_current[0]) & jnv;

  assign pc_mux_sel = pc_mux_sel_jz | pc_mux_sel_jnz |pc_mux_sel_jv |pc_mux_sel_jnv | jmp | int_ff1 | ret;

  assign flag_current = (ret == 1'b1) ? flag_prv : flag_ex;
  assign flag_mux = (int_ff2 == 1'b1) ? flag_ex : flag_prv;

  assign address_mux = (interrupt == 1'b1) ? (current_address + 16'h0001) : address_prv;
  assign jmp_address = (int_ff1 == 1'b1) ? 16'hF000 : jmp_address_pm;
  assign jmp_loc = (ret == 1'b1) ? address_prv : jmp_address;

  assign flag_prv_temp = (reset == 1'b1) ? flag_mux : 2'b0;
  assign int_ff1_temp = (reset == 1'b1) ? interrupt : 1'b0;
  assign int_ff2_temp = (reset == 1'b1) ? int_ff1 : 1'b0;
  assign address_prv_temp = (reset == 1'b1) ? address_mux : 16'b0;

  always @(posedge clk) begin
    flag_prv <= flag_prv_temp;
    int_ff1 <= int_ff1_temp;
    int_ff2 <= int_ff2_temp;
    address_prv <= address_prv_temp;
  end

endmodule

module modify_packet (
    input rst_n,
    input clk,

    input       gmii_dv_i,
    input [7:0] gmii_data_i,
    input       gmii_er_i,

    output reg [ 7:0] gmii_data_o,
    output reg        gmii_en_o,
    output reg        gmii_er_o,
    input      [15:0] local_time,
    output reg [31:0] cnt_pkt
);



  reg [ 2:0] state_modify;
  reg [ 3:0] cnt_pkt_8B;
  reg [15:0] local_time_reg;
  localparam    IDLE_S              = 3'd0,
              WAIT_PKT_HEAD_S     = 3'd1,
              FAKE_PTP_PARSER_S   = 3'd2,
              FAKE_PTP_TPEY_S     = 3'd3,
              ADD_MSEND_ST_S      = 3'd4,
              ADD_SSEND_ST_S      = 3'd5,
              WAIT_TAIL_S         = 3'd6;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      gmii_er_o      <= 1'b0;
      gmii_data_o    <= 8'b0;
      gmii_en_o      <= 1'b0;
      cnt_pkt        <= 32'b0;
      cnt_pkt_8B     <= 4'b0;
      local_time_reg <= 16'b0;
      state_modify   <= IDLE_S;
    end else begin
      gmii_er_o   <= gmii_er_i;
      gmii_data_o <= gmii_data_i;
      gmii_en_o   <= gmii_dv_i;

      case (state_modify)
        IDLE_S: begin
          if (gmii_dv_i == 1'b1) begin
            local_time_reg <= local_time;
            cnt_pkt        <= cnt_pkt + 32'd1;
            state_modify   <= WAIT_PKT_HEAD_S;
          end else begin
            state_modify <= IDLE_S;
          end
        end
        WAIT_PKT_HEAD_S: begin
          if (gmii_data_i[7:0] == 8'hd5) begin
            cnt_pkt_8B   <= 4'b0;
            state_modify <= FAKE_PTP_PARSER_S;
          end else begin
            state_modify <= WAIT_PKT_HEAD_S;
          end
        end
        FAKE_PTP_PARSER_S: begin

          cnt_pkt_8B <= 4'd1 + cnt_pkt_8B;
          if (gmii_data_i[7:0] == {4'b0, cnt_pkt_8B}) begin

            if (cnt_pkt_8B == 4'd5) state_modify <= FAKE_PTP_TPEY_S;
          end else  
            state_modify <= WAIT_TAIL_S;
        end
        FAKE_PTP_TPEY_S: begin





          state_modify <= WAIT_TAIL_S;
          if (gmii_data_i[1:0] == 2'd0) begin
            cnt_pkt_8B   <= 4'b0;
            state_modify <= ADD_MSEND_ST_S;
          end else if (gmii_data_i[1:0] == 2'd1) begin
            cnt_pkt_8B   <= 4'b0;
            state_modify <= ADD_SSEND_ST_S;
          end

          gmii_data_o[2:0] <= gmii_data_i[2:0] + 3'd1;

        end
        ADD_MSEND_ST_S: begin

          cnt_pkt_8B <= 4'd1 + cnt_pkt_8B;
          gmii_data_o         <= (cnt_pkt_8B[1:0] == 2'd1)? local_time_reg[15:8]:
                                (cnt_pkt_8B[1:0] == 2'd2)? local_time_reg[7:0]: 
                                gmii_data_i[7:0];

          if (cnt_pkt_8B == 4'd2) state_modify <= WAIT_TAIL_S;
        end
        ADD_SSEND_ST_S: begin

          cnt_pkt_8B <= 4'd1 + cnt_pkt_8B;
          gmii_data_o         <= (cnt_pkt_8B[2:0] == 3'd5)? local_time_reg[15:8]:
                                (cnt_pkt_8B[2:0] == 3'd6)? local_time_reg[7:0]: 
                                gmii_data_i[7:0];

          if (cnt_pkt_8B == 4'd6) state_modify <= WAIT_TAIL_S;
        end
        WAIT_TAIL_S: begin
          if (gmii_dv_i == 1'b0) begin  
            state_modify <= IDLE_S;
          end else begin
            state_modify <= WAIT_TAIL_S;
          end
        end
        default: begin
          state_modify <= IDLE_S;
        end
      endcase

    end
  end


endmodule

module opcode_dect (
    clk,
    rst_n,
    din,
    din_vld,

    dout_vld,
    dout
);


  parameter DOUT_W = 8;
  parameter DIN_W = 4;


  input clk;
  input rst_n;
  input [DIN_W-1:0] din;
  input din_vld;

  wire [DIN_W-1:0] din;
  wire             din_vld;

  output [DOUT_W-1:0] dout;
  output dout_vld;


  reg  [DOUT_W-1:0] dout;
  reg               dout_vld;


  reg  [     2-1:0] cnt0;
  wire              add_cnt0;
  wire              end_cnt0;

  reg  [     2-1:0] cnt1;
  wire              add_cnt1;
  wire              end_cnt1;

  reg  [      11:0] din_tmp;
  wire [      15:0] din_top;
  reg               flag;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      cnt0 <= 0;
    end else if (add_cnt0) begin
      if (end_cnt0) cnt0 <= 0;
      else cnt0 <= cnt0 + 1;
    end
  end

  assign add_cnt0 = flag && din_vld;
  assign end_cnt0 = add_cnt0 && cnt0 == 2 - 1;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      cnt1 <= 0;
    end else if (add_cnt1) begin
      if (end_cnt1) cnt1 <= 0;
      else cnt1 <= cnt1 + 1;
    end
  end

  assign add_cnt1 = end_cnt0;
  assign end_cnt1 = add_cnt1 && cnt1 == 2 - 1;

  assign din_top  = {din_tmp[11:0], din} == 16'h55d5;
  always @(posedge clk or negedge rst_n) begin
    if (rst_n == 1'b0) begin
      flag <= 0;
    end else if (din_vld && flag == 0 && din_top) begin
      flag <= 1;
    end else if (end_cnt1) begin
      flag <= 0;
    end
  end

  always @(posedge clk or negedge rst_n) begin
    if (rst_n == 1'b0) begin
      din_tmp <= 0;
    end else if (din_vld && flag == 0) begin
      din_tmp <= {din_tmp[7:0], din};
    end
  end

  always @(posedge clk or negedge rst_n) begin
    if (rst_n == 1'b0) begin
      dout <= 0;
    end else if (din_vld) begin
      dout <= {dout[3:0], din};
    end
  end

  always @(posedge clk or negedge rst_n) begin
    if (rst_n == 1'b0) begin
      dout_vld <= 1'b0;
    end else if (end_cnt0) begin
      dout_vld <= 1'b1;
    end else begin
      dout_vld <= 1'b0;
    end
  end
endmodule

module rcn_fifo_async (
    input rst_in,
    input clk_in,
    input clk_out,

    input [68:0] rcn_in,
    input push,
    output full,

    output [68:0] rcn_out,
    input pop,
    output empty
);
  parameter DEPTH = 16;  

  reg [1:0] cross_in;
  reg [5:0] head_in;
  reg [5:0] head_snapshot;
  reg [5:0] tail_in;

  reg [1:0] cross_out;
  reg [5:0] head_out;
  reg [5:0] tail_out;
  reg [5:0] tail_snapshot;

  always @(posedge clk_in) cross_in <= cross_out;

  always @(posedge clk_out or posedge rst_in)
    if (rst_in) cross_out <= 2'b00;
    else
      case (cross_in)
        2'b00:   cross_out <= 2'b01;
        2'b01:   cross_out <= 2'b11;
        2'b11:   cross_out <= 2'b10;
        default: cross_out <= 2'b00;
      endcase

  wire [5:0] head_in_next = (head_in == (DEPTH - 1)) ? 6'd0 : head_in + 6'd1;
  wire fifo_full = (head_in_next == tail_in);

  always @(posedge clk_in or posedge rst_in)
    if (rst_in) begin
      head_in <= 6'd0;
      head_snapshot <= 6'd0;
      tail_in <= 6'd0;
    end else begin
      if (push) head_in <= head_in_next;

      case (cross_in)
        2'b01: head_snapshot <= head_in;
        2'b10: tail_in <= tail_snapshot;
      endcase
    end

  wire [5:0] tail_out_next = (tail_out == (DEPTH - 1)) ? 6'd0 : tail_out + 6'd1;
  wire fifo_empty = (tail_out == head_out);

  always @(posedge clk_out or posedge rst_in)
    if (rst_in) begin
      head_out <= 6'd0;
      tail_out <= 6'd0;
      tail_snapshot <= 6'd0;
    end else begin
      if (pop) tail_out <= tail_out_next;

      case (cross_out)
        2'b01: tail_snapshot <= tail_out;
        2'b10: head_out <= head_snapshot;
      endcase
    end

  reg [67:0] fifo[(DEPTH - 1):0];

  always @(posedge clk_in) if (push) fifo[head_in] <= rcn_in[67:0];

  assign full = fifo_full;
  assign empty = fifo_empty;

  assign rcn_out = {!fifo_empty, fifo[tail_out]};

endmodule

module pipeline_processor (
    input wire clk,
    input wire rst,
    input wire [3:0] data_in,
    output reg [3:0] data_out
);
    reg [3:0] stage1_reg;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            stage1_reg <= 4'b0000;
            data_out <= 4'b0000;
        end else begin
            stage1_reg <= data_in + 1; 
            data_out <= stage1_reg * 2; 
        end
    end
endmodule

module ALU_32bit (  
    input [31:0] A,  
    input [31:0] B,  
    input [2:0] op_select,  
    output reg [31:0] result,  
    output reg zero_flag  
);  
    always @(*) begin  
        case (op_select)  
            3'b000: result = A + B; 
            3'b001: result = A - B; 
            3'b010: result = A & B; 
            3'b011: result = A | B; 
            3'b100: result = A ^ B; 
            default: result = 32'b0;  
        endcase  
        zero_flag = (result == 32'b0);  
    end  
endmodule

module ARQ_System(  
    input clk,  
    input rst,  
    input [7:0] data_in,  
    input error_in,  
    output reg [7:0] data_out,  
    output reg ack  
);  
    reg [7:0] data_reg;  
    reg error_detected;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            data_reg <= 8'b0;  
            error_detected <= 1'b0;  
            ack <= 1'b0;  
        end else begin  
            data_reg <= data_in;  
            error_detected <= error_in;  
            if (!error_detected) begin  
                data_out <= data_reg;  
                ack <= 1'b1;  
            end else begin  
                ack <= 1'b0;  
            end  
        end  
    end  
endmodule

module ARQ_System(
    input clk,
    input reset,
    input [7:0] data_in,
    input ack_nack,
    output reg [7:0] data_out,
    output reg resend
);
    reg [7:0] data_buffer;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            data_out <= 8'b0;
            data_buffer <= 8'b0;
            resend <= 1'b0;
        end else begin
            data_buffer <= data_in; 
            if (ack_nack) begin 
                data_out <= data_buffer; 
                resend <= 1'b0; 
            end else begin 
                resend <= 1'b1; 
            end
        end
    end
endmodule

