    parameter signed [15:0] a2 = 16'h1C2D; 
    parameter signed [15:0] b1 = 16'h1E2F; 
    parameter signed [15:0] b2 = 16'h2031; 

    reg signed [15:0] y_n_1; 
    reg signed [15:0] y_n_2; 

