		casex ({aluOp, funct})
		  8'b00xxxxxx: aluCtr = 'b0010;
		  8'b01xxxxxx: aluCtr = 'b0110;
		  8'b10100000: aluCtr = 'b0010;
		  8'b10100010: aluCtr = 'b0110;
		  8'b10100100: aluCtr = 'b0000;
		  8'b10100101: aluCtr = 'b0001;
		  8'b10101010: aluCtr = 'b0111;
		endcase

