module encoder(
input wire [2:0] B,
output reg [2:0] Vp
); 

always @(B) begin
    case(B)
    3'b000 : begin
      Vp <= 3'b000;
    end
    3'b001 : begin
      Vp <= 3'b001;
    end
    3'b010 : begin
      Vp <= 3'b001;
    end
    3'b011 : begin
      Vp <= 3'b011;
    end
    3'b100 : begin
      Vp <= 3'b100;
    end
    3'b101 : begin
      Vp <= 3'b101;
    end
    3'b110 : begin
      Vp <= 3'b110;
    end
    3'b111 : begin
      Vp <= 3'b111;
    end
    default : begin
      Vp <= 3'b000;
    end
    endcase
  end
endmodule

