    output reg [7:0] l_s_typeE,
    output reg [1:0] mfhi_loE,
    output reg [1:0] reg_dstE,		
    output reg alu_imm_selE,	
    output reg mem_read_enE,	
    output reg mem_write_enE,	
    output reg reg_write_enE,	
