parameter IR_EMITTER_GPIO_DIR_REG_ADR_H       = 8'h13;  











assign IR_Emitter_Interrupt_o                 = IR_Emitter_Interrupt & IR_Emitter_Interrupt_Enable;




assign command_reg_we_dcd                     = (RegAddr_i_1ff == IR_EMITTER_COMMAND_REG_ADR)         & RegWr_En_i;
assign control_reg_we_dcd                     = (RegAddr_i_1ff == IR_EMITTER_CONTROL_REG_ADR)         & RegWr_En_i;

assign IR_Emitter_Carrier_Cycle_Len_L_we_dcd  = (RegAddr_i_1ff == IR_EMITTER_CARRIER_CYCLE_LEN_ADR_L) & RegWr_En_i;
assign IR_Emitter_Carrier_Cycle_Len_H_we_dcd  = (RegAddr_i_1ff == IR_EMITTER_CARRIER_CYCLE_LEN_ADR_H) & RegWr_En_i;

assign IR_Emitter_Carrier_Duty_Len_L_we_dcd   = (RegAddr_i_1ff == IR_EMITTER_CARRIER_DUTY_LEN_ADR_L)  & RegWr_En_i;
assign IR_Emitter_Carrier_Duty_Len_H_we_dcd   = (RegAddr_i_1ff == IR_EMITTER_CARRIER_DUTY_LEN_ADR_H)  & RegWr_En_i;

assign IR_Emitter_MemRd_Start_L_we_dcd        = (RegAddr_i_1ff == IR_EMITTER_MEM_READ_START_ADR_L)    & RegWr_En_i;
assign IR_Emitter_MemRd_Start_H_we_dcd        = (RegAddr_i_1ff == IR_EMITTER_MEM_READ_START_ADR_H)    & RegWr_En_i;

assign IR_Emitter_MemRd_Stop_L_we_dcd         = (RegAddr_i_1ff == IR_EMITTER_MEM_READ_STOP_ADR_L)     & RegWr_En_i;
assign IR_Emitter_MemRd_Stop_H_we_dcd         = (RegAddr_i_1ff == IR_EMITTER_MEM_READ_STOP_ADR_H)     & RegWr_En_i;

assign IR_Emitter_MemAddr_Reg_L_we_dcd        = (RegAddr_i_1ff == IR_EMITTER_MEM_ADDR_REG_ADR_L)      & RegWr_En_i;

assign IR_Emitter_Gpio_Port_Reg_L_we_dcd      = (RegAddr_i_1ff == IR_EMITTER_GPIO_PORT_REG_ADR_L)     & RegWr_En_i;
assign IR_Emitter_Gpio_Dir_Reg_L_we_dcd       = (RegAddr_i_1ff == IR_EMITTER_GPIO_DIR_REG_ADR_L)      & RegWr_En_i;




always @(
        IR_Emitter_Run_Modulator_o      or
        IR_Emitter_Mode_Modulator_o     or
        IR_Emitter_Busy_Modulator_i     or
		IR_LED_Gpio_Polarity_o          or
		IR_LED_Gpio_o                   or
        IR_Emitter_Carrier_Cycle_Len_o  or
        IR_Emitter_Carrier_Duty_Len_o   or
        IR_Emitter_MemRd_Start_o        or
        IR_Emitter_MemRd_Stop_o         or
        IR_Emitter_MemAddr_Reg_o        or
        IR_Emitter_Gpio_Port_i          or
        IR_Emitter_Gpio_Dir_o           or
        IR_Emitter_Interrupt            or
        IR_Emitter_Interrupt_Enable     or
		RegAddr_i_1ff                   or
		RegData_o_comb
        )
begin
    case(RegAddr_i_1ff)
    DEVICE_ID_ADR_L:                    RegData_o_comb <=  DEVICE_ID_NUM_L;
    DEVICE_ID_ADR_H:                    RegData_o_comb <=  DEVICE_ID_NUM_H;

    DEVICE_REVISION_ADR_L:              RegData_o_comb <=  DEVICE_REV_NUM_L;
    DEVICE_REVISION_ADR_H:              RegData_o_comb <=  DEVICE_REV_NUM_H;

    IR_EMITTER_COMMAND_REG_ADR:         RegData_o_comb <= {3'h0, IR_Emitter_Busy_Modulator_i, 3'h0, IR_Emitter_Run_Modulator_o};
    IR_EMITTER_CONTROL_REG_ADR:         RegData_o_comb <= {2'h0, IR_Emitter_Interrupt_Enable, 
			                                                     IR_Emitter_Interrupt, 
																 IR_LED_Gpio_Polarity_o, 
																 IR_LED_Gpio_o, 
																 IR_Emitter_Mode_Modulator_o};

    IR_EMITTER_CARRIER_CYCLE_LEN_ADR_L: RegData_o_comb <= IR_Emitter_Carrier_Cycle_Len_o[HOST_DATA_IN_BITS-1:0];
    IR_EMITTER_CARRIER_CYCLE_LEN_ADR_H: RegData_o_comb <= IR_Emitter_Carrier_Cycle_Len_o[CARRIER_CYCLE_BITS-1:HOST_DATA_IN_BITS];

    IR_EMITTER_CARRIER_DUTY_LEN_ADR_L:  RegData_o_comb <= IR_Emitter_Carrier_Duty_Len_o [HOST_DATA_IN_BITS-1:0];
    IR_EMITTER_CARRIER_DUTY_LEN_ADR_H:  RegData_o_comb <= IR_Emitter_Carrier_Duty_Len_o [CARRIER_DUTY_BITS-1:HOST_DATA_IN_BITS];

    IR_EMITTER_MEM_READ_START_ADR_L:    RegData_o_comb <= IR_Emitter_MemRd_Start_o[HOST_DATA_IN_BITS-1:0];
    IR_EMITTER_MEM_READ_START_ADR_H:    RegData_o_comb <= IR_Emitter_MemRd_Start_o[MEM_ADR_BUS_BITS-1:HOST_DATA_IN_BITS];

    IR_EMITTER_MEM_READ_STOP_ADR_L:     RegData_o_comb <= IR_Emitter_MemRd_Stop_o[HOST_DATA_IN_BITS-1:0];
    IR_EMITTER_MEM_READ_STOP_ADR_H:     RegData_o_comb <= IR_Emitter_MemRd_Stop_o[MEM_ADR_BUS_BITS-1:HOST_DATA_IN_BITS];

    IR_EMITTER_MEM_ADDR_REG_ADR_L:      RegData_o_comb <= {2'h0, IR_Emitter_MemAddr_Reg_o[MEM_ADR_BUS_BITS-HOST_ADR_IN_BITS:0]};

    IR_EMITTER_GPIO_PORT_REG_ADR_L:     RegData_o_comb <= IR_Emitter_Gpio_Port_i[HOST_DATA_IN_BITS-1:0];
    IR_EMITTER_GPIO_DIR_REG_ADR_L:      RegData_o_comb <= IR_Emitter_Gpio_Dir_o[HOST_DATA_IN_BITS-1:0];
	default:                            RegData_o_comb <=  8'h0;
	endcase
end



always @(posedge Clock_i or posedge Reset_i) 
begin
    if (Reset_i)
    begin

        RegAddr_i_1ff                      <=  0;

        RegData_o                          <=  0;

        IR_Emitter_Run_Modulator_o         <=  1'b0;
        IR_Emitter_Mode_Modulator_o        <=  2'h0;

        IR_Emitter_Carrier_Cycle_Len_o     <=  0;
        IR_Emitter_Carrier_Duty_Len_o      <=  0;

        IR_Emitter_MemRd_Start_o           <=  0;
        IR_Emitter_MemRd_Stop_o            <=  0;

		IR_Emitter_MemAddr_Reg_o           <=  0;

        IR_LED_Gpio_Polarity_o             <=  1'b1;
        IR_LED_Gpio_o                      <=  1'b0;

        IR_Emitter_Gpio_Port_o             <=  GPIO_PORT_VALUE;
        IR_Emitter_Gpio_Dir_o              <=  GPIO_DIR_VALUE;

        IR_Emitter_Busy_Modulator_i_1ff    <=  1'b0;

        IR_Emitter_Interrupt               <=  1'b0;
        IR_Emitter_Interrupt_Enable        <=  1'b0;

    end
    else 
    begin  

        RegAddr_i_1ff                      <= RegAddr_i;
        RegData_o                          <= RegData_o_comb;

        IR_Emitter_Run_Modulator_o         <= command_reg_we_dcd && RegData_i[0];

        if (control_reg_we_dcd)
		begin
            IR_Emitter_Mode_Modulator_o    <= RegData_i[1:0];
            IR_LED_Gpio_o                  <= RegData_i[2];
            IR_LED_Gpio_Polarity_o         <= RegData_i[3];
            IR_Emitter_Interrupt_Enable    <= RegData_i[5];
        end



        if (control_reg_we_dcd)
            IR_Emitter_Interrupt           <= RegData_i[4];
		else if (IR_Emitter_Busy_Modulator_i_1ff && (!IR_Emitter_Busy_Modulator_i))
            IR_Emitter_Interrupt           <= 1'b1;

        IR_Emitter_Busy_Modulator_i_1ff    <=  IR_Emitter_Busy_Modulator_i;


        if (IR_Emitter_Carrier_Cycle_Len_L_we_dcd)
            IR_Emitter_Carrier_Cycle_Len_o[HOST_DATA_IN_BITS-1:0]                  <= RegData_i[HOST_DATA_IN_BITS-1:0];

        if (IR_Emitter_Carrier_Cycle_Len_H_we_dcd)
            IR_Emitter_Carrier_Cycle_Len_o[CARRIER_CYCLE_BITS-1:HOST_DATA_IN_BITS] <= RegData_i[CARRIER_CYCLE_BITS-HOST_DATA_IN_BITS-1:0];

        if (IR_Emitter_Carrier_Duty_Len_L_we_dcd)
            IR_Emitter_Carrier_Duty_Len_o [HOST_DATA_IN_BITS-1:0]                  <= RegData_i[HOST_DATA_IN_BITS-1:0];

        if (IR_Emitter_Carrier_Duty_Len_H_we_dcd)
            IR_Emitter_Carrier_Duty_Len_o [CARRIER_DUTY_BITS-1:HOST_DATA_IN_BITS]  <= RegData_i[CARRIER_DUTY_BITS-HOST_DATA_IN_BITS-1:0];

        if (IR_Emitter_MemRd_Start_L_we_dcd)
            IR_Emitter_MemRd_Start_o      [HOST_DATA_IN_BITS-1:0]                  <= RegData_i[HOST_DATA_IN_BITS-1:0];

        if (IR_Emitter_MemRd_Start_H_we_dcd)
            IR_Emitter_MemRd_Start_o      [MEM_ADR_BUS_BITS-1:HOST_DATA_IN_BITS]   <= RegData_i[MEM_ADR_BUS_BITS-HOST_DATA_IN_BITS-1:0];

        if (IR_Emitter_MemRd_Stop_L_we_dcd)
            IR_Emitter_MemRd_Stop_o       [HOST_DATA_IN_BITS-1:0]                  <= RegData_i[HOST_DATA_IN_BITS-1:0];

        if (IR_Emitter_MemRd_Stop_H_we_dcd)
            IR_Emitter_MemRd_Stop_o       [MEM_ADR_BUS_BITS-1:HOST_DATA_IN_BITS]   <= RegData_i[MEM_ADR_BUS_BITS-HOST_DATA_IN_BITS-1:0];

        if (IR_Emitter_MemAddr_Reg_L_we_dcd)
            IR_Emitter_MemAddr_Reg_o      [MEM_ADR_BUS_BITS-HOST_ADR_IN_BITS:0]    <= RegData_i[MEM_ADR_BUS_BITS-HOST_ADR_IN_BITS:0];

        if (IR_Emitter_Gpio_Port_Reg_L_we_dcd)
            IR_Emitter_Gpio_Port_o        [HOST_DATA_IN_BITS-1:0]                  <= RegData_i[HOST_DATA_IN_BITS-1:0];

        if (IR_Emitter_Gpio_Dir_Reg_L_we_dcd)
            IR_Emitter_Gpio_Dir_o         [HOST_DATA_IN_BITS-1:0]                  <= RegData_i[HOST_DATA_IN_BITS-1:0];

	end
end






endmodule

module ALU_mux(ReadData2, Sign_Extnd_out, ALUSrc, ALUIn2);

input [31:0] ReadData2,Sign_Extnd_out;
input ALUSrc;
output reg [31:0] ALUIn2;


always @(ReadData2,Sign_Extnd_out,ALUSrc)
begin

if(ALUSrc)
	ALUIn2 <= Sign_Extnd_out;
else
	ALUIn2 <=  ReadData2;

end

endmodule

module phy_dly_ctrl #
  (
   parameter TCQ            = 100,    
   parameter DQ_WIDTH       = 64,     
   parameter DQS_CNT_WIDTH  = 3,      
   parameter DQS_WIDTH      = 8,      
   parameter RANK_WIDTH     = 1,      
   parameter nCWL           = 5,      
   parameter REG_CTRL       = "OFF",  
   parameter WRLVL          = "ON",   
   parameter PHASE_DETECT   = "ON",   
   parameter DRAM_TYPE      = "DDR3", 
   parameter nDQS_COL0      = 4,      
   parameter nDQS_COL1      = 4,      
   parameter nDQS_COL2      = 0,      
   parameter nDQS_COL3      = 0,      
   parameter DQS_LOC_COL0   = 32'h03020100, 
   parameter DQS_LOC_COL1   = 32'h07060504, 
   parameter DQS_LOC_COL2   = 0,            
   parameter DQS_LOC_COL3   = 0,            
   parameter DEBUG_PORT     = "OFF"   
   )
  (
   input                        clk,
   input                        rst,
   input [3:0]                  clk_rsync,
   input [3:0]                  rst_rsync,

   input                        wrlvl_done,
   input [1:0]                  rdlvl_done,
   input                        pd_cal_done,
   input                        mc_data_sel,
   input [RANK_WIDTH:0]         mc_ioconfig,
   input                        mc_ioconfig_en,
   input [0:0]                  phy_ioconfig,
   input                        phy_ioconfig_en,
   input                        dqs_oe,

   input [5*DQS_WIDTH-1:0]      dlyval_wrlvl_dqs,
   input [5*DQS_WIDTH-1:0]      dlyval_wrlvl_dq,

   input [DQS_WIDTH-1:0]        dlyce_rdlvl_cpt,
   input                        dlyinc_rdlvl_cpt,
   input [3:0]                  dlyce_rdlvl_rsync,
   input                        dlyinc_rdlvl_rsync,
   input [5*DQS_WIDTH-1:0]      dlyval_rdlvl_dq,
   input [5*DQS_WIDTH-1:0]      dlyval_rdlvl_dqs,

   input [DQS_WIDTH-1:0]        dlyce_pd_cpt,
   input [DQS_WIDTH-1:0]        dlyinc_pd_cpt,
   input [5*DQS_WIDTH-1:0]      dlyval_pd_dqs,

   output reg [5*DQS_WIDTH-1:0] dlyval_dqs,
   output reg [5*DQS_WIDTH-1:0] dlyval_dq,
   output                       dlyrst_cpt,
   output [DQS_WIDTH-1:0]       dlyce_cpt,
   output [DQS_WIDTH-1:0]       dlyinc_cpt,
   output                       dlyrst_rsync,
   output [3:0]                 dlyce_rsync,
   output [3:0]                 dlyinc_rsync,

   input                        dbg_pd_off
   );

  reg [DQS_WIDTH-1:0]        dlyce_cpt_mux;
  reg [3:0]                  dlyce_rsync_mux;
  reg [DQS_WIDTH-1:0]        dlyinc_cpt_mux;
  reg [3:0]                  dlyinc_rsync_mux;
  reg                        dqs_oe_r;
  reg                        dqs_wr;
  wire [0:0]                 mux_ioconfig;
  wire                       mux_ioconfig_en;
  wire                       mux_rd_wr;
  reg                        mux_rd_wr_last_r;
  reg                        rd_wr_r;
  reg [3:0]                  rd_wr_rsync_r;
  reg [3:0]                  rd_wr_rsync_tmp_r;
  reg [3:0]                  rd_wr_rsync_tmp_r1;










  assign dlyrst_cpt   = rst;
  assign dlyrst_rsync = rst;










  assign mux_ioconfig    = (mc_data_sel) ?
                           mc_ioconfig[RANK_WIDTH] :
                           phy_ioconfig;
  assign mux_ioconfig_en = (mc_data_sel) ?
                           mc_ioconfig_en :
                           phy_ioconfig_en;

  assign mux_rd_wr = mux_ioconfig[0];

  always @(posedge clk)
    dqs_oe_r <= #TCQ dqs_oe;






  always @(dqs_oe or mux_rd_wr_last_r)
    dqs_wr = mux_rd_wr_last_r | dqs_oe;


  always @(posedge clk)
    if (mux_ioconfig_en)
      mux_rd_wr_last_r <= #TCQ mux_rd_wr;






  always @(posedge clk) begin
    if (mux_ioconfig_en) begin
      if ((dqs_wr)&& (DRAM_TYPE == "DDR3"))
        rd_wr_r <= #TCQ 1'b1;
      else
        rd_wr_r <= #TCQ mux_rd_wr;
    end else begin
      if ((dqs_wr)&& (DRAM_TYPE == "DDR3"))
        rd_wr_r <= #TCQ 1'b1;
      else
        rd_wr_r <= #TCQ mux_rd_wr;
    end
  end


  genvar r_i;
  generate
    for (r_i = 0; r_i < 4; r_i = r_i + 1) begin: gen_sync_rd_wr
      if (DRAM_TYPE == "DDR2") begin :  gen_cwl_ddr2
        if (nCWL <= 3) begin: gen_cwl_ddr2_ls_4

          always @(posedge clk_rsync[r_i]) begin
            rd_wr_rsync_tmp_r[r_i] <= #TCQ rd_wr_r;
            rd_wr_rsync_r[r_i]     <= #TCQ rd_wr_rsync_tmp_r[r_i];      
          end
        end else begin  
          always @(posedge clk_rsync[r_i]) begin:gen_cwl_ddr2_gt_3
            rd_wr_rsync_tmp_r[r_i] <= #TCQ rd_wr_r;
            rd_wr_rsync_tmp_r1[r_i] <= #TCQ rd_wr_rsync_tmp_r[r_i];
            rd_wr_rsync_r[r_i]     <= #TCQ rd_wr_rsync_tmp_r1[r_i];     
          end
        end 
      end else if ((nCWL == 5) || 
                   ((nCWL == 6) && (REG_CTRL == "ON"))) begin: gen_cwl_5_ddr3














        always @(posedge clk_rsync[r_i])
          rd_wr_rsync_r[r_i] <= #TCQ rd_wr_r;
      end else begin: gen_cwl_gt_5_ddr3


        always @(posedge clk_rsync[r_i]) begin
          rd_wr_rsync_tmp_r[r_i] <= #TCQ rd_wr_r;
          rd_wr_rsync_r[r_i]     <= #TCQ rd_wr_rsync_tmp_r[r_i];
        end
      end
    end
  endgenerate









  always @(posedge clk) begin
    if (!rdlvl_done[1]) begin


      dlyce_cpt_mux        <= #TCQ dlyce_rdlvl_cpt;
      dlyinc_cpt_mux       <= #TCQ {DQS_WIDTH{dlyinc_rdlvl_cpt}};
      dlyce_rsync_mux      <= #TCQ dlyce_rdlvl_rsync;
      dlyinc_rsync_mux     <= #TCQ {4{dlyinc_rdlvl_rsync}};
    end else begin
      if ((PHASE_DETECT == "OFF") || 
          ((DEBUG_PORT == "ON") && dbg_pd_off)) begin











        dlyce_cpt_mux        <= #TCQ dlyce_rdlvl_cpt;
        dlyinc_cpt_mux       <= #TCQ {DQS_WIDTH{dlyinc_rdlvl_cpt}};
        dlyce_rsync_mux      <= #TCQ dlyce_rdlvl_rsync;
        dlyinc_rsync_mux     <= #TCQ {4{dlyinc_rdlvl_rsync}};
      end else begin

        dlyce_cpt_mux    <= #TCQ dlyce_pd_cpt;
        dlyinc_cpt_mux   <= #TCQ dlyinc_pd_cpt;





        dlyce_rsync_mux  <= #TCQ 'b0;
        dlyinc_rsync_mux <= #TCQ 'b0;



      end
    end
  end

  assign dlyce_cpt     = dlyce_cpt_mux;
  assign dlyinc_cpt    = dlyinc_cpt_mux;
  assign dlyce_rsync   = dlyce_rsync_mux;
  assign dlyinc_rsync  = dlyinc_rsync_mux;













  generate
    genvar c0_i;
    if (nDQS_COL0 > 0) begin: gen_c0    
    for (c0_i = 0; c0_i < nDQS_COL0; c0_i = c0_i + 1) begin: gen_loop_c0

























      always @ (posedge clk_rsync[0]) begin
        if (rd_wr_rsync_r[0]) begin

          dlyval_dqs[5*(DQS_LOC_COL0[8*c0_i+:8])+:5]
            <= #TCQ dlyval_wrlvl_dqs[5*(DQS_LOC_COL0[8*c0_i+:8])+:5];

          dlyval_dq[5*(DQS_LOC_COL0[8*c0_i+:8])+:5]
            <= #TCQ dlyval_wrlvl_dq[5*(DQS_LOC_COL0[8*c0_i+:8])+:5];
        end else begin

          if ((PHASE_DETECT == "ON") && rdlvl_done[1]) begin 

            dlyval_dqs[5*(DQS_LOC_COL0[8*c0_i+:8])+:5]
              <= #TCQ dlyval_pd_dqs[5*(DQS_LOC_COL0[8*c0_i+:8])+:5];
          end else begin 


            dlyval_dqs[5*(DQS_LOC_COL0[8*c0_i+:8])+:5]
              <= #TCQ dlyval_rdlvl_dqs[5*(DQS_LOC_COL0[8*c0_i+:8])+:5];
          end     

          dlyval_dq[5*(DQS_LOC_COL0[8*c0_i+:8])+:5]
            <= #TCQ dlyval_rdlvl_dq[5*(DQS_LOC_COL0[8*c0_i+:8])+:5];
          end
        end
      end
    end
  endgenerate









  generate
    genvar c1_i;
    if (nDQS_COL1 > 0) begin: gen_c1
      for (c1_i = 0; c1_i < nDQS_COL1; c1_i = c1_i + 1) begin: gen_loop_c1
        always @(posedge clk_rsync[1]) begin
          if (rd_wr_rsync_r[1]) begin
            dlyval_dqs[5*(DQS_LOC_COL1[8*c1_i+7-:8])+:5]
              <= #TCQ dlyval_wrlvl_dqs[5*(DQS_LOC_COL1[8*c1_i+7-:8])+:5];
            dlyval_dq[5*(DQS_LOC_COL1[8*c1_i+7-:8])+:5]
              <= #TCQ dlyval_wrlvl_dq[5*(DQS_LOC_COL1[8*c1_i+:8])+:5];
          end else begin
            if ((PHASE_DETECT == "ON") && rdlvl_done[1]) begin 

              dlyval_dqs[5*(DQS_LOC_COL1[8*c1_i+:8])+:5]
                <= #TCQ dlyval_pd_dqs[5*(DQS_LOC_COL1[8*c1_i+:8])+:5];
            end else begin


              dlyval_dqs[5*(DQS_LOC_COL1[8*c1_i+:8])+:5]
                <= #TCQ dlyval_rdlvl_dqs[5*(DQS_LOC_COL1[8*c1_i+:8])+:5];
            end                
            dlyval_dq[5*(DQS_LOC_COL1[8*c1_i+:8])+:5]
              <= #TCQ dlyval_rdlvl_dq[5*(DQS_LOC_COL1[8*c1_i+:8])+:5];
          end
        end
      end
    end
  endgenerate


  generate
    genvar c2_i;
    if (nDQS_COL2 > 0) begin: gen_c2
      for (c2_i = 0; c2_i < nDQS_COL2; c2_i = c2_i + 1) begin: gen_loop_c2
        always @(posedge clk_rsync[2]) begin
          if (rd_wr_rsync_r[2]) begin
            dlyval_dqs[5*(DQS_LOC_COL2[8*c2_i+7-:8])+:5]
              <= #TCQ dlyval_wrlvl_dqs[5*(DQS_LOC_COL2[8*c2_i+7-:8])+:5];
            dlyval_dq[5*(DQS_LOC_COL2[8*c2_i+7-:8])+:5]
              <= #TCQ dlyval_wrlvl_dq[5*(DQS_LOC_COL2[8*c2_i+:8])+:5];
          end else begin
            if ((PHASE_DETECT == "ON") && rdlvl_done[1]) begin 

              dlyval_dqs[5*(DQS_LOC_COL2[8*c2_i+:8])+:5]
                <= #TCQ dlyval_pd_dqs[5*(DQS_LOC_COL2[8*c2_i+:8])+:5];
            end else begin


              dlyval_dqs[5*(DQS_LOC_COL2[8*c2_i+:8])+:5]
                <= #TCQ dlyval_rdlvl_dqs[5*(DQS_LOC_COL2[8*c2_i+:8])+:5];
            end                
            dlyval_dq[5*(DQS_LOC_COL2[8*c2_i+:8])+:5]
              <= #TCQ dlyval_rdlvl_dq[5*(DQS_LOC_COL2[8*c2_i+:8])+:5];
          end
        end
      end
    end
  endgenerate


  generate
    genvar c3_i;
    if (nDQS_COL3 > 0) begin: gen_c3
      for (c3_i = 0; c3_i < nDQS_COL3; c3_i = c3_i + 1) begin: gen_loop_c3
        always @(posedge clk_rsync[3]) begin
          if (rd_wr_rsync_r[3]) begin
            dlyval_dqs[5*(DQS_LOC_COL3[8*c3_i+7-:8])+:5]
              <= #TCQ dlyval_wrlvl_dqs[5*(DQS_LOC_COL3[8*c3_i+7-:8])+:5];
            dlyval_dq[5*(DQS_LOC_COL3[8*c3_i+7-:8])+:5]
              <= #TCQ dlyval_wrlvl_dq[5*(DQS_LOC_COL3[8*c3_i+:8])+:5];
          end else begin
            if ((PHASE_DETECT == "ON") && rdlvl_done[1]) begin

              dlyval_dqs[5*(DQS_LOC_COL3[8*c3_i+:8])+:5]
                <= #TCQ dlyval_pd_dqs[5*(DQS_LOC_COL3[8*c3_i+:8])+:5];
            end else begin


              dlyval_dqs[5*(DQS_LOC_COL3[8*c3_i+:8])+:5]
                <= #TCQ dlyval_rdlvl_dqs[5*(DQS_LOC_COL3[8*c3_i+:8])+:5];
            end                
            dlyval_dq[5*(DQS_LOC_COL3[8*c3_i+:8])+:5]
              <= #TCQ dlyval_rdlvl_dq[5*(DQS_LOC_COL3[8*c3_i+:8])+:5];
          end
        end
      end
    end
  endgenerate

endmodule

module uart_rx #(
  parameter DATA_BITS = 8,
  parameter STOP_TICK = 16
) (
  input                  clk_i,
  input                  rst_ni,
  input                  sample_tick_i,
  input                  rx_i,
  output reg             rx_done_tick_o,
  output [DATA_BITS-1:0] rx_data_o
);


localparam [1:0]    S_IDLE  = 2'b00;
localparam [1:0]    S_START = 2'b01;
localparam [1:0]    S_DATA  = 2'b10;
localparam [1:0]    S_STOP  = 2'b11;


reg [1:0]           state_reg, state_next;
reg [3:0]           tick_count_reg, tick_count_next; 
reg [2:0]           data_count_reg, data_count_next; 
reg [DATA_BITS-1:0] data_buf_reg, data_buf_next;     
reg                 rx_reg, rx_next;



always @(posedge clk_i, negedge rst_ni) begin
  if (~rst_ni)
    begin
      state_reg      <= S_IDLE;
      tick_count_reg <= 0;
      data_count_reg <= 0;
      data_buf_reg   <= 0;
      rx_reg         <= 1;
    end
  else
    begin
      state_reg      <= state_next;
      tick_count_reg <= tick_count_next;
      data_count_reg <= data_count_next;
      data_buf_reg   <= data_buf_next;
      rx_reg         <= rx_next;
    end
end


always @(*) begin
  state_next      = state_reg;
  tick_count_next = tick_count_reg;
  data_count_next = data_count_reg;
  data_buf_next   = data_buf_reg;
  rx_done_tick_o  = 1'b0;
  rx_next         = rx_i;

  case (state_reg)

    S_IDLE: begin
      if (~rx_reg)
        begin
          state_next      = S_START;
          tick_count_next = 0;
        end
    end 


    S_START: begin
      if (sample_tick_i)
        begin
          if (tick_count_reg == 7) 
            begin
              if (~rx_reg) 
                begin
                  state_next      = S_DATA;
                  tick_count_next = 0;
                  data_count_next = 0;
                end
              else
                  state_next      = S_IDLE;
            end
          else
            tick_count_next = tick_count_reg + 1'b1;
        end
    end 


    S_DATA: begin
      if (sample_tick_i)
        begin
          if (tick_count_reg == 15)
            begin
              tick_count_next = 0;
              data_buf_next   = {rx_reg, data_buf_reg[7:1]}; 
              if (data_count_reg == (DATA_BITS - 1))
                state_next = S_STOP;
              else
                data_count_next = data_count_reg + 1'b1;
            end
          else
            tick_count_next = tick_count_reg + 1'b1;
        end
    end 


    S_STOP: begin
      if (sample_tick_i)
        begin
          if (tick_count_reg == (STOP_TICK - 1))
            begin
              state_next     = S_IDLE;
              rx_done_tick_o = 1'b1;
            end
          else
            tick_count_next = tick_count_reg + 1'b1;
        end
    end 

    default: state_next = S_IDLE;
  endcase
end


assign rx_data_o = data_buf_reg;

endmodule

`timescale 1ns / 1ps




















module VendingMachine(
    input clk,                    
    input rst,                    
    input [2:0] product_code,     
    input online_payment,         
    input start,                  
    input cancel,                 
    input [6:0] total_coin_value, 

    output reg [3:0] state,               
    output reg dispense_product,         
    output reg [6:0] return_change,      
    output reg [6:0] product_price       
);


localparam IDLE_STATE = 4'b0000;
localparam SELECT_PRODUCT_STATE = 4'b0001;
localparam PEN_SELECTION_STATE = 4'b0010;
localparam NOTEBOOK_SELECTION_STATE = 4'b0011;
localparam COKE_SELECTION_STATE = 4'b0100;
localparam LAYS_SELECTION_STATE = 4'b0101;
localparam WATER_BOTTLE_SELECTION_STATE = 4'b0110;
localparam DISPENSE_AND_RETURN_STATE = 4'b0111;


parameter WATER_BOTTLE_PRICE = 7'd20;
parameter LAYS_PRICE = 7'd35;
parameter COKE_PRICE = 7'd30;
parameter PEN_PRICE = 7'd15;
parameter NOTEBOOK_PRICE = 7'd50;


reg [3:0] current_state;
reg [3:0] next_state;
reg [6:0] product_price_reg;
reg [6:0] return_change_reg;


always @(posedge clk or posedge rst) begin
    if (rst) begin
        current_state <= IDLE_STATE;
        product_price_reg <= 0;
        return_change_reg <= 0;
    end else begin
        current_state <= next_state;
        product_price_reg <= product_price_reg; 
        return_change_reg <= return_change_reg; 
    end
end


always @(*) begin
    case (current_state)
        IDLE_STATE: begin
            if (start)
                next_state = SELECT_PRODUCT_STATE;
            else if (cancel)
                next_state = IDLE_STATE;
            else 
                next_state = IDLE_STATE;
        end    
        SELECT_PRODUCT_STATE: begin
            case (product_code)
                3'b000: begin
                    next_state = PEN_SELECTION_STATE; 
                    product_price_reg = PEN_PRICE;
                end
                3'b001: begin
                    next_state = NOTEBOOK_SELECTION_STATE; 
                    product_price_reg = NOTEBOOK_PRICE;
                end
                3'b010: begin
                    next_state = COKE_SELECTION_STATE; 
                    product_price_reg = COKE_PRICE;
                end
                3'b011: begin
                    next_state = LAYS_SELECTION_STATE; 
                    product_price_reg = LAYS_PRICE;
                end
                3'b100: begin
                    next_state = WATER_BOTTLE_SELECTION_STATE; 
                    product_price_reg = WATER_BOTTLE_PRICE;
                end
                default: begin
                    next_state = IDLE_STATE; 
                    product_price_reg = 0;
                end
            endcase
        end
        PEN_SELECTION_STATE, NOTEBOOK_SELECTION_STATE, COKE_SELECTION_STATE, LAYS_SELECTION_STATE, WATER_BOTTLE_SELECTION_STATE: begin
            if (cancel) begin 
                next_state = IDLE_STATE;
                return_change_reg = total_coin_value;
            end
            else if (total_coin_value >= product_price_reg)
                next_state = DISPENSE_AND_RETURN_STATE;
            else if (online_payment)
                next_state = DISPENSE_AND_RETURN_STATE;
            else
                next_state = current_state; 
        end
        DISPENSE_AND_RETURN_STATE: begin
            next_state = IDLE_STATE;
            if (online_payment)
                return_change_reg = 0; 
            else if (total_coin_value >= product_price_reg)
                return_change_reg = total_coin_value - product_price_reg;
        end
    endcase
end


always @(*) begin
    state = current_state;
    case (current_state)
        DISPENSE_AND_RETURN_STATE: begin
            dispense_product = 1;
            return_change = return_change_reg;
            product_price = product_price_reg;
        end
        default: begin
            dispense_product = 0;
            return_change = 0;
            product_price = 0; 
        end
    endcase
end

endmodule

`timescale 1ns / 1ps



















module dragonbridge_fsm(
		input wire clk,
		input wire rst,

		output reg spi_cs_n,
		output reg[7:0] spi_clk_div,
		output reg spi_cpol,
		output reg spi_cpha,
		output reg spi_transfer_req,
		input wire spi_transfer_ready,
		input wire spi_transfer_done,
		output reg[7:0] spi_to_agent,
		input wire[7:0] spi_from_agent,

		output reg[15:0] i2c_clk_div,
		output reg i2c_start_req,
		output reg i2c_stop_req,
		output reg i2c_write_req,
		output reg i2c_read_req,
		input wire i2c_ready,
		output reg i2c_host_ack,
		input wire i2c_agent_ack,
		output reg[7:0] i2c_to_agent,
		input wire[7:0] i2c_from_agent,

		output reg[15:0] uart_clk_div,
		output reg uart_tx_req,
		output reg[7:0] uart_tx_data,
		input wire[7:0] uart_rx_data,
		input wire uart_tx_ready,
		input wire uart_rx_ready,

		output reg[7:0] cmd_count,
		output reg[7:0] last_tx,
		output reg[7:0] last_rx
	);


	localparam[7:0] CMD_NOP = 8'h00;		
	localparam[7:0] CMD_TEST = 8'h01;	
	localparam[7:0] CMD_BAUD = 8'h02;	

	localparam[7:0] CMD_SPI_SPEED = 8'h03;	
	localparam[7:0] CMD_SPI_MODE = 8'h04;	
	localparam[7:0] CMD_SPI_CHIPSEL = 8'h05;	
	localparam[7:0] CMD_SPI_TRANSFER = 8'h06;	

	localparam[7:0] CMD_I2C_SPEED = 8'h07;	
	localparam[7:0] CMD_I2C_START = 8'h08;	
	localparam[7:0] CMD_I2C_STOP = 8'h09;	
	localparam[7:0] CMD_I2C_WRITE = 8'h0A;	
	localparam[7:0] CMD_I2C_READ = 8'h0B;	
	localparam[7:0] CMD_I2C_HOST_ACK = 8'h0C;	
	localparam[7:0] CMD_I2C_AGENT_ACK = 8'h0D;	


	localparam[7:0] S_IDLE = 8'h00;
	localparam[7:0] S_TEST = 8'h01;
	localparam[7:0] S_TEST_REQ = 8'h02;
	localparam[7:0] S_BAUD_H = 8'h03;
	localparam[7:0] S_BAUD_L = 8'h04;

	localparam[7:0] S_SPI_SPEED = 8'h05;
	localparam[7:0] S_SPI_MODE = 8'h06;
	localparam[7:0] S_SPI_CHIPSEL = 8'h07;
	localparam[7:0] S_SPI_TRANSFER_GET = 8'h08;
	localparam[7:0] S_SPI_TRANSFER_SRQ = 8'h09;
	localparam[7:0] S_SPI_TRANSFER_SGT = 8'h0A;
	localparam[7:0] S_SPI_TRANSFER_URQ = 8'h0B;

	localparam[7:0] S_I2C_SPEED_H = 8'h0C;
	localparam[7:0] S_I2C_SPEED_L = 8'h0D;
	localparam[7:0] S_I2C_START_R = 8'h0E;
	localparam[7:0] S_I2C_START_W = 8'h0F;
	localparam[7:0] S_I2C_STOP_R = 8'h10;
	localparam[7:0] S_I2C_STOP_W = 8'h11;
	localparam[7:0] S_I2C_WRITE_GET = 8'h12;
	localparam[7:0] S_I2C_WRITE_W = 8'h13;
	localparam[7:0] S_I2C_READ_IGT = 8'h14;
	localparam[7:0] S_I2C_READ_URQ = 8'h15;
	localparam[7:0] S_I2C_HOST_ACK = 8'h16;
	localparam[7:0] S_I2C_AGENT_ACK = 8'h17;

	reg[7:0] state;
	reg[7:0] baud_buf;

	always @(posedge clk or posedge rst)
	begin
		if(rst)
		begin
			spi_cs_n <= 1'b0;
			spi_clk_div <= 8'h00;	
			spi_cpol <= 1'b0;
			spi_cpha <= 1'b0;
			spi_transfer_req <= 1'b0;
			spi_to_agent <= 8'h00;

			i2c_clk_div <= 16'h0000;
			i2c_start_req <= 1'b0;
			i2c_stop_req <= 1'b0;
			i2c_write_req <= 1'b0;
			i2c_read_req <= 1'b0;
			i2c_host_ack <= 1'b0;
			i2c_to_agent <= 8'h00;

			uart_clk_div <= 16'd433;	
			uart_tx_req <= 1'b0;
			uart_tx_data <= 8'h00;

			cmd_count <= 8'h00;
			last_tx <= 8'h00;
			last_rx <= 8'h00;

			state <= S_IDLE;
			baud_buf <= 8'h00;
		end
		else
		begin
			case(state)
			S_IDLE:
			begin
				if(uart_rx_ready)
				begin
					cmd_count <= cmd_count + 8'h01;
					case(uart_rx_data)
					CMD_NOP: ;
					CMD_TEST: state <= S_TEST;
					CMD_BAUD: state <= S_BAUD_H;

					CMD_SPI_SPEED: state <= S_SPI_SPEED;
					CMD_SPI_MODE: state <= S_SPI_MODE;
					CMD_SPI_CHIPSEL: state <= S_SPI_CHIPSEL;
					CMD_SPI_TRANSFER: state <= S_SPI_TRANSFER_GET;

					CMD_I2C_SPEED: state <= S_I2C_SPEED_H;
					CMD_I2C_START: state <= S_I2C_START_R;
					CMD_I2C_STOP: state <= S_I2C_STOP_R;
					CMD_I2C_WRITE: state <= S_I2C_WRITE_GET;
					CMD_I2C_READ: state <= S_I2C_READ_IGT;
					CMD_I2C_HOST_ACK: state <= S_I2C_HOST_ACK;
					CMD_I2C_AGENT_ACK: state <= S_I2C_AGENT_ACK;

					default: ;
					endcase
				end
			end
			S_TEST:
			begin
				if(uart_rx_ready)
				begin
					uart_tx_data <= uart_rx_data;
					uart_tx_req <= 1'b1;
					state <= S_TEST_REQ;
				end
			end
			S_TEST_REQ:
			begin
				if(uart_tx_ready)
				begin
					uart_tx_req <= 1'b0;
					state <= S_IDLE;
				end
			end
			S_BAUD_H:
			begin
				if(uart_rx_ready)
				begin
					baud_buf <= uart_rx_data;
					state <= S_BAUD_L;
				end
			end
			S_BAUD_L:
			begin
				if(uart_rx_ready)
				begin
					uart_clk_div <= {baud_buf, uart_rx_data};
					state <= S_IDLE;
				end
			end


			S_SPI_SPEED:
			begin
				if(uart_rx_ready)
				begin
					spi_clk_div <= uart_rx_data;
					state <= S_IDLE;
				end
			end
			S_SPI_MODE:
			begin
				if(uart_rx_ready)
				begin
					spi_cpha <= uart_rx_data[0];
					spi_cpol <= uart_rx_data[1];
					state <= S_IDLE;
				end
			end
			S_SPI_CHIPSEL:
			begin
				if(uart_rx_ready)
				begin
					spi_cs_n <= uart_rx_data[0];
					state <= S_IDLE;
				end
			end
			S_SPI_TRANSFER_GET:
			begin
				if(uart_rx_ready)
				begin
					spi_to_agent <= uart_rx_data;
					last_tx <= uart_rx_data;
					spi_transfer_req <= 1'b1;
					state <= S_SPI_TRANSFER_SRQ;
				end
			end
			S_SPI_TRANSFER_SRQ:
			begin
				if(spi_transfer_ready)
				begin
					spi_transfer_req <= 1'b0;
					state <= S_SPI_TRANSFER_SGT;
				end
			end
			S_SPI_TRANSFER_SGT:
			begin
				if(spi_transfer_done)
				begin
					uart_tx_data <= spi_from_agent;
					last_rx <= spi_from_agent;
					uart_tx_req <= 1'b1;
					state <= S_SPI_TRANSFER_URQ;
				end
			end
			S_SPI_TRANSFER_URQ:
			begin
				if(uart_tx_ready)
				begin
					uart_tx_req <= 1'b0;
					state <= S_IDLE;
				end
			end


			S_I2C_SPEED_H:
			begin
				if(uart_rx_ready)
				begin
					i2c_clk_div[15:8] <= uart_rx_data;
					state <= S_I2C_SPEED_L;
				end
			end
			S_I2C_SPEED_L:
			begin
				if(uart_rx_ready)
				begin
					i2c_clk_div[7:0] <= uart_rx_data;
					state <= S_IDLE;
				end
			end
			S_I2C_START_R:
			begin
				i2c_start_req <= 1'b1;
				state <= S_I2C_START_W;
			end
			S_I2C_START_W:
			begin
				if(i2c_ready)
				begin
					i2c_start_req <= 1'b0;
					state <= S_IDLE;
				end
			end
			S_I2C_STOP_R:
			begin
				i2c_stop_req <= 1'b1;
				state <= S_I2C_STOP_W;
			end
			S_I2C_STOP_W:
			begin
				if(i2c_ready)
				begin
					i2c_stop_req <= 1'b0;
					state <= S_IDLE;
				end
			end
			S_I2C_WRITE_GET:
			begin
				if(uart_rx_ready)
				begin
					i2c_to_agent <= uart_rx_data;
					last_tx <= uart_rx_data;
					i2c_write_req <= 1'b1;
					state <= S_I2C_WRITE_W;
				end
			end
			S_I2C_WRITE_W:
			begin
				if(i2c_ready)
				begin
					i2c_write_req <= 1'b0;
					state <= S_IDLE;
				end
			end
			S_I2C_READ_IGT:
			begin
				i2c_read_req <= 1'b1;
				if(i2c_ready)
				begin
					i2c_read_req <= 1'b0;
					uart_tx_data <= i2c_from_agent;
					last_rx <= i2c_from_agent;
					uart_tx_req <= 1'b1;
					state <= S_I2C_READ_URQ;
				end
			end
			S_I2C_READ_URQ:
			begin
				if(uart_tx_ready)
				begin
					uart_tx_req <= 1'b0;
					state <= S_IDLE;
				end
			end
			S_I2C_HOST_ACK:
			begin
				if(uart_rx_ready)
				begin
					i2c_host_ack <= uart_rx_data[0];
					state <= S_IDLE;
				end
			end
			S_I2C_AGENT_ACK:
			begin
				uart_tx_data <= {7'h00, i2c_agent_ack};
				uart_tx_req <= 1'b1;
				if(uart_tx_ready)
				begin
					uart_tx_req <= 1'b0;
					state <= S_IDLE;
				end
			end

			default: ;
			endcase
		end
	end

endmodule

`define LOG2_MAX_CLOCK_FACTOR 4  

`define BITS_PER_CHAR         8  















`define TEMPLATE_BITS     9'h086  


module auto_baud_with_tracking
  (
  clk_i,
  reset_i,
  serial_dat_i,
  auto_baud_locked_o,
  baud_clk_o
  );





parameter CLOCK_FACTOR_PP = 8;     
parameter LOG2_MAX_COUNT_PP = 16;  









parameter m1_idle          = 4'h0;  
parameter m1_measure_0     = 4'h1;  
parameter m1_measure_1     = 4'h2;  
parameter m1_measure_2     = 4'h3;  
parameter m1_measure_3     = 4'h4;  
parameter m1_measure_4     = 4'h5;  
parameter m1_verify_0      = 4'h8;  
parameter m1_verify_1      = 4'h9;  
parameter m1_run           = 4'h6;  
parameter m1_verify_failed = 4'h7;  


input clk_i;                 
input reset_i;               
input serial_dat_i;          

output auto_baud_locked_o;   
output baud_clk_o;           



wire mid_bit_count;       






wire main_count_rollover;       
wire baud_count_rollover;       
wire clock_count_rollover;      


wire enable_clock_count;        

wire verify_done;               

reg idle;                 
reg measure;              
reg clear_counters;       
reg verify;               
reg verify_good;          
reg character_miscompare; 
reg run;                  

reg [`LOG2_MAX_CLOCK_FACTOR-1:0] clock_count; 

reg [LOG2_MAX_COUNT_PP-1:0] main_count;       
reg [LOG2_MAX_COUNT_PP-1:0] baud_count;       
reg [LOG2_MAX_COUNT_PP-1:0] measurement;      
reg [LOG2_MAX_COUNT_PP-1:0] baud;             
reg [`BITS_PER_CHAR:0] target_bits;           




reg [3:0] m1_state;
reg [3:0] m1_next_state;














assign enable_clock_count = measure || (verify && main_count_rollover);
always @(posedge clk_i or posedge reset_i)
begin
  if (reset_i) clock_count <= 0;
  else if (clear_counters) clock_count <= 0;
  else if (enable_clock_count)
  begin  
    if (clock_count_rollover) clock_count <= 0;
    else clock_count <= clock_count + 1;
  end
end

assign clock_count_rollover = (clock_count == (CLOCK_FACTOR_PP-1));








assign mid_bit_count = (
                        (clock_count == ((CLOCK_FACTOR_PP>>1)-1))
                        && enable_clock_count
                        );








always @(posedge clk_i or posedge reset_i)
begin
  if (reset_i) main_count <= 0;
  else 
  begin

    if (clear_counters) main_count <= 0;

    else if (measure && mid_bit_count) main_count <= main_count + 1;


    else if (verify)
    begin
      if (main_count_rollover) main_count <= 0;
      else main_count <= main_count + 1;
    end
  end
end

assign main_count_rollover = (main_count == measurement);







always @(posedge clk_i or posedge reset_i)
begin
  if (reset_i) baud_count <= 0;
  else 
  begin

    if (run)
    begin
      if (baud_count_rollover) baud_count <= 0;
      else baud_count <= baud_count + 1;
    end
  end
end
assign baud_count_rollover = (baud_count == baud);




always @(posedge clk_i or posedge reset_i)
begin
  if (reset_i) target_bits <= `TEMPLATE_BITS;
  else 
  begin
    if (~verify) target_bits <= `TEMPLATE_BITS;

    if (verify && mid_bit_count) target_bits <= target_bits>>1;
  end
end

assign verify_done = (
                       (target_bits == 1)
                       && verify
                       && mid_bit_count
                      );






always @(posedge clk_i or posedge reset_i)
begin
  if (reset_i) character_miscompare <= 0;
  else  
  begin
    if (idle) character_miscompare <= 0;
    if (verify && mid_bit_count
        && (target_bits[0] ^ serial_dat_i)) character_miscompare <= 1;
  end
end







always @(posedge clk_i or posedge idle)
begin

  if (idle) measurement <= -1;





  else if (clear_counters) measurement <= (main_count>>1);
end





always @(posedge clk_i or posedge reset_i)
begin

  if (reset_i) baud <= -1;





  else if (verify_good) baud <= measurement;
end







always @(posedge clk_i or posedge reset_i)
begin
  if (reset_i) run <= 0;
  else  
  begin
    if (verify_good) run <= 1;
  end
end

assign baud_clk_o = baud_count_rollover;
















always @(posedge clk_i or posedge reset_i)
begin : m1_state_register
  if (reset_i) m1_state <= m1_idle;          
  else m1_state <= m1_next_state;
end


always @(m1_state
         or mid_bit_count
         or serial_dat_i
         or verify_done
         or character_miscompare
         )
begin : m1_state_logic


  idle <= 1'b0;
  verify_good <= 1'b0;
  measure <= 1'b0;
  clear_counters <= 1'b0;
  verify <= 1'b0;

  case (m1_state) 

    m1_idle :
      begin
        idle <= 1'b1;
        if (serial_dat_i == 0) m1_next_state <= m1_measure_0;
        else m1_next_state <= m1_idle;
      end

    m1_measure_0 :
      begin
        measure <= 1'b1;


        if (mid_bit_count && ~serial_dat_i) m1_next_state <= m1_measure_1;

        else if (mid_bit_count && serial_dat_i) m1_next_state <= m1_idle;
        else m1_next_state <= m1_measure_0;
      end

    m1_measure_1 :
      begin
        measure <= 1'b1;

        if (serial_dat_i) m1_next_state <= m1_measure_2;


        else m1_next_state <= m1_measure_1;
      end

    m1_measure_2 :
      begin
        measure <= 1'b1;


        if (mid_bit_count && serial_dat_i) m1_next_state <= m1_measure_3;

        else if (mid_bit_count && ~serial_dat_i) m1_next_state <= m1_idle;
        else m1_next_state <= m1_measure_2;
      end

    m1_measure_3 :
      begin
        measure <= 1'b1;

        if (!serial_dat_i) m1_next_state <= m1_measure_4;


        else m1_next_state <= m1_measure_3;
      end



    m1_measure_4 :
      begin
        clear_counters <= 1'b1; 
        m1_next_state <= m1_verify_0;
      end

    m1_verify_0 :  
      begin
        verify <= 1'b1;
        if (verify_done) m1_next_state <= m1_verify_1;
        else m1_next_state <= m1_verify_0;
      end




    m1_verify_1 :  
      begin
        if (character_miscompare) m1_next_state <= m1_verify_failed;
        else m1_next_state <= m1_run;
      end

    m1_verify_failed : 
      begin
        clear_counters <= 1'b1;
        m1_next_state <= m1_idle;
      end




    m1_run :       
      begin
        verify_good <= 1'b1;
        m1_next_state <= m1_idle;
      end

    default : m1_next_state <= m1_idle;
  endcase
end


assign auto_baud_locked_o = run;


endmodule

module async_qdr_interface #(
    parameter QDR_LATENCY = 10
  ) (
    input  host_clk,
    input  host_rst,
    input  host_en,
    input  host_rnw,
    input  [31:0] host_addr,
    input  [31:0] host_datai,
    input   [3:0] host_be,
    output [31:0] host_datao,
    output host_ack,
    input  qdr_clk,
    input  qdr_rst,
    output qdr_req,
    input  qdr_ack,
    output [31:0] qdr_addr,
    output qdr_r,
    output qdr_w,
    output [35:0] qdr_d,
    output  [3:0] qdr_be,
    input  [35:0] qdr_q
  );








  reg [31:0] host_addr_reg;
  reg [31:0] host_datai_reg;
  reg  [3:0] host_be_reg;
  reg host_rnw_reg;

  reg [31:0] host_datao_reg;

  reg second_cycle;

  wire second_word = host_addr_reg[2];

  assign qdr_addr = host_addr_reg[31:3];

  assign qdr_r  = qdr_req & host_rnw_reg;
  assign qdr_w  = qdr_req & !host_rnw_reg;
  assign qdr_d  = {1'b0, host_datai_reg[31:24], 1'b0, host_datai_reg[23:16], 1'b0, host_datai_reg[15:8], 1'b0, host_datai_reg[7:0]};
  assign qdr_be = (second_cycle && second_word) || (!second_cycle && !second_word) ?
                     host_be_reg : 4'b0;

  assign host_datao = host_datao_reg;
  reg host_ack_reg;
  assign host_ack = host_ack_reg;



  reg trans_reg;
  reg trans_regR;
  reg trans_regRR;





  reg resp_reg;
  reg resp_regR;
  reg resp_regRR;






  reg wait_clear;

  always @(posedge host_clk) begin
    host_ack_reg <= 1'b0;

    resp_regR  <= resp_reg;
    resp_regRR <= resp_regR;

    if (host_rst) begin
      trans_reg  <= 1'b0;
      wait_clear <= 1'b0;
      host_ack_reg <= 1'b0;
    end else begin
      if (host_en) begin
        trans_reg  <= 1'b1;
        wait_clear <= 1'b0;
      end
      if (resp_regRR) begin
        trans_reg  <= 1'b0;
        wait_clear <= 1'b1;
      end
      if (wait_clear && !resp_regRR) begin
        wait_clear   <= 1'b0;
        host_ack_reg <= 1'b1;
      end
    end
  end

  reg qdr_trans_strb, qdr_resp_ready;
  reg hshake_state;

  localparam RESP_IDLE = 1'b0;
  localparam RESP_BUSY = 1'b1;

  always @(posedge qdr_clk) begin
    qdr_trans_strb <= 1'b0;

    trans_regR  <= trans_reg;
    trans_regRR <= trans_regR;
    if (qdr_rst) begin
      hshake_state <= RESP_IDLE;
      resp_reg   <= 1'b0;
    end else begin
      case (hshake_state)
        RESP_IDLE: begin
          if (trans_regRR) begin
            qdr_trans_strb <= 1'b1;
            host_addr_reg  <= host_addr;
            host_datai_reg <= host_datai;
            host_be_reg    <= host_be;
            host_rnw_reg   <= host_rnw;
            hshake_state   <= RESP_BUSY;
          end
        end
        RESP_BUSY: begin
          if (qdr_resp_ready)
            resp_reg  <= 1'b1;

          if (!trans_regRR) begin
            resp_reg  <= 1'b0;
            hshake_state   <= RESP_IDLE;
          end
        end
      endcase
    end
  end



  reg [QDR_LATENCY - 1:0] qvld_shifter;

  reg [1:0] resp_state;
  localparam IDLE    = 2'd0;
  localparam WAIT    = 2'd1;
  localparam COLLECT = 2'd2;
  localparam FINAL   = 2'd3;

  always @(posedge qdr_clk) begin
    qdr_resp_ready <= 1'b0;
    second_cycle   <= 1'b0;
    qvld_shifter   <= {qvld_shifter[QDR_LATENCY - 2:0], resp_state == WAIT && qdr_ack};

    if (qdr_rst) begin
      resp_state <= IDLE;
    end else begin
      case (resp_state)
        IDLE: begin
          if (qdr_trans_strb) begin
            resp_state <= WAIT;
          end
        end
        WAIT: begin
          if (qdr_ack) begin
            second_cycle <= 1'b1;
            resp_state <= COLLECT;
          end
        end
        COLLECT: begin
          if (!host_rnw_reg) begin
            resp_state <= IDLE;
            qdr_resp_ready <= 1'b1;
          end else if (qvld_shifter[QDR_LATENCY-1]) begin
            if (!second_word) begin
              resp_state <= IDLE;
              host_datao_reg <= {qdr_q[34:27], qdr_q[25:18], qdr_q[16:9], qdr_q[7:0]};
              qdr_resp_ready <= 1'b1;
            end else begin
              resp_state <= FINAL;
            end
          end
        end
        FINAL: begin
          qdr_resp_ready <= 1'b1;
          host_datao_reg <= {qdr_q[34:27], qdr_q[25:18], qdr_q[16:9], qdr_q[7:0]};
          resp_state <= IDLE;
        end
      endcase
    end
  end

  assign qdr_req = qdr_trans_strb || resp_state == WAIT;

endmodule

module run (
    input  wire       rst,
    input  wire       clk,
    input  wire       i_vl,
    input  wire [7:0] i_x,
    input  wire [7:0] i_px,
    input  wire       i_s,
    input  wire       i_q,
    input  wire [3:0] i_cn,
    output reg        o_vl,
    output reg  [4:0] o_zc,
    output reg  [8:0] o_bv,
    output reg  [3:0] o_bc
);


localparam [4:0] LIMIT = 5'd23;


function  signed [8:0] modrange;
    input signed [9:0] val;
    reg   signed [9:0] new_val;
begin
    new_val = val;
    if ( new_val < 10'sd0 )
        new_val = new_val + 10'sd256;
    if ( new_val >= 10'sd128 )
        new_val = new_val - 10'sd256;
    modrange = new_val[8:0];
end
endfunction


function  [ 3:0] get_k_r;
    input [ 6:0] N;
    input [12:0] A;
    input [ 0:0] q;
    reg   [18:0] Nt, At;
    integer i;
begin
    Nt = {12'h0, N};
    At = { 6'h0, A};
    get_k_r = 4'd0;
    if (q)
        At = At + {13'd0, N[6:1]};
    for (i=0; i<13; i=i+1)
        if ((Nt<<i) < At)
            get_k_r = get_k_r + 4'd1;
end
endfunction


function  [6:0] N_update;
    input [6:0] N;
begin
    N_update = N;
    if (N[6])
        N_update = (N_update >>> 1);
    N_update = N_update + 7'd1;
end
endfunction


function  [5:0] B_update;
    input [0:0] errm0, reset;
    input [5:0] B;
begin
    B_update = B;
    if (errm0)
        B_update = B_update + 6'd1;
    if (reset)
        B_update = (B_update >>> 1);
end
endfunction


function  [12:0] A_update;
    input [ 0:0] reset, aeqb;
    input [ 9:0] merr;
    input [12:0] A;
    reg   [10:0] Ap;
begin
    Ap = {1'b0, merr} + {10'd0, ~aeqb};
    A_update = A + {3'b0, Ap[10:1]};
    if (reset)
        A_update = (A_update >>> 1);
end
endfunction



reg [ 6:0] Nram [0:1];
reg [12:0] Aram [0:1];
reg [ 5:0] Bram [0:1];

reg              a_vl;
reg        [7:0] a_x;
reg        [7:0] a_px;
reg              a_q;
reg              a_s;
reg        [3:0] a_cn;

reg              b_vl;
reg              b_q;
reg        [6:0] b_N;
reg signed [9:0] b_err;
reg        [3:0] b_cn;

reg              c_vl;
reg              c_q;
reg        [6:0] c_N;
reg signed [8:0] c_err;
reg        [3:0] c_cn;

reg              d_vl;
reg              d_q;
reg        [6:0] d_N;
reg              d_2BltN;
reg              d_errne0;
reg              d_errgt0;
reg        [8:0] d_abserr;
reg        [3:0] d_cn;

reg              e_vl;
reg        [3:0] e_k;
reg        [9:0] e_merr;
reg        [3:0] e_cn;

reg              f_vl;
reg        [3:0] f_k;
reg        [8:0] f_merr;
reg        [8:0] f_merr_sk;
reg        [4:0] f_lm;

reg         g_vl;
reg  [ 4:0] g_zc;
reg  [ 8:0] g_bv;
reg  [ 3:0] g_bc;

reg         h_vl;
reg  [ 4:0] h_zc;
reg  [ 8:0] h_bv;
reg  [ 3:0] h_bc;

reg         j_vl;
reg  [ 4:0] j_zc;
reg  [ 8:0] j_bv;
reg  [ 3:0] j_bc;

reg         k_vl;
reg  [ 4:0] k_zc;
reg  [ 8:0] k_bv;
reg  [ 3:0] k_bc;


always @ (posedge clk) begin
    a_vl <= i_vl & (~rst);
    a_x <= i_x;
    a_px <= i_px;
    a_q <= i_q;
    a_s <= i_s;
    a_cn <= i_cn;
end


wire [6:0] a_N = Nram[a_q];

always @ (posedge clk) begin
    b_vl <= a_vl & (~rst);
    if (rst) begin
        Nram[0] <= 7'd1;
        Nram[1] <= 7'd1;
    end else if (a_vl)
        Nram[a_q] <= N_update(a_N);
    b_q <= a_q;
    b_N <= a_N;
    if (a_s)
        b_err <= $signed({2'h0, a_px}) - $signed({2'h0, a_x});
    else
        b_err <= $signed({2'h0, a_x}) - $signed({2'h0, a_px});
    b_cn <= a_cn;
end


always @ (posedge clk) begin
    c_vl <= b_vl & (~rst);
    c_q <= b_q;
    c_N <= b_N;
    c_err <= modrange(b_err);
    c_cn <= b_cn;
end


wire [5:0] c_B = Bram[c_q];

always @ (posedge clk) begin
    d_vl <= c_vl & (~rst);
    if (rst) begin
        Bram[0] <= 6'd0;
        Bram[1] <= 6'd0;
    end else if (c_vl)
        Bram[c_q] <= B_update((c_err<9'sd0), c_N[6], c_B);
    d_q <= c_q;
    d_N <= c_N;
    d_2BltN <= ({c_B,1'b0} < c_N);
    d_errne0 <= c_err != 9'sd0;
    d_errgt0 <= c_err >  9'sd0;
    if (c_err < 9'sd0)
        d_abserr <= $unsigned(-c_err);
    else
        d_abserr <= $unsigned( c_err);
    d_cn <= c_cn;
end


wire [12:0] d_A    = Aram[d_q];
wire [ 3:0] d_k    = get_k_r(d_N, d_A, d_q);
wire        d_map  = d_errne0 & (d_errgt0 == ((d_k==4'd0) & d_2BltN));
wire [ 9:0] d_merr = ({d_abserr, 1'b0} - {9'd0,d_q} - {9'd0,d_map});

always @ (posedge clk) begin
    e_vl <= d_vl & (~rst);
    if (rst) begin
        Aram[0] <= 13'd4;
        Aram[1] <= 13'd4;
    end else if (d_vl)
        Aram[d_q] <= A_update(d_N[6], d_q, d_merr, d_A);
    e_k <= d_k;
    e_merr <= d_merr[8:0];
    e_cn <= d_cn;
end


wire [9:0] e_merr_sk_e = (e_merr >> e_k);

always @ (posedge clk) begin
    f_vl <= e_vl & (~rst);
    f_k <= e_k;
    f_merr <= e_merr[8:0];
    f_merr_sk <= e_merr_sk_e[8:0];
    f_lm <= LIMIT - {1'b0, e_cn};
end


always @ (posedge clk) begin
    g_vl <= f_vl & (~rst);
    if (f_merr_sk < {4'd0,f_lm}) begin
        g_zc <= f_merr_sk[4:0] + {4'h0, f_vl};
        g_bv <= f_merr;
        g_bc <= f_k;
    end else begin
        g_zc <= f_lm + {4'h0, f_vl};
        g_bv <= f_merr - 9'd1;
        g_bc <= 4'd8;
    end
end


always @ (posedge clk) begin
    h_vl <= g_vl & (~rst);
    h_zc <= g_zc;
    h_bv <= g_bv;
    h_bc <= g_bc;
end


always @ (posedge clk) begin
    j_vl <= h_vl & (~rst);
    j_zc <= h_zc;
    j_bv <= h_bv;
    j_bc <= h_bc;
end


always @ (posedge clk) begin
    k_vl <= j_vl & (~rst);
    k_zc <= j_zc;
    k_bv <= j_bv;
    k_bc <= j_bc;
end


always @ (posedge clk) begin
    o_vl <= k_vl & (~rst);
    o_zc <= k_zc;
    o_bv <= k_bv;
    o_bc <= k_bc;
end

endmodule

`timescale 1ns / 1ps

module CacheController(WE,ADDR,DIN,FOUND,MD,RREQ,RST,CLK,MADDR,MWE,MRDY,CDOUT,CDIN,CWE,DOUT,RDY,LIM,SIGNED);

	parameter START = 1;
	parameter WAIT = 3;
	parameter CHECK_CACHE = 4;
	parameter WAIT_MREAD = 5;
	parameter CACHE_UPDATE = 6;
	parameter WAIT_MWRITE = 7;
	parameter MREAD_BUF = 8;




	parameter W_MASK_B = {{24{1'b0}},{8{1'b1}}};
	parameter W_MASK_H = {{16{1'b0}},{16{1'b1}}};
	parameter W_MASK_W = {32{1'b1}};

	input [31:0] ADDR, DIN, CDOUT;
	input [2:0] LIM;
	inout [7:0] MD;
	output reg[31:0] MADDR, DOUT;
	output reg[31+3+1:0] CDIN;
	input WE, CLK, FOUND, RREQ, MRDY, RST, SIGNED;
	output reg MWE, CWE, RDY;
	reg [31:0] mask; 
	reg [3:0] state;
	reg [7:0] mdin [3:0];
	reg [7:0] rbuf [3:0];
	reg [2:0] incr;
	wire [31:0] flattened;
	wire io_flag;










	assign MD = MWE ? mdin[incr] : 8'bZ;
	assign flattened = {rbuf[3],rbuf[2],rbuf[1],rbuf[0]};
	assign io_flag = ADDR[31];

	always @(*)
	begin
		case(LIM)
			0: mask = W_MASK_B;
			1: mask = W_MASK_H;
			default: mask = W_MASK_W;
		endcase
	end

	always @(posedge CLK)
	begin
		if (RST) begin
			state <= START;
		end else begin
			case (state)




				START: begin
						RDY <= 1;
						CWE <= 0;
						MWE <= 0;
						incr <= 0;
						state <= WAIT;
					end
				WAIT: begin
						RDY <= 0;


						CDIN <= {SIGNED,LIM,(DIN & mask)};
						MADDR <= ADDR;

						if (WE & !io_flag) begin

							MWE <= 1;
							{mdin[3],mdin[2],mdin[1],mdin[0]} <= DIN;
							state <= WAIT_MWRITE;

						end else if (RREQ & !io_flag) begin
							{rbuf[3],rbuf[2],rbuf[1],rbuf[0]} <= {32{1'b0}};
							state <= CHECK_CACHE;
						end
					end
				CHECK_CACHE: begin

						if (FOUND) begin
							DOUT <= CDOUT;
							state <= START;

						end else begin
							state <= WAIT_MREAD;
						end
					end
				WAIT_MREAD: begin
						if (MRDY) begin
							state <= MREAD_BUF;
						end
					end



				MREAD_BUF: begin
						MADDR <= MADDR + 1;
						incr <= incr + 1;
						rbuf[incr] <= MD;
						if (incr >= LIM) begin						
							state <= CACHE_UPDATE;
						end else begin
							state <= WAIT_MREAD;
						end
					end


				CACHE_UPDATE: begin

						case (LIM)

							0: {CDIN,DOUT} <= {SIGNED,LIM,{2{{24{(SIGNED & flattened[7])}},flattened[7:0]}}};
							1: {CDIN,DOUT} <= {SIGNED,LIM,{2{{16{(SIGNED & flattened[15])}},flattened[15:0]}}};
							default: {CDIN,DOUT} <= {SIGNED,LIM,{2{flattened}}};
						endcase
						state <= START;
					end
				WAIT_MWRITE: begin
						if (MRDY) begin
							if (incr >= LIM) begin
								state <= START;
							end else begin
								MADDR <= MADDR + 1;
								incr <= incr + 1;
							end
						end
					end
				default: state <= START;
			endcase

		end 
	end 

endmodule

module control_unit(
    input [31:0] instruction,      
    input branch_taken,            
    output [3:0] alu_control,      
    output reg [2:0] store_select, 
    output reg [2:0] data_mem_select, 
    output reg [2:0] imm_select,   
    output reg [2:0] branch_select, 
    output  reg_write_ctrl,     
    output reg data_mem_write_ctrl,
    output reg [2:0] write_data_source, 
    output reg A_source_select,   
    output reg B_source_select,   
    output reg [1:0] pc_source_select, 
    output [4:0] destination_reg,  
    output [4:0] source_reg_1,     
    output [4:0] source_reg_2,     
    output reg halt_signal        
);

    wire [6:0] funct7;
    wire [6:0] opcode;
    wire [2:0] funct3;


    assign opcode = instruction[6:0];
    assign funct7 = instruction[31:25];
    assign source_reg_2 = instruction[24:20];
    assign source_reg_1 = instruction[19:15];
    assign funct3 = instruction[14:12];
    assign destination_reg = instruction[11:7];

    wire is_alu_reg, is_alu_imm, is_branch, is_jalr, is_jal, is_auipc, is_lui, is_load, is_store, is_system;


    assign is_alu_reg = (opcode == 7'b0110011); 
    assign is_alu_imm = (opcode == 7'b0010011); 
    assign is_branch = (opcode == 7'b1100011); 
    assign is_jalr   = (opcode == 7'b1100111);   
    assign is_jal    = (opcode == 7'b1101111);    
    assign is_auipc  = (opcode == 7'b0010111);  
    assign is_lui    = (opcode == 7'b0110111);    
    assign is_load   = (opcode == 7'b0000011);   
    assign is_store  = (opcode == 7'b0100011);  
    assign is_system = (opcode == 7'b1110011); 


    assign reg_write_ctrl = is_alu_reg || is_alu_imm || is_load || is_lui || is_auipc || is_jal || is_jalr;

    assign alu_control = {funct7[5], funct3};


    always @(*) begin
        if (is_branch) begin
            case (funct3)
                3'b000: branch_select = 3'b000; 
                3'b001: branch_select = 3'b001; 
                3'b100: branch_select = 3'b011; 
                3'b101: branch_select = 3'b010; 
                3'b110: branch_select = 3'b100; 
                3'b111: branch_select = 3'b101; 
                default: branch_select = 3'b111; 
            endcase
        end else if (is_jal || is_jalr) begin
            branch_select = 3'b110; 
        end else begin
            branch_select = 3'b111; 
        end
    end


    always @(*) begin
        if (is_load) begin
            case (funct3)
                3'b000: data_mem_select = 3'b000; 
                3'b001: data_mem_select = 3'b001; 
                3'b010: data_mem_select = 3'b010; 
                3'b100: data_mem_select = 3'b100; 
                3'b101: data_mem_select = 3'b101; 
                default: data_mem_select = 3'b111; 
            endcase
        end else begin
            data_mem_select = 3'b111; 
        end
    end


    always @(*) begin
        if (is_store) begin
            case (funct3[1:0])
                2'b00: store_select = 2'b00; 
                2'b01: store_select = 2'b01; 
                2'b10: store_select = 2'b10; 
                default: store_select = 2'b11; 
            endcase
        end else begin
            store_select = 2'b11; 
        end
    end


    always @(*) begin
        if (is_alu_imm || is_load) begin
            imm_select = 3'b000; 
        end else if (is_branch) begin
            imm_select = 3'b010; 
        end else if (is_store) begin
            imm_select = 3'b001; 
        end else if (is_jal || is_jalr) begin
            imm_select = 3'b100; 
        end else if (is_lui || is_auipc) begin
            imm_select = 3'b011; 
        end else begin
            imm_select = 3'b111; 
        end
    end


    always @(*) begin
        if (is_store) begin
            data_mem_write_ctrl = 1'b1;
        end else begin
            data_mem_write_ctrl = 1'b0;
        end
    end


    always @(*) begin
        if (is_alu_reg) begin
            A_source_select = 1'b0; 
            B_source_select = 1'b0; 
        end else if (is_branch || is_auipc || is_jal) begin
            A_source_select = 1'b1; 
            B_source_select = 1'b1; 
        end else if (is_jalr || is_alu_imm || is_load || is_store) begin
            A_source_select = 1'b0; 
            B_source_select = 1'b1; 
        end else begin
            A_source_select = 1'b0; 
            B_source_select = 1'b0; 
        end
    end


    always @(*) begin
        if (is_alu_reg || is_alu_imm) begin
            write_data_source = 2'b00; 
        end else if (is_load) begin
            write_data_source = 2'b01; 
        end else if (is_jal || is_jalr) begin
            write_data_source = 2'b10; 
        end else if (is_lui) begin
            write_data_source = 2'b11; 
        end else if (is_auipc) begin
            write_data_source = 3'b100; 
        end else begin
            write_data_source = 3'b111; 
        end
    end


    always @(*) begin
        if (is_jalr) begin
            pc_source_select = 2'b01;  
        end else if (is_jal || branch_taken) begin
            pc_source_select = 2'b10;  
        end else begin
            pc_source_select = 2'b00;  
        end
    end


    always @(*) begin
        if (is_system) begin
            halt_signal = 1'b1;
        end else begin
            halt_signal = 1'b0;
        end
    end

endmodule

module i2s_read(
    clk_p,
    rst,
    adclrc,
    adcdat,
    data,
    data_en
);

input clk_p;
input rst;
input adclrc;
input adcdat;

output [15:0] data;
output data_en;

localparam [2:0]
    STATE_IDLE = 3'd0,
    STATE_LEFT = 3'd1,
    STATE_LEFT_WAIT = 3'd2,
    STATE_RIGHT_WAIT = 3'd3;

reg [2:0] state_r, state_w;
reg [3:0] counter_r, counter_w;
reg [15:0] buffer_r, buffer_w;
reg data_en_r, data_en_w;

assign data = buffer_r;
assign data_en = data_en_r;

always @(*) begin
    state_w = state_r;
    counter_w = counter_r;
    buffer_w = buffer_r;
    data_en_w = data_en_r;
    case (state_r)
        STATE_IDLE:
            if (adclrc == 1'b0) begin
                state_w = STATE_LEFT_WAIT;
            end
        STATE_LEFT: begin
            if (counter_r == 4'd15) begin
                data_en_w = 1'b1;
                state_w = STATE_LEFT_WAIT;
            end
            counter_w = counter_r + 1;
            buffer_w = {buffer_r[14:0], adcdat};
        end
        STATE_LEFT_WAIT: begin
            data_en_w = 1'b0;
            if (adclrc == 1'b1) begin
                state_w = STATE_RIGHT_WAIT;
                counter_w = 4'd0;
                buffer_w = 16'd0;
            end
        end
        STATE_RIGHT_WAIT: begin
            if (adclrc == 1'b0) begin
                state_w = STATE_LEFT;
                counter_w = 4'd0;
                buffer_w = 16'd0;
            end
        end
    endcase
end

always @(posedge clk_p or negedge rst) begin
    if (rst == 1'b0) begin
        state_r <= STATE_IDLE;
        counter_r <= 4'd0;
        buffer_r <= 16'd0;
        data_en_r <= 1'b0;
    end
    else begin
        state_r <= state_w;
        counter_r <= counter_w;
        buffer_r <= buffer_w;
        data_en_r <= data_en_w;
    end
end

endmodule

module ONE_YEAR (
    input  wire                         CLK,
    input  wire                         RST,            
    input  wire                         FSM_RST,        
    input  wire                         TRG,            
    output reg [4:0]                    STATE_OUT       
);





parameter JANUARY   = 4'd0;
parameter FEBRUARY  = 4'd1;
parameter MARCH     = 4'd2;
parameter APRIL     = 4'd3;
parameter MAY       = 4'd4;
parameter JUNE      = 4'd5;
parameter JULY      = 4'd6;
parameter AUGUST    = 4'd7;
parameter SEPTEMBER = 4'd8;
parameter OCTOBER   = 4'd9;
parameter NOVEMBER  = 4'd10;
parameter DECEMBER  = 4'd11;







reg                                     trg_ff1;
reg                                     trg_ff2;
reg                                     trg_redg;


reg                                     j2f_ff1;
reg                                     j2f_ff2;
reg                                     j2f_trg;


reg [3:0]                               current_state;
reg [3:0]                               next_state;







always @ (posedge CLK or posedge RST) begin
    if (RST) begin
        trg_ff1     <=  1'b0;
        trg_ff2     <=  1'b0;
        trg_redg    <=  1'b0;
    end else begin
        trg_ff1     <=  TRG;
        trg_ff2     <=  trg_ff1;
        trg_redg    <=  trg_ff1 & (~trg_ff2);
    end
end



always @ (posedge CLK or posedge RST) begin
    if (RST) begin
        j2f_ff1     <=  1'b0;
        j2f_ff2     <=  1'b0;
        j2f_trg     <=  1'b0;
    end else begin
        j2f_ff1     <=  1'b1;
        j2f_ff2     <=  j2f_ff1;
        j2f_trg     <=  j2f_ff2;
    end
end



always @ (posedge CLK or posedge FSM_RST) begin
    if (FSM_RST) begin
        current_state   <=  JANUARY;
    end else begin
        current_state   <=  next_state;
    end
end

always @ (current_state or j2f_trg or trg_redg) begin
    case (current_state)
        JANUARY     : begin
                if (j2f_trg == 1'b1)
                    next_state  <=  FEBRUARY;     
                else
                    next_state  <=  current_state;
            end

        FEBRUARY    : begin
                if (trg_redg == 1'b1)
                    next_state  <=  MARCH;
                else
                    next_state  <=  current_state;
            end

        MARCH    : begin
                if (trg_redg == 1'b1)
                    next_state  <=  APRIL;
                else
                    next_state  <=  current_state;
            end

        APRIL    : begin
                if (trg_redg == 1'b1)
                    next_state  <=  MAY;
                else
                    next_state  <=  current_state;
            end

        MAY    : begin
                if (trg_redg == 1'b1)
                    next_state  <=  JUNE;
                else
                    next_state  <=  current_state;
            end

        JUNE    : begin
                if (trg_redg == 1'b1)
                    next_state  <=  JULY;
                else
                    next_state  <=  current_state;
            end

        JULY    : begin
                if (trg_redg == 1'b1)
                    next_state  <=  AUGUST;
                else
                    next_state  <=  current_state;
            end

        AUGUST    : begin
                if (trg_redg == 1'b1)
                    next_state  <=  SEPTEMBER;
                else
                    next_state  <=  current_state;
            end

        SEPTEMBER    : begin
                if (trg_redg == 1'b1)
                    next_state  <=  OCTOBER;
                else
                    next_state  <=  current_state;
            end

        OCTOBER    : begin
                if (trg_redg == 1'b1)
                    next_state  <=  NOVEMBER;
                else
                    next_state  <=  current_state;
            end

        NOVEMBER    : begin
                if (trg_redg == 1'b1)
                    next_state  <=  DECEMBER;
                else
                    next_state  <=  current_state;
            end

        DECEMBER    : begin
                if (trg_redg == 1'b1)
                    next_state  <=  JANUARY;
                else
                    next_state  <=  current_state;
            end

        default     : 
            next_state  <=  JANUARY;

    endcase
end



always @ (posedge CLK or posedge RST) begin
    if (RST) begin
        STATE_OUT   <=  5'b10000;
    end else begin
        case (current_state)
            JANUARY     : STATE_OUT   <=  5'b00000 + 5'd1;
            FEBRUARY    : STATE_OUT   <=  5'b00000 + 5'd2;
            MARCH       : STATE_OUT   <=  5'b00000 + 5'd3;
            APRIL       : STATE_OUT   <=  5'b00000 + 5'd4;
            MAY         : STATE_OUT   <=  5'b00000 + 5'd5;
            JUNE        : STATE_OUT   <=  5'b00000 + 5'd6;
            JULY        : STATE_OUT   <=  5'b00000 + 5'd7;
            AUGUST      : STATE_OUT   <=  5'b00000 + 5'd8;
            SEPTEMBER   : STATE_OUT   <=  5'b00000 + 5'd9;
            OCTOBER     : STATE_OUT   <=  5'b00000 + 5'd10;
            NOVEMBER    : STATE_OUT   <=  5'b00000 + 5'd11;
            DECEMBER    : STATE_OUT   <=  5'b00000 + 5'd12;
            default     : STATE_OUT   <=  5'b11111;         
        endcase
    end
end


endmodule

module Moore_State_Machine (
    input wire clk,
    input wire reset,
    input wire input_signal,
    output reg output_signal
);


parameter STATE_A = 2'b00;
parameter STATE_B = 2'b01;
parameter STATE_C = 2'b10;
parameter STATE_D = 2'b11;


reg [1:0] state_reg;
always @(posedge clk or posedge reset) begin
    if (reset) begin
        state_reg <= STATE_A;
    end else begin
        case (state_reg)
            STATE_A: state_reg <= (input_signal) ? STATE_B : STATE_C;
            STATE_B: state_reg <= STATE_C;
            STATE_C: state_reg <= STATE_D;
            STATE_D: state_reg <= STATE_A;
        endcase
    end
end


always @(*) begin
    case (state_reg)
        STATE_A: output_signal = 1'b0;
        STATE_B: output_signal = 1'b1;
        STATE_C: output_signal = 1'b0;
        STATE_D: output_signal = 1'b1;
    endcase
end

endmodule

module ad7606_if(
	input                        clk,
	input                        rst_n,
	input [15:0]                 ad_data,             
	input                        ad_busy,             
	input                        first_data,          
	output [2:0]                 ad_os,               
	output reg                   ad_cs,               
	output reg                   ad_rd,               
	output reg                   ad_reset,            
	output reg                   ad_convstab,         
	output                       ad_data_valid,
	output reg [15:0]            ad_ch1,
	output reg [15:0]            ad_ch2,
	output reg [15:0]            ad_ch3,
	output reg [15:0]            ad_ch4,
	output reg [15:0]            ad_ch5,
	output reg [15:0]            ad_ch6,
	output reg [15:0]            ad_ch7,
	output reg [15:0]            ad_ch8
);



reg [15:0]  rst_cnt;
reg [5:0]   i;
reg [3:0]   state;

parameter IDLE=4'd0;
parameter AD_CONV=4'd1;
parameter Wait_1=4'd2;
parameter Wait_busy=4'd3;
parameter READ_CH1=4'd4;
parameter READ_CH2=4'd5;
parameter READ_CH3=4'd6;
parameter READ_CH4=4'd7;
parameter READ_CH5=4'd8;
parameter READ_CH6=4'd9;
parameter READ_CH7=4'd10;
parameter READ_CH8=4'd11;
parameter READ_DONE=4'd12;

assign ad_os=3'b000;
assign ad_data_valid = state == READ_DONE ? 1'b1 : 1'b0;

always@(posedge clk or negedge rst_n)
begin
	if(rst_n == 1'b0)
	begin
		rst_cnt <= 16'd0;
		ad_reset <= 1'b0;
	end
	else if(rst_cnt < 16'hffff)
	begin
		rst_cnt <= rst_cnt + 16'd1;
		ad_reset <= 1'b1;
	end
	else
		ad_reset <= 1'b0;
end

always@(posedge clk)
begin
	if(ad_reset==1'b1)
	begin
		state <= IDLE;
		ad_ch1 <= 0;
		ad_ch2 <= 0;
		ad_ch3 <= 0;
		ad_ch4 <= 0;
		ad_ch5 <= 0;
		ad_ch6 <= 0;
		ad_ch7 <= 0;
		ad_ch8 <= 0;
		ad_cs <= 1'b1;
		ad_rd <= 1'b1;
		ad_convstab <= 1'b1;
		i <= 6'd0;
	end
	else
	begin
		case(state)
			IDLE:
			begin
				ad_cs<=1'b1;
				ad_rd<=1'b1;
				ad_convstab<=1'b1;
				if(i==20)
				begin
					i <= 6'd0;
					state<=AD_CONV;
				end
				else
					i <= i + 6'd1;
			end
			AD_CONV:
			begin
				if(i==2)                                  
				begin                          
					i <= 6'd0;
					state<=Wait_1;
					ad_convstab<=1'b1;
				end
				else 
				begin
					i <= i + 6'd1;
					ad_convstab<=1'b0;       
				end
			end
			Wait_1:
			begin
				if(i==5) 
				begin                                     
					i <= 6'd0;
					state<=Wait_busy;
				end
				else
					i <= i + 6'd1;
			end
			Wait_busy:
			begin
				if(ad_busy==1'b0) 
				begin                                     
					i <= 6'd0;
					state<=READ_CH1;
				end
			end
			READ_CH1:
			begin
				ad_cs<=1'b0;                              
				if(i==3) 
				begin
					ad_rd<=1'b1;
					i <= 6'd0;
					ad_ch1<=ad_data;                        
					state<=READ_CH2;
				end
				else 
				begin
					ad_rd<=1'b0;
					i <= i + 6'd1;
				end
			end
			READ_CH2:
			begin
				if(i==3) 
				begin
					ad_rd<=1'b1;
					i <= 6'd0;
					ad_ch2<=ad_data;                        
					state<=READ_CH3;
				end
				else 
				begin
					ad_rd<=1'b0;
					i <= i + 6'd1;
				end
			end
			READ_CH3:
			begin
				if(i==3) 
				begin
					ad_rd<=1'b1;
					i <= 6'd0;
					ad_ch3<=ad_data;                        
					state<=READ_CH4;
				end
				else 
				begin
					ad_rd<=1'b0;
					i <= i + 6'd1;
				end
			end
			READ_CH4: 
			begin
				if(i==3) 
				begin
					ad_rd<=1'b1;
					i <= 6'd0;
					ad_ch4<=ad_data;                        
					state<=READ_CH5;
				end
				else 
				begin
					ad_rd<=1'b0;
					i <= i + 6'd1;
				end
			end
			READ_CH5:
			begin
				if(i==3) 
				begin
					ad_rd<=1'b1;
					i <= 6'd0;
					ad_ch5<=ad_data;                        
					state<=READ_CH6;
				end
				else 
				begin
					ad_rd<=1'b0;
					i <= i + 6'd1;
				end
			end
			READ_CH6:
			begin
				if(i==3) 
				begin
					ad_rd<=1'b1;
					i <= 6'd0;
					ad_ch6<=ad_data;                        
					state<=READ_CH7;
				end
				else 
				begin
					ad_rd<=1'b0;
					i <= i + 6'd1;
				end
			end
			READ_CH7:
			begin
				if(i==3) 
				begin
					ad_rd<=1'b1;
					i <= 6'd0;
					ad_ch7<=ad_data;                        
					state<=READ_CH8;
				end
				else 
				begin
					ad_rd<=1'b0;
					i <= i + 6'd1;
				end
			end
			READ_CH8:
			begin
				if(i==3) 
				begin
					ad_rd<=1'b1;
					i <= 6'd0;
					ad_ch8<=ad_data;                        
					state<=READ_DONE;
				end
				else 
				begin
					ad_rd<=1'b0;
					i <= i + 6'd1;
				end
			end
			READ_DONE:
			begin
				ad_rd<=1'b1;
				ad_cs<=1'b1;
				state<=IDLE;
			end
			default:
				state<=IDLE;
		 endcase
	end

 end

endmodule

module uctl_ctrlAhbTx#(
   parameter  CNTR_WD   = 20 ,
              ADDR_SIZE = 32 ,
              DATA_SIZE = 32 ,
              ADD_WIDTH = 4  


)(









   input  wire                    uctl_sysClk          ,
   input  wire                    uctl_sysRst_n        ,




   input  wire [CNTR_WD   -1  :0] dmaTx2ctrl_len       ,
   input  wire                    dmaTx2ctrl_sRdWr     ,
   input  wire                    dmaTx2ctrl_stransEn  ,
   input  wire [ADDR_SIZE -1  :0] dmaTx2ctrl_sRdAddr   ,

   output reg                     ctrl2dmaTx_dataDn    ,




   input  wire [5           -1:0] words_inFifo         ,




   input  wire                    ahbc2ctrl_ack        ,
   input  wire                    ahbc2ctrl_addrDn     ,
   input  wire                    ahbc2ctrl_dataDn     ,
   input  wire [31           :0]  ahbc2ctrl_sWrAddr     ,

   output reg                     ctrl2ahbc_trEn       ,
   output wire [4            :0]  ctrl2ahbc_beats      ,
   output wire [2            :0]  ctrl2ahbc_hSize      ,  
   output wire [ADDR_SIZE -1 :0]  ctrl2ahbc_sRdAddr    ,  
   output reg                     ctrl2ahbc_sRdWr 

   );

   localparam  IDLE           = 3'b000,
               MKBURST        = 3'b001,
               SUBTRREQ       = 3'b010,
               SUBTRANS       = 3'b011,
               WTDDN          = 3'b100,

               WORD           = 3'b010 ,
               HWORD          = 3'b001 ,
               BYTES          = 3'b000 ,


               INCR16         = 3'b111,                           
               INCR           = 3'b001;  

  localparam   DEPTH     = 2**ADD_WIDTH;





   reg  [2                    :0] nxt_state            ,
                                  cur_state            ;
   reg  [CNTR_WD            -1:0] nBytes               ; 
   reg                            nBytes_ld            ;
   reg                            nBytes_decr          ;
   reg                            sys_addr_ld          ;
   reg                            ctrl2ahbc_trEn_nxt   ;
   reg  [2                    :0] ctrlHsize            ; 
   reg  [4                    :0] ctrlBeats            ; 
   reg  [5                  -1:0] nWords_delta         ;
   reg  [7                  -1:0] nBytes_delta         ; 
   wire                           threshold            ;
   reg [31            :0]         sys_rdAdd            ;
   reg                            RdWr_ld              ;
   reg                            idle_state           ; 

   always @ (posedge uctl_sysClk , negedge  uctl_sysRst_n) begin
      if(!uctl_sysRst_n) begin
         sys_rdAdd <= {32{1'b0}};
      end
      else if(sys_addr_ld) begin
         sys_rdAdd <= dmaTx2ctrl_sRdAddr;
      end 
      else if(ahbc2ctrl_addrDn && !idle_state) begin
         sys_rdAdd <= ahbc2ctrl_sWrAddr;
      end
   end


   always @ (posedge uctl_sysClk , negedge  uctl_sysRst_n) begin
      if(!uctl_sysRst_n) begin
         ctrl2ahbc_trEn    <= 1'b0;
      end
      else begin 
         ctrl2ahbc_trEn    <= ctrl2ahbc_trEn_nxt;
      end
   end

   always @ (posedge uctl_sysClk , negedge  uctl_sysRst_n) begin
      if(!uctl_sysRst_n) begin
         ctrl2ahbc_sRdWr    <= 1'b0;
      end
      else if(RdWr_ld == 1'b1) begin 
         ctrl2ahbc_sRdWr    <= dmaTx2ctrl_sRdWr;
      end
   end



   always @ (posedge uctl_sysClk , negedge  uctl_sysRst_n) begin
      if(!uctl_sysRst_n) begin
         nBytes <= {CNTR_WD{1'b0}};             
      end

      else if(nBytes_ld) begin 
         nBytes <= dmaTx2ctrl_len;
      end
      else if(nBytes_decr) begin
         nBytes <=  nBytes - nBytes_delta;
      end
   end

   always@(*) begin
      if(nBytes >= 20'd64) begin
         ctrlHsize    =  WORD  ;
         ctrlBeats    =  5'd16;
         nBytes_delta =  7'd64;
         nWords_delta =  5'd16;
      end
      else if (nBytes < 4) begin
         ctrlHsize    =  BYTES;
         ctrlBeats    =  nBytes[4:0];
         nBytes_delta =  nBytes[6:0];
         nWords_delta =  5'd1;
      end
      else begin 
         ctrlHsize    =  WORD;

         ctrlBeats    =   nBytes[6:2];
         nBytes_delta =  {nBytes[6:2], 2'b00};
         nWords_delta =  nBytes[6:2];
      end
   end

   assign threshold        = ((DEPTH - words_inFifo) >= nWords_delta)? 1'b1 : 1'b0; 
   assign ctrl2ahbc_beats  = ctrlBeats   ;
   assign ctrl2ahbc_hSize  = ctrlHsize   ;
   assign ctrl2ahbc_sRdAddr = sys_rdAdd ;



   always @ (*) begin
   nxt_state          = cur_state ;
   nBytes_ld          = 1'b0;
   ctrl2ahbc_trEn_nxt = 1'b0;
   ctrl2dmaTx_dataDn  = 1'b0;
   sys_addr_ld        = 1'b0;
   nBytes_decr        = 1'b0;
   RdWr_ld            = 1'b0;
   idle_state         = 1'b0;

   case(cur_state) 

      IDLE: begin
         idle_state  = 1'b1;
         if(dmaTx2ctrl_stransEn == 1'b1) begin
            nBytes_ld          = 1'b1;
            if(threshold) begin
               ctrl2ahbc_trEn_nxt = 1'b1;
               sys_addr_ld        = 1'b1;
               nxt_state          = SUBTRREQ;
               RdWr_ld            = 1'b1;
            end
            else begin
               ctrl2ahbc_trEn_nxt = 1'b0;
               RdWr_ld            = 1'b0;
               nxt_state          = IDLE;
            end
         end
      end

      MKBURST:begin
         RdWr_ld = 1'b0;
         if(nBytes== {CNTR_WD{1'b0}} ) begin
            if(ahbc2ctrl_dataDn) begin
               ctrl2dmaTx_dataDn    =1'b1;
               nxt_state = IDLE;
            end
            else begin
               nxt_state = WTDDN;
            end
         end
         else begin
            if(threshold == 1'b1)begin
               nxt_state = SUBTRREQ;
               ctrl2ahbc_trEn_nxt = 1'b1;
            end
            else begin
               nxt_state = MKBURST;
               ctrl2ahbc_trEn_nxt = 1'b0;
            end
         end
      end

      SUBTRREQ: begin 
         RdWr_ld = 1'b0;
         if(ahbc2ctrl_ack) begin
            nBytes_decr = 1'b1;
            if(ahbc2ctrl_addrDn) begin
               nxt_state = MKBURST;


            end
            else begin
               nxt_state = SUBTRANS;
            end
         ctrl2ahbc_trEn_nxt = 1'b0;
         end
      end


      SUBTRANS: begin
         RdWr_ld = 1'b0;
         if(ahbc2ctrl_addrDn) begin
            nxt_state = MKBURST;
         end
         else begin
            nxt_state = SUBTRANS;
         end
      end


      WTDDN: begin
         RdWr_ld = 1'b0;
         if(ahbc2ctrl_dataDn) begin
            ctrl2dmaTx_dataDn   =1'b1;
            nxt_state     = IDLE;
         end
      end


   endcase
   end


   always @ (posedge uctl_sysClk or negedge  uctl_sysRst_n) begin
      if(!uctl_sysRst_n) begin
         cur_state <=  IDLE;
      end
      else begin
         cur_state <= nxt_state;
      end
   end 


endmodule

`define INSTRUCTION_WIDTH 32

`define ALU_CTRL_WIDTH 5



`define R_TYPE 5'b01100

`define JALR 5'b11001
`define LOAD 5'b00000
`define ALU 5'b00100

`define STORE 5'b01000

`define BRANCH 5'b11000

`define U_TYPE 5'b01101, 5'b00101

`define JAL 5'b11011

module ctrl(


	output reg [(`ALU_CTRL_WIDTH-1):0] alu_ctrl,

	output reg reg_file_wr_en,

	output reg [1:0] reg_file_wr_back_sel,

	output reg alu_op2_sel,

	output reg d_mem_rd_en,

	output reg d_mem_wr_en,

	output reg [1:0] d_mem_size,

	output reg jal,

	output reg jalr, 

	input [(`INSTRUCTION_WIDTH - 1):0] inst
);


	always @ (*) begin

		if (inst[1:0] == 2'b11) begin

			case (inst[6:2])


				`R_TYPE: begin






					alu_ctrl[3:0] = {inst[30], inst[14:12]};

					alu_ctrl[4] = 1'b0;


					reg_file_wr_en = 1'b1;


					reg_file_wr_back_sel = 2'b00;


					alu_op2_sel = 1'b0;


					d_mem_rd_en = 1'b0;


					d_mem_wr_en = 1'b0;


					d_mem_size = 2'bxx;


					jal = 1'b0;


					jalr = 1'b0;
				end


				`JALR: begin


					alu_ctrl = inst[6:2];


					reg_file_wr_en = 1'b1;


					reg_file_wr_back_sel = 2'b10;


					alu_op2_sel = 1'b1;


					d_mem_rd_en = 1'b0;


					d_mem_wr_en = 1'b0;


					d_mem_size = 2'bxx;


					jal = 1'b0;


					jalr = 1'b1;
				end

				`LOAD: begin




					alu_ctrl = {(`ALU_CTRL_WIDTH){1'b0}};


					reg_file_wr_en = 1'b1;


					reg_file_wr_back_sel = 2'b01;


					alu_op2_sel = 1'b1;


					d_mem_rd_en = 1'b1;


					d_mem_wr_en = 1'b0;


					d_mem_size = inst[13:12];


					jal = 1'b0;


					jalr = 1'b0;
				end

				`ALU: begin

					if(inst[14:12] == 3'b010 || inst[14:12] == 3'b011) begin





						alu_ctrl = {1'b0, 1'b1, inst[14:12]};
					end

					else begin





						alu_ctrl = {2'b00, inst[14:12]};
					end



					reg_file_wr_en = 1'b1;


					reg_file_wr_back_sel = 2'b00;


					alu_op2_sel = 1'b1;


					d_mem_rd_en = 1'b0;


					d_mem_wr_en = 1'b0;


					d_mem_size = 2'bxx;


					jal = 1'b0;


					jalr = 1'b0;	
				end	


				`STORE: begin




					alu_ctrl = {(`ALU_CTRL_WIDTH){1'b0}};


					reg_file_wr_en = 1'b0;



					reg_file_wr_back_sel = 2'bxx;


					alu_op2_sel = 1'b1;


					d_mem_rd_en = 1'b0;


					d_mem_wr_en = 1'b1;


					d_mem_size = inst[13:12];


					jal = 1'b0;


					jalr = 1'b0;
				end


				`BRANCH: begin




					alu_ctrl = {1'b1, 1'b0, inst[14:12]};


					reg_file_wr_en = 1'b0;



					reg_file_wr_back_sel = 2'bxx;


					alu_op2_sel = 1'b0;


					d_mem_rd_en = 1'b0;


					d_mem_wr_en = 1'b0;


					d_mem_size = 2'bxx;


					jal = 1'b0;


					jalr = 1'b0;
				end


				`U_TYPE: begin



					if(inst[5]==1) begin


						alu_ctrl = 5'b11000;
					end

					else begin
						alu_ctrl = {(`ALU_CTRL_WIDTH){1'bx}};
					end					


					reg_file_wr_en = 1'b1;



					if(inst[5]==1) begin
						reg_file_wr_back_sel = 2'b00;
					end

					else begin
						reg_file_wr_back_sel = 2'b11;
					end					


					alu_op2_sel = 1'b1;


					d_mem_rd_en = 1'b0;


					d_mem_wr_en = 1'b0;


					d_mem_size = 2'bxx;


					jal = 1'b0;


					jalr = 1'b0;
				end


				`JAL:begin

					alu_ctrl = {(`ALU_CTRL_WIDTH){1'bx}};


					reg_file_wr_en = 1'b1;


					reg_file_wr_back_sel = 2'b10;


					alu_op2_sel = 1'bx;


					d_mem_rd_en = 1'b0;


					d_mem_wr_en = 1'b0;


					d_mem_size = 2'bxx;

					jal = 1'b1;


					jalr = 1'b0;
				end			


				default: begin


					alu_ctrl = {(`ALU_CTRL_WIDTH){1'bx}};


					reg_file_wr_en = 1'b0;



					reg_file_wr_back_sel = 2'bxx;


					alu_op2_sel = 1'bx;


					d_mem_rd_en = 1'b0;


					d_mem_wr_en = 1'b0;



					d_mem_size = 2'bxx;


					jal = 1'b0;


					jalr = 1'b0;
				end

			endcase

		end

		else begin


			alu_ctrl = {(`ALU_CTRL_WIDTH){1'bx}};


			reg_file_wr_en = 1'b0;



			reg_file_wr_back_sel = 2'bxx;


			alu_op2_sel = 1'bx;


			d_mem_rd_en = 1'b0;


			d_mem_wr_en = 1'b0;



			d_mem_size = 2'bxx;


			jal = 1'b0;


			jalr = 1'b0;
		end

	end

endmodule

module FSM_RX (
    input wire clk,
    input wire rst,
    input wire PAR_EN,
    input wire RX_IN,
    input wire par_err,
    input wire strt_glitch,
    input wire stp_err,
    input wire [3:0] bit_cnt,
    input wire [2:0] edge_cnt,
    output reg data_samp_en,
    output reg par_chk_en,
    output reg stp_chk_en,
    output reg strt_chk_en,
    output reg enable,
    output reg deser_en,
    output reg data_valid


);

  reg [2:0] current_state;
  reg [2:0] next_state;

  localparam idle = 3'b000;
  localparam start_bit = 3'b001;
  localparam data_bits = 3'b011;
  localparam parity_bit = 3'b111;
  localparam stop_bit = 3'b101;
  always @(posedge clk or negedge rst) begin
    if (!rst) begin
      current_state <= idle;
    end else begin
      current_state <= next_state;
    end
  end


  always @(*) begin


    deser_en = 1'b0;
    data_valid = 1'b0;
    data_samp_en = 1'b0;
    enable = 1'b0;
    par_chk_en = 1'b0;
    stp_chk_en = 1'b0;
    strt_chk_en = 1'b0;
    case (current_state)
      idle: begin


        if (RX_IN == 1'b0) begin
          strt_chk_en = 1'b1;
          enable = 1'b1;
          data_samp_en = 1'b1;
          par_chk_en = 1'b0;
          stp_chk_en = 1'b0;
          deser_en = 1'b0;
          data_valid = 1'b0;
          next_state = start_bit;
        end else begin
          next_state = idle;
        end

      end

      start_bit: begin
        strt_chk_en = 1'b1;
        if (edge_cnt == 3'b000 && bit_cnt == 4'b1) begin

          if (strt_glitch == 1'b1) begin
            next_state = idle;
          end else if (bit_cnt == 4'b1  ) begin
            enable = 1'b1;
            data_samp_en = 1'b1;
            deser_en = 1'b0;
            data_valid = 1'b0;
            next_state = data_bits;
          end

        end 
            else if (bit_cnt == 4'b1011  ) begin
            enable = 1'b1;
            data_samp_en = 1'b1;
            deser_en = 1'b0;
            data_valid = 1'b0;
            next_state = data_bits;
          end
        else begin
          strt_chk_en = 1'b1;
          enable = 1'b1;
          data_samp_en = 1'b1;
          data_valid = 1'b0;
          deser_en = 1'b0;
          next_state = start_bit;
        end
      end

      data_bits: begin
        deser_en = 1'b1;

        if (bit_cnt == 4'b1001) begin
          deser_en = 1'b1;
          if (PAR_EN == 1) begin
            enable = 1'b1;
            data_samp_en = 1'b1;
            par_chk_en = 1'b1;
            data_valid = 1'b0;
            next_state = parity_bit;
          end else begin
            enable = 1'b1;
            data_samp_en = 1'b1;
            stp_chk_en = 1'b1;
            data_valid = 1'b0;
            next_state = stop_bit;
          end

        end else if (edge_cnt == 3'b0) begin

          enable = 1'b1;
          data_samp_en = 1'b1;
          deser_en = 1'b1;
          data_valid = 1'b0;
          next_state = data_bits;

        end else begin

          enable = 1'b1;
          data_samp_en = 1'b1;
          deser_en = 1'b0;
          data_valid = 1'b0;
          next_state = data_bits;

        end

      end

      parity_bit: begin


        if (edge_cnt == 3'b000 && bit_cnt == 4'b1010) begin

          if (par_err == 1) begin
            next_state = idle;
          end else begin
            enable = 1'b1;
            data_samp_en = 1'b1;
            stp_chk_en = 1'b1;
            par_chk_en = 1'b0;
            data_valid = 1'b0;
            next_state = stop_bit;
          end
        end else begin
          enable = 1'b1;
          data_samp_en = 1'b1;
          par_chk_en = 1'b1;
          data_valid = 1'b0;
          next_state = parity_bit;
        end
      end


      stop_bit: begin
        deser_en = 1'b0;
        stp_chk_en = 1'b1;
        if (PAR_EN) begin

          if (edge_cnt == 3'b000 && bit_cnt == 4'b1011) begin

            if (stp_err == 1) begin
              data_valid = 1'b0;
              next_state = idle;
            end else begin

              data_valid = 1'b1;
              next_state = idle;
            end
          end else begin
            enable = 1'b1;
            data_samp_en = 1'b1;
            stp_chk_en = 1'b1;
            next_state = stop_bit;
          end
        end else begin

      if (edge_cnt == 3'b000 && bit_cnt == 4'b1010) begin

            if (stp_err == 1) begin
              next_state = idle;
            end else begin

              data_valid = 1'b1;
              next_state = idle;
            end
          end else begin
            enable = 1'b1;
            data_samp_en = 1'b1;
            stp_chk_en = 1'b1;
            data_valid = 1'b0;
            next_state = stop_bit;
          end

        end
      end

      default: begin
        data_samp_en = 1'b0;
        par_chk_en = 1'b0;
        stp_chk_en = 1'b0;
        strt_chk_en = 1'b0;
        enable = 1'b0;
        deser_en = 1'b0;
        data_valid = 1'b0;
        next_state = idle;
      end
    endcase
  end

endmodule

module DUT (clock, reset, start, in, ready, out);
	input clock, reset, start;
	input [7:0] in;
	output ready;
	output [17:0] out;

	reg			ready, ready_n;
	reg [17:0]  out, out_n;
	reg signed [17:0]  outData1 [0:3];
	reg signed [17:0]  outData1_n [0:3];
	reg [3:0]	outputCount, outputCount_n;

	reg signed [7:0]	inData1 [0:11];
	reg signed [7:0]	inData1_n [0:11];
	reg signed [7:0]	inData2 [0:11];
    reg signed [7:0]	inData2_n [0:11];
	reg [4:0]	inputCount, inputCount_n;

	reg			readyToOutput, readyToOutput_n;
	reg         readyToCalc, readyToCalc_n;

	reg [3:0]	state, state_n;

	integer i;
	parameter idle = 4'd0, input_data = 4'd1, output_data_1 = 4'd2, calc_data = 4'd3,
				output_data_2 = 4'd4;

	always @ (posedge clock or posedge reset)	begin
		if (reset)	begin
			ready <= 0;
			out <= 0;
			for (i=0;i<4;i=i+1)	begin
				outData1[i] <= 0;
			end
			for (i=0;i<12;i=i+1)	begin
				inData1[i] <= 0;
            	inData2[i] <= 0;
            end
			outputCount <= 0;
			inputCount <= 0;
			readyToOutput <= 0;
			readyToCalc <= 0;
			state <= idle;

		end

		else	begin
			ready <= ready_n;
            out <= out_n;
            for (i=0;i<4;i=i+1)	begin
            	outData1[i] <= outData1_n[i];
            end
            for (i=0;i<12;i=i+1)	begin
            	inData1[i] <= inData1_n[i];
            	inData2[i] <= inData2_n[i];
            end
            outputCount <= outputCount_n;
            inputCount <= inputCount_n;
            readyToOutput <= readyToOutput_n;
			readyToCalc <= readyToCalc_n;
            state <= state_n;
		end
	end

	always @ (*)	begin
		case (state)	
			idle:
				state_n = input_data;
			input_data:
				state_n = (readyToOutput) ? output_data_1 : input_data;
			output_data_1:
				state_n = (readyToCalc) ? calc_data : output_data_1;
			calc_data:
				state_n = (readyToOutput) ? output_data_2 : calc_data;
			output_data_2:
				state_n = (readyToCalc) ? idle : output_data_2;
			default:
				state_n = state;
		endcase
	end

	always @ (*)	begin
		case (state)	
			idle:	begin
				ready_n = 0;
				out_n = 0;
				for (i=0;i<4;i=i+1)	begin
					outData1_n[i] = outData1[i];
				end
				outputCount_n = 0;
				for (i=0;i<12;i=i+1)	begin
					inData1_n[i] = inData1[i];
					inData2_n[i] = inData2[i];
				end
				inputCount_n = 0;
				readyToOutput_n = 0;
				readyToCalc_n = 0;

			end

			input_data:	begin
				ready_n = 0;
                out_n = 0;
				outData1_n[0] = inData1[0]*inData1[9] + inData1[1]*inData1[10] + inData1[2]*inData1[11];
                outData1_n[1] = inData1[3]*inData1[9] + inData1[4]*inData1[10] + inData1[5]*inData1[11];
				outData1_n[2] = inData1[6]*inData1[9] + inData1[7]*inData1[10] + inData1[8]*inData1[11];

				if ((outData1[0] < outData1[1] && outData1[0] > outData1[2]) ||
					(outData1[0] > outData1[1] && outData1[0] < outData1[2]))
					outData1_n[3] = outData1[0];
				else if ((outData1[1] < outData1[0] && outData1[1] > outData1[2]) ||
                         (outData1[1] > outData1[0] && outData1[1] < outData1[2]))
                         outData1_n[3] = outData1[1];
				else
					outData1_n[3] = outData1[2];

				outputCount_n = 0;
                for (i=0;i<12;i=i+1)	begin
                	inData1_n[i] = inData1[i];
                	inData2_n[i] = inData2[i];
                end
				if (inputCount < 12)
					inData1_n[inputCount] = in;
				else if (inputCount < 24)
					inData2_n[inputCount - 12] = in;

                inputCount_n = (start) ? inputCount + 1 : inputCount;
                readyToOutput_n = (inputCount > 23) ? 1 : 0;
                readyToCalc_n = 0;

			end

			output_data_1:	begin
				ready_n = (outputCount < 4) ? 1 : 0;
                out_n = outData1[outputCount];
                for (i=0;i<4;i=i+1)	begin
                	outData1_n[i] = outData1[i];
                end
                outputCount_n = outputCount + 1;
                for (i=0;i<12;i=i+1)	begin
                	inData1_n[i] = inData1[i];
                	inData2_n[i] = inData2[i];
                end
                inputCount_n = 0;
                readyToOutput_n = 0;
                readyToCalc_n = (outputCount > 3) ? 1 : 0;

			end

			calc_data:	begin
				ready_n = 0;
                out_n = 0;
                outData1_n[0] = inData2[0]*inData2[9] + inData2[1]*inData2[10] + inData2[2]*inData2[11];
                outData1_n[1] = inData2[3]*inData2[9] + inData2[4]*inData2[10] + inData2[5]*inData2[11];
                outData1_n[2] = inData2[6]*inData2[9] + inData2[7]*inData2[10] + inData2[8]*inData2[11];
                if ((outData1[0] < outData1[1] && outData1[0] > outData1[2]) ||
                	(outData1[0] > outData1[1] && outData1[0] < outData1[2]))
                	outData1_n[3] = outData1[0];
                else if ((outData1[1] < outData1[0] && outData1[1] > outData1[2]) ||
                         (outData1[1] > outData1[0] && outData1[1] < outData1[2]))
                         outData1_n[3] = outData1[1];
                else
                	outData1_n[3] = outData1[2];
                outputCount_n = 0;
                for (i=0;i<12;i=i+1)	begin
                	inData1_n[i] = inData1[i];
                	inData2_n[i] = inData2[i];
                end
                inputCount_n = 0;
                readyToOutput_n = 1;
                readyToCalc_n = 0;
			end
			output_data_2:	begin
				ready_n = (outputCount < 4) ? 1 : 0;
                out_n = outData1[outputCount];
                for (i=0;i<4;i=i+1)	begin
                	outData1_n[i] = outData1[i];
                end
                outputCount_n = outputCount + 1;
                for (i=0;i<12;i=i+1)	begin
                	inData1_n[i] = inData1[i];
                	inData2_n[i] = inData2[i];
                end
                inputCount_n = 0;
                readyToOutput_n = 0;
                readyToCalc_n = (outputCount > 3) ? 1 : 0;


			end
			default:	begin
				ready_n = ready;	
                out_n = out;
                for (i=0;i<4;i=i+1)	begin
                	outData1_n[i] = outData1[i];
                end
                outputCount_n = outputCount;
                for (i=0;i<12;i=i+1)	begin
                	inData1_n[i] = inData1[i];
                	inData2_n[i] = inData2[i];
                end
                inputCount_n = inputCount;
                readyToOutput_n = readyToOutput;
                readyToCalc_n = readyToCalc;





			end



		endcase


	end














endmodule

module tri_mem_mux
#(
parameter addr_bus_size = 16,
parameter data_bus_size = 16
)
(



input [(addr_bus_size - 1):0] addr_a,
input [(data_bus_size - 1):0] data_a,
input start_a,
input rw_a,

input [(addr_bus_size - 1):0] addr_b,
input [(data_bus_size - 1):0] data_b,
input start_b,
input rw_b,
input [2:0] select,



output [(addr_bus_size - 1):0] addr_x,
output [(data_bus_size - 1):0] data_x,
output start_x, 
output rw_x,

output [(addr_bus_size - 1):0] addr_y,
output [(data_bus_size - 1):0] data_y,
output start_y,
output rw_y,

output [(addr_bus_size - 1):0] addr_z,
output [(data_bus_size - 1):0] data_z,
output start_z,
output rw_z

);

localparam [(addr_bus_size - 1):0] dummy_addr = 0;
localparam [(data_bus_size - 1):0] dummy_data = 0;
localparam dummy_start = 1'b1; 
localparam dummy_rw = 1'b0; 

localparam [2:0] A = 3'b000, 
					  B = 3'b001, 
					  C = 3'b010, 
					  D = 3'b011, 
					  E = 3'b100, 
					  F = 3'b101; 


assign addr_x = (select == A || select == B)? addr_a : ((select == C || select == E)? addr_b : dummy_addr);
assign data_x = (select == A || select == B)? data_a : ((select == C || select == E)? data_b : dummy_data);
assign start_x = (select == A || select == B)? start_a : ((select == C || select == E)? start_b : dummy_start);
assign rw_x = (select == A || select == B)? rw_a : ((select == C || select == E)? rw_b : dummy_rw);


assign addr_y = (select == C || select == D)? addr_a : ((select == A || select == F)? addr_b : dummy_addr);
assign data_y = (select == C || select == D)? data_a : ((select == A || select == F)? data_b : dummy_data);
assign start_y = (select == C || select == D)? start_a : ((select == A || select == F)? start_b : dummy_start);
assign rw_y = (select == C || select == D)? rw_a : ((select == A || select == F)? rw_b : dummy_rw);


assign addr_z = (select == E || select == F)? addr_a : ((select == B || select == D)? addr_b : dummy_addr);
assign data_z = (select == E || select == F)? data_a : ((select == B || select == D)? data_b : dummy_data);
assign start_z = (select == E || select == F)? start_a : ((select == B || select == D)? start_b : dummy_start);
assign rw_z = (select == E || select == F)? rw_a : ((select == B || select == D)? rw_b : dummy_rw);



endmodule

module cache_control(
	clk, rst_n, re, we, fetch, writeData, ready, instruction, readData,
	IMhit, DMhit, d_dirty, memRd, d_tag, iaddr, daddr, IO,
	DO, MO, Memre, IMwe, DMwe,	Memwe, IDI, DDI, 	
	Memaddr, i_data,	d_data
);


input clk, rst_n, re, we, fetch, IMhit, DMhit, d_dirty, memRd;
input [7:0] d_tag;
input [15:0] iaddr, daddr, writeData;
input [63:0] IO, DO, MO;

output IDI;
output reg Memre, IMwe, DMwe, Memwe, DDI, ready;
output [15:0] instruction, readData;
output reg [13:0] Memaddr;
output reg [63:0] i_data, d_data;


reg [1:0] state, nextState; 

assign IDI 	= 1'b0; 

assign instruction = ~rst_n ? 16'h0000 : (iaddr[1] ? (iaddr[0] ? IO[63:48] : IO[47:32]) : (iaddr[0] ? IO[31:16] : IO[15:0]));

assign readData = ~rst_n ? 16'hF000 : (daddr[1] ? (daddr[0] ? DO[63:48] : DO[47:32]) : (daddr[0] ? DO[31:16] : DO[15:0]));

always @(posedge clk or negedge rst_n) begin
	if (~rst_n) begin
		state <= 2'b00;
	end else begin
		state <= nextState;
	end
end


always @(*) begin

	IMwe 		= 1'b0;
	i_data 		= 0;

	DMwe 		= 1'b0;
	DDI 	= 1'b0;
	d_data 		= 0;

	Memwe		= 1'b0;
	Memre 		= 1'b0;
	Memaddr 		= 0;

	ready 		= 1'b0;

	nextState 	= 2'b00;

	case (state)



		2'b00 : begin
			if ((re | we) & ~DMhit) begin
				if (d_dirty) begin
					Memaddr 	= {d_tag, daddr[7:2]};
					Memwe 	= 1'b1;

					nextState = 2'b10;					
				end else begin
					Memaddr 	= daddr[15:2];
					Memre 	= 1'b1;

					nextState = 2'b01;
				end

			end else if (fetch & ~IMhit) begin
				Memaddr	= iaddr[15:2];
				Memre 	= 1'b1;

				nextState = 2'b01;


			end else begin

				if (we) begin
					d_data		= shift_in(DO, writeData, daddr[1:0]);
					DDI 	= 1'b1;
					DMwe 		= 1'b1;
				end

				ready = 1'b1;
				nextState = 2'b00;
			end
		end



		2'b01 : begin
			if (memRd) begin

				if ((re | we) & ~DMhit) begin
					if (we) begin
						d_data		= shift_in(MO, writeData, daddr[1:0]);
						DDI 	= 1'b1;
						DMwe 		= 1'b1;	
					end else begin
						d_data		= MO;
						DMwe		= 1'b1;
					end

				end else begin
					i_data 	= MO;
					IMwe 	= 1'b1;
				end

				nextState = 2'b00;

			end else if ((re | we) & ~DMhit) begin
				Memaddr 	= daddr[15:2];
				Memre 	= 1'b1;

				nextState = 2'b01;

			end else if (fetch & ~IMhit) begin
				Memaddr	= iaddr[15:2];
				Memre 	= 1'b1;

				nextState = 2'b01;

			end else begin
				nextState = 2'b00;
			end
		end

				2'b10 : begin
			Memaddr 	= {d_tag, daddr[7:2]};
			Memwe 	= 1'b1;

			nextState = memRd ? 2'b11 : 2'b10;
		end



		2'b11 : begin
			Memaddr 	= daddr[15:2];
			Memre 	= 1'b1;

			nextState = 2'b01;
		end

		default : begin end
	endcase
end

function [63:0] shift_in;

input [63:0] line;
input [15:0] in;
input [1:0] shamt;

begin
	case (shamt)
		2'b00 : shift_in = {line[63:16], in};
		2'b01 : shift_in = {line[63:32], in, line[15:0]};
		2'b10 : shift_in = {line[63:48], in, line[31:0]};
		2'b11 : shift_in = {in, line[47:0]};
	endcase	
end

endfunction

endmodule

`timescale 1ns / 1ps


module MIPS_32( FS, S, T, N, Z, V, C, Y_hi, Y_lo );

   input wire [4:0] FS;          
	input wire [31:0] S, T;       
	output reg N, Z, V, C;        
	output reg [31:0] Y_hi, Y_lo; 

	reg [31:0] Ans, Flag;         
	reg Ct, Vt;

	always @( * ) 
	begin

	N = 1'bx;                     
	Z = 1'bx;
	V = 1'bx;
	C = 1'bx;
	Y_hi = 32'h0;
	Y_lo = 32'h0;

		case ( FS )


		   5'h00:
			begin

			   {N,Z,V,C,Y_hi,Y_lo} = 
			      {
   					( S[31] ) ? 1'b1:1'b0,          
					   ( S     == 32'h0 ) ? 1'b1:1'b0, 
					     1'b0,                         
					     1'b0,                         
					     32'h0,                        
					     S                             
					};

			end


			5'h01:
			begin

			   {N,Z,V,C,Y_hi,Y_lo} = 
			      {
   					( T[31] ) ? 1'b1:1'b0,          
					   ( T     == 32'h0 ) ? 1'b1:1'b0, 
					     1'b0,                         
					     1'b0,                         
					     32'h0,                        
					     T                             
					};

			end



			5'h02:
			begin

			   {Ct, Ans} = S + T; 


				if( ( S[31] == T[31] ) && ( Ans[31] != S[31] ) )
				   Vt = 1'b1;
				else
				   Vt = 1'b0;

			   {N,Z,V,C,Y_hi,Y_lo} = 
			      {
   					( Ans[31] ) ? 1'b1:1'b0,          
					   ( Ans     == 32'h0 ) ? 1'b1:1'b0, 
					     Vt,                             
					     Ct,                             
					     32'h0,                          
					     Ans                             
					};

			end


			5'h03:
			begin

			   {Ct, Ans} = S - T; 


				if( ( S[31] != T[31] ) && ( Ans[31] == T[31] ) )
				   Vt = 1'b1;
				else
				   Vt = 1'b0;

			   {N,Z,V,C,Y_hi,Y_lo} = 
			      {
   					( Ans[31] ) ? 1'b1:1'b0,          
					   ( Ans     == 32'h0 ) ? 1'b1:1'b0, 
					     Vt,                             
					     Ct,                             
					     32'h0,                          
					     Ans[31:0]                       
					};

			end


			5'h04:
			begin

			   {Ct, Ans} = S + T; 

			   {N,Z,V,C,Y_hi,Y_lo} = 
			      {
   					  1'b0,                           
					   ( Ans     == 32'h0 ) ? 1'b1:1'b0, 
					   ( Ct ) ? 1'b1:1'b0,               
					     Ct,                             
					     32'h0,                          
					     Ans                             
					};

			end


			5'h05:
			begin

			   {Ct, Ans} = S - T; 

			   {N,Z,V,C,Y_hi,Y_lo} = 
			      {
   					  1'b0,                           
					   ( Ans     == 32'h0 ) ? 1'b1:1'b0, 
					   ( Ct ) ? 1'b1:1'b0,               
					   ( Ct ) ? 1'b1:1'b0,               
					     32'h0,                          
					     Ans                             
					};

			end


			5'h06:
			begin

				if (  


					   ( 


						( ( S[31] == 1'b1 ) && ( T[31] == 1'b0 ) && 
				      ! ( ( S[30:0] == T[30:0] ) && ( S[30:0] == 31'h0 ) ) )

					   || 


   				   ( ( S[31] == T[31] ) && ( S[30:0] < T[30:0] ) ) 

						)

					) 

					Flag = 32'h1;

				else
				   Flag = 32'h0; 

			   {N,Z,V,C,Y_hi,Y_lo} = 
			      {
   					1'b0,                   
					   ~Flag[0],               
					   1'bx,                   
					   1'bx,                   
					   32'h0,                  
					   Flag                    
					};

			end


			5'h07:
			begin

			   Flag = ( S < T ) ? 32'h1:32'h0;

			   {N,Z,V,C,Y_hi,Y_lo} = 
			      {
   					1'b0,                   
					   ~Flag[0],               
					   1'bx,                   
					   1'bx,                   
					   32'h0,                  
					   Flag                    
					};

			end


			5'h08:
			begin

			   Ans = S & T; 

			   {N,Z,V,C,Y_hi,Y_lo} = 
			      {
   					( Ans[31] ) ? 1'b1:1'b0,      
					   ( Ans == 32'h0 ) ? 1'b1:1'b0, 
					     1'bx,                       
					     1'bx,                       
					     32'h0,                      
					     Ans                         
					};

			end


			5'h09:
			begin

			   Ans = S | T; 

			   {N,Z,V,C,Y_hi,Y_lo} = 
			      {
   					( Ans[31] ) ? 1'b1:1'b0,      
					   ( Ans == 32'h0 ) ? 1'b1:1'b0, 
					     1'bx,                       
					     1'bx,                       
					     32'h0,                      
					     Ans                         
					};

			end


			5'h0A:
			begin

			   Ans = S ^ T; 

			   {N,Z,V,C,Y_hi,Y_lo} = 
			      {
   				   ( Ans[31] ) ? 1'b1:1'b0,      
					   ( Ans == 32'h0 ) ? 1'b1:1'b0, 
					     1'bx,                       
					     1'bx,                       
					     32'h0,                      
					     Ans                         
					};

			end


			5'h0B:
			begin

			   Ans = ~ ( S | T ); 

			   {N,Z,V,C,Y_hi,Y_lo} = 
			      {
   					( Ans[31] ) ? 1'b1:1'b0,      
					   ( Ans == 32'h0 ) ? 1'b1:1'b0, 
					     1'bx,                       
					     1'bx,                       
					     32'h0,                      
					     Ans                         
					};

			end


			5'h0C:
			begin

			   Ct = T[31];                         
			   Ans = T << 1;                       

			   {N,Z,V,C,Y_hi,Y_lo} = 
			      {
   				   ( Ans[31] ) ? 1'b1:1'b0,      
					   ( Ans == 32'h0 ) ? 1'b1:1'b0, 
					     1'bx,                       
					     Ct,                         
					     32'h0,                      
					     Ans                         
					};

			end


			5'h0D:
			begin

			   Ct = T[0];                          
			   Ans = T >> 1;                       

			   {N,Z,V,C,Y_hi,Y_lo} = 
			      {
   				   ( Ans[31] ) ? 1'b1:1'b0,      
					   ( Ans == 32'h0 ) ? 1'b1:1'b0, 
					     1'bx,                       
					     Ct,                         
					     32'h0,                      
					     Ans                         
					};

			end


			5'h0E:
			begin

			   Ct = T[0];                       
			   Ans = { T[31], T[31], T[30:1] }; 

			   {N,Z,V,C,Y_hi,Y_lo} = 
			      {
   				   ( Ans[31] ) ? 1'b1:1'b0,      
					   ( Ans == 32'h0 ) ? 1'b1:1'b0, 
					     1'bx,                       
					     Ct,                         
					     32'h0,                      
					     Ans                         
					};

			end


			5'h0F:
			begin

			   {Ct, Ans} = S + 1'b1; 
				Vt = ( S[31] != Ans[31] ) ? 1'b1:1'b0; 

			   {N,Z,V,C,Y_hi,Y_lo} = 
			      {
   				   ( Ans[31] ) ? 1'b1:1'b0,      
					   ( Ans == 32'h0 ) ? 1'b1:1'b0, 
					     Vt,                         
					     Ct,                         
					     32'h0,                      
					     Ans                         
					};

			end


			5'h10:
			begin

			   {Ct, Ans} = S - 1'b1; 
				Vt = ( S[31] != Ans[31] ) ? 1'b1:1'b0; 

			   {N,Z,V,C,Y_hi,Y_lo} = 
			      {
   				   ( Ans[31] ) ? 1'b1:1'b0,      
					   ( Ans == 32'h0 ) ? 1'b1:1'b0, 
					     Vt,                         
					     Ct,                         
					     32'h0,                      
					     Ans                         
					};

			end


			5'h11:
			begin

			   {Ct, Ans} = S + 3'h4; 
				Vt = ( S[31] != Ans[31] ) ? 1'b1:1'b0; 

			   {N,Z,V,C,Y_hi,Y_lo} = 
			      {
   				   ( Ans[31] ) ? 1'b1:1'b0,      
					   ( Ans == 32'h0 ) ? 1'b1:1'b0, 
					     Vt,                         
					     Ct,                         
					     32'h0,                      
					     Ans                         
					};

			end


			5'h12:
			begin

			   {Ct, Ans} = S - 3'h4; 
				Vt = ( S[31] != Ans[31] ) ? 1'b1:1'b0; 

			   {N,Z,V,C,Y_hi,Y_lo} = 
			      {
   				   ( Ans[31] ) ? 1'b1:1'b0,      
					   ( Ans == 32'h0 ) ? 1'b1:1'b0, 
					     Vt,                         
					     Ct,                         
					     32'h0,                      
					     Ans                         
					};

			end


			5'h13:
			begin

			   {N,Z,V,C,Y_hi,Y_lo} = 
			      {
   				   1'b0,                         
					   1'b1,                         
					   1'bx,                         
					   1'bx,                         
					   32'h0,                        
					   32'h0                         
					};

			end


			5'h14:
			begin

			   {N,Z,V,C,Y_hi,Y_lo} = 
			      {
   				   1'b1,                         
					   1'b0,                         
					   1'bx,                         
					   1'bx,                         
					   32'h0,                        
					   32'hffffffff                  
					};

			end


			5'h15:
			begin

			   {N,Z,V,C,Y_hi,Y_lo} = 
			      {
   				   1'b0,                         
					   1'b0,                         
					   1'bx,                         
					   1'bx,                         
					   32'h0,                        
					   32'h3FC                       
					};

			end


			5'h16:
			begin

			   Ans = S & { 16'h0, T[15:0] };       

			   {N,Z,V,C,Y_hi,Y_lo} = 
			      {
   				   ( Ans[31] ) ? 1'b1:1'b0,      
					   ( Ans == 32'h0 ) ? 1'b1:1'b0, 
					   1'bx,                         
					   1'bx,                         
					   32'h0,                        
					   Ans                           
					};

			end


			5'h17:
			begin

			   Ans = S | { 16'h0, T[15:0] };       

			   {N,Z,V,C,Y_hi,Y_lo} = 
			      {
   				   ( Ans[31] ) ? 1'b1:1'b0,      
					   ( Ans == 32'h0 ) ? 1'b1:1'b0, 
					   1'bx,                         
					   1'bx,                         
					   32'h0,                        
					   Ans                           
					};

			end


			5'h18:
			begin

			   Ans = { T[15:0], 16'h0 };           

			   {N,Z,V,C,Y_hi,Y_lo} = 
			      {
   				   ( Ans[31] ) ? 1'b1:1'b0,      
					   ( Ans == 32'h0 ) ? 1'b1:1'b0, 
					   1'bx,                         
					   1'bx,                         
					   32'h0,                        
					   Ans                           
					};

			end


			5'h19:
			begin

			   Ans = S ^ { 16'h0, T[15:0] };       

			   {N,Z,V,C,Y_hi,Y_lo} = 
			      {
   				   ( Ans[31] ) ? 1'b1:1'b0,      
					   ( Ans == 32'h0 ) ? 1'b1:1'b0, 
					   1'bx,                         
					   1'bx,                         
					   32'h0,                        
					   Ans                           
					};

			end

			default:
			begin

			   {N,Z,V,C,Y_hi,Y_lo} = 
			      {
   				   1'bx,                         
					   1'bx,                         
					   1'bx,                         
					   1'bx,                         
					   32'hxxxxxxxx,                 
					   32'hxxxxxxxx                  
					};

			end

		endcase

	end   


endmodule

module input_p4_interface
#(

