  input                                                           m_axis_2_tready,

  output reg [C_S_AXIS_DATA_WIDTH - 1:0]                          m_axis_3_tdata,
  output reg [((C_S_AXIS_DATA_WIDTH / 8)) - 1:0]                  m_axis_3_tkeep,
  output reg [C_M_AXIS_TUSER_WIDTH-1:0]                           m_axis_3_tuser,
  output reg                                                      m_axis_3_tvalid,
  output reg                                                      m_axis_3_tlast,
  input                                                           m_axis_3_tready,


  input   [C_M_AXIS_DATA_WIDTH - 1:0]                             s_axis_tdata,
  input   [((C_M_AXIS_DATA_WIDTH / 8)) - 1:0]                     s_axis_tkeep,
  input   [C_M_AXIS_TUSER_WIDTH-1:0]                              s_axis_tuser,
  input                                                           s_axis_tvalid,
  input                                                           s_axis_tlast,
  output reg                                                      s_axis_tready,


  input                                                           S_AXI_ACLK,
  input                                                           S_AXI_ARESETN
);



  localparam VLAN_WIDTH=32;
  localparam VLAN_WIDTH_ID=12;
  localparam VLAN_THRESHOLD_BGN=128;
  localparam VLAN_THRESHOLD_END=96;

  localparam NUM_STATES=3;
  localparam WAIT_PKT=0;
  localparam WRITE_PKT_BEG=1;
  localparam WRITE_PKT_END=2;
  localparam END_PKT=3;




  wire [VLAN_WIDTH - 1:0]                   vlan_tdata;
  wire [(( VLAN_WIDTH/2 )) - 1:0]           vlan_prot_id;
  wire [(( VLAN_WIDTH/2 )) - 1:0]           vlan_info;
  wire [(( VLAN_WIDTH_ID/4 )) - 1:0]        vlan_info_prio;
  wire                                      vlan_info_drop;
  wire [VLAN_WIDTH_ID -1 :0]                vlan_info_id;

  reg [NUM_STATES-1:0]                      ipi_state;
  reg                                       ipi_end_pkt;
  reg [(( VLAN_WIDTH/2 )) - 1:0]            ipi_vlan_prot_id;
  reg [VLAN_WIDTH_ID -1 :0]                 ipi_vlan_info_id;

  reg [C_S_AXIS_DATA_WIDTH - 1:0]           ipi_tdata;
  reg [((C_S_AXIS_DATA_WIDTH / 8)) - 1:0]   ipi_tkeep;
  reg [C_M_AXIS_TUSER_WIDTH-1:0]            ipi_tuser;
  reg                                       ipi_tvalid;
  reg                                       ipi_tlast;
  reg [C_S_AXIS_DATA_WIDTH - 1:0]           ipi_tdata_next;
  reg [((C_S_AXIS_DATA_WIDTH / 8)) - 1:0]   ipi_tkeep_next;
  reg [C_M_AXIS_TUSER_WIDTH-1:0]            ipi_tuser_next;
  reg                                       ipi_tvalid_next;
  reg                                       ipi_tlast_next;



  assign vlan_tdata = s_axis_tdata [VLAN_THRESHOLD_BGN - 1:VLAN_THRESHOLD_END];
  assign vlan_prot_id = vlan_tdata [((VLAN_WIDTH/2)) - 1:0];
  assign vlan_info = vlan_tdata [VLAN_WIDTH - 1:(( VLAN_WIDTH/2 ))];
  assign vlan_info_prio = vlan_info [7:5];
  assign vlan_info_drop = vlan_info [4];
  assign vlan_info_id = {vlan_info[3:0], vlan_info[15: 8]};


  always @(posedge axis_aclk) begin
    if( axis_resetn ) begin
      case( ipi_state )

        WAIT_PKT: begin
          s_axis_tready <= 1;

          ipi_end_pkt <= 0;
          ipi_vlan_prot_id <= vlan_prot_id;
          ipi_vlan_info_id <= vlan_info_id;

          ipi_tdata  <= s_axis_tdata;
          ipi_tuser  <= s_axis_tuser;
          ipi_tkeep  <= s_axis_tkeep;
          ipi_tvalid <= s_axis_tvalid;
          ipi_tlast  <= s_axis_tlast;
          ipi_tdata_next <= 0;
          ipi_tkeep_next <= 0;
          ipi_tuser_next <= 0;
          ipi_tvalid_next<= 0;
          ipi_tlast_next <= 0;

          m_axis_0_tdata  <= 0;
          m_axis_0_tkeep  <= 0;
          m_axis_0_tuser  <= 0;
          m_axis_0_tvalid <= 0;
          m_axis_0_tlast  <= 0;

          m_axis_1_tdata  <= 0;
          m_axis_1_tkeep  <= 0;
          m_axis_1_tuser  <= 0;
          m_axis_1_tvalid <= 0;
          m_axis_1_tlast  <= 0;

          m_axis_2_tdata  <= 0;
          m_axis_2_tkeep  <= 0;
          m_axis_2_tuser  <= 0;
          m_axis_2_tvalid <= 0;
          m_axis_2_tlast  <= 0;

          m_axis_3_tdata  <= 0;
          m_axis_3_tkeep  <= 0;
          m_axis_3_tuser  <= 0;
          m_axis_3_tvalid <= 0;
          m_axis_3_tlast  <= 0;


          if ( s_axis_tvalid ) begin
            ipi_state = WRITE_PKT_BEG;
          end
          else begin
            ipi_state = WAIT_PKT;
          end
        end

        WRITE_PKT_BEG: begin
          s_axis_tready <= 1;

          ipi_tdata_next  <= s_axis_tdata;
          ipi_tuser_next  <= s_axis_tuser;
          ipi_tkeep_next  <= s_axis_tkeep;
          ipi_tvalid_next <= s_axis_tvalid;
          ipi_tlast_next  <= s_axis_tlast;

          if ( ipi_vlan_prot_id == 16'h0081 ) begin 
            ipi_state = WRITE_PKT_END;
            if ( ipi_vlan_info_id == 12'h001 ) begin 
              if ( m_axis_0_tready == 1 ) begin
                m_axis_0_tdata  <= ipi_tdata;
                m_axis_0_tuser  <= ipi_tuser;
                m_axis_0_tkeep  <= ipi_tkeep;
                m_axis_0_tvalid <= ipi_tvalid;
                m_axis_0_tlast  <= ipi_tlast;
              end
            end
            else if ( ipi_vlan_info_id == 12'h002 ) begin 
              if ( m_axis_1_tready == 1 ) begin
                m_axis_1_tdata  <= ipi_tdata;
                m_axis_1_tuser  <= ipi_tuser;
                m_axis_1_tkeep  <= ipi_tkeep;
                m_axis_1_tvalid <= ipi_tvalid;
                m_axis_1_tlast  <= ipi_tlast;
              end
            end
            else if ( ipi_vlan_info_id == 12'h003 ) begin 
              if ( m_axis_2_tready == 1 ) begin
                m_axis_2_tdata  <= ipi_tdata;
                m_axis_2_tuser  <= ipi_tuser;
                m_axis_2_tkeep  <= ipi_tkeep;
                m_axis_2_tvalid <= ipi_tvalid;
                m_axis_2_tlast  <= ipi_tlast;
              end
            end
            else if ( ipi_vlan_info_id == 12'h004 ) begin 
              if ( m_axis_3_tready == 1 ) begin
                m_axis_3_tdata  <= ipi_tdata;
                m_axis_3_tuser  <= ipi_tuser;
                m_axis_3_tkeep  <= ipi_tkeep;
                m_axis_3_tvalid <= ipi_tvalid;
                m_axis_3_tlast  <= ipi_tlast;
              end
            end
            else begin
              ipi_state = WAIT_PKT;
            end
          end
          else begin
            ipi_state = WAIT_PKT;
          end
          if ( s_axis_tlast ) begin
            ipi_state = WRITE_PKT_END;
            s_axis_tready <= 0;
            ipi_end_pkt <= 1;
          end
          else begin
            if( ipi_end_pkt ) begin
              ipi_state = WAIT_PKT;
              s_axis_tready <= 1;
            end
          end

        end 

        WRITE_PKT_END: begin
          s_axis_tready <= 1;

          ipi_tdata <= s_axis_tdata;
          ipi_tuser <= s_axis_tuser;
          ipi_tkeep <= s_axis_tkeep;
          ipi_tvalid <= s_axis_tvalid;
          ipi_tlast <= s_axis_tlast;


          ipi_state = WRITE_PKT_BEG;
          if ( ipi_vlan_info_id == 12'h001 ) begin 
            if ( m_axis_0_tready == 1 ) begin
              m_axis_0_tdata  <= ipi_tdata_next;
              m_axis_0_tuser  <= ipi_tuser_next;
              m_axis_0_tkeep  <= ipi_tkeep_next;
              m_axis_0_tvalid <= ipi_tvalid_next;
              m_axis_0_tlast  <= ipi_tlast_next;
            end
          end
          else if ( ipi_vlan_info_id == 12'h002 ) begin 
            if ( m_axis_1_tready == 1 ) begin
              m_axis_1_tdata  <= ipi_tdata_next;
              m_axis_1_tuser  <= ipi_tuser_next;
              m_axis_1_tkeep  <= ipi_tkeep_next;
              m_axis_1_tvalid <= ipi_tvalid_next;
              m_axis_1_tlast  <= ipi_tlast_next;
            end
          end
          else if ( ipi_vlan_info_id == 12'h003 ) begin 
            if ( m_axis_2_tready == 1 ) begin
              m_axis_2_tdata  <= ipi_tdata_next;
              m_axis_2_tuser  <= ipi_tuser_next;
              m_axis_2_tkeep  <= ipi_tkeep_next;
              m_axis_2_tvalid <= ipi_tvalid_next;
              m_axis_2_tlast  <= ipi_tlast_next;
            end
          end
          else if ( ipi_vlan_info_id == 12'h004 ) begin 
            if ( m_axis_3_tready == 1 ) begin
              m_axis_3_tdata  <= ipi_tdata_next;
              m_axis_3_tuser  <= ipi_tuser_next;
              m_axis_3_tkeep  <= ipi_tkeep_next;
              m_axis_3_tvalid <= ipi_tvalid_next;
              m_axis_3_tlast  <= ipi_tlast_next;
            end
          end
          else begin
            ipi_state = WAIT_PKT;
          end
          if ( s_axis_tlast ) begin
            ipi_state = WRITE_PKT_BEG;
            s_axis_tready <= 0;
            ipi_end_pkt <= 1;
          end
          else begin
            if( ipi_end_pkt ) begin
              ipi_state = WAIT_PKT;
              s_axis_tready <= 1;
            end
          end
        end 

      endcase 
    end
    else begin 
      s_axis_tready <= 0;

      ipi_vlan_prot_id <= 0;
      ipi_vlan_info_id <= 0;
      ipi_tdata <= 0;
      ipi_tkeep <= 0;
      ipi_tuser <= 0;
      ipi_tvalid <= 0;
      ipi_tlast <= 0;
      ipi_tdata_next <= 0;
      ipi_tkeep_next <= 0;
      ipi_tuser_next <= 0;
      ipi_tvalid_next <= 0;
      ipi_tlast_next <= 0;

      m_axis_0_tdata  <= 0;
      m_axis_0_tkeep  <= 0;
      m_axis_0_tuser  <= 0;
      m_axis_0_tvalid <= 0;
      m_axis_0_tlast  <= 0;
      m_axis_1_tdata  <= 0;
      m_axis_1_tkeep  <= 0;
      m_axis_1_tuser  <= 0;
      m_axis_1_tvalid <= 0;
      m_axis_1_tlast  <= 0;
      m_axis_2_tdata  <= 0;
      m_axis_2_tkeep  <= 0;
      m_axis_2_tuser  <= 0;
      m_axis_2_tvalid <= 0;
      m_axis_2_tlast  <= 0;
      m_axis_3_tdata  <= 0;
      m_axis_3_tkeep  <= 0;
      m_axis_3_tuser  <= 0;
      m_axis_3_tvalid <= 0;
      m_axis_3_tlast  <= 0;

      ipi_end_pkt <= 0;
      ipi_state = WAIT_PKT;
    end 

  end 

endmodule

module RxUnit(
Clk,
Reset,
Enable,
RxD,
RD,
FErr,
OErr,
DRdy,
DataIn
);

input Clk; 
input Reset; 
input Enable; 
input RxD; 
input RD; 
output FErr; 
output OErr; 
output DRdy; 
output[7:0] DataIn;

wire   Clk;
wire   Reset;
wire   Enable;
wire   RxD;
wire   RD;
wire   FErr;
wire   OErr;
wire   DRdy;
wire  [7:0] DataIn;




reg  Start; 
reg  tmpRxD; 
reg  tmpDRdy; 
reg  outErr; 
reg  frameErr; 
reg [3:0] BitCnt; 
reg [3:0] SampleCnt; 
reg [7:0] ShtReg; 
reg [7:0] DOut; 




  always @(posedge Clk) begin
    if(Reset == 1'b0) begin
      BitCnt <= 4'b0000;
      SampleCnt <= 4'b0000;
      Start <= 1'b0;
      tmpDRdy <= 1'b0;
      frameErr <= 1'b0;
      outErr <= 1'b0;
      ShtReg <= 8'b00000000; 
      DOut <= 8'b00000000; 
    end
    else begin
      if(RD == 1'b1) begin
        tmpDRdy <= 1'b0;

      end
      if(Enable == 1'b1) begin
        if(Start == 1'b0) begin
          if(RxD == 1'b0) begin

            SampleCnt <= SampleCnt + 4'b0001;
            Start <= 1'b1;
          end
        end
        else begin
          if(SampleCnt == 4'b1000) begin

            tmpRxD <= RxD;
            SampleCnt <= SampleCnt + 4'b0001;
          end
          else if(SampleCnt == 4'b1111) begin
            case(BitCnt)
            4'b0000 : begin
              if(tmpRxD == 1'b1) begin

                Start <= 1'b0;
              end
              else begin
                BitCnt <= BitCnt + 4'b0001;
              end
              SampleCnt <= SampleCnt + 4'b0001;

            end
            4'b0001,4'b0010,4'b0011,4'b0100,4'b0101,4'b0110,4'b0111,4'b1000 : begin
              BitCnt <= BitCnt + 4'b0001;
              SampleCnt <= SampleCnt + 4'b0001;
              ShtReg <= {tmpRxD,ShtReg[7:1] };
            end
            4'b1001 : begin
              if(tmpRxD == 1'b0) begin 
                frameErr <= 1'b1;
              end
              else begin
                frameErr <= 1'b0;
              end
              if(tmpDRdy == 1'b1) begin 
                outErr <= 1'b1;
              end
              else begin
                outErr <= 1'b0;
              end
              tmpDRdy <= 1'b1;
              DOut <= ShtReg;
              BitCnt <= 4'b0000;
              Start <= 1'b0;
            end
            default : begin
            end
            endcase
          end
          else begin
            SampleCnt <= SampleCnt + 4'b0001;
          end
        end
      end
    end
  end

  assign DRdy = tmpDRdy;
  assign DataIn = DOut;
  assign FErr = frameErr;
  assign OErr = outErr;


endmodule

module cva6_tlb_sv32 (
	clk_i,
	rst_ni,
	flush_i,
	update_i,
	lu_access_i,
	lu_asid_i,
	lu_vaddr_i,
	lu_content_o,
	asid_to_be_flushed_i,
	vaddr_to_be_flushed_i,
	lu_is_4M_o,
	lu_hit_o,
	port_content_q_o,
	port_tags_q_o,
	port_replace_en_o
);
	parameter [31:0] TLB_ENTRIES = 4;
	parameter [31:0] ASID_WIDTH = 1;
	input wire clk_i;
	input wire rst_ni;
	input wire flush_i;
	input wire [62:0] update_i;
	input wire lu_access_i;
	input wire [ASID_WIDTH - 1:0] lu_asid_i;
	localparam cva6_config_pkg_CVA6ConfigXlen = 32;
	localparam riscv_XLEN = cva6_config_pkg_CVA6ConfigXlen;
	localparam riscv_VLEN = 32;
	input wire [31:0] lu_vaddr_i;
	output reg [31:0] lu_content_o;
	input wire [ASID_WIDTH - 1:0] asid_to_be_flushed_i;
	input wire [31:0] vaddr_to_be_flushed_i;
	output reg lu_is_4M_o;
	output reg lu_hit_o;
	reg [(TLB_ENTRIES * 31) - 1:0] tags_q;
	reg [(TLB_ENTRIES * 31) - 1:0] tags_n;
	reg [(TLB_ENTRIES * 32) - 1:0] content_q;
	reg [(TLB_ENTRIES * 32) - 1:0] content_n;
	reg [9:0] vpn0;
	reg [9:0] vpn1;
	reg [TLB_ENTRIES - 1:0] lu_hit;
	reg [TLB_ENTRIES - 1:0] replace_en;

output wire [127:0] port_content_q_o;
assign port_content_q_o = content_q;
output wire [123:0] port_tags_q_o;
assign port_tags_q_o = tags_q;
output wire [TLB_ENTRIES-1:0] port_replace_en_o;
assign port_replace_en_o = replace_en;

wire [31:0] content_q_0;
wire [30:0] tags_q_0;
assign content_q_0 = content_q[0*32+31:0*32];
assign tags_q_0 = tags_q[0*31+30:0*31];
wire [31:0] content_q_1;
wire [30:0] tags_q_1;
assign content_q_1 = content_q[1*32+31:1*32];
assign tags_q_1 = tags_q[1*31+30:1*31];
wire [31:0] content_q_2;
wire [30:0] tags_q_2;
assign content_q_2 = content_q[2*32+31:2*32];
assign tags_q_2 = tags_q[2*31+30:2*31];
wire [31:0] content_q_3;
wire [30:0] tags_q_3;
assign content_q_3 = content_q[3*32+31:3*32];
assign tags_q_3 = tags_q[3*31+30:3*31];

wire [30:0] tdata;
assign tdata = update_i[31-:32];
wire [31:0] cdata;
assign cdata = {update_i[40-:9], update_i[60:51], update_i[50:41], update_i[61], 1'b1};

	always @(*) begin : translation
		vpn0 = lu_vaddr_i[21:12];
		vpn1 = lu_vaddr_i[31:22];
		lu_hit = {TLB_ENTRIES {1'd0}};
		lu_hit_o = 1'b0;
		lu_content_o = 32'h00000000;
		lu_is_4M_o = 1'b0;
		begin : sv2v_autoblock_1
			reg [31:0] i;
			for (i = 0; i < TLB_ENTRIES; i = i + 1)
				if ((tags_q[i * 31] && ((lu_asid_i == tags_q[(i * 31) + 30-:9]) || content_q[(i * 32) + 5])) && (vpn1 == tags_q[(i * 31) + 21-:10]))
					if (tags_q[(i * 31) + 1] || (vpn0 == tags_q[(i * 31) + 11-:10])) begin
						lu_is_4M_o = tags_q[(i * 31) + 1];
						lu_content_o = content_q[i * 32+:32];
						lu_hit_o = 1'b1;
						lu_hit[i] = 1'b1;
					end
		end
	end
	wire asid_to_be_flushed_is0;
	wire vaddr_to_be_flushed_is0;
	reg [TLB_ENTRIES - 1:0] vaddr_vpn0_match;
	reg [TLB_ENTRIES - 1:0] vaddr_vpn1_match;
	assign asid_to_be_flushed_is0 = ~(|asid_to_be_flushed_i);
	assign vaddr_to_be_flushed_is0 = ~(|vaddr_to_be_flushed_i);
	always @(*) begin : update_flush
		tags_n = tags_q;
		content_n = content_q;
		begin : sv2v_autoblock_2
			reg [31:0] i;
			for (i = 0; i < TLB_ENTRIES; i = i + 1)
				begin
					vaddr_vpn0_match[i] = vaddr_to_be_flushed_i[21:12] == tags_q[(i * 31) + 11-:10];
					vaddr_vpn1_match[i] = vaddr_to_be_flushed_i[31:22] == tags_q[(i * 31) + 21-:10];
					if (flush_i) begin
						if (asid_to_be_flushed_is0 && vaddr_to_be_flushed_is0)
							tags_n[i * 31] = 1'b0;
						else if ((asid_to_be_flushed_is0 && ((vaddr_vpn0_match[i] && vaddr_vpn1_match[i]) || (vaddr_vpn1_match[i] && tags_q[(i * 31) + 1]))) && ~vaddr_to_be_flushed_is0)
							tags_n[i * 31] = 1'b0;
						else if ((((!content_q[(i * 32) + 5] && ((vaddr_vpn0_match[i] && vaddr_vpn1_match[i]) || (vaddr_vpn1_match[i] && tags_q[(i * 31) + 1]))) && (asid_to_be_flushed_i == tags_q[(i * 31) + 30-:9])) && !vaddr_to_be_flushed_is0) && !asid_to_be_flushed_is0)
							tags_n[i * 31] = 1'b0;
						else if (((!content_q[(i * 32) + 5] && vaddr_to_be_flushed_is0) && (asid_to_be_flushed_i == tags_q[(i * 31) + 30-:9])) && !asid_to_be_flushed_is0)
							tags_n[i * 31] = 1'b0;
					end
					else if (update_i[62] & replace_en[i]) begin
						tags_n[i * 31+:31] = {update_i[40-:9], update_i[60:51], update_i[50:41], update_i[61], 1'b1};
						content_n[i * 32+:32] = update_i[31-:32];
					end
				end
		end
	end
	reg [(2 * (TLB_ENTRIES - 1)) - 1:0] plru_tree_q;
	reg [(2 * (TLB_ENTRIES - 1)) - 1:0] plru_tree_n;
	always @(*) begin : plru_replacement
		plru_tree_n = plru_tree_q;
		begin : sv2v_autoblock_3
			reg [31:0] i;
			for (i = 0; i < TLB_ENTRIES; i = i + 1)
				begin : sv2v_autoblock_4
					reg [31:0] idx_base;
					reg [31:0] shift;
					reg [31:0] new_index;
					if (lu_hit[i] & lu_access_i) begin : sv2v_autoblock_5
						reg [31:0] lvl;
						for (lvl = 0; lvl < $clog2(TLB_ENTRIES); lvl = lvl + 1)
							begin
								idx_base = $unsigned((2 ** lvl) - 1);
								shift = $clog2(TLB_ENTRIES) - lvl;
								new_index = ~((i >> (shift - 1)) & 32'b00000000000000000000000000000001);
								plru_tree_n[idx_base + (i >> shift)] = new_index[0];
							end
					end
				end
		end
		begin : sv2v_autoblock_6
			reg [31:0] i;
			for (i = 0; i < TLB_ENTRIES; i = i + 1)
				begin : sv2v_autoblock_7
					reg en;
					reg [31:0] idx_base;
					reg [31:0] shift;
					reg [31:0] new_index;
					en = 1'b1;
					begin : sv2v_autoblock_8
						reg [31:0] lvl;
						for (lvl = 0; lvl < $clog2(TLB_ENTRIES); lvl = lvl + 1)
							begin
								idx_base = $unsigned((2 ** lvl) - 1);
								shift = $clog2(TLB_ENTRIES) - lvl;
								new_index = (i >> (shift - 1)) & 32'b00000000000000000000000000000001;
								if (new_index[0])
									en = en & plru_tree_q[idx_base + (i >> shift)];
								else
									en = en & ~plru_tree_q[idx_base + (i >> shift)];
							end
					end
					replace_en[i] = en;
				end
		end
	end
	always @(posedge clk_i or negedge rst_ni)
		if (~rst_ni) begin
			tags_q <= {TLB_ENTRIES {31'd0}};
			content_q <= {TLB_ENTRIES {32'd0}};
			plru_tree_q <= {2 * (TLB_ENTRIES - 1) {1'd0}};
		end
		else begin
			tags_q <= tags_n;
			content_q <= content_n;
			plru_tree_q <= plru_tree_n;
		end
	initial begin : p_assertions

	end
	function signed [31:0] countSetBits;
		input reg [TLB_ENTRIES - 1:0] vector;
		reg signed [31:0] count;
		begin
			count = 0;
			begin : sv2v_autoblock_9
				integer idx;
				for (idx = TLB_ENTRIES - 1; idx >= 0; idx = idx - 1)
					count = count + vector[idx];
			end
			countSetBits = count;
		end
	endfunction
endmodule

module sdram_read(
	input				rd_clk			,	
	input				rd_rst_n		,
	input				rd_en			,
	input				init_end		,
	input		[23:0]	rd_addr			,
	input		[15:0]	rd_data			,
	input		[9:0]	rd_burst_len	,

	output				rd_end			,
	output				rd_ack			,
	output	reg	[3:0]	rd_sdram_cmd	,
	output	reg	[12:0]	rd_sdram_addr	,
	output	reg	[1:0]	rd_sdram_bank	,
	output		[15:0]	rd_sdram_data	
);

parameter	TRCD = 10'd2,
			TCL	 = 10'd3,
			TRP	 = 10'd4;

parameter	RD_IDLE	    = 4'd0,
			RD_ACT	    = 4'd1,
			RD_TRCD	    = 4'd2,
			RD_RD_CMD	= 4'd3,
			RD_CL	    = 4'd4,
			RD_DATA	    = 4'd5,
			RD_PRE	    = 4'd6,
			RD_TRP	    = 4'd7,
			RD_END	    = 4'd8;

parameter	NOP 		= 4'b0111,
			ACTIVE      = 4'b0011,
			READ        = 4'b0101,
			BURST_STOP  = 4'b0110,
			PRECHARGE   = 4'b0010;


reg [3:0] state_cur;
reg [3:0] state_next;

reg [9:0]	cnt_fsm;
reg 		cnt_fsm_rst;
reg [15:0]	rd_data_reg;


wire	trcd_end_flag	;
wire	cl_end_flag		;
wire	tread_end_flag	;
wire	trp_end_flag	;
wire	rdburst_end_flag;

assign trcd_end_flag	=	(state_cur == RD_TRCD && cnt_fsm == TRCD - 1'b1) ? 1'b1 : 1'b0; 
assign cl_end_flag		=   (state_cur == RD_CL && cnt_fsm == TCL - 1'b1) ? 1'b1 : 1'b0; 
assign tread_end_flag	=   (state_cur == RD_DATA && cnt_fsm == rd_burst_len) ? 1'b1 : 1'b0; 
assign trp_end_flag	    =   (state_cur == RD_TRP && cnt_fsm == TRP - 1'b1) ? 1'b1 : 1'b0; 
assign rdburst_end_flag = 	(state_cur == RD_DATA && cnt_fsm == rd_burst_len - 4) ? 1'b1 : 1'b0; 

assign rd_end = (state_cur == RD_END) ? 1'b1 : 1'b0;
assign rd_sdram_data = rd_ack ? rd_data_reg : 16'd0;

assign rd_ack = ((state_cur == RD_DATA) && (cnt_fsm >= 10'd1) && (cnt_fsm < rd_burst_len + 1'b1));


always@(posedge rd_clk or negedge rd_rst_n)begin
	if(~rd_rst_n)
		rd_data_reg <= 16'd0;
	else
		rd_data_reg <= rd_data;
end
always@(*)begin
	case(state_cur)
		RD_TRCD : 	cnt_fsm_rst = trcd_end_flag ? 1'b1 : 1'b0;
		RD_CL 	: 	cnt_fsm_rst = cl_end_flag ? 1'b1 : 1'b0;
		RD_DATA : 	cnt_fsm_rst = tread_end_flag ? 1'b1 : 1'b0;
		RD_TRP 	: 	cnt_fsm_rst = trp_end_flag ? 1'b1 : 1'b0;
		default	:	cnt_fsm_rst = 1'b1;
	endcase
end
always@(posedge rd_clk or negedge rd_rst_n)begin
	if(~rd_rst_n)begin
		cnt_fsm <= 10'd0;
	end
	else begin
		if(cnt_fsm_rst)
			cnt_fsm <= 10'd0;
		else
			cnt_fsm <= cnt_fsm + 1'b1;
	end
end


always@(posedge rd_clk or negedge rd_rst_n)begin
	if(~rd_rst_n)
		state_cur <= RD_IDLE;
	else
		state_cur <= state_next;
end
always@(*)begin
	case(state_cur)
		RD_IDLE	  	:	state_next = (rd_en & init_end) ? RD_ACT : RD_IDLE;
		RD_ACT	  	:  	state_next = RD_TRCD;
		RD_TRCD	  	:   state_next = trcd_end_flag ? RD_RD_CMD : RD_TRCD;
		RD_RD_CMD	:	state_next = RD_CL;
		RD_CL	  	:   state_next = cl_end_flag ? RD_DATA : RD_CL;
		RD_DATA	  	:  	state_next = tread_end_flag ? RD_PRE : RD_DATA;
		RD_PRE	  	:   state_next = RD_TRP;
		RD_TRP	  	:  	state_next = trp_end_flag ? RD_END : RD_TRP;
		RD_END	  	:  	state_next = RD_IDLE;
		default		:	state_next = RD_IDLE;
	endcase	
end
always@(posedge rd_clk or negedge rd_rst_n)begin
	if(~rd_rst_n)begin
		rd_sdram_cmd	<=	NOP;
		rd_sdram_addr	<=	13'h1fff;
		rd_sdram_bank	<=	2'b11;
	end
	else begin
		case(state_cur)
			RD_IDLE	  	:begin
				rd_sdram_cmd	<=	NOP;
			    rd_sdram_addr	<=	13'h1fff;
			    rd_sdram_bank	<=	2'b11;
			end
		    RD_ACT	  	:begin
				rd_sdram_cmd	<=	ACTIVE;
				rd_sdram_addr	<=	rd_addr[21:9];
				rd_sdram_bank	<=	rd_addr[23:22];
			end  
		    RD_TRCD	  	:begin
				rd_sdram_cmd	<=	NOP;
			    rd_sdram_addr	<=	13'h1fff;
			    rd_sdram_bank	<=	2'b11;
			end  
		    RD_RD_CMD	:begin
				rd_sdram_cmd	<=	READ;
			    rd_sdram_addr	<=	{4'd0,rd_addr[8:0]};
			    rd_sdram_bank	<=	rd_addr[23:22];
			end	
		    RD_CL	  	:begin
				rd_sdram_cmd	<=	NOP;
			    rd_sdram_addr	<=	13'h1fff;
			    rd_sdram_bank	<=	2'b11;
			end  
		    RD_DATA	  	:begin
				rd_sdram_addr	<=	13'h1fff;
				rd_sdram_bank	<=	2'b11;
				if(rdburst_end_flag)
					rd_sdram_cmd	<=	BURST_STOP;
				else
					rd_sdram_cmd	<=	NOP;
			end  
		    RD_PRE	  	:begin
				rd_sdram_cmd	<=	PRECHARGE;
			    rd_sdram_addr	<=	13'h0400;
			    rd_sdram_bank	<=	rd_addr[23:22];
			end  
		    RD_TRP	  	:begin
				rd_sdram_cmd	<=	NOP;
			    rd_sdram_addr	<=	13'h1fff;
			    rd_sdram_bank	<=	2'b11;
			end  
		    RD_END	  	:begin
				rd_sdram_cmd	<=	NOP;
			    rd_sdram_addr	<=	13'h1fff;
			    rd_sdram_bank	<=	2'b11;
			end  
			default		:begin
				rd_sdram_cmd	<=	NOP;
			    rd_sdram_addr	<=	13'h1fff;
			    rd_sdram_bank	<=	2'b11;
			end
		endcase
	end
end
endmodule

module Identificador(clk, reset, ok, nota, fim, tipo, estado_atual);

  input wire ok, reset, clk;
	input  wire [3:0] nota;
	output reg fim;
	output reg [1:0] tipo;


	parameter inicio  = 4'b0000,
	          s_n1    = 4'b0001,
	          s_n2    = 4'b0010,
 	          s_N3_La = 4'b0011,
	          s_N3_Si = 4'b0100,
						s_adj	  = 4'b0101,
						s_N4_Do = 4'b0110,
						s_N4_Si = 4'b0111,
						s_N4_Re = 4'b1000,
						s_comp  = 4'b1001,
						s_adv   = 4'b1010,
						s_erro	= 4'b1011;

	parameter nota_nula1 = 4'b0000,
						Do         = 4'b0001,
						Re         = 4'b0010,
						Mi         = 4'b0011,
						Fa         = 4'b0100,
						Sol        = 4'b0101,
						La         = 4'b0110,
						Si         = 4'b0111,
						nota_nula2 = 4'b1000,
						Do_m       = 4'b1001,
						Re_m       = 4'b1010,
						Mi_m       = 4'b1011,
						Fa_m       = 4'b1100,
						Sol_m      = 4'b1101,
						La_m       = 4'b1110,
						Si_m       = 4'b1111;

	parameter t_nenhum = 2'b00,
						t_adj    = 2'b01,
 						t_comp   = 2'b10,
						t_adv    = 2'b11;

	parameter processado  = 1'b1,
						em_processo = 1'b0;

	output reg [3:0] estado_atual;
	reg [3:0] prox_estado;

	always @(posedge clk)
  begin

		if(reset)
    begin

			estado_atual = inicio;

    end

		else
    begin

    	estado_atual = prox_estado;
    end

	end

	always @(posedge ok or posedge reset)
  begin

		if (reset)
    begin

    	prox_estado = inicio;

    end

    else
    begin

      case(estado_atual)

        inicio:
        begin

        	if(nota == nota_nula1 || nota == nota_nula2)
          begin

            prox_estado = s_erro;

          end

          else
          begin

            prox_estado = s_n1;

          end

        end


  			s_n1:
        begin

        	if(nota != nota_nula1 && nota != nota_nula2)
          begin

            prox_estado = s_n2;

          end

          else
          begin

            prox_estado = s_erro;

          end

        end


  			s_n2:
        begin

  				if(nota == La_m)
          begin

  					prox_estado = s_N3_La;

          end

          else if(nota == Si_m)
          begin

            prox_estado = s_N3_Si;

          end

  				else
          begin

            prox_estado = s_erro;

          end

  			end


  			s_N3_La:
        begin

        	if(nota == nota_nula1 || nota == nota_nula2)
          begin

  					prox_estado = s_adj;

          end

          else if(nota == Do)
          begin

            prox_estado = s_N4_Do;
          end

  				else if(nota == Si_m)
          begin

  					prox_estado = s_N4_Si;

          end

          else
          begin

            prox_estado = s_erro;

          end

        end


        s_N3_Si:
        begin

          if(nota == nota_nula1 || nota == nota_nula2)
          begin

            prox_estado = s_adj;

          end

  				else if(nota == Re)
          begin

            prox_estado = s_N4_Re;

          end

          else
          begin

  					prox_estado = s_erro;

          end

  			end


  			s_N4_Do:
        begin
    			if(nota == nota_nula1 || nota == nota_nula2)
          begin

            prox_estado = s_comp;

          end

    			else
          begin

            prox_estado = s_erro;

          end

        end


        s_N4_Re:
        begin

        	if(nota == nota_nula1 || nota == nota_nula2)
          begin

            prox_estado = s_comp;

          end

          else
          begin

            prox_estado = s_erro;

          end

        end


        s_N4_Si:
        begin

        	if(nota == nota_nula1 || nota == nota_nula2)
          begin

            prox_estado = s_adv;

          end

          else
          begin

    				prox_estado = s_erro;

          end

    		end


        s_comp:
        begin

        	prox_estado = s_comp;

        end


        s_adv:
        begin

        	prox_estado = s_adv;

        end


        s_adj:
        begin

        	prox_estado = s_adj;

        end


    		s_erro:
        begin

        	prox_estado = s_erro;

        end

  		endcase

  	end

  end


  always @ (estado_atual)
  begin

		case(estado_atual)

			s_erro:
      begin

      	fim = processado;
				tipo = t_nenhum;

      end

			s_adj:
      begin

      	fim = processado;
				tipo = t_adj;

      end


      s_comp:
      begin

      	fim = processado;
				tipo = t_comp;

      end


      s_adv:
      begin

      	fim = processado;
				tipo = t_adv;

      end

			s_N3_La:
      begin

      	fim = em_processo;
				tipo = t_nenhum;

      end


      s_N3_Si:
      begin

      	fim = em_processo;
				tipo = t_nenhum;

      end


      s_N4_Do:
      begin

      	fim = em_processo;
				tipo = t_nenhum;

      end


      s_N4_Si:
      begin

      	fim = em_processo;
				tipo = t_nenhum;

      end


      s_N4_Re:
      begin

      	fim = em_processo;
				tipo = t_nenhum;

      end


      default:
      begin

      	fim = em_processo;
				tipo = t_nenhum;

      end

		endcase

	end

endmodule

module debug_sram(
    input         clk,
    input         aresetn,


    output  [3:0]   arid,
    output  [31:0]  araddr,
    output  [7:0]   arlen,  
    output  [2:0]   arsize,
    output  [1:0]   arburst,
    output  [1:0]   arlock, 
    output  [3:0]   arcache,
    output  [2:0]   arprot, 
    output  reg     arvalid,
    input           arready,


    input   [3:0]    rid,
    input   [63:0]   rdata,
    input   [1:0]    rresp,
    input            rlast,
    input            rvalid,
    output  reg      rready,


    input            break_point,
    input            cpu_rready,
    output  reg      rvalid_r,
    output  reg      rid_r,
    output  reg[63:0]rdata_r,
    output  reg      rlast_r,
    output  reg      flag,        


    input           infom_flag,
    input   [31:0]  start_addr,
    output          mem_flag,
    output  [ 7:0]  mem_rdata 

    );
assign arid       =4'd2;
assign araddr     =start_addr;
assign arlen      =1'b0;
assign arsize     =3'd0;
assign arburst    =2'b01;
assign arlock     = 1'b0;
assign arcache    = 1'b0;
assign arprot     = 1'b0;


reg       mem_flag_r;
reg[63:0] mem_rdata_r;
reg       delay;

always@(posedge clk or negedge aresetn)begin
  if(!aresetn)
    delay<=1'b1;
  else if(infom_flag)
    delay<=1'b0;
  else 
    delay<=1'b1;
end

always@(posedge clk or negedge aresetn)begin
    if(!aresetn)
      arvalid<=1'b0;
    else if(arvalid && arready)
      arvalid<=1'b0;
    else if(infom_flag && delay)
      arvalid<=1'b1;
end

always@(posedge clk or negedge aresetn)begin
    if(!aresetn)begin
      rready     <=1'b0;
      mem_flag_r <=1'b0;
      mem_rdata_r<=64'd0;
    end
    else if(arvalid && arready)
      rready<=1'b1;
    else if(rvalid && rready && rid==4'd2)begin
      rready     <=1'b0;
      mem_flag_r <=1'b1;
      mem_rdata_r<=rdata[63:0];
    end
    else begin 
      mem_flag_r <=1'b0;
      mem_rdata_r<=64'd0;
    end
end


always@(posedge clk or negedge aresetn)begin
  if(!aresetn)begin
    rvalid_r<=1'b0;
    rid_r   <=1'b0;
    rdata_r <=64'd0;
    rlast_r <=1'b0;
    flag    <=1'b0;
  end
  else if(rvalid && rid!=4'd2)begin
    rvalid_r<=rvalid;
    rid_r   <=rid;
    rdata_r <=rdata;
    rlast_r <=rlast;
    flag    <=1'b1;
    end
  else if(!break_point && cpu_rready)begin
    rvalid_r<=1'b0;
    rid_r   <=1'b0;
    rdata_r <=64'd0;
    rlast_r <=1'b0;
    flag    <=1'b0;
  end
end

assign mem_rdata=(start_addr[2:0]==3'b000)? mem_rdata_r[ 7:0] :
                 (start_addr[2:0]==3'b001)? mem_rdata_r[15:8] :
                 (start_addr[2:0]==3'b010)? mem_rdata_r[23:16]:
                 (start_addr[2:0]==3'b011)? mem_rdata_r[31:24]:
                 (start_addr[2:0]==3'b100)? mem_rdata_r[39:32]:
                 (start_addr[2:0]==3'b101)? mem_rdata_r[47:40]:
                 (start_addr[2:0]==3'b110)? mem_rdata_r[55:48]:
                                            mem_rdata_r[63:56];
assign mem_flag=mem_flag_r;

endmodule

module note_gen(
    clk, 
    rst, 
    note_div_left, 
    note_div_right,
    audio_left,
    audio_right,
    volume
);


    input clk; 
    input rst; 
    input [21:0] note_div_left, note_div_right; 
    output reg [15:0] audio_left, audio_right;
    input [2:0] volume;


    reg [21:0] clk_cnt_next, clk_cnt;
    reg [21:0] clk_cnt_next_2, clk_cnt_2;
    reg b_clk, b_clk_next;
    reg c_clk, c_clk_next;


    always @(posedge clk or posedge rst)
        if (rst == 1'b1)
            begin
                clk_cnt <= 22'd0;
                clk_cnt_2 <= 22'd0;
                b_clk <= 1'b0;
                c_clk <= 1'b0;
            end
        else
            begin
                clk_cnt <= clk_cnt_next;
                clk_cnt_2 <= clk_cnt_next_2;
                b_clk <= b_clk_next;
                c_clk <= c_clk_next;
            end

    always @*
        if (clk_cnt == note_div_left)
            begin
                clk_cnt_next = 22'd0;
                b_clk_next = ~b_clk;
            end
        else
            begin
                clk_cnt_next = clk_cnt + 1'b1;
                b_clk_next = b_clk;
            end

    always @*
        if (clk_cnt_2 == note_div_right)
            begin
                clk_cnt_next_2 = 22'd0;
                c_clk_next = ~c_clk;
            end
        else
            begin
                clk_cnt_next_2 = clk_cnt_2 + 1'b1;
                c_clk_next = c_clk;
            end






    always @(*) begin
        case (volume)
            3'd0 : begin
                audio_left = 16'h0000;
                audio_right = 16'h0000;
            end
            3'd1: begin
                audio_left = (b_clk == 1'b0) ? 16'hF000 : 16'h1000;
                audio_right = (c_clk == 1'b0) ? 16'hF000 : 16'h1000;
            end
            3'd2 : begin
                audio_left = (b_clk == 1'b0) ? 16'hE000 : 16'h2000;
                audio_right = (c_clk == 1'b0) ? 16'hE000 : 16'h2000;
            end
            3'd3 : begin
                audio_left = (b_clk == 1'b0) ? 16'hB000 : 16'h4000;
                audio_right = (c_clk == 1'b0) ? 16'hB000 : 16'h4000;
            end
            3'd4 : begin
                audio_left = (b_clk == 1'b0) ? 16'hA000 : 16'h6000;
                audio_right = (c_clk == 1'b0) ? 16'hA000 : 16'h6000;
            end
            3'd5 : begin
                audio_left = (b_clk == 1'b0) ? 16'h9000 : 16'h7000;
                audio_right = (c_clk == 1'b0) ? 16'h9000 : 16'h7000;
            end
            default : begin
                audio_left = 16'h0000;
                audio_right = 16'h0000;
            end
        endcase
    end 

endmodule

`timescale 1 ns / 1 ps

module afifo #(

	parameter	ADDRSIZE = 3,


	parameter	DATASIZE  = 32,


	parameter	SYNC_STAGES    = 2,

	parameter MEM_TYPE = 0

	) 
	(

    input   wire                  wclk, 
    input   wire                  wr_reset, 
    input   wire                  wr,
    input   wire [DATASIZE-1:0]   wr_data,
    output                        wr_full,
    input   wire                  rclk,
    input   wire                  rd_reset,
    input   wire                  rd,
    output       [DATASIZE-1:0]   rd_data,
    output  reg                   rd_empty

    );

    reg     [ADDRSIZE:0]          rd_addr;
    reg     [ADDRSIZE:0]          wr_addr;
    wire    [ADDRSIZE:0]          rd_wgray;
    wire    [ADDRSIZE:0]          wr_rgray;
    wire    [ADDRSIZE:0]          next_rd_addr;
    wire    [ADDRSIZE:0]          next_wr_addr;
    reg     [ADDRSIZE:0]          rgray, wgray;
    wire                          ren;
    wire                          read_empty;



    assign	next_wr_addr = wr_addr + 1;
    always @(posedge wclk )
    if (wr_reset)
    begin
        wr_addr <= 0;
        wgray   <= 0;
    end else if (wr && !wr_full)
    begin
        wr_addr <= next_wr_addr;

        wgray   <= next_wr_addr ^ (next_wr_addr >> 1);
    end


    assign	next_rd_addr = rd_addr + 1;
    always @(posedge rclk)
    if (rd_reset)
    begin
        rd_addr <= 0;
        rgray   <= 0;
    end else if (ren && !read_empty)
    begin
        rd_addr <= next_rd_addr;

        rgray   <= next_rd_addr ^ (next_rd_addr >> 1);
    end



	assign 	wr_full = (wr_rgray == { ~wgray[ADDRSIZE:ADDRSIZE-1], wgray[ADDRSIZE-2:0] });


	assign  read_empty = (rd_wgray == rgray);

	assign  ren = (rd_empty || rd);


    always @(posedge rclk )
        if (rd_reset)
            rd_empty <= 1'b1;
         else if (ren)
            rd_empty <= read_empty;


    synchronizer # (.SYNC_STAGES(SYNC_STAGES),
                    .ADDRSIZE   (ADDRSIZE))
    synchronizer(
                .wptr_reg    (wr_rgray),
                .rptr_reg    (rd_wgray),
                .wr_clk      (wclk),
                .rd_clk      (rclk),
                .wr_rst      (wr_reset),
                .rd_rst      (rd_reset),
                .wptr        (wgray),
                .rptr        (rgray)
                );

   dual_port_ram # (.DATASIZE(DATASIZE),
                    .ADDRSIZE (ADDRSIZE)
                    )
   dual_port_ram(
                 .rdata  (rd_data),
                 .wr_clk (wclk),
                 .rd_clk (rclk),
                 .wen    (wr && !wr_full),
                 .ren    (ren),
                 .wdata  (wr_data),
                 .waddr  (wr_addr),
                 .raddr  (rd_addr)
                 );

endmodule

module dual_port_ram #(

    parameter DATASIZE = 32,

    parameter ADDRSIZE = 4
)
(
    output reg [DATASIZE-1:0]   rdata,
    input                       wr_clk,
    input                       rd_clk,
    input                       wen,
    input                       ren,
    input      [DATASIZE-1:0]   wdata,
    input      [ADDRSIZE:0]     waddr,
    input      [ADDRSIZE:0]     raddr
);



       reg [DATASIZE-1:0] mem	[(1<<ADDRSIZE)-1:0];

        always @(posedge rd_clk) begin
            if (ren) begin
                rdata   <= mem[raddr[ADDRSIZE-1:0]];
            end
        end

        always @(posedge wr_clk) begin
            if (wen) 
            mem[waddr[ADDRSIZE-1:0]]  <=  wdata;
        end

endmodule

module synchronizer #(


    parameter SYNC_STAGES   = 2,
    parameter ADDRSIZE      = 4
)
(
    output  [ADDRSIZE:0]    wptr_reg,
    output  [ADDRSIZE:0]    rptr_reg,
    input                   wr_clk,
    input                   rd_clk,
    input                   wr_rst,
    input                   rd_rst,
    input   [ADDRSIZE:0]    wptr,
    input   [ADDRSIZE:0]    rptr

);

    reg [ADDRSIZE:0] wr_sync_register[0:SYNC_STAGES-1];
    reg [ADDRSIZE:0] rd_sync_register[0:SYNC_STAGES-1];


    assign wptr_reg = wr_sync_register[SYNC_STAGES-1];
    assign rptr_reg = rd_sync_register[SYNC_STAGES-1];

    always @(posedge wr_clk) begin
        if (wr_rst) begin
            wr_sync_register[0] <= 0;
        end
        else begin
            wr_sync_register[0] <= rptr;
        end   
    end

    always @(posedge rd_clk) begin
        if (rd_rst) begin
            rd_sync_register[0] <= 0;
        end
        else begin
            rd_sync_register[0] <= wptr;
        end

    end

    genvar i;

    generate
        for(i=0; i<(SYNC_STAGES-1); i = i+1)begin
            always@(posedge wr_clk ) begin
                if(wr_rst) begin
                    wr_sync_register[i+1] <= 0;
                end
                else begin
                    wr_sync_register[i+1] <= wr_sync_register[i];
                end
            end     
            always @(posedge rd_clk ) begin
                if (rd_rst) begin
                    rd_sync_register[i+1] <= 0;
                end
                else begin
                    rd_sync_register[i+1] <= rd_sync_register[i];
                end    
            end
        end
    endgenerate


endmodule

