module cpu_checker(
    input [7:0] char,
    input clk,
    input reset,
    output [1:0] format_type
    );
	 reg [4:0] status = `S0;
	 reg [1:0] flag = 2'b00;
	 reg [3:0] Regd = 4'b0000; 
	 reg [3:0] Regh = 4'b0000; 

	 always@(posedge clk)begin
	   if (reset)begin
	      status <= `S0;
	      flag <= 2'b00;
	      Regd <= 4'b0000;
			Regh <= 4'b0000;
	   end
	   else begin
	      case(status)
	      `S0 : begin
			         if(char == "^")
						status <= `S1;
						else begin
						status <= `S0;
						flag <= 2'b00;
						end
			     end
			`S1 : begin  
			         if(char >= "0" && char <= "9") begin
						status <= `S2;
						Regd <= Regd + 1;  
						end
						else 
						status <= `S0;
			     end
			`S2 : begin  
			         if (char >= "0" && char <= "9")begin
						   if (Regd >= 4'b0100) begin
						   status <= `S0;
						   Regd <= 4'b0;
						   end
						   else begin
							Regd <= Regd + 1;
						   status <= `S2;
						   end
						end
						else if (char == "@") begin
						status <= `S3;
						Regd <= 4'b0;
						end
						else
						status <= `S0;
				  end
			`S3 : begin 
                  if ((char >= "0" && char <= "9")||(char >= "a" && char <= "f"))begin
						status <= `S4;
						Regh <= Regh +1;  
						end
                  else
						status <= `S0;
			     end
         `S4 : begin 
                  if (char == ":") begin
						   if (Regh == 4'b1000) begin  
                     status <= `S5;
						   Regh <= 4'b0;
						   end
						   else begin
						   status <= `S0;
						   Regh <= 4'b0;
						   end
					   end
						else if ((char >= "0" && char <= "9")||(char >= "a" && char <= "f")) begin
						status <= `S4;
						Regh <= Regh + 1;
                  end
                  else
                  status <= `S0;							
              end
         `S5 : begin 
                  if (char == " ")
                  status <= `S6;
                  else if (char == "$")begin
						status <= `S71;
						flag <= 2'b01;
						end
						else if (char == "*")begin
						status <= `S72;
						flag <= 2'b10;
						end
						else
						status <= `S0;
				  end	
			`S6 : begin 
			          if (char == " ")
						 status <= `S6;
						 else if (char == "$")begin
						 status <= `S71;
						 flag <= 2'b01;
						 end
						 else if (char == "*")begin
						 status <= `S72;
						 flag <= 2'b10;
						 end
						 else
						 status <= `S0;
					end
			`S71 : begin 
			           if (char >= "0" && char <= "9")begin
						  status <= `S81;
						  Regd <= Regd + 1;
						  end
						  else
						  status <= `S0;
				   end
			`S72 : begin  
			          if ((char >= "0" && char <= "9")||(char >= "a" && char <= "f"))begin
						 status <= `S82;
						 Regh <= Regh + 1;
						 end
						 else
						 status <= `S0;
					end
			`S81 : begin 
			          if (char >= "0" && char <= "9")begin
						    if (Regd >= 4'b0100) begin
							 status <= `S0;
							 Regd <= 4'b0;
							 end
							 else begin
						    status <= `S81;
							 Regd <= Regd + 1;
							 end
						 end
						 else if (char == " ")
						 status <= `S9;
						 else if (char == "<")
						 status <= `S10;
						 else
						 status <= `S0;
			      end
			`S82 : begin 
						 if (char == " ") begin
						    if (Regh == 4'b1000) begin
						    status <= `S9;
							 Regh <= 4'b0;
							 end
						    else begin
							 status <= `S0;
							 Regh <= 4'b0;
						    end
						 end
						 else if (char == "<") begin
						         if (Regh == 4'b1000) begin
									status <= `S10;
									Regh <= 4'b0;
									end
									else begin
									status <= `S0;
									Regh <= 4'b0;
									end
						 end
						 else if ((char >= "0" && char <= "9")||(char >= "a" && char <= "f"))begin
						 status <= `S82;
						 Regh <= Regh + 1;
						 end
						 else
						 status <= `S0;
			     end
			`S9 : begin 
			         if(char == " ")
						status <= `S9;
						else if (char == "<")
						status <= `S10;
						else
						status <= `S0;
			      end
			`S10 : begin 
			          if (char == "=")
						 status <= `S11;
						 else 
						 status <= `S0;
					end
			`S11 : begin 
			          if (char == " ")
						 status <= `S12;
						 else if ((char >= "0" && char <= "9")||(char >= "a" && char <= "f")) begin
						 status <= `S13;
						 Regh <= Regh + 1;
						 end
						 else
						 status <= `S0;
			      end
			`S12 : begin 
			          if (char == " ")
						 status <= `S12;
						 else if ((char >= "0" && char <= "9")||(char >= "a" && char <= "f"))begin
						 status <= `S13;
						 Regh <= Regh +1;
						 end
						 else
						 status <= `S0;
					end
			`S13 : begin 
			          if ((char >= "0" && char <= "9")||(char >= "a" && char <= "f")) begin
						 status <= `S13;
						 Regh <= Regh + 1;
						 end
						 else if (char == "#") begin
						         if (Regh == 4'b1000) begin
						         status <= `S14;
									Regh <= 4'b0;
									end
									else begin
									status <= `S0;
									Regh <= 4'b0;
									end
						 end
						 else
						 status <= `S0;
					end
			`S14 : begin
			          if (char == "^") begin
						 status <= `S1;
						 flag <= 2'b00;
						 end
						 else
						 status <= `S0;
					end
			default : status <= `S0;
	      endcase
	   end
	 end
    assign format_type = (status == `S14) ? flag : 2'b00;

endmodule

`default_nettype none






module uart_phy_txd #(
	parameter CLOCK_FREQUENCY	= 50000000,
	parameter UART_BAUDRATE		= 115200,
	parameter UART_STOPBIT		= 1
) (

	input wire			reset,
	input wire			clk,
	input wire			clk_ena,	


	output wire			in_ready,
	input wire			in_valid,
	input wire  [7:0]	in_data,


	output wire			txd,
	input wire			cts			
);








	localparam CLOCK_DIVNUM = ((CLOCK_FREQUENCY + UART_BAUDRATE/2 - 1)/ UART_BAUDRATE) - 1;
	localparam INIT_BITCOUNT = (UART_STOPBIT > 1)? 11 : 10;






	wire			reset_sig = reset;				


	wire			clock_sig = clk;				

	reg [11:0]		divcount_reg;
	reg [3:0]		bitcount_reg;
	reg [8:0]		txd_reg;
	reg [1:0]		ctsin_reg;










	assign in_ready = (bitcount_reg == 4'd0)? ctsin_reg[1] : 1'b0;
	assign txd = txd_reg[0];

	always @(posedge clock_sig or posedge reset_sig) begin
		if (reset_sig) begin
			divcount_reg <= 1'd0;
			bitcount_reg <= 1'd0;
			txd_reg <= 9'h1ff;
			ctsin_reg <= 2'b00;

		end
		else begin
			if (clk_ena) begin
				ctsin_reg <= {ctsin_reg[0], cts};

				if (bitcount_reg == 4'd0) begin
					if (in_valid && ctsin_reg[1]) begin
						divcount_reg <= CLOCK_DIVNUM[11:0];
						bitcount_reg <= INIT_BITCOUNT[3:0];
						txd_reg <= {in_data, 1'b0};
					end
				end
				else begin
					if (divcount_reg == 0) begin
						divcount_reg <= CLOCK_DIVNUM[11:0];
						bitcount_reg <= bitcount_reg - 1'd1;
						txd_reg <= {1'b1, txd_reg[8:1]};
					end
					else begin
						divcount_reg <= divcount_reg - 1'd1;
					end
				end

			end
		end
	end

endmodule







module uart_phy_rxd #(
	parameter CLOCK_FREQUENCY	= 50000000,
	parameter UART_BAUDRATE		= 115200,
	parameter UART_STOPBIT		= 1
) (

	input wire			reset,
	input wire			clk,
	input wire			clk_ena,	


	input wire			out_ready,
	output wire			out_valid,
	output wire [7:0]	out_data,
	output wire [1:0]	out_error,	


	input wire			rxd,
	output wire			rts			
);








	localparam CLOCK_DIVNUM = ((CLOCK_FREQUENCY + UART_BAUDRATE/2 - 1)/ UART_BAUDRATE) - 1;
	localparam BIT_CAPTURE  = (CLOCK_DIVNUM / 2);






	wire			reset_sig = reset;				


	wire			clock_sig = clk;				

	reg [2:0]		rxdin_reg;
	reg				rts_reg;

	reg [11:0]		divcount_reg;
	reg [3:0]		bitcount_reg;
	reg [7:0]		shift_reg;
	reg [7:0]		outdata_reg;
	reg				outvalid_reg;
	reg				overflow_reg;
	reg				stoperror_reg;










	always @(posedge clock_sig or posedge reset_sig) begin
		if (reset_sig) begin
			rxdin_reg <= 3'b111;
			divcount_reg <= 1'd0;
			bitcount_reg <= 1'd0;
			shift_reg <= 8'h00;
			outvalid_reg <= 1'b0;
			outdata_reg  <= 8'h00;
			overflow_reg <= 1'b0;
			stoperror_reg <= 1'b0;
			rts_reg <= 1'b0;

		end
		else begin
			if (clk_ena) begin
				rxdin_reg <= {rxdin_reg[1:0], rxd};
				rts_reg <= (!out_ready && outvalid_reg)? 1'b0 : 1'b1;

				if (out_ready && outvalid_reg) begin
					overflow_reg <= 1'b0;
					outvalid_reg <= 1'b0;
				end
				else if (divcount_reg == 0 && bitcount_reg == 4'd1 && rxdin_reg[2] == 1'b1) begin
					overflow_reg <= outvalid_reg;
					outvalid_reg <= 1'b1;
				end


				if (bitcount_reg == 4'd0) begin
					if (rxdin_reg[2:1] == 2'b10) begin
						divcount_reg <= BIT_CAPTURE[11:0];
						bitcount_reg <= 4'd10;
					end
				end
				else begin
					if (divcount_reg == 0) begin
						divcount_reg <= CLOCK_DIVNUM[11:0];

						if (bitcount_reg == 4'd10) begin			
							if (rxdin_reg[2] != 1'b0) begin
								bitcount_reg <= 4'd0;
							end
							else begin
								bitcount_reg <= bitcount_reg - 1'd1;
							end
						end
						else if (bitcount_reg == 4'd1) begin		
							if (rxdin_reg[2] != 1'b1) begin
								stoperror_reg <= 1'b1;
							end
							else begin
								outdata_reg  <= shift_reg;
								stoperror_reg <= 1'b0;
							end

							bitcount_reg <= bitcount_reg - 1'd1;
						end
						else begin
							bitcount_reg <= bitcount_reg - 1'd1;
							shift_reg <= {rxdin_reg[2], shift_reg[7:1]};
						end

					end
					else begin
						divcount_reg <= divcount_reg - 1'd1;
					end
				end

			end
		end
	end

	assign rts = rts_reg;
	assign out_valid = outvalid_reg;
	assign out_data  = outdata_reg;
	assign out_error = {stoperror_reg, overflow_reg};

endmodule







module uart_to_bytes #(
	parameter CLOCK_FREQUENCY	= 50000000,
	parameter UART_BAUDRATE		= 115200,
	parameter UART_STOPBIT		= 1
) (

	input wire			reset,
	input wire			clk,


	output wire			in_ready,
	input wire			in_valid,
	input wire  [7:0]	in_data,


	input wire			out_ready,
	output wire			out_valid,
	output wire [7:0]	out_data,


	output wire			txd,
	input wire			cts,		
	input wire			rxd,
	output wire			rts			
);




	uart_phy_txd #(
		.CLOCK_FREQUENCY	(CLOCK_FREQUENCY),
		.UART_BAUDRATE		(UART_BAUDRATE),
		.UART_STOPBIT		(UART_STOPBIT)
	)
	u_txd (
		.reset		(reset),
		.clk		(clk),
		.clk_ena	(1'b1),
		.in_ready	(in_ready),
		.in_valid	(in_valid),
		.in_data	(in_data),
		.txd		(txd),
		.cts		(cts)
	);

	uart_phy_rxd #(
		.CLOCK_FREQUENCY	(CLOCK_FREQUENCY),
		.UART_BAUDRATE		(UART_BAUDRATE),
		.UART_STOPBIT		(UART_STOPBIT)
	)
	u_rxd (
		.reset		(reset),
		.clk		(clk),
		.clk_ena	(1'b1),
		.out_ready	(out_ready),
		.out_valid	(out_valid),
		.out_data	(out_data),
		.out_error	(),
		.rxd		(rxd),
		.rts		(rts)
	);



endmodule

module cpu #( 
	parameter ADDR_W = 64,
	parameter INST_W = 32,
	parameter DATA_W = 64
)(
    input                   i_clk,
    input                   i_rst_n,
    input                   i_i_valid_inst, 
    input  [ INST_W-1 : 0 ] i_i_inst,       
    input                   i_d_valid_data, 
    input  [ DATA_W-1 : 0 ] i_d_data,       
    output                  o_i_valid_addr, 
    output [ ADDR_W-1 : 0 ] o_i_addr,       
    output [ DATA_W-1 : 0 ] o_d_w_data,     
    output [ ADDR_W-1 : 0 ] o_d_w_addr,     
    output [ ADDR_W-1 : 0 ] o_d_r_addr,     
    output                  o_d_MemRead,    
    output                  o_d_MemWrite,   
    output                  o_finish
);


    reg o_i_valid_addr_r, o_i_valid_addr_w;
    reg [ADDR_W-1:0] o_i_addr_r, o_i_addr_w;
    reg [DATA_W-1:0] o_d_w_data_r, o_d_w_data_w;
    reg [ADDR_W-1:0] o_d_w_addr_r, o_d_w_addr_w;
    reg [ADDR_W-1:0] o_d_r_addr_r, o_d_r_addr_w;
    reg o_d_MemRead_r, o_d_MemRead_w;
    reg o_d_MemWrite_r, o_d_MemWrite_w;
    reg o_finish_r, o_finish_w;

    reg [6:0] opcode_r, opcode_w;
    reg [4:0] rd_r, rd_w, rs1, rs2;
    reg [DATA_W-1:0] imm;
    reg signed [DATA_W-1:0] imm_s_r, imm_s_w;
    reg [2:0] func3;
    reg [6:0] func7;

    reg [ADDR_W-1:0] pc_r, pc_w;
    reg [3:0] cs, ns;
    reg [DATA_W-1:0] alu_res_r, alu_res_w;
    reg take_br_r, take_br_w;
    reg [DATA_W-1:0] reg_file[31:0], reg_file_w[31:0];

    integer i;
    parameter stage_wb_fetch = 0;
    parameter stage_ex = 4;
    parameter stage_pc = 7;


    assign o_i_valid_addr = o_i_valid_addr_r;
    assign o_i_addr = o_i_addr_r;
    assign o_d_w_data = o_d_w_data_r;
    assign o_d_w_addr = o_d_w_addr_r;
    assign o_d_r_addr = o_d_r_addr_r;
    assign o_d_MemRead = o_d_MemRead_r;
    assign o_d_MemWrite = o_d_MemWrite_r;
    assign o_finish = o_finish_r;


    always @(*) begin

        case (cs)
            4'd0: ns=1;
            4'd1: ns=2;
            4'd2: ns=3;
            4'd3: ns=4;
            4'd4: ns=5;
            4'd5: ns=6;
            4'd6: ns=7;
            4'd7: ns=0;
            default: ns=0;
        endcase
    end

    always @(*) begin

        if (cs == stage_wb_fetch) begin
            o_i_valid_addr_w = 1;
            o_i_addr_w = pc_r;
        end else begin
            o_i_valid_addr_w = 0;
            o_i_addr_w = 0;
        end
    end

    always @(*) begin

        if (cs == stage_ex) begin
            opcode_w = i_i_inst[6:0];
            rd_w = i_i_inst[11:7];
            rs1 = i_i_inst[19:15];
            rs2 = i_i_inst[24:20];
            func3 = i_i_inst[14:12];
            func7 = i_i_inst[31:25];
            case (opcode_w)
                7'b0000011: begin
                    imm = {52'b0, i_i_inst[31:20]};
                    imm_s_w = 0;
                end
                7'b0100011: begin
                    imm = {52'b0, i_i_inst[31:25], i_i_inst[11:7]};
                    imm_s_w = 0;
                end
                7'b1100011: begin
                    imm = 0;
                    imm_s_w = {{52{i_i_inst[31]}}, i_i_inst[31], i_i_inst[7], i_i_inst[30:25], i_i_inst[11:8], 1'b0};
                end
                7'b0010011: begin
                    imm = {52'b0, i_i_inst[31:20]};
                    imm_s_w = 0;
                end
                7'b0110011: begin
                    imm = 0;
                    imm_s_w = 0;
                end
                default: begin
                    imm = 0;
                    imm_s_w = 0;
                end
            endcase
            if (opcode_w == 7'b1111111) begin
                o_finish_w = 1;
            end else begin
                o_finish_w = 0;
            end
        end else begin
            opcode_w = opcode_r;
            rd_w = rd_r;
            rs1 = 0;
            rs2 = 0;
            func3 = 0;
            func7 = 0;
            imm = 0;
            imm_s_w = imm_s_r;
            o_finish_w = o_finish_r;
        end
    end

    always @(*) begin

        if (cs == stage_ex) begin
            case (opcode_w)
                7'b0010011: begin
                    case (func3)
                        3'b000: begin 
                            alu_res_w = reg_file[rs1]+imm;
                        end
                        3'b100: begin 
                            alu_res_w = reg_file[rs1]^imm;
                        end
                        3'b110: begin 
                            alu_res_w = reg_file[rs1]|imm;
                        end
                        3'b111: begin 
                            alu_res_w = reg_file[rs1]&imm;
                        end
                        3'b001: begin 
                            alu_res_w = reg_file[rs1]<<imm;
                        end
                        3'b101: begin 
                            alu_res_w = reg_file[rs1]>>imm;
                        end
                        default: begin
                            alu_res_w = 0;
                        end
                    endcase
                end
                7'b0110011: begin
                    case (func3)
                        3'b000: begin
                            if (func7 == 7'b0) begin 
                                alu_res_w = reg_file[rs1]+reg_file[rs2];
                            end else begin 
                                alu_res_w = reg_file[rs1]-reg_file[rs2];
                            end
                        end
                        3'b100: begin 
                            alu_res_w = reg_file[rs1]^reg_file[rs2];
                        end
                        3'b110: begin 
                            alu_res_w = reg_file[rs1]|reg_file[rs2];
                        end
                        3'b111: begin 
                            alu_res_w = reg_file[rs1]&reg_file[rs2];
                        end
                        default: begin
                            alu_res_w = 0;
                        end
                    endcase
                end
                default: begin
                    alu_res_w = 0;
                end
            endcase
        end else begin
            alu_res_w = alu_res_r;
        end
    end

    always @(*) begin

        if (cs == stage_ex) begin
            case (opcode_w)
                7'b1100011: begin
                    if (func3 == 3'b0) begin 
                        take_br_w = (reg_file[rs1]==reg_file[rs2]);
                    end else begin 
                        take_br_w = (reg_file[rs1]!=reg_file[rs2]);
                    end
                end
                default: begin
                    take_br_w = 0;
                end
            endcase
        end else begin
            take_br_w = take_br_r;
        end
    end

    always @(*) begin

        if (cs == stage_ex) begin
            case (opcode_w)
                7'b0000011: begin
                    o_d_MemRead_w = 1;
                    o_d_MemWrite_w = 0;
                    o_d_w_data_w = 0;
                    o_d_w_addr_w = 0;
                    o_d_r_addr_w = reg_file[rs1]+imm;
                end
                7'b0100011: begin
                    o_d_MemRead_w = 0;
                    o_d_MemWrite_w = 1;
                    o_d_w_data_w = reg_file[rs2];
                    o_d_w_addr_w = reg_file[rs1]+imm;
                    o_d_r_addr_w = 0;
                end
                default: begin
                    o_d_MemRead_w = 0;
                    o_d_MemWrite_w = 0;
                    o_d_w_data_w = 0;
                    o_d_w_addr_w = 0;
                    o_d_r_addr_w = 0;
                end
            endcase
        end else begin
            o_d_MemRead_w = o_d_MemRead_r;
            o_d_MemWrite_w = o_d_MemWrite_r;
            o_d_w_data_w = o_d_w_data_r;
            o_d_w_addr_w = o_d_w_addr_r;
            o_d_r_addr_w = o_d_r_addr_r;
        end
    end

    always @(*) begin

        if (cs == stage_pc) begin
            if (opcode_r == 7'b1100011) begin
                if (take_br_r) begin
                    pc_w = pc_r+imm_s_r;
                end else begin
                    pc_w = pc_r+4;
                end
            end else begin
                pc_w = pc_r+4;
            end
        end else begin
            pc_w = pc_r;
        end
    end

    always @(*) begin

        for (i=0; i<32; i=i+1) begin
            reg_file_w[i] = reg_file[i];
        end

        if (cs == stage_wb_fetch) begin
            case (opcode_r)
                7'b0000011: begin
                    reg_file_w[rd_r] = i_d_data;
                end
                7'b0010011: begin
                    reg_file_w[rd_r] = alu_res_r;
                end
                7'b0110011: begin
                    reg_file_w[rd_r] = alu_res_r;
                end
            endcase
        end
    end


    always @(posedge i_clk or negedge i_rst_n) begin
        if (~i_rst_n) begin
            o_i_valid_addr_r <= 0;
            o_i_addr_r <= 0;
            o_d_w_data_r <= 0;
            o_d_w_addr_r <= 0;
            o_d_r_addr_r <= 0;
            o_d_MemRead_r <= 0;
            o_d_MemWrite_r <= 0;
            o_finish_r <= 0;

            opcode_r <= 0;
            rd_r <= 0;
            imm_s_r <= 0;

            pc_r <= 0;
            cs <= 0;
            alu_res_r <= 0;
            for (i=0; i<32; i++) begin
                reg_file[i] <= 0;
            end
            take_br_r <= 0;

        end else begin
            o_i_valid_addr_r <= o_i_valid_addr_w;
            o_i_addr_r <= o_i_addr_w;
            o_d_w_data_r <= o_d_w_data_w;
            o_d_w_addr_r <= o_d_w_addr_w;
            o_d_r_addr_r <= o_d_r_addr_w;
            o_d_MemRead_r <= o_d_MemRead_w;
            o_d_MemWrite_r <= o_d_MemWrite_w;
            o_finish_r <= o_finish_w;

            opcode_r <= opcode_w;
            rd_r <= rd_w;
            imm_s_r <= imm_s_w;

            pc_r <= pc_w;
            cs <= ns;
            alu_res_r <= alu_res_w;
            for (i=0; i<32; i++) begin
                reg_file[i] <= reg_file_w[i];
            end
            take_br_r <= take_br_w;
        end
    end



endmodule

module pcieCore_gtp_pipe_rate #
(
    parameter PCIE_SIM_SPEEDUP = "FALSE",                   
    parameter TXDATA_WAIT_MAX  = 4'd15                      
)
(
    input               RATE_CLK,
    input               RATE_RST_N,
    input       [ 1:0]  RATE_RATE_IN,
    input               RATE_DRP_DONE,
    input               RATE_RXPMARESETDONE,
    input               RATE_TXRATEDONE,
    input               RATE_RXRATEDONE,
    input               RATE_TXSYNC_DONE,
    input               RATE_PHYSTATUS,
    output              RATE_PCLK_SEL,
    output              RATE_DRP_START,
    output              RATE_DRP_X16,
    output      [ 2:0]  RATE_RATE_OUT,
    output              RATE_TXSYNC_START,
    output              RATE_DONE,
    output              RATE_IDLE,
    output      [ 4:0]  RATE_FSM
);
(* ASYNC_REG = "TRUE", SHIFT_EXTRACT = "NO" *)    reg         [ 1:0]  rate_in_reg1;
(* ASYNC_REG = "TRUE", SHIFT_EXTRACT = "NO" *)    reg                 drp_done_reg1;
(* ASYNC_REG = "TRUE", SHIFT_EXTRACT = "NO" *)    reg                 rxpmaresetdone_reg1;
(* ASYNC_REG = "TRUE", SHIFT_EXTRACT = "NO" *)    reg                 txratedone_reg1;
(* ASYNC_REG = "TRUE", SHIFT_EXTRACT = "NO" *)    reg                 rxratedone_reg1;
(* ASYNC_REG = "TRUE", SHIFT_EXTRACT = "NO" *)    reg                 phystatus_reg1;
(* ASYNC_REG = "TRUE", SHIFT_EXTRACT = "NO" *)    reg                 txsync_done_reg1;
(* ASYNC_REG = "TRUE", SHIFT_EXTRACT = "NO" *)    reg         [ 1:0]  rate_in_reg2;
(* ASYNC_REG = "TRUE", SHIFT_EXTRACT = "NO" *)    reg                 drp_done_reg2;
(* ASYNC_REG = "TRUE", SHIFT_EXTRACT = "NO" *)    reg                 rxpmaresetdone_reg2;
(* ASYNC_REG = "TRUE", SHIFT_EXTRACT = "NO" *)    reg                 txratedone_reg2;
(* ASYNC_REG = "TRUE", SHIFT_EXTRACT = "NO" *)    reg                 rxratedone_reg2;
(* ASYNC_REG = "TRUE", SHIFT_EXTRACT = "NO" *)    reg                 phystatus_reg2;
(* ASYNC_REG = "TRUE", SHIFT_EXTRACT = "NO" *)    reg                 txsync_done_reg2;
    wire        [ 2:0]  rate;
    reg         [ 3:0]  txdata_wait_cnt = 4'd0;
    reg                 txratedone      = 1'd0;
    reg                 rxratedone      = 1'd0;
    reg                 phystatus       = 1'd0;
    reg                 ratedone        = 1'd0;
    reg                 pclk_sel =  1'd0;
    reg         [ 2:0]  rate_out =  3'd0;
    reg         [ 3:0]  fsm      =  0;
    localparam          FSM_IDLE           = 0;
    localparam          FSM_TXDATA_WAIT    = 1;
    localparam          FSM_PCLK_SEL       = 2;
    localparam          FSM_DRP_X16_START  = 3;
    localparam          FSM_DRP_X16_DONE   = 4;
    localparam          FSM_RATE_SEL       = 5;
    localparam          FSM_RXPMARESETDONE = 6;
    localparam          FSM_DRP_X20_START  = 7;
    localparam          FSM_DRP_X20_DONE   = 8;
    localparam          FSM_RATE_DONE      = 9;
    localparam          FSM_TXSYNC_START   = 10;
    localparam          FSM_TXSYNC_DONE    = 11;
    localparam          FSM_DONE           = 12; 
always @ (posedge RATE_CLK)
begin
    if (!RATE_RST_N)
        begin
        rate_in_reg1        <= 2'd0;
        drp_done_reg1       <= 1'd0;
        rxpmaresetdone_reg1 <= 1'd0;
        txratedone_reg1     <= 1'd0;
        rxratedone_reg1     <= 1'd0;
        phystatus_reg1      <= 1'd0;
        txsync_done_reg1    <= 1'd0;
        rate_in_reg2        <= 2'd0;
        drp_done_reg2       <= 1'd0;
        rxpmaresetdone_reg2 <= 1'd0;
        txratedone_reg2     <= 1'd0;
        rxratedone_reg2     <= 1'd0;
        phystatus_reg2      <= 1'd0;
        txsync_done_reg2    <= 1'd0;
        end
    else
        begin
        rate_in_reg1        <= RATE_RATE_IN;
        drp_done_reg1       <= RATE_DRP_DONE;
        rxpmaresetdone_reg1 <= RATE_RXPMARESETDONE;
        txratedone_reg1     <= RATE_TXRATEDONE;
        rxratedone_reg1     <= RATE_RXRATEDONE;
        phystatus_reg1      <= RATE_PHYSTATUS;
        txsync_done_reg1    <= RATE_TXSYNC_DONE;
        rate_in_reg2        <= rate_in_reg1;
        drp_done_reg2       <= drp_done_reg1;
        rxpmaresetdone_reg2 <= rxpmaresetdone_reg1;
        txratedone_reg2     <= txratedone_reg1;
        rxratedone_reg2     <= rxratedone_reg1;
        phystatus_reg2      <= phystatus_reg1;
        txsync_done_reg2    <= txsync_done_reg1;
        end
end


assign rate = (rate_in_reg2 == 2'd1) ? 3'd1 : 3'd0;
always @ (posedge RATE_CLK)
begin
    if (!RATE_RST_N)
        txdata_wait_cnt <= 4'd0;
    else
        if ((fsm == FSM_TXDATA_WAIT) && (txdata_wait_cnt < TXDATA_WAIT_MAX))
            txdata_wait_cnt <= txdata_wait_cnt + 4'd1;
        else if ((fsm == FSM_TXDATA_WAIT) && (txdata_wait_cnt == TXDATA_WAIT_MAX))
            txdata_wait_cnt <= txdata_wait_cnt;
        else
            txdata_wait_cnt <= 4'd0;
end
always @ (posedge RATE_CLK)
begin
    if (!RATE_RST_N)
        begin
        txratedone <= 1'd0;
        rxratedone <= 1'd0;
        phystatus  <= 1'd0;
        ratedone   <= 1'd0;
        end
    else
        begin
        if ((fsm == FSM_RATE_DONE) || (fsm == FSM_RXPMARESETDONE) || (fsm == FSM_DRP_X20_START) || (fsm == FSM_DRP_X20_DONE))
            begin
            if (txratedone_reg2)
                txratedone <= 1'd1;
            else
                txratedone <= txratedone;
            if (rxratedone_reg2)
                rxratedone <= 1'd1;
            else
                rxratedone <= rxratedone;
            if (phystatus_reg2)
                phystatus <= 1'd1;
            else
                phystatus <= phystatus;
            if (rxratedone && txratedone && phystatus)
                ratedone <= 1'd1;
            else
                ratedone <= ratedone;
            end
        else
            begin
            txratedone <= 1'd0;
            rxratedone <= 1'd0;
            phystatus  <= 1'd0;
            ratedone   <= 1'd0;
            end
        end
end
always @ (posedge RATE_CLK)
begin
    if (!RATE_RST_N)
        begin
        fsm      <= FSM_IDLE;
        pclk_sel <= 1'd0;
        rate_out <= 3'd0;
        end
    else
        begin
        case (fsm)
        FSM_IDLE :
            begin
            if (rate_in_reg2 != rate_in_reg1)
                begin
                fsm      <= FSM_TXDATA_WAIT;
                pclk_sel <= pclk_sel;
                rate_out <= rate_out;
                end
            else
                begin
                fsm      <= FSM_IDLE;
                pclk_sel <= pclk_sel;
                rate_out <= rate_out;
                end
            end
        FSM_TXDATA_WAIT :
            begin
            fsm      <= (txdata_wait_cnt == TXDATA_WAIT_MAX) ? FSM_PCLK_SEL : FSM_TXDATA_WAIT;
            pclk_sel <= pclk_sel;
            rate_out <= rate_out;
            end


        FSM_PCLK_SEL :
            begin
            fsm      <= (PCIE_SIM_SPEEDUP == "TRUE") ? FSM_RATE_SEL : FSM_DRP_X16_START;
            pclk_sel <= (rate_in_reg2 == 2'd1);
            rate_out <= rate_out;
            end
        FSM_DRP_X16_START :
            begin
            fsm      <= (!drp_done_reg2) ? FSM_DRP_X16_DONE : FSM_DRP_X16_START;
            pclk_sel <= pclk_sel;
            rate_out <= rate_out;
            end
        FSM_DRP_X16_DONE :
            begin
            fsm      <= drp_done_reg2 ? FSM_RATE_SEL : FSM_DRP_X16_DONE;
            pclk_sel <= pclk_sel;
            rate_out <= rate_out;
            end
        FSM_RATE_SEL :
            begin
            fsm      <= (PCIE_SIM_SPEEDUP == "TRUE") ? FSM_RATE_DONE : FSM_RXPMARESETDONE;
            pclk_sel <= pclk_sel;
            rate_out <= rate;                               
            end
        FSM_RXPMARESETDONE :
            begin
            fsm      <= (!rxpmaresetdone_reg2) ? FSM_DRP_X20_START : FSM_RXPMARESETDONE;
            pclk_sel <= pclk_sel;
            rate_out <= rate_out;
            end
        FSM_DRP_X20_START :
            begin
            fsm      <= (!drp_done_reg2) ? FSM_DRP_X20_DONE : FSM_DRP_X20_START;
            pclk_sel <= pclk_sel;
            rate_out <= rate_out;
            end
        FSM_DRP_X20_DONE :
            begin
            fsm      <= drp_done_reg2 ? FSM_RATE_DONE : FSM_DRP_X20_DONE;
            pclk_sel <= pclk_sel;
            rate_out <= rate_out;
            end
        FSM_RATE_DONE :
            begin
            if (ratedone)
                fsm <= FSM_TXSYNC_START;
            else
                fsm <= FSM_RATE_DONE;
            pclk_sel <= pclk_sel;
            rate_out <= rate_out;
            end
        FSM_TXSYNC_START:
            begin
            fsm      <= (!txsync_done_reg2 ? FSM_TXSYNC_DONE : FSM_TXSYNC_START);
            pclk_sel <= pclk_sel;
            rate_out <= rate_out;
            end
        FSM_TXSYNC_DONE:
            begin
            fsm      <= (txsync_done_reg2 ? FSM_DONE : FSM_TXSYNC_DONE);
            pclk_sel <= pclk_sel;
            rate_out <= rate_out;
            end
        FSM_DONE :
            begin
            fsm      <= FSM_IDLE;
            pclk_sel <= pclk_sel;
            rate_out <= rate_out;
            end
        default :
            begin
            fsm      <= FSM_IDLE;
            pclk_sel <= 1'd0;
            rate_out <= 3'd0;
            end
        endcase
        end
end
assign RATE_PCLK_SEL     = pclk_sel;
assign RATE_DRP_START    = (fsm == FSM_DRP_X16_START) || (fsm == FSM_DRP_X20_START);
assign RATE_DRP_X16      = (fsm == FSM_DRP_X16_START) || (fsm == FSM_DRP_X16_DONE);
assign RATE_RATE_OUT     = rate_out;
assign RATE_TXSYNC_START = (fsm == FSM_TXSYNC_START);
assign RATE_DONE         = (fsm == FSM_DONE);
assign RATE_IDLE         = (fsm == FSM_IDLE);
assign RATE_FSM          = {1'd0, fsm};
endmodule

module mod_m_counter #(
  parameter MOD     = 65,         
  parameter MOD_BIT = $clog2(MOD) 
) (
  input  clk_i,
  input  rst_ni,
  output max_tick_o
);


  reg  [MOD_BIT-1:0] count_reg;
  wire [MOD_BIT-1:0] count_next;



  always @(posedge clk_i, negedge rst_ni) begin
    if (~rst_ni)
      count_reg <= 0;
    else
      count_reg <= count_next;
  end


  assign count_next = (count_reg == (MOD - 1)) ? {(MOD_BIT){1'b0}} : count_reg + 1'b1;


  assign max_tick_o = (count_reg == (MOD-1)) ? 1'b1 : 1'b0;

endmodule

module processador_fsm (flagz, flagn, opcode, clock, reset,pc_inicio, pc_inc, pc_wr, ir_wr, ir_re, mar_wr, clk_md, clk_mi, mbr_wr_m, mbr_wr_b, mbr_re_b, ac_wr, ac_re, ula_sel, ula_re, wren);


	output reg pc_inicio;
	output reg pc_inc;
	output reg pc_wr;
	output reg ir_wr;
	output reg ir_re;
	output reg mar_wr;
	output reg clk_md;
	output reg clk_mi;
	output reg mbr_wr_m;
	output reg mbr_wr_b;
	output reg mbr_re_b;
	output reg ac_wr;
	output reg ac_re;
	output reg [3:0]ula_sel;
	output reg ula_re;
	output reg wren;


	input flagz;
	input flagn;
	input [3:0]opcode;
	input clock;
	input reset;


	reg [4:0]est_f;
	reg [4:0]est_a;
	reg [3:0]opcodeInter;


	parameter inicio = 5'b00000;
	parameter ler_ir = 5'b00001;
	parameter dec_opcode_1 = 5'b00010;
	parameter dec_opcode_2 = 5'b00011;
	parameter load_1 = 5'b00100;
	parameter load_2 = 5'b00101;
	parameter load_3 = 5'b00110;
	parameter load_4 = 5'b00111;
	parameter load_5 = 5'b01000;
	parameter store_1 = 5'b01001;
	parameter store_2 = 5'b01010;
	parameter store_3 = 5'b01011;
	parameter store_4 = 5'b01100;
	parameter store_5 = 5'b01101;
	parameter ula_op_1 = 5'b01110;
	parameter ula_op_2 = 5'b01111;
	parameter ula_op_3 = 5'b10000;
	parameter ula_op_4 = 5'b10001;
	parameter ula_op_5 = 5'b10010;
	parameter ula_op_6 = 5'b10011;
	parameter jump = 5'b10100;
	parameter pc_incre = 5'b10101;


	parameter lda = 4'b0000;
	parameter sta = 4'b0001;
	parameter add = 4'b0010;
	parameter sub = 4'b0011;
	parameter mul = 4'b0100;
	parameter div = 4'b0101;
	parameter andp = 4'b0110;
	parameter orp = 4'b0111;
	parameter notp = 4'b1000;
	parameter jmp = 4'b1001;
	parameter jn = 4'b1010;
	parameter jz = 4'b1011;
	parameter nop = 4'b1100;


	always @ (est_a, opcode, flagn, flagz)
	begin

		est_f=inicio;
		case (est_a)
			inicio: 
				est_f=ler_ir;
			pc_incre:
				est_f=ler_ir;
			ler_ir:
				est_f=dec_opcode_1;
			dec_opcode_1: 
				est_f=dec_opcode_2;
			dec_opcode_2:
				begin
					case (opcode)
						lda: 
							est_f = load_1;
						sta: 
							est_f = store_1;
						add: 
							est_f = ula_op_1;
						sub: 
							est_f = ula_op_1;
						mul:
							est_f = ula_op_1;
						div: 
							est_f = ula_op_1;
						andp: 
							est_f = ula_op_1;
						orp: 
							est_f = ula_op_1;
						notp: 
							est_f = ula_op_4;
						jmp: 
							est_f = jump;
						nop: 
							est_f = pc_incre;
						jz:
							begin 
								if (flagz) est_f = jump;
								else est_f = pc_incre;
							end
						jn :
							begin 
								if (flagn) est_f = jump;
								else est_f=pc_incre;
							end
						default:	;

					endcase
				end
			load_1:	
				est_f=load_2;
			load_2: 
				est_f=load_3;
			load_3: 
				est_f=load_4;
			load_4: 
				est_f=load_5;
			load_5: 
				est_f=pc_incre;
			store_1: 
				est_f=store_2;
			store_2: 
				est_f=store_3;
			store_3: 
				est_f=store_4;
			store_4: 
				est_f=store_5;
			store_5: 
				est_f=pc_incre;
			ula_op_1: 
				est_f=ula_op_2;
			ula_op_2: 
				est_f=ula_op_3;
			ula_op_3: 
				est_f=ula_op_4;
			ula_op_4: 
				est_f=ula_op_5;
			ula_op_5: 
				est_f=ula_op_6;
			ula_op_6: 
				est_f=pc_incre;
			jump: 
				est_f=ler_ir;
			default:;
		endcase
	end	
	always @ (est_a)
	begin

		pc_inicio = 1'b0;
		pc_inc = 1'b0;
		pc_wr = 1'b0;
		ir_wr = 1'b0;
		ir_re = 1'b0;
		mar_wr = 1'b0;
		clk_md = 1'b0;
		clk_mi = 1'b0;
		mbr_wr_m = 1'b0;
		mbr_wr_b = 1'b0;
		mbr_re_b = 1'b0;
		ac_wr = 1'b0;
		ac_re = 1'b0;
		ula_sel = 4'b0000;
		ula_re = 1'b0;
		wren=1'b0;
		case (est_a)
				inicio: 
					pc_inicio=1'b1;
				pc_incre:
					pc_inc=1'b1;
				ler_ir:
					clk_mi=1'b1;
				dec_opcode_1:
					ir_wr=1'b1;
				dec_opcode_2:
					begin
					ir_re=1'b1;
					opcodeInter=opcode;
					end
				load_1:
					begin
						mar_wr=1'b1;
						ir_re=1'b1;
					end
				load_2:
						clk_md=1'b1;
				load_3:
						mbr_wr_m=1'b1;
				load_4:
						mbr_re_b=1'b1;
				load_5:
					begin
						ac_wr=1'b1;
						mbr_re_b=1'b1;
					end
				store_1:
					begin
						mar_wr=1'b1;
						ir_re=1'b1;
					end
				store_2:
					begin
						ac_re=1'b1;
						clk_md=1'b1;
					end
				store_3:
					begin
						ac_re=1'b1;
						mbr_wr_b=1'b1;
					end
				store_4:
					begin
						clk_md=1'b1;
						wren=1'b1;
					end
				store_5:
					begin
						clk_md=1'b1;
						wren=1'b1;
					end
				ula_op_1:
					begin
						mar_wr=1'b1;
						ir_re=1'b1;
					end
				ula_op_2:
						clk_md=1'b1;
				ula_op_3:
						mbr_wr_m=1'b1;
				ula_op_4:
						ula_sel=opcodeInter;
				ula_op_5:
						ula_re=1'b1;
				ula_op_6:
					begin
						ula_re=1'b1;
						ac_wr=1'b1;
					end
				jump:
					begin
						pc_wr=1'b1;
						ir_re=1'b1;
					end
				default:;
			endcase

	end	
	always @ (posedge clock)
		begin
			if (reset) est_a<=inicio;
			else est_a<=est_f;
		end
endmodule

`timescale  1ns/1ns


















module  adc
(
    input   wire            sys_clk         ,   
    input   wire            sys_rst_n       ,   
    input   wire    [7:0]   ad_data         ,   

    output  wire            ad_clk          ,   
    output  wire            sign            ,   
    output  wire    [15:0]  volt                
);




parameter   CNT_DATA_MAX = 11'd1024;    


wire    [27:0]  data_p      ;   
wire    [27:0]  data_n      ;   


reg             median_en   ;   
reg     [10:0]  cnt_median  ;   
reg     [18:0]  data_sum_m  ;   
reg     [7:0]   data_median ;   
reg     [1:0]   cnt_sys_clk ;   
reg             clk_sample  ;   
reg     [27:0]  volt_reg    ;   








assign  ad_clk = ~clk_sample;


assign  sign = (ad_data < data_median) ? 1'b1 : 1'b0;


always@(posedge sys_clk or negedge sys_rst_n)
    if(sys_rst_n == 1'b0)
        begin
            cnt_sys_clk <=  2'd0;
            clk_sample  <=  1'b0;
        end
        else
        begin
            cnt_sys_clk <=  cnt_sys_clk + 2'd1;
        if(cnt_sys_clk == 2'd1)
            begin
            cnt_sys_clk <=  2'd0;
            clk_sample  <=  ~clk_sample;
            end
        end


always@(posedge clk_sample or negedge sys_rst_n)
    if(sys_rst_n == 1'b0)
        median_en   <=  1'b0;
    else    if(cnt_median == CNT_DATA_MAX)
        median_en   <=  1'b1;
    else
        median_en   <=  median_en;


always@(posedge clk_sample or negedge sys_rst_n)
    if(sys_rst_n == 1'b0)
        cnt_median    <=  11'd0;
    else    if(median_en == 1'b0)
        cnt_median    <=  cnt_median + 1'b1;


always@(posedge clk_sample or negedge sys_rst_n)
    if(sys_rst_n == 1'b0)
        data_sum_m  <=  19'd0;
    else    if(cnt_median == CNT_DATA_MAX)
        data_sum_m    <=  19'd0;
    else
        data_sum_m    <=  data_sum_m + ad_data;


always@(posedge clk_sample or negedge sys_rst_n)
    if(sys_rst_n == 1'b0)
        data_median    <=  8'd0;
    else    if(cnt_median == CNT_DATA_MAX)
        data_median    <=  data_sum_m / CNT_DATA_MAX;
    else
        data_median    <=  data_median;



assign  data_p = (median_en == 1'b1) ? 8192_0000 / ((255 - data_median) * 2) : 0;
assign  data_n = (median_en == 1'b1) ? 8192_0000 / ((data_median + 1) * 2) : 0;


always@(posedge clk_sample or negedge sys_rst_n)
    if(sys_rst_n == 1'b0)
        volt_reg    <= 'd0;
    else    if(median_en == 1'b1)
        if((ad_data > (data_median - 3))&&(ad_data < (data_median + 3)))
            volt_reg    <= 'd0;
        else    if(ad_data < data_median)
            volt_reg <= (data_n *(data_median - ad_data)) >> 13;
        else    if(ad_data > data_median)
            volt_reg <= (data_p *(ad_data - data_median)) >> 13;
    else
        volt_reg    <= 'd0;


assign  volt    =   volt_reg;

endmodule

module UART_CONTROLLER #(
    parameter length = 32,
    parameter CLKS_PER_BIT = 434, 
    parameter SIG_RUN = 82,
    parameter SIG_STOP = 83,
    parameter DATA_LENGTH = 256
) (

    input i_clk, 
    input i_rst, 
    input i_rxd,
    output o_txd,

    input [2*length-1:0] i_fft_data,
    input i_tx_valid,
    output reg o_tx_ready 
);

localparam ST_IDLE = 2'd0;
localparam ST_SEND = 2'd1;
localparam ST_SHIFT = 2'd2;
localparam ST_FFT = 2'd3;
wire w_Rx_DV;
wire [7:0] w_Rx_Byte;
wire w_Tx_Done;
reg r_Tx_DV;
reg [7:0] r_Tx_Byte;
reg [9:0] r_cnt_tx;
reg [2*length-1:0] r_uart_data_tx_shift;
reg [3:0] r_cnt_data;
reg [1:0] r_ps;

uart_rx #(.CLKS_PER_BIT(CLKS_PER_BIT)) uart_rx
  (
   .i_Clock(i_clk),
   .i_Rx_Serial(i_rxd),
   .o_Rx_DV(w_Rx_DV),
   .o_Rx_Byte(w_Rx_Byte)
   );
uart_tx #(.CLKS_PER_BIT(CLKS_PER_BIT)) uart_tx
   (
    .i_Clock(i_clk),
    .i_Tx_DV(r_Tx_DV),
    .i_Tx_Byte(r_Tx_Byte),
    .o_Tx_Active(),
    .o_Tx_Serial(o_txd),
    .o_Tx_Done(w_Tx_Done)
    );

always @(posedge i_clk) begin
    if(i_rst) begin
        r_ps <= ST_IDLE;
        r_Tx_DV <= 0;
        r_Tx_Byte <= 0;
        r_cnt_tx <= 0;
        r_cnt_data <= 0;
        o_tx_ready <= 0;
    end
    else begin
        case (r_ps)
           ST_IDLE :
           begin
            if(w_Rx_DV) begin
                if(w_Rx_Byte == SIG_STOP) r_ps <= ST_IDLE;
                else if(w_Rx_Byte == SIG_RUN) begin
                    if(r_cnt_tx < DATA_LENGTH) begin
                        r_ps <= ST_FFT;
                        o_tx_ready <= 1;
                    end
                    else begin
                        r_ps <= ST_IDLE;
                        r_cnt_tx <= 0;
                    end
                end
            end
            else r_ps <= ST_IDLE;
           end
           ST_SEND :
           begin
            if(r_cnt_data > 7) begin
                r_ps <= ST_IDLE;
                r_cnt_data <= 0;
                r_Tx_DV <= 0;
                r_cnt_tx <= r_cnt_tx + 1'b1;
            end
            else begin
                r_ps <= ST_SHIFT;
                r_Tx_DV <= 1;
                r_Tx_Byte <= r_uart_data_tx_shift[63:56];
                r_cnt_data <= r_cnt_data + 1'b1;
            end
           end
           ST_SHIFT :
           begin
            if(w_Tx_Done) begin
                r_ps <= ST_SEND;
                r_uart_data_tx_shift <= (r_uart_data_tx_shift<<8);
            end
            else begin
                r_ps <= ST_SHIFT;
                r_Tx_DV <= 0;
            end
           end
           ST_FFT :
           begin
            if(i_tx_valid) begin
                o_tx_ready <= 0;
                r_ps <= ST_SEND;
                r_uart_data_tx_shift <= i_fft_data;
            end
            else r_ps <= ST_FFT; 
           end
            default: r_ps <= ST_IDLE; 
        endcase
    end
end
endmodule



























module uart_rx
  #(parameter CLKS_PER_BIT = 0)
  (
   input        i_Clock,
   input        i_Rx_Serial,
   output       o_Rx_DV,
   output [7:0] o_Rx_Byte
   );

  localparam s_IDLE         = 3'b000;
  localparam s_RX_START_BIT = 3'b001;
  localparam s_RX_DATA_BITS = 3'b010;
  localparam s_RX_STOP_BIT  = 3'b011;
  localparam s_CLEANUP      = 3'b100;

  reg           r_Rx_Data_R = 1'b1;
  reg           r_Rx_Data   = 1'b1;

  reg [15:0]     r_Clock_Count = 0;
  reg [2:0]     r_Bit_Index   = 0; 
  reg [7:0]     r_Rx_Byte     = 0;
  reg           r_Rx_DV       = 0;
  reg [2:0]     r_SM_Main     = 0;




  always @(posedge i_Clock)
    begin
      r_Rx_Data_R <= i_Rx_Serial;
      r_Rx_Data   <= r_Rx_Data_R;
    end



  always @(posedge i_Clock)
    begin

      case (r_SM_Main)
        s_IDLE :
          begin
            r_Rx_DV       <= 1'b0;
            r_Clock_Count <= 0;
            r_Bit_Index   <= 0;

            if (r_Rx_Data == 1'b0)          
              r_SM_Main <= s_RX_START_BIT;
            else
              r_SM_Main <= s_IDLE;
          end


        s_RX_START_BIT :
          begin
            if (r_Clock_Count == (CLKS_PER_BIT-1)/2)
              begin
                if (r_Rx_Data == 1'b0)
                  begin
                    r_Clock_Count <= 0;  
                    r_SM_Main     <= s_RX_DATA_BITS;
                  end
                else
                  r_SM_Main <= s_IDLE;
              end
            else
              begin
                r_Clock_Count <= r_Clock_Count + 1'b1;
                r_SM_Main     <= s_RX_START_BIT;
              end
          end 



        s_RX_DATA_BITS :
          begin
            if (r_Clock_Count < CLKS_PER_BIT-1)
              begin
                r_Clock_Count <= r_Clock_Count + 1'b1;
                r_SM_Main     <= s_RX_DATA_BITS;
              end
            else
              begin
                r_Clock_Count          <= 0;
                r_Rx_Byte[r_Bit_Index] <= r_Rx_Data;


                if (r_Bit_Index < 7)
                  begin
                    r_Bit_Index <= r_Bit_Index + 1'b1;
                    r_SM_Main   <= s_RX_DATA_BITS;
                  end
                else
                  begin
                    r_Bit_Index <= 0;
                    r_SM_Main   <= s_RX_STOP_BIT;
                  end
              end
          end 



        s_RX_STOP_BIT :
          begin

            if (r_Clock_Count < CLKS_PER_BIT-1)
              begin
                r_Clock_Count <= r_Clock_Count + 1'b1;
                r_SM_Main     <= s_RX_STOP_BIT;
              end
            else
              begin
                r_Rx_DV       <= 1'b1;
                r_Clock_Count <= 0;
                r_SM_Main     <= s_CLEANUP;
              end
          end 



        s_CLEANUP :
          begin
            r_SM_Main <= s_IDLE;
            r_Rx_DV   <= 1'b0;
          end


        default :
          r_SM_Main <= s_IDLE;

      endcase
    end

  assign o_Rx_DV   = r_Rx_DV;
  assign o_Rx_Byte = r_Rx_Byte;

endmodule 

module uart_tx
  #(parameter CLKS_PER_BIT = 0)
  (
   input       i_Clock,
   input       i_Tx_DV,
   input [7:0] i_Tx_Byte,
   output      o_Tx_Active,
   output reg  o_Tx_Serial,
   output      o_Tx_Done
   );

  localparam s_IDLE         = 3'b000;
  localparam s_TX_START_BIT = 3'b001;
  localparam s_TX_DATA_BITS = 3'b010;
  localparam s_TX_STOP_BIT  = 3'b011;
  localparam s_CLEANUP      = 3'b100;

  reg [2:0]    r_SM_Main     = 0;
  reg [15:0]    r_Clock_Count = 0;
  reg [2:0]    r_Bit_Index   = 0;
  reg [7:0]    r_Tx_Data     = 0;
  reg          r_Tx_Done     = 0;
  reg          r_Tx_Active   = 0;

  always @(posedge i_Clock)
    begin

      case (r_SM_Main)
        s_IDLE :
          begin
            o_Tx_Serial   <= 1'b1;         
            r_Tx_Done     <= 1'b0;
            r_Clock_Count <= 0;
            r_Bit_Index   <= 0;

            if (i_Tx_DV == 1'b1)
              begin
                r_Tx_Active <= 1'b1;
                r_Tx_Data   <= i_Tx_Byte;
                r_SM_Main   <= s_TX_START_BIT;
              end
            else
              r_SM_Main <= s_IDLE;
          end 



        s_TX_START_BIT :
          begin
            o_Tx_Serial <= 1'b0;


            if (r_Clock_Count < CLKS_PER_BIT-1'b1)
              begin
                r_Clock_Count <= r_Clock_Count + 1'b1;
                r_SM_Main     <= s_TX_START_BIT;
              end
            else
              begin
                r_Clock_Count <= 0;
                r_SM_Main     <= s_TX_DATA_BITS;
              end
          end 



        s_TX_DATA_BITS :
          begin
            o_Tx_Serial <= r_Tx_Data[r_Bit_Index];

            if (r_Clock_Count < CLKS_PER_BIT-1'b1)
              begin
                r_Clock_Count <= r_Clock_Count + 1'b1;
                r_SM_Main     <= s_TX_DATA_BITS;
              end
            else
              begin
                r_Clock_Count <= 0;


                if (r_Bit_Index < 7)
                  begin
                    r_Bit_Index <= r_Bit_Index + 1'b1;
                    r_SM_Main   <= s_TX_DATA_BITS;
                  end
                else
                  begin
                    r_Bit_Index <= 0;
                    r_SM_Main   <= s_TX_STOP_BIT;
                  end
              end
          end 



        s_TX_STOP_BIT :
          begin
            o_Tx_Serial <= 1'b1;


            if (r_Clock_Count < CLKS_PER_BIT-1)
              begin
                r_Clock_Count <= r_Clock_Count + 1'b1;
                r_SM_Main     <= s_TX_STOP_BIT;
              end
            else
              begin
                r_Tx_Done     <= 1'b1;
                r_Clock_Count <= 0;
                r_SM_Main     <= s_CLEANUP;
                r_Tx_Active   <= 1'b0;
              end
          end 



        s_CLEANUP :
          begin
            r_Tx_Done <= 1'b0;
            r_SM_Main <= s_IDLE;
          end


        default :
          r_SM_Main <= s_IDLE;

      endcase
    end

  assign o_Tx_Active = r_Tx_Active;
  assign o_Tx_Done   = r_Tx_Done;

endmodule

