module CU(
    input clk,
    input reset,
    input start,
    input CO,
    input Z,
    output reg WE,
    output reg Busy,
    output reg [1:0] InsSel,
    output reg [2:0] InMuxAdd,
    output reg [3:0] OutMuxAdd,
    output reg [3:0] RegAdd,
    output reg [7:0] CUconst
    );

    reg [4:0] s;




    always @(posedge clk or posedge reset) begin

        if(reset) begin
            s <= 0;
            WE <= 0;
            Busy <= 0;
            InsSel <= 0;
            CUconst <= 0;
            InMuxAdd <= 0;
            OutMuxAdd <= 0;
            RegAdd <= 0;


        end
        else begin
            case(s)
            0 : begin 
                if(start) begin
                    s <= 1;
                    Busy <= 1;
                end
            end
            1: begin 
                InMuxAdd <= 0;
                RegAdd <= 3;
                WE <= 1;
                s <= 2;
            end
            2: begin 
                InMuxAdd <= 1;
                RegAdd <= 4;
                WE <= 1;
                s <= 3;
            end
            3: begin 
                OutMuxAdd <= 3;
                InMuxAdd <= 4;
                RegAdd <= 1;
                WE <= 1;
                s <= 4;
            end
            4: begin 
                OutMuxAdd <= 3;
                InMuxAdd <= 4;
                RegAdd <= 2;
                WE <= 1;
                s <= 5;
                InsSel <= 2; 
            end
            5: begin 
                InMuxAdd <= 3; 
                RegAdd <= 1;
                WE <= 1;
                s <= 6;
            end
            6: begin  
                InMuxAdd <= 3; 
                RegAdd <= 1;
                WE <= 1;
                s <= 7;
            end
            7: begin  
                InMuxAdd <= 3; 
                RegAdd <= 1;
                WE <= 1;
                s <= 8;
            end
            8: begin  
                InMuxAdd <= 3; 
                RegAdd <= 1;
                WE <= 1;
                s <= 9;
            end
            9: begin  
                InMuxAdd <= 3; 
                RegAdd <= 5;
                WE <= 1;
                s <= 10;
            end
            10: begin  
                InMuxAdd <= 4; 
                OutMuxAdd <= 5; 
                RegAdd <= 1; 
                WE <= 1;
                s <= 11;               
            end
            11: begin  
                InMuxAdd <= 4; 
                OutMuxAdd <= 4; 
                RegAdd <= 2; 
                WE <= 1;
                s <= 12;  
            end
            12: begin 
                InMuxAdd <= 3; 
                RegAdd <= 6; 
                WE <= 1;
                s <= 13;
            end
            13: begin 
                InMuxAdd <= 4; 
                OutMuxAdd <= 6; 
                RegAdd <= 1; 
                WE <= 1;
                InsSel <= 3;
                s <= 14;
            end
            14: begin 
                CUconst <= 8'b1111_1101; 
                InMuxAdd <= 2; 
                RegAdd <= 2; 
                WE <= 1;
                InsSel <= 3;
                s <= 15;                
            end
            15: begin 
                if(CO) begin 
                    InMuxAdd <= 4;
                    OutMuxAdd <= 7;
                    RegAdd <= 1;
                    WE <= 1;
                    s <= 20;

                end
                else begin 
                    InsSel <= 2; 
                    InMuxAdd <= 3; 
                    RegAdd <= 8; 
                    WE <= 1;
                    s <= 16;
                end
            end
            16: begin 
                InMuxAdd <= 4;
                OutMuxAdd <= 7;
                RegAdd <= 1; 
                WE <= 1;
                s <= 17;
            end
            17: begin 
                CUconst <= 1;
                InMuxAdd <= 2;
                RegAdd <= 2; 
                WE <= 1;
                InsSel <= 2; 
                s <= 18;
            end
            18: begin 
                InMuxAdd <= 3; 
                WE <= 1;
                RegAdd <= 7; 
                s <= 19;
            end
            19: begin 
                OutMuxAdd <= 8;
                InMuxAdd <= 4; 
                WE <= 1;
                RegAdd <= 1; 
                s <= 14; 
            end
            20: begin 
                CUconst <= 8'b1111_1111; 
                InMuxAdd <= 2; 
                RegAdd <= 2; 
                WE <= 1;
                InsSel <= 2;
                s <= 21;
            end
            21: begin
                InMuxAdd <= 3; 
                RegAdd <= 0; 
                WE <= 1;
                s <= 22;
            end
            22: begin
                WE <= 0; 
                Busy <= 0;

            end
            endcase
        end

    end

endmodule

module reservation_station (
    input wire clk,
