module controller_BOOTH(


    output reg LdA,
    output reg clrA,
    output reg sftA,


    output reg LdQ,
    output reg clrQ,
    output reg sftQ,


    output reg sftDff,
    output reg clrff,


    output reg LdM,
    output reg clrM,


    output reg add_sub,
    output reg EnableALU,


    output reg decr,
    output reg LdCount,



    output reg done,

    input wire clk,
    input wire q0,
    input wire qm1,
    input wire start,
    input wire eqz
    );


    reg [3:0] state;


    parameter   idle=   4'b1100,     
                clear=  4'b1110,     
                load=   4'b1010,     
                dummy=  4'b1000,     
                check=  4'b1001,     
                shift=  4'b0000,     
                add=    4'b0001,     
                sub=    4'b0010,     
                done_state=   4'b0100;     




    always @(posedge clk) begin
        case (state)


            idle: if(start) state<= clear;



            clear: state<= load;




            load: state<= dummy;



            dummy: state<= check;



            check: begin
                if(eqz== 1) state<= done_state;
                else if({q0, qm1}== 2'b01) state<= add;
                else if({q0, qm1}== 2'b10) state<= sub;
                else state<= shift;
            end




            shift: state<= dummy;





            add: state<= shift;




            sub: state<= shift;




            done_state: state<= idle;



            default: state<= idle;
        endcase
    end




    always @(state) begin
        case (state)
            idle: begin


                {LdA, clrA, sftA}= 3'b000;


                {LdQ, clrQ, sftQ}= 3'b000;


                {LdM, clrM, clrff, sftDff, done}= 5'b0000; 

                {add_sub, EnableALU, LdCount, decr}= 4'b0000;
            end

            clear: begin

                {LdA, clrA, sftA}= 3'b010; 


                {LdQ, clrQ, sftQ}= 3'b010; 


                {LdM, clrM, clrff, sftDff, done}= 5'b01_100; 
                {add_sub, EnableALU, LdCount, decr}= 4'b0000;
            end

            load: begin
                {LdA, clrA, sftA}= 3'b000;


                {LdQ, clrQ, sftQ}= 3'b100;


                {LdM, clrM, clrff, sftDff, done}= 5'b10_000;


                {add_sub, EnableALU, LdCount, decr}= 4'b0010;
            end

            dummy: begin


                {LdA, clrA, sftA}= 3'b000;


                {LdQ, clrQ, sftQ}= 3'b000;


                {LdM, clrM, clrff, sftDff, done}= 5'b0000; 

                {add_sub, EnableALU, LdCount, decr}= 4'b0000;
            end

            check: begin


                {LdA, clrA, sftA}= 3'b000; 
                {LdQ, clrQ, sftQ}= 3'b000; 
                {LdM, clrM, clrff, sftDff, done}= 5'b00_000; 
                {add_sub, EnableALU, LdCount, decr}= 4'b0000;
            end

            add: begin


                {LdA, clrA, sftA}= 3'b100; 
                {LdQ, clrQ, sftQ}= 3'b000; 
                {LdM, clrM, clrff, sftDff, done}= 5'b00_000;

                {add_sub, EnableALU, LdCount, decr}= 4'b1100;
            end

            sub: begin

                {LdA, clrA, sftA}= 3'b100; 
                {LdQ, clrQ, sftQ}= 3'b000; 
                {LdM, clrM, clrff, sftDff, done}= 5'b00_000;

                {add_sub, EnableALU, LdCount, decr}= 4'b0100;
            end

            shift: begin

                {LdA, clrA, sftA}= 3'b001;

                {LdQ, clrQ, sftQ}= 3'b001;

                {LdM, clrM, clrff, sftDff, done}= 5'b00_010;

                {add_sub, EnableALU, LdCount, decr}= 4'b0001;
            end


            done_state: begin

                {LdA, clrA, sftA}= 3'b000; 
                {LdQ, clrQ, sftQ}= 3'b000; 
                {LdM, clrM, clrff, sftDff, done}= 5'b00_001; 
                {add_sub, EnableALU, LdCount, decr}= 4'b0000;
            end

            default: begin

                {LdA, clrA, sftA}= 3'b000; 
                {LdQ, clrQ, sftQ}= 3'b000; 
                {LdM, clrM, clrff, sftDff, done}= 5'b00_000; 
                {add_sub, EnableALU, LdCount, decr}= 4'b0000;
            end
        endcase
    end
endmodule

