module my_div(
        input clk,
        input reset,
        input div,
        input div_signed,
        input [31:0] x,
        input [31:0] y,
        output [31:0] s, 
        output [31:0] r, 
        output complete
);
        wire x_signed;
        wire y_signed;
        wire s_signed;
        wire r_signed;
        wire [31:0] x_abs;
        wire [31:0] y_abs;
        reg [63:0] div_a;
        reg [63:0] div_mask; 
        reg [31:0] div_s;
        wire [31:0] div_r;
        reg [5:0] time_cnter;

        wire ss_res_is_pos;
        wire [63:0] ss_a_aligned;

        assign x_signed = x[31] & div_signed;
        assign y_signed = y[31] & div_signed;
        assign s_signed = (x[31]^y[31]) & div_signed;
        assign r_signed = x[31] & div_signed;
        assign x_abs = ({32{x_signed}}^x) + x_signed;
        assign y_abs = ({32{y_signed}}^y) + y_signed;

        always @(posedge clk) begin
                if(div & (time_cnter == 6'b0))
                        div_mask <= 64'h000000007fffffff;
                else
                        div_mask <= {1'b1,div_mask[63:1]};
        end
        always @(posedge clk) begin
                if(div & (time_cnter == 6'b0))
                        div_a <= {32'b0,x_abs};
                else if(ss_res_is_pos) 
                        div_a <= ( div_mask & div_a ) | ss_a_aligned;
        end
        always @(posedge clk) begin
                if(div & (time_cnter == 6'b0))
                        div_s <= 32'b0;
                else 
                        div_s <= {div_s[30:0],ss_res_is_pos};
        end

        always @(posedge clk) begin
                if(reset | ~div | complete)
                        time_cnter <= 6'b0;
                else 
                        time_cnter <= time_cnter + 1'b1;
        end
        assign complete = time_cnter == 6'd33;

        shift_sub ss1(
                .a_in           (div_a),
                .time_cnter     (time_cnter),
                .b              (y_abs),
                .res_is_pos     (ss_res_is_pos),
                .a_aligned      (ss_a_aligned)
        );

        assign div_r = div_a[31:0];
        assign s = ({32{s_signed}}^div_s) + s_signed;
        assign r = ({32{r_signed}}^div_r) + r_signed;
endmodule

module shift_sub (
        input wire [63:0] a_in,
        input wire [5:0 ] time_cnter,
        input wire [31:0] b,
        output wire res_is_pos,         
        output wire [63:0] a_aligned  
);
        wire [64:0] a_in_shift; 

        wire [32:0] adder_a;
        wire [32:0] adder_b;
        wire adder_cin;
        wire [32:0] adder_res;
        wire [64:0] a_aligned_shift;

        assign a_in_shift = {1'b0,a_in} << time_cnter;
        assign adder_a = a_in_shift[64:32];
        assign adder_b = ~{1'b0,b};
        assign adder_cin = 1'b1;
        assign adder_res = adder_a + adder_b + adder_cin;

        assign a_aligned_shift = {adder_res,32'b0}>>time_cnter;
        assign a_aligned = a_aligned_shift[63:0];
        assign res_is_pos = ~adder_res[32];
endmodule

module alu (SW, KEY, LEDR, HEX0, HEX1, HEX2, HEX3, HEX4, HEX5);
  input [7:0] SW;
  input [2:0] KEY;
  output [7:0] LEDR;
  output [6:0] HEX0;
  output [6:0] HEX1;
  output [6:0] HEX2;
  output [6:0] HEX3;
  output [6:0] HEX4;
  output [6:0] HEX5;

  reg [7:0] ALUout;

  wire [4:0] wire0;
  wire [4:0] wire1;
  rc_adder u0(.SW({1'b0, SW[7:4], 4'b0001}), .LEDR(wire0[4:0]));
  rc_adder u1(.SW({1'b0, SW[7:0]}), .LEDR(wire1[4:0]));

  always @ ( * ) begin
    case (KEY[2:0])
      3'b000: ALUout = {3'b000, wire0};
      3'b001: ALUout = {3'b000, wire1};
      3'b010: ALUout = SW[7:4] + SW[3:0];
      3'b011: ALUout = {SW[7:4] | SW[3:0], SW[7:4] ^ SW[3:0]};
      3'b100: ALUout = {7'b0000000, SW[7] | SW[6] | SW[5] | SW[4] | SW[3] | SW[2] | SW[1] | SW[0]};
      3'b101: ALUout = {SW[7:4], SW[3:0]};
      default: ALUout = 8'b0000_0000;
    endcase
  end

  assign LEDR = (ALUout);

  decoder d0(.SW(SW[3:0]), .HEX0(HEX0[6:0]));
  decoder d1(.SW(4'b0000), .HEX0(HEX1[6:0]));
  decoder d2(.SW(SW[7:4]), .HEX0(HEX2[6:0]));
  decoder d3(.SW(4'b0000), .HEX0(HEX3[6:0]));
  decoder d4(.SW(LEDR[3:0]), .HEX0(HEX4[6:0]));
  decoder d5(.SW(LEDR[7:4]), .HEX0(HEX5[6:0]));

endmodule 






module rc_adder (SW, LEDR);
  input [8:0] SW;
  output [4:0] LEDR;

  wire _0to1, _1to2, _2to3;

    full_adder u0(
                .ci(SW[8]),
                .a(SW[4]),
                .b(SW[0]),
                .s(LEDR[0]),
                .co(_0to1)
                );

    full_adder u1(.ci(_0to1),
                .a(SW[5]),
                .b(SW[1]),
                .s(LEDR[1]),
                .co(_1to2));

    full_adder u2(.ci(_1to2),
                .a(SW[6]),
                .b(SW[2]),
                .s(LEDR[2]),
                .co(_2to3));

    full_adder u3(.ci(_2to3),
                .a(SW[7]),
                .b(SW[3]),
                .s(LEDR[3]),
                .co(LEDR[4]));


endmodule 



module full_adder (ci, a, b, s, co);
  input ci;
  input a, b;
  output s;
  output co;

  assign s = a ^ b ^ ci;
  assign co = (a & b) | ((a ^ b) & ci);

endmodule 









module decoder(SW, HEX0);
	input [3:0] SW;
	output [6:0] HEX0;

	s0 u0(.c3(SW[3]),
				  .c2(SW[2]),
				  .c1(SW[1]),
				  .c0(SW[0]),
				  .o(HEX0[0])
				  );

	s1 u1(.c3(SW[3]),
				  .c2(SW[2]),
				  .c1(SW[1]),
				  .c0(SW[0]),
				  .o(HEX0[1])
				  );


	s2 u2(.c3(SW[3]),
				  .c2(SW[2]),
				  .c1(SW[1]),
				  .c0(SW[0]),
				  .o(HEX0[2])
				  );


	s3 u3(.c3(SW[3]),
				  .c2(SW[2]),
				  .c1(SW[1]),
				  .c0(SW[0]),
				  .o(HEX0[3])
				  );


	s4 u4(.c3(SW[3]),
				  .c2(SW[2]),
				  .c1(SW[1]),
				  .c0(SW[0]),
				  .o(HEX0[4])
				  );


	s5 u5(.c3(SW[3]),
				  .c2(SW[2]),
				  .c1(SW[1]),
				  .c0(SW[0]),
				  .o(HEX0[5])
				  );


	s6 u6(.c3(SW[3]),
				  .c2(SW[2]),
				  .c1(SW[1]),
				  .c0(SW[0]),
				  .o(HEX0[6])
				  );

endmodule


module s0(c3, c2, c1, c0, o);
	input c3, c2, c1, c0;
	output o;

	assign o = ~c3 & ~c2 & ~c1 & c0 | ~c3 & c2 & ~c1 & ~c0 | c3 & c2 & ~c1 & c0 | c3 & ~c2 & c1 & c0;
endmodule



module s1(c3, c2, c1, c0, o);
	input c3, c2, c1, c0;
	output o;

	assign o = ~c3 & c2 & ~c1 & c0 | c3 & c2 & ~c0 | c1 & c0 & c3 | c1 & ~c0 & c2;
endmodule



module s2(c3, c2, c1, c0, o);
	input c3, c2, c1, c0;
	output o;

	assign o = ~c3 & ~c2 & c1 & ~c0 | c3 & c2 & ~c0 | c3 & c2 & c1;
endmodule



module s3(c3, c2, c1, c0, o);
	input c3, c2, c1, c0;
	output o;

	assign o = ~c3 & c2 & ~c1 & ~c0 | c3 & ~c2 & c1 & ~c0 | ~c1 & c0 & ~c2 | c1 & c0 & c2;
endmodule



module s4(c3, c2, c1, c0, o);
	input c3, c2, c1, c0;
	output o;

	assign o = ~c3 & c0 | ~c3 & c2 & ~c1 | ~c1 & c0 & ~c2;
endmodule



module s5(c3, c2, c1, c0, o);
	input c3, c2, c1, c0;
	output o;

	assign o = c3 & c2 & ~c1 & c0 | c1 & c0 & ~c3 | ~c3 & ~c2 & c0 | ~c3 & ~c2 & c1;
endmodule



module s6(c3, c2, c1, c0, o);
	input c3, c2, c1, c0;
	output o;

	assign o = ~c3 & c2 & c1 & c0 | c3 & c2 & ~c1 & ~c0 | ~c3 & ~c2 & ~c1;
endmodule

`timescale 1ns / 1ps

 module cu   (clk, reset, IR, ALU_Status,                       
             W_Adr, R_Adr, S_Adr, adr_sel, s_sel, pc_ld,     
             pc_inc, pc_sel, ir_ld, mw_en, rw_en, alu_op,       
             status);                                                 


   input        clk, reset ;                                       
   input [15:0] IR;                                     
   input [2:0]  ALU_Status;                                        

   output       adr_sel, s_sel ;                                
   output       pc_ld, pc_inc, pc_sel, ir_ld;   
   output       mw_en, rw_en ;                   
   output [2:0] W_Adr, R_Adr, S_Adr ;                 
   output [3:0] alu_op ;                                         
   output [7:0] status ;                    


   reg   [2:0] W_Adr, R_Adr, S_Adr; 
   reg         adr_sel, s_sel ;
   reg         pc_ld, pc_inc ;
   reg         pc_sel, ir_ld ;
   reg         mw_en, rw_en ;
   reg   [3:0] alu_op ;

   reg   [4:0] state ;
   reg   [4:0] nextstate ;
   reg   [7:0] status ;
   reg         ps_N, ps_Z, ps_C ,
               ns_N, ns_Z, ns_C ;

   parameter   RESET = 0,  FETCH = 1,  DECODE = 2,
               ADD = 3,    SUB = 4,    CMP = 5,    MOV = 6,
               INC = 7,    DEC = 8,    SHL = 9,    SHR = 10,
               LOAD = 11,  STO = 12,   LDI = 13,   
               JE = 14,    JNE = 15,   JC = 16,    JMP = 17,
               HALT = 18,
               ILLEGAL_OP = 31 ;



   always @(posedge clk or posedge reset)
      if (reset)
         state = RESET ;
      else
         state = nextstate;

   always @(posedge clk or posedge reset)
      if (reset)
         {ps_N, ps_Z, ps_C} = 3'b0 ;
      else
         {ps_N, ps_Z, ps_C} = {ns_N, ns_Z, ns_C} ;



   always @ (state)
      case (state)
      RESET :  begin 
               W_Adr   = 3'b000;     R_Adr  = 3'b000;     S_Adr  = 3'b000 ;
               adr_sel = 1'b0  ;     s_sel  = 1'b0  ;     pc_sel = 1'b0   ;
               pc_ld   = 1'b0  ;     pc_inc = 1'b0  ;     ir_ld  = 1'b0   ;
               mw_en   = 1'b0  ;     rw_en  = 1'b0  ;     alu_op = 4'h0   ;

               {ns_N, ns_Z, ns_C} = 3'b0;
               status = 8'hFF;
               nextstate = FETCH;
               end

      FETCH :  begin 
               W_Adr   = 3'b000;     R_Adr  = 3'b000;     S_Adr  = 3'b000 ;
               adr_sel = 1'b0  ;     s_sel  = 1'b0  ;     pc_sel = 1'b0   ;
               pc_ld   = 1'b0  ;     pc_inc = 1'b1  ;     ir_ld  = 1'b1   ;
               mw_en   = 1'b0  ;     rw_en  = 1'b0  ;     alu_op = 4'h0   ;

               {ns_N, ns_Z, ns_C} = {ps_N, ps_Z, ps_C};
               status = 8'h80;
               nextstate = DECODE;
               end

      DECODE : begin 
               W_Adr   = 3'b000;     R_Adr  = 3'b000;     S_Adr  = 3'b000 ;
               adr_sel = 1'b0  ;     s_sel  = 1'b0  ;     pc_sel = 1'b0   ;
               pc_ld   = 1'b0  ;     pc_inc = 1'b0  ;     ir_ld  = 1'b0   ;
               mw_en   = 1'b0  ;     rw_en  = 1'b0  ;     alu_op = 4'b0   ;

               {ns_N, ns_Z, ns_C} = {ps_N, ps_Z, ps_C};
               status = 8'hC0;
                  case (IR[15:9])
                     7'h70  :   nextstate = ADD  ;
                     7'h71  :   nextstate = SUB  ;
                     7'h72  :   nextstate = CMP  ;
                     7'h73  :   nextstate = MOV  ;
                     7'h74  :   nextstate = SHL  ;
                     7'h75  :   nextstate = SHR  ;
                     7'h76  :   nextstate = INC  ;
                     7'h77  :   nextstate = DEC  ;
                     7'h78  :   nextstate = LOAD ;
                     7'h79  :   nextstate = STO  ;
                     7'h7a  :   nextstate = LDI  ;
                     7'h7b  :   nextstate = HALT ;
                     7'h7c  :   nextstate = JE   ;
                     7'h7d  :   nextstate = JNE  ;
                     7'h7e  :   nextstate = JC   ;
                     7'h7f  :   nextstate = JMP  ;
                     default:   nextstate = ILLEGAL_OP ;
                  endcase
               end



               ADD : begin
                     W_Adr   = IR[8:6];    R_Adr  = IR[5:3];    S_Adr  = IR[2:0] ;
                     adr_sel = 1'b0  ;     s_sel  = 1'b0   ;    pc_sel = 1'b0    ;
                     pc_ld   = 1'b0  ;     pc_inc = 1'b0   ;    ir_ld  = 1'b0    ;
                     mw_en   = 1'b0  ;     rw_en  = 1'b1   ;    alu_op = 4'b0100 ;

                     {ns_N, ns_Z, ns_C} = ALU_Status;
                     status = {ps_N, ps_Z, ps_C, 5'b00000};
                     nextstate = FETCH;
                     end



               SUB : begin
                     W_Adr   = IR[8:6];    R_Adr  = IR[5:3];    S_Adr  = IR[2:0] ;
                     adr_sel = 1'b0   ;     s_sel  = 1'b0  ;    pc_sel = 1'b0    ;
                     pc_ld   = 1'b0   ;     pc_inc = 1'b0  ;    ir_ld  = 1'b0    ;
                     mw_en   = 1'b0   ;     rw_en  = 1'b1  ;    alu_op = 4'b0101 ;

                     {ns_N, ns_Z, ns_C} = ALU_Status;
                     status = {ps_N, ps_Z, ps_C, 5'b00001};
                     nextstate = FETCH;
                     end



               CMP : begin
                     W_Adr   = 3'b000;     R_Adr  = IR[5:3];     S_Adr  = IR[2:0] ;
                     adr_sel = 1'b0  ;     s_sel  = 1'b0   ;     pc_sel = 1'b0    ;
                     pc_ld   = 1'b0  ;     pc_inc = 1'b0   ;     ir_ld  = 1'b0    ;
                     mw_en   = 1'b0  ;     rw_en  = 1'b0   ;     alu_op = 4'b0101 ;

                     {ns_N, ns_Z, ns_C} = ALU_Status;
                     status = {ps_N, ps_Z, ps_C, 5'b00010};
                     nextstate = FETCH;
                     end



               MOV : begin
                     W_Adr   = IR[8:6];    R_Adr  = 3'b000;     S_Adr  = IR[2:0] ;
                     adr_sel = 1'b0   ;    s_sel  = 1'b0  ;     pc_sel = 1'b0    ;
                     pc_ld   = 1'b0   ;    pc_inc = 1'b0  ;     ir_ld  = 1'b0    ;
                     mw_en   = 1'b0   ;    rw_en  = 1'b1  ;     alu_op = 4'b0    ;
                     {ns_N, ns_Z, ns_C} = {ps_N, ps_Z, ps_C};

                     status = {ps_N,ps_Z,ps_C,5'b00111};
                     nextstate = FETCH;
                     end



               SHL : begin
                     W_Adr   = IR[8:6];    R_Adr  = 3'b000;     S_Adr  = IR[2:0] ;
                     adr_sel = 1'b0   ;    s_sel  = 1'b0  ;     pc_sel = 1'b0    ;
                     pc_ld   = 1'b0   ;    pc_inc = 1'b0  ;     ir_ld  = 1'b0    ;
                     mw_en   = 1'b0   ;    rw_en  = 1'b1  ;     alu_op = 4'b0111 ;

                     {ns_N, ns_Z, ns_C} = ALU_Status;
                     status = {ps_N,ps_Z,ps_C,5'b00100};
                     nextstate = FETCH;
                     end



               SHR : begin
                     W_Adr   = IR[8:6];    R_Adr  = 3'b000;     S_Adr  = IR[2:0] ;
                     adr_sel = 1'b0   ;    s_sel  = 1'b0  ;     pc_sel = 1'b0    ;
                     pc_ld   = 1'b0   ;    pc_inc = 1'b0  ;     ir_ld  = 1'b0    ;
                     mw_en   = 1'b0   ;    rw_en  = 1'b1  ;     alu_op = 4'b0110 ;

                     {ns_N, ns_Z, ns_C} = ALU_Status;
                     status = {ps_N,ps_Z,ps_C,5'b00101};
                     nextstate = FETCH;
                     end



               INC : begin
                     W_Adr   = IR[8:6];    R_Adr  = 3'b000;     S_Adr  = IR[2:0] ;
                     adr_sel = 1'b0   ;    s_sel  = 1'b0  ;     pc_sel = 1'b0    ;
                     pc_ld   = 1'b0   ;    pc_inc = 1'b0  ;     ir_ld  = 1'b0    ;
                     mw_en   = 1'b0   ;    rw_en  = 1'b1  ;     alu_op = 4'b0010 ;

                     {ns_N, ns_Z, ns_C} = ALU_Status;
                     status = {ps_N,ps_Z,ps_C,5'b00110};
                     nextstate = FETCH;
                     end



               DEC : begin
                     W_Adr   = IR[8:6];    R_Adr  = 3'b000;     S_Adr  = IR[2:0] ;
                     adr_sel = 1'b0   ;    s_sel  = 1'b0  ;     pc_sel = 1'b0    ;
                     pc_ld   = 1'b0   ;    pc_inc = 1'b0  ;     ir_ld  = 1'b0    ;
                     mw_en   = 1'b0   ;    rw_en  = 1'b1  ;     alu_op = 4'b0011 ;

                     {ns_N, ns_Z, ns_C} = ALU_Status;
                     status = {ps_N,ps_Z,ps_C,5'b0111};
                     nextstate = FETCH;
                     end








              LOAD : begin
                     W_Adr   = IR[8:6];    R_Adr  = IR[2:0];    S_Adr  = 3'b000 ;
                     adr_sel = 1'b1   ;    s_sel  = 1'b1   ;    pc_sel = 1'b0   ;
                     pc_ld   = 1'b0   ;    pc_inc = 1'b0   ;    ir_ld  = 1'b0   ;
                     mw_en   = 1'b0   ;    rw_en  = 1'b1   ;    alu_op = 4'b0   ;

                     {ns_N, ns_Z, ns_C} = {ps_N, ps_Z, ps_C};
                     status = {ps_N,ps_Z,ps_C,5'b01000};
                     nextstate = FETCH;
                     end



               STO : begin
                     W_Adr   = 3'b000;     R_Adr  = IR[8:6];    S_Adr  = IR[2:0];
                     adr_sel = 1'b1  ;     s_sel  = 1'b0   ;    pc_sel = 1'b0   ;
                     pc_ld   = 1'b0  ;     pc_inc = 1'b0   ;    ir_ld  = 1'b0   ;
                     mw_en   = 1'b1  ;     rw_en  = 1'b0   ;    alu_op = 4'b0   ;

                     {ns_N, ns_Z, ns_C} = {ps_N, ps_Z, ps_C};
                     status = {ps_N,ps_Z,ps_C,5'b01001};
                     nextstate = FETCH;
                     end



               LDI : begin

                     W_Adr   = IR[8:6];    R_Adr  = 3'b000;     S_Adr  = 3'b000 ;
                     adr_sel = 1'b0   ;    s_sel  = 1'b1  ;     pc_sel = 1'b0   ;
                     pc_ld   = 1'b0   ;    pc_inc = 1'b1  ;     ir_ld  = 1'b0   ;
                     mw_en   = 1'b0   ;    rw_en  = 1'b1  ;     alu_op = 4'b0   ;

                     {ns_N, ns_Z, ns_C} = {ps_N, ps_Z, ps_C};
                     status = {ps_N,ps_Z,ps_C,5'b01010};
                     nextstate = FETCH;
                     end



                JE : begin
                     W_Adr   = 3'b000;     R_Adr  = 3'b000;     S_Adr  = 3'b000 ;
                     adr_sel = 1'b0  ;     s_sel  = 1'b0  ;     pc_sel = 1'b0   ;
                     pc_ld   = ps_Z  ;     pc_inc = 1'b0  ;     ir_ld  = 1'b0   ;
                     mw_en   = 1'b0  ;     rw_en  = 1'b0  ;     alu_op = 4'b0   ;

                     {ns_N, ns_Z, ns_C} = {ps_N, ps_Z, ps_C};
                     status = {ps_N,ps_Z,ps_C,5'b01100};
                     nextstate = FETCH;
                     end







               JNE : begin
                     W_Adr   = 3'b000;     R_Adr  = 3'b000;     S_Adr  = 3'b000 ;
                     adr_sel = 1'b0  ;     s_sel  = 1'b0  ;     pc_sel = 1'b0   ;
                     pc_ld   = !ps_Z ;     pc_inc = 1'b0  ;     ir_ld  = 1'b0   ;
                     mw_en   = 1'b0  ;     rw_en  = 1'b0  ;     alu_op = 4'b0   ;

                     {ns_N, ns_Z, ns_C} = {ps_N, ps_Z, ps_C};
                     status = {ps_N, ps_Z, ps_C, 5'b01101};
                     nextstate = FETCH;
                     end



                JC : begin
                     W_Adr   = 3'b000;     R_Adr  = 3'b000;     S_Adr  = 3'b000 ;
                     adr_sel = 1'b0  ;     s_sel  = 1'b0  ;     pc_sel = 1'b0   ;
                     pc_ld   = ps_C  ;     pc_inc = 1'b0  ;     ir_ld  = 1'b0   ;
                     mw_en   = 1'b0  ;     rw_en  = 1'b0  ;     alu_op = 4'b0   ;

                     {ns_N, ns_Z, ns_C} = {ps_N, ps_Z, ps_C};
                     status = {ps_N,ps_Z,ps_C,5'b01110};
                     nextstate = FETCH;
                     end



               JMP : begin
                     W_Adr   = 3'b000;     R_Adr  = 3'b000;     S_Adr  = IR[2:0];
                     adr_sel = 1'b0  ;     s_sel  = 1'b0  ;     pc_sel = 1'b1   ;
                     pc_ld   = 1'b1  ;     pc_inc = 1'b0  ;     ir_ld  = 1'b0   ;
                     mw_en   = 1'b0  ;     rw_en  = 1'b0  ;     alu_op = 4'b0   ;

                     {ns_N, ns_Z, ns_C} = {ps_N, ps_Z, ps_C};
                     status = {ps_N,ps_Z,ps_C, 5'b01111};
                     nextstate = FETCH;
                     end



              HALT : begin
                     W_Adr   = 3'b000;     R_Adr  = 3'b000;     S_Adr  = 3'b000 ;
                     adr_sel = 1'b0  ;     s_sel  = 1'b0  ;     pc_sel = 1'b0   ;
                     pc_ld   = 1'b0  ;     pc_inc = 1'b0  ;     ir_ld  = 1'b0   ;
                     mw_en   = 1'b0  ;     rw_en  = 1'b0  ;     alu_op = 4'h0   ;

                     {ns_N, ns_Z, ns_C} = 3'b0;
                     status = {ps_N,ps_Z,ps_C, 5'b01011};
                     nextstate = HALT;
                     end







        ILLEGAL_OP : begin
                     W_Adr   = 3'b000;     R_Adr  = 3'b000;     S_Adr  = 3'b000 ;
                     adr_sel = 1'b0  ;     s_sel  = 1'b0  ;     pc_sel = 1'b0   ;
                     pc_ld   = 1'b0  ;     pc_inc = 1'b0  ;     ir_ld  = 1'b0   ;
                     mw_en   = 1'b0  ;     rw_en  = 1'b0  ;     alu_op = 4'h0   ;

                     {ns_N, ns_Z, ns_C} = 3'b0;
                     status = 8'hF0;
                     nextstate = ILLEGAL_OP;
                     end
               endcase

endmodule

`timescale 1ns/1ns
module fir
       #(  parameter pADDR_WIDTH = 12,
           parameter pDATA_WIDTH = 32,
           parameter Tape_Num    = 11
        )
       (
           output  wire                     awready,
           output  wire                     wready,
           input   wire                     awvalid,
           input   wire [(pADDR_WIDTH-1):0] awaddr,
           input   wire                     wvalid,
           input   wire [(pDATA_WIDTH-1):0] wdata,
           output  wire                     arready,
           input   wire                     rready,
           input   wire                     arvalid,
           input   wire [(pADDR_WIDTH-1):0] araddr,
           output  wire                     rvalid,
           output  wire [(pDATA_WIDTH-1):0] rdata,
           input   wire                     ss_tvalid,
           input   wire [(pDATA_WIDTH-1):0] ss_tdata,
           input   wire                     ss_tlast,
           output  wire                     ss_tready,
           input   wire                     sm_tready,
           output  wire                     sm_tvalid,
           output  wire [(pDATA_WIDTH-1):0] sm_tdata,
           output  wire                     sm_tlast,


           output  wire           [3:0]     tap_WE,
           output  wire                     tap_EN,
           output  wire [(pDATA_WIDTH-1):0] tap_Di,
           output  wire [(pADDR_WIDTH-1):0] tap_A,
           input   wire [(pDATA_WIDTH-1):0] tap_Do,


           output  wire            [3:0]    data_WE,
           output  wire                     data_EN,
           output  wire [(pDATA_WIDTH-1):0] data_Di,
           output  wire [(pADDR_WIDTH-1):0] data_A,
           input   wire [(pDATA_WIDTH-1):0] data_Do,

           input   wire                     axis_clk,
           input   wire                     axis_rst_n
       );



parameter ready = 0;
parameter start = 1;
parameter finish = 2;

reg [1:0] state;
wire stream_prepared;
reg ap_start_sig;
reg     sm_tlast_r;
reg     ss_finish_r;
wire    ss_finish;
reg ctrl_tap_ready_r, tap_EN_sr_r, tap_EN_r_d;
wire ctrl_tap_ready, ctrl_tap_valid, muxsel, ffen;

always @( posedge axis_clk ) begin
    if ( !axis_rst_n ) begin
        state <= ready;
    end
    else begin
        case(state)
            ready: begin
                if(stream_prepared  && ap_start_sig)
                    state <= start;

                sm_tlast_r <= 0;
            end

            start: begin
                if(ss_finish && sm_tlast)
                    state <= finish;

                if(ss_finish  && !ctrl_tap_valid)
                    sm_tlast_r <= 1;
                else
                    sm_tlast_r <= 0;

            end

            finish: begin
                sm_tlast_r <= 0;

            end
            default:
                state <= ready;

        endcase
    end
end






reg stream_prepared_r,ss_read_valid_r,ss_tready_r;
wire    ss_read_valid;

reg [pADDR_WIDTH-1:0] data_WA_r;
reg [pDATA_WIDTH-1:0] data_Di_r;
reg [3:0]             data_WE_r;
reg [3:0]              ss_count_r;

wire [pADDR_WIDTH-1:0] data_WA;
wire [3:0]             ss_count;


assign ss_tready = ss_tready_r;
assign data_WE = data_WE_r ;
assign data_WA = data_WA_r;
assign data_Di = data_Di_r;
assign ss_count = ss_count_r;
assign stream_prepared = stream_prepared_r;
assign ss_read_valid = ss_read_valid_r;
assign ss_finish = ss_finish_r;


reg data_EN_sw_r,data_EN_sr_r ,data_EN_r_d;
wire    ss_write_valid;

always @( posedge axis_clk ) begin
    if ( !axis_rst_n ) begin
        ss_tready_r <= 0;
        ss_finish_r <= 0;

        data_WA_r <= 0;
        ss_count_r <= 0;
        stream_prepared_r <= 0;

        ss_read_valid_r <= 0;
    end
    else begin
        if (!ss_tready && ss_tvalid) begin
            case(state)
                ready: begin
                    if((ss_count <= Tape_Num - 1) && !stream_prepared) begin
                        data_WE_r <= 4'b1111;
                        data_EN_sw_r <= 1;

                        data_WA_r <= (ss_count == 0) ? 0:data_WA_r + 4;
                        ss_count_r <= ss_count_r + 1;
                        data_Di_r <= 0;

                    end
                    else begin
                        stream_prepared_r <= 1;
                        ss_count_r <= 4'd10;

                        data_EN_sw_r <= 0;
                        data_WE_r <= 0;
                    end

                end

                start: begin
                    if(ss_write_valid) begin
                        ss_tready_r <= 1;
                        data_WE_r <= 4'b1111;
                        data_EN_sw_r <= 1;

                        data_WA_r <= (ss_count == 4'd10) ? 0 :data_WA_r + 4;
                        ss_count_r <=(ss_count == 4'd10) ? 0 :ss_count_r + 1;
                        data_Di_r <= ss_tdata;

                        ss_read_valid_r <= 1;

                    end
                    else if (sm_tvalid)
                        ss_read_valid_r <= 0;
                    else begin
                        data_WE_r <= 0;
                        ss_tready_r <= 0;

                    end



                end
            endcase
        end
        else begin
            data_WE_r <= 4'b0;
            data_EN_sw_r <= 0;
            ss_tready_r <= 0;
            if(ss_tlast)
                ss_finish_r <= 1;


        end

    end

end


reg sm_tvalid_r;
reg [pADDR_WIDTH-1:0] data_RA_r;
reg [pDATA_WIDTH-1:0]  sm_tdata_r;

wire [pADDR_WIDTH-1:0] data_RA;


assign data_RA = data_RA_r;
assign data_EN = data_EN_sw_r | data_EN_r_d;

always@(posedge axis_clk) begin
    data_EN_r_d <= data_EN_sr_r;
end


assign data_A =(data_EN_sw_r) ? data_WA :(data_EN_sr_r) ? data_RA : 0;
assign sm_tvalid = sm_tvalid_r;
assign sm_tdata = sm_tdata_r;
assign sm_tlast = sm_tlast_r;
assign ss_write_valid = ~ ss_read_valid;








reg [pADDR_WIDTH-1:0] tap_RA_lr_r, tap_RA_sr_r;
wire [pADDR_WIDTH-1:0]  ctrl_tap_addr, ctrl_data_addr;
wire [3:0] ctrl_count;


wire en;
reg o_valid_r, ffen_r;
reg[3:0] count_r;
reg [pADDR_WIDTH-1:0]tap_last_addr_r;
reg [pADDR_WIDTH-1:0]o_data_addr_r, o_tap_addr_r;


assign ctrl_tap_valid = o_valid_r;
assign ctrl_data_addr = o_data_addr_r;
assign ctrl_tap_addr = o_tap_addr_r;
assign ctrl_count = count_r;
assign ffen = ffen_r;
assign muxsel = ~ffen ;
assign en = ctrl_tap_ready & ctrl_tap_valid;



always@(posedge axis_clk) begin
    if (!axis_rst_n) begin
        o_data_addr_r <= 0;
        o_tap_addr_r <= 12'd40;
        ffen_r <= 0;
        o_valid_r <= 0;
        count_r <= 0;
    end
    else if(en) begin
        o_valid_r       <= (ctrl_count == 4'd11) ? 0 : 1;

        o_data_addr_r   <= (ctrl_count == 4'd11)? 0:o_data_addr_r + 4;

        o_tap_addr_r    <= (ctrl_count == 4'd11) ? tap_last_addr_r :(ctrl_tap_addr == 12'd40) ? 0 : ctrl_tap_addr + 4;

        tap_last_addr_r <= (ctrl_count == 0 && ctrl_tap_addr == 0) ? 12'd40 :(ctrl_count == 0) ? ctrl_tap_addr - 4 : tap_last_addr_r;

        count_r <= (ctrl_count == 4'd11) ? 0 :ctrl_count + 1;

        ffen_r <= 1;
    end
    else begin
        o_valid_r <= 1;
        ffen_r <= 0;
    end
end




always @( posedge axis_clk ) begin
    if ( !axis_rst_n ) begin
        sm_tvalid_r <= 0;

        ctrl_tap_ready_r <= 0;

        data_EN_sr_r <= 0;
        tap_EN_sr_r <= 0;
    end
    else begin
        if (sm_tready && !sm_tvalid) begin
            case(state)
                ready: begin
                end

                start: begin
                    if(ss_read_valid && ctrl_tap_valid) begin
                        sm_tvalid_r     <= 0;
                        data_EN_sr_r    <= 1;
                        tap_EN_sr_r     <= 1;
                        data_RA_r       <= ctrl_data_addr;
                        tap_RA_sr_r     <= ctrl_tap_addr;
                        ctrl_tap_ready_r<= 1;

                    end
                    else if (ss_read_valid && !ctrl_tap_valid) begin
                        sm_tvalid_r     <= 1;
                        ctrl_tap_ready_r<= 0 ;

                    end
                end
            endcase
        end
        else begin
            sm_tvalid_r <= 0;
        end
    end
end





reg ffen_d;
wire [pDATA_WIDTH-1:0] o_ram_data, o_cof_data;

always@(posedge axis_clk) begin
    ffen_d <= ffen;

    if(!axis_rst_n)
        sm_tdata_r<=0;
    else if(sm_tvalid)
        sm_tdata_r<=0;
    else if(ffen_d)
        sm_tdata_r <= sm_tdata_r +(o_ram_data*o_cof_data);

end


reg [pDATA_WIDTH-1:0] old_ram_data_r, old_cof_data_r;
wire [pDATA_WIDTH-1:0] old_ram_data, old_cof_data;
wire [pDATA_WIDTH-1:0] new_ram_data, new_cof_data;

assign o_ram_data = muxsel ?  old_ram_data : new_ram_data;
assign o_cof_data = muxsel ?  old_cof_data : new_cof_data;
assign old_ram_data = old_ram_data_r;
assign old_cof_data = old_cof_data_r;

assign new_cof_data = tap_Do;
assign new_ram_data = data_Do;


always@(posedge axis_clk) begin
    if(ffen) begin
        old_ram_data_r <= new_ram_data;
        old_cof_data_r <= new_cof_data;
    end
end


assign ctrl_tap_ready = ctrl_tap_ready_r;







reg awready_r, wready_r;
assign awready = awready_r;
assign wready = wready_r;

reg [pADDR_WIDTH-1:0] tap_WA_r;
reg [pDATA_WIDTH-1:0] tap_Di_r;
reg [pDATA_WIDTH-1:0] data_length;

wire [pADDR_WIDTH-1:0] tap_WA;

assign tap_WE = {4{awready & wready}};
assign tap_WA = tap_WA_r;
assign tap_Di = tap_Di_r;





always @( posedge axis_clk ) begin
    if ( !axis_rst_n ) begin
        awready_r <= 0;
        wready_r <= 0;
        ap_start_sig <= 0;
    end
    else begin
        if (!awready && awvalid) begin
            if(awaddr>=12'h20 && awaddr<=12'h60) begin
                awready_r <= 1;
                tap_WA_r <= awaddr-12'h20;
            end

            else
                awready_r <= 0;
        end
        else begin
            awready_r <= 0;
        end

        if (!wready && wvalid) begin
            wready_r <= 1;
            if(awaddr>=12'h20 && awaddr<=12'h60) begin
                tap_Di_r <= wdata;
            end
            else if (awaddr==12'h10)
                data_length <= wdata;
            else if(awaddr==0 && wdata==1)
                ap_start_sig <= 1;

        end
        else begin
            wready_r <= 0;
            ap_start_sig <= 0;
        end

    end
end


reg arready_r, rvalid_r;
reg [pDATA_WIDTH-1:0] rdata_r;

assign arready = arready_r;
assign rvalid = rvalid_r;
assign rdata = rdata_r ;

wire [pADDR_WIDTH-1:0] tap_RA;
assign tap_RA = (tap_EN_sr_r) ? tap_RA_sr_r : tap_RA_lr_r;
assign tap_EN = {awready & wready} | tap_EN_r_d ;

always @( posedge axis_clk ) begin
    tap_EN_r_d <= {arvalid & arready} | tap_EN_sr_r;
end

assign tap_A = ({awready & wready}) ? tap_WA :
       ({arvalid & arready} | tap_EN_sr_r) ? tap_RA : 0;




always@(*) begin
    case(state)
        ready: begin
            if(araddr==0 && rvalid)
                rdata_r =32'h04;
            else if(araddr==0 && rvalid && ap_start_sig)
                rdata_r =32'h01;
            else
                rdata_r = tap_Do;
        end

        start: begin
            if(araddr==0 && rvalid)
                rdata_r =32'h00;
            else if(awaddr==12'h10 && rvalid)
                rdata_r = data_length;
            else
                rdata_r = tap_Do;
        end

        finish: begin
            if(araddr==0 && rvalid)
                rdata_r =32'h06;
            else
                rdata_r = tap_Do;
        end
        default:
            rdata_r = 0;
    endcase
end


always @( posedge axis_clk ) begin
    if ( !axis_rst_n ) begin
        arready_r <= 0;
        rvalid_r <= 0;
    end
    else begin
        if(!arready && arvalid && !rvalid) begin
            if(araddr>=12'h20 && araddr<=12'h60) begin
                arready_r <= 1;
                tap_RA_lr_r <= araddr-12'h20;
            end
            else if(araddr==0) begin
                arready_r <= 1;
            end
            else if (awaddr==12'h10)
                arready_r <= 1;
            else
                arready_r <= 0;

        end
        else if(arready && arvalid && !rvalid) begin
            arready_r <= 0;
            rvalid_r <= 1;
        end
        else begin
            arready_r <= 0;
            rvalid_r <= 0;
        end
    end
end

endmodule

`timescale 1 ns / 1 ps
module fast_pat_fetch (
    input           clk,
    input           rst_n,

    output          onchip_mem_chip_select,
    output          onchip_mem_clk_ena,
    output          onchip_mem_chip_read,
    output [12:0]   onchip_mem_addr,
    output [31:0]   onchip_mem_byte_enable,
    output [255:0]  onchip_mem_write_data,
    output          onchip_mem_write,

    input [255:0]   onchip_mem_read_data,
    input           start,
    output reg      frame_trig,
    input           frame_busy,
    input           h_sync_in,
    input           v_sync_in,
    input           de_in,
    input           de_first_offset_line_in,
    input [23:0]    display_video_left_offset_in,
    output reg      h_sync_out,
    output reg      v_sync_out,
    output reg      de_out,
    output reg [23:0]   pix_data_out

);


localparam  IDLE_s = 2'd0,
            INIT_READ_ONCHIP_MEM_s = 2'd1,
            SEND_DATA_s = 2'd2,
            END_s = 2'd3;

reg        timer_ena;
wire        timer_out;
wire        timer_rst;
reg [1:0]   state;


reg [1:0]   mem_rd_cnt;
reg         mem_rd, mem_rd_r;
reg         mem_rd_valid;
reg         mem_sel;
reg         mem_clken;
reg [12:0]  mem_addr;
reg [255:0] mem_wr_data;
reg         mem_wr;
reg [31:0]  mem_wr_byte_ena;
reg [767:0] mem_data;
reg [4:0]   cnt; 


reg [6:0]   pix_cnt_per_de;
reg [11:0]  line_cnt;

assign onchip_mem_clk_ena = mem_clken;
assign onchip_mem_chip_select = mem_sel;
assign onchip_mem_chip_read = mem_rd;
assign onchip_mem_addr = mem_addr;
assign onchip_mem_write_data = mem_wr_data;
assign onchip_mem_write = mem_wr;
assign onchip_mem_byte_enable = mem_wr_byte_ena;


always @(posedge clk) begin
    mem_rd_r <= mem_rd;
    mem_rd_valid <= mem_rd_r;
end

always @(posedge clk) begin
    if(~rst_n) begin
         mem_data <= 0;
    end else begin
        if (mem_rd_valid) begin



            case(mem_rd_cnt)
                2'd0: mem_data[767:512] <= onchip_mem_read_data;
                2'd1: mem_data[511:256] <= onchip_mem_read_data;
                2'd2: mem_data[255:0] <= onchip_mem_read_data;
                2'd3: mem_data <= mem_data;

                default:mem_data <= 'h0;
            endcase 
        end

    end
end


reg h_sync_r, h_sync_p;
reg v_sync_r, v_sync_p;
reg de_r, de_p;
always @(posedge clk) begin
    if(~rst_n) begin
        h_sync_r <= 1'b0;
        h_sync_p <= 1'b0;
        v_sync_r <= 1'b0;
        v_sync_p <= 1'b0;
    end else begin
        h_sync_r <= h_sync_in;
        h_sync_p <= ~h_sync_r & h_sync_in;

        v_sync_r <= v_sync_in;
        v_sync_p <= ~v_sync_r & v_sync_in;


        de_r <= de_in;
        de_p <= ~de_r & de_in;
    end
end

always @(posedge clk) begin
    if(~rst_n) begin
        line_cnt <= 0;
    end else begin
        if (v_sync_p) begin
            line_cnt <= 'h0;
        end
        else if (de_p) begin
            line_cnt <= line_cnt + 1'd1;
            $display("line_cnt is %d",line_cnt);
        end
    end
end


always @(posedge clk) begin
    if(~rst_n) begin
        state <= IDLE_s;
        timer_ena <= 1'b0;
        mem_rd_cnt <= 'h0;
        mem_rd <= 1'b0;
        mem_addr <= 'h0;
        mem_sel <= 1'b0;
        frame_trig <= 1'b0;
        cnt <= 'h0;
        pix_data_out <= 'h0;
        pix_cnt_per_de <= 'h0;
        mem_wr <= 1'b0;
        mem_wr_data <= 'h0;
        mem_wr_byte_ena <= 'h0;
        mem_clken <= 1'b0;
    end else begin
        mem_rd <= 1'b0;
        mem_wr <= 1'b0;
        mem_wr_byte_ena <= 'h0;
        mem_clken <= 1'b1;

        case (state)
            IDLE_s: begin
                mem_sel <= 1'b1;
                mem_rd <= 1'b1;
                if ((onchip_mem_read_data[7:0] == 8'h77) || start) begin
                    state <= INIT_READ_ONCHIP_MEM_s;
                    mem_rd <= 1'b1;
                    mem_sel <= 1'b1;
                    mem_addr <= 'h1;
                end
                timer_ena <= 1'b1;
                pix_cnt_per_de <= 'h0;
            end
            INIT_READ_ONCHIP_MEM_s: begin
                if (mem_rd_cnt == 2'd2 && mem_rd_valid) begin
                    mem_rd <= 1'b0;
                    if (!frame_busy) begin
                        state <= SEND_DATA_s;
                        frame_trig <= 1'b1;
                        mem_rd_cnt <= 'h0;
                    end
                    else begin
                        state <= INIT_READ_ONCHIP_MEM_s;
                    end
                end
                else if (mem_rd_valid) begin
                    mem_rd_cnt <= mem_rd_cnt + 1'd1;
                    mem_rd <= 1'b1;
                    mem_sel <= 1'b1;
                    mem_addr <= mem_addr + 1'd1;
                    $display("mem_addr is %d",mem_addr);
                end
                else begin
                    mem_rd <= 1'b0;
                end
            end
            SEND_DATA_s: begin
                frame_trig <= 1'b0;
                if (de_in) begin
                    pix_cnt_per_de <= pix_cnt_per_de + 1'd1;
                end
                else begin
                    pix_cnt_per_de <= 0;
                end

                if (de_in & de_first_offset_line_in) begin
                    pix_data_out <= display_video_left_offset_in;
                end
                else if (de_in) begin
                    if (pix_cnt_per_de < 7'd80) begin
                        cnt <= cnt + 1'd1;
                        case(cnt)
                            5'd0: pix_data_out <= mem_data[767: (767 - 24 * 1 + 1)];
                            5'd1: pix_data_out <= mem_data[(767 - 24 * 1) : (767 - 24 * 2 + 1)];
                            5'd2: pix_data_out <= mem_data[(767 - 24 * 2) : (767 - 24 * 3 + 1)];
                            5'd3: pix_data_out <= mem_data[(767 - 24 * 3) : (767 - 24 * 4 + 1)];
                            5'd4: pix_data_out <= mem_data[(767 - 24 * 4) : (767 - 24 * 5 + 1)];
                            5'd5: pix_data_out <= mem_data[(767 - 24 * 5) : (767 - 24 * 6 + 1)];
                            5'd6: pix_data_out <= mem_data[(767 - 24 * 6) : (767 - 24 * 7 + 1)];
                            5'd7: pix_data_out <= mem_data[(767 - 24 * 7) : (767 - 24 * 8 + 1)];
                            5'd8: pix_data_out <= mem_data[(767 - 24 * 8) : (767 - 24 * 9 + 1)];
                            5'd9: pix_data_out <= mem_data[(767 - 24 * 9) : (767 - 24 * 10 + 1)];
                            5'd10: pix_data_out <= mem_data[(767 - 24 * 10) : (767 - 24 * 11 + 1)];
                            5'd11: pix_data_out <= mem_data[(767 - 24 * 11) : (767 - 24 * 12 + 1)];
                            5'd12: pix_data_out <= mem_data[(767 - 24 * 12) : (767 - 24 * 13 + 1)];
                            5'd13: pix_data_out <= mem_data[(767 - 24 * 13) : (767 - 24 * 14 + 1)];
                            5'd14: pix_data_out <= mem_data[(767 - 24 * 14) : (767 - 24 * 15 + 1)];
                            5'd15: pix_data_out <= mem_data[(767 - 24 * 15) : (767 - 24 * 16 + 1)];
                            5'd16: pix_data_out <= mem_data[(767 - 24 * 16) : (767 - 24 * 17 + 1)];
                            5'd17: pix_data_out <= mem_data[(767 - 24 * 17) : (767 - 24 * 18 + 1)];
                            5'd18: pix_data_out <= mem_data[(767 - 24 * 18) : (767 - 24 * 19 + 1)];
                            5'd19: pix_data_out <= mem_data[(767 - 24 * 19) : (767 - 24 * 20 + 1)];
                            5'd20: pix_data_out <= mem_data[(767 - 24 * 20) : (767 - 24 * 21 + 1)];
                            5'd21: pix_data_out <= mem_data[(767 - 24 * 21) : (767 - 24 * 22 + 1)];
                            5'd22: pix_data_out <= mem_data[(767 - 24 * 22) : (767 - 24 * 23 + 1)];
                            5'd23: pix_data_out <= mem_data[(767 - 24 * 23) : (767 - 24 * 24 + 1)];
                            5'd24: pix_data_out <= mem_data[(767 - 24 * 24) : (767 - 24 * 25 + 1)];
                            5'd25: pix_data_out <= mem_data[(767 - 24 * 25) : (767 - 24 * 26 + 1)];
                            5'd26: pix_data_out <= mem_data[(767 - 24 * 26) : (767 - 24 * 27 + 1)];
                            5'd27: pix_data_out <= mem_data[(767 - 24 * 27) : (767 - 24 * 28 + 1)];
                            5'd28: pix_data_out <= mem_data[(767 - 24 * 28) : (767 - 24 * 29 + 1)];
                            5'd29: pix_data_out <= mem_data[(767 - 24 * 29) : (767 - 24 * 30 + 1)];
                            5'd30: pix_data_out <= mem_data[(767 - 24 * 30) : (767 - 24 * 31 + 1)];
                            5'd31: pix_data_out <= mem_data[(767 - 24 * 31) : 0];
                            default: pix_data_out <= 'h0;
                        endcase 

                    end
                    else begin
                        cnt <= cnt;
                        pix_data_out <= 0;
                    end
                end


                if ((cnt == 5'd27 || cnt == 5'd29 || cnt == 5'd31) & de_in) begin
                    mem_rd <= 1'd1;
                    mem_sel <= 1'b1;
                    mem_addr <= mem_addr + 1'd1;
                    $display("mem_addr is %d",mem_addr);
                    $display("data is %d", $bits("/"));
                end
                else begin
                    mem_rd <= 1'd0;
                end

                if (mem_rd_valid) begin
                    if (mem_rd_cnt == 2'd2) begin
                        mem_rd_cnt <= 'h0;
                    end
                    else begin
                        mem_rd_cnt <= mem_rd_cnt + 1'd1;
                    end
                end

                if (line_cnt == 'd1080 && de_p) begin
                    state <= END_s;
                end
            end
            END_s: begin
                mem_wr <= 1'b1;  
                mem_addr <= 'h0;
                mem_wr_data <= 'h0;
                mem_sel <= 1'b1;
                state <= IDLE_s;
                mem_wr_byte_ena <= 32'hffffffff;
			    mem_rd_cnt <= 'h0;
                cnt <= 'h0;
            end
            default: begin
                state <= IDLE_s;
                mem_wr <= 1'b0;
                mem_rd <= 1'b0;
            end
        endcase
    end
end

always @(posedge clk) begin
    if(~rst_n) begin
        h_sync_out <= 1'b0;
        v_sync_out <= 1'b0;
        de_out <= 1'b0;
    end else begin
        h_sync_out <= h_sync_in;
        v_sync_out <= v_sync_in;
        de_out <= de_in;
    end
end




endmodule

module localbus_manage(
clk,
reset,
localbus_cs_n,
localbus_rd_wr,
localbus_data,
localbus_ale,
localbus_ack_n,
localbus_data_out,

parserRuleSet_valid,
parserRuleSet,
result_valid,
result,
lookupRuleSet_valid,
lookupRuleSet
);
input	clk;
input	reset;
input	localbus_cs_n;
input	localbus_rd_wr;
input	[31:0]	localbus_data;
input	localbus_ale;
output	reg	localbus_ack_n;
output	reg	[31:0] localbus_data_out;

output	reg	parserRuleSet_valid;
output	reg	[169:0]	parserRuleSet;




input	result_valid;
input	[119:0]	result;
output	reg	lookupRuleSet_valid;
output	reg	[63:0]	lookupRuleSet;

reg	[31:0]	localbus_addr;
reg	[119:0]	result_temp;

reg	[3:0]	state;
parameter	idle		= 4'd0,
			read_rule	= 4'd1,
			write_rule	= 4'd2,
			wait_back	= 4'd3;

always @ (posedge clk or negedge reset) begin
	if(!reset) begin
		localbus_ack_n <= 1'b1;
		localbus_data_out <= 32'b0;
		state <= idle;
		parserRuleSet_valid <= 1'b0;
		parserRuleSet <= 170'b0;
		lookupRuleSet_valid <= 1'b0;
		lookupRuleSet <= 64'b0;
		localbus_addr <= 32'b0;
	end
	else begin
		case(state)
			idle: begin
				if(localbus_ale==1'b1) begin
					localbus_addr <= localbus_data;
					if(localbus_rd_wr==1'b1) begin
						state <= read_rule;
					end
					else begin
						state <= write_rule;
					end
				end
				else state <= idle;
			end
			read_rule: begin
				if(localbus_cs_n==1'b0) begin
					localbus_ack_n <= 1'b0;
					state <= wait_back;
					case(localbus_addr[1:0])
						2'd0: localbus_data_out <= {8'b0,result_temp[119:96]};
						2'd1: localbus_data_out <= result_temp[95:64];
						2'd2: localbus_data_out <= result_temp[63:32];
						2'd3: localbus_data_out <= result_temp[31:0];
						default: localbus_data_out <= 32'b0;
					endcase
				end
				else state <= read_rule;
			end
			write_rule: begin
				if(localbus_cs_n==1'b0) begin
					localbus_ack_n <= 1'b0;
					state <= wait_back;
					case(localbus_addr[2:0])
						3'd0: parserRuleSet[169:160] <= localbus_data[9:0];
						3'd1: parserRuleSet[159:128] <= localbus_data;
						3'd2: parserRuleSet[127:96] <= localbus_data;
						3'd3: parserRuleSet[95:64] <= localbus_data;
						3'd4: parserRuleSet[63:32] <= localbus_data;
						3'd5: begin 
							parserRuleSet[31:0] <= localbus_data;
							parserRuleSet_valid <= 1'b1;
						end
						3'd6: lookupRuleSet[63:32]	<= localbus_data;
						3'd7: begin 
							lookupRuleSet[31:0]	<= localbus_data;
							lookupRuleSet_valid <= 1'b1;
						end
						default: begin
						end
					endcase
				end
				else state <= write_rule;
			end
			wait_back: begin
				parserRuleSet_valid <= 1'b0;
				lookupRuleSet_valid <= 1'b0;
				if(localbus_cs_n==1'b1) begin
					state <= idle;
					localbus_ack_n <= 1'b1;
				end
				else state <= wait_back;
			end
			default: state <= idle;
		endcase
	end
end


always @ (posedge clk or negedge reset) begin
	if(!reset) begin
		result_temp <= 120'b0;
	end
	else begin
		if(result_valid==1'b1) result_temp <= result;
		else result_temp <= result_temp;
	end	
end


