module MemControl
#(
	parameter DATA_WIDTH=32
)
(



	input [(DATA_WIDTH-1):0] Address,
	input [(DATA_WIDTH-1):0] WriteData_in,
	input MemWrite,

	output [(DATA_WIDTH-1):0] ReadData,


	output [(DATA_WIDTH-1):0]ID_Address,
	output [(DATA_WIDTH-1):0]WriteData_out,
	output ID_MemWrite,
	output Tx_MemWrite,
	output Tx_data_Memwrite,
	output Clean_rx_Memwrite,

	input [(DATA_WIDTH-1):0]ID_ReadData,
	input [(DATA_WIDTH-1):0]Rx_ReadData,
	input [(DATA_WIDTH-1):0]Rx_ready_ReadData



);


localparam TX_ADDR          = 32'h10010024;
localparam TX_DATA_ADDR     = 32'h10010028;
localparam RX_READY_ADDR    = 32'h1001002C;
localparam RX_DATA_ADDR     = 32'h10010030;
localparam CLEAN_RX_ADDR    = 32'h10010034;


reg IdMem;
reg tx;
reg tx_data;
reg rx_ready;
reg rx_data;
reg clean_rx;
reg [31:0]ReadData_r;

always@(*) begin
  IdMem = ( (Address != TX_ADDR) & (Address != TX_DATA_ADDR) & (Address != RX_READY_ADDR) & (Address != RX_DATA_ADDR) & (Address != CLEAN_RX_ADDR) ) ? 1'b1 : 1'b0;
  tx = (Address == TX_ADDR) ? 1'b1 : 1'b0;
  tx_data =  (Address == TX_DATA_ADDR) ? 1'b1 : 1'b0;
  rx_ready = (Address == RX_READY_ADDR) ? 1'b1 : 1'b0;
  rx_data = (Address == RX_DATA_ADDR) ? 1'b1 : 1'b0;
  clean_rx = (Address == CLEAN_RX_ADDR) ? 1'b1 : 1'b0;
  if(IdMem)
	  ReadData_r = ID_ReadData;
  else if(rx_ready)
     ReadData_r = Rx_ready_ReadData;
  else if (rx_data)
	  ReadData_r = Rx_ReadData;
  else
     ReadData_r = ID_ReadData;
end

assign  ID_Address     = (IdMem) ? Address : 32'h0000_0000;
assign  WriteData_out      = WriteData_in ;
assign  ID_MemWrite    = (IdMem) ? MemWrite    : 1'b0;

assign Tx_MemWrite = (tx) ? MemWrite : 1'b0;

assign Tx_data_Memwrite = (tx_data) ? MemWrite: 1'b0;

assign Clean_rx_Memwrite = (clean_rx) ? MemWrite: 1'b0;
assign ReadData = ReadData_r;






endmodule

module MUX4x4(soma, sub, mul, selop, resul);
	input [7:0]soma;
	input [7:0]sub;
	input [7:0]	mul; 
	input [3:0]selop;
	output reg [7:0]resul;

	always @ (soma or sub or mul or selop)
		begin : MUX
		 case(selop) 
			 4'b1010 : resul = mul;
			 4'b1011 : resul = sub;
			 4'b1100 : resul = soma;
			 default: resul = 8'b00000000;
		 endcase
		end

endmodule

module Async_FIFO(wr_clk_i,
                  rd_clk_i,
                  rst_i,
                  wr_en_i,
                  wdata_i,
                  full_o,
                  wr_error_o,
                  rd_en_i,
                  rdata_o,
                  empty_o,
                  rd_error_o);

    parameter DEPTH = 16, WIDTH = 8, PTR_WIDTH = 4;


    input wr_clk_i, rd_clk_i;
    input rst_i;


    input wr_en_i;
    input [WIDTH-1:0] wdata_i;
    output reg full_o;
    output reg wr_error_o;


    input rd_en_i;
    output reg [WIDTH-1:0] rdata_o;
    output reg empty_o;
    output reg rd_error_o;

    integer i;


    reg [WIDTH-1:0] memory [DEPTH-1:0];


    reg [PTR_WIDTH-1:0] wr_ptr;
    reg [PTR_WIDTH-1:0] rd_ptr;

    reg [PTR_WIDTH-1:0] wr_ptr_gray;
    reg [PTR_WIDTH-1:0] rd_ptr_gray;

    reg [PTR_WIDTH-1:0] wr_ptr_rd_clk;
    reg [PTR_WIDTH-1:0] rd_ptr_wr_clk;

    reg [PTR_WIDTH-1:0] wr_ptr_gray_rd_clk;
    reg [PTR_WIDTH-1:0] rd_ptr_gray_wr_clk;

    reg wr_toggle_f;
    reg rd_toggle_f;
    reg wr_toggle_f_rd_clk;
    reg rd_toggle_f_wr_clk;



    always @(posedge wr_clk_i) begin
        if (rst_i == 1) begin

            full_o             = 0;
            empty_o            = 1;
            wr_error_o         = 0;
            rd_error_o         = 0;
            rdata_o            = 0;
            wr_ptr             = 0;
            rd_ptr             = 0;
            wr_ptr_gray        = 0;
            rd_ptr_gray        = 0;
            wr_ptr_rd_clk      = 0;
            rd_ptr_wr_clk      = 0;
            wr_toggle_f        = 0;
            rd_toggle_f        = 0;
            wr_toggle_f_rd_clk = 0;
            rd_toggle_f_wr_clk = 0;

            for(i = 0; i <DEPTH; i = i + 1) begin
                memory[i] = 1;
            end
        end
        else begin

            wr_error_o = 0;

            if (wr_en_i == 1) begin
                if (full_o == 1) begin
                    wr_error_o = 1;
                end
                else begin
                    memory[wr_ptr] = wdata_i;
                    if (wr_ptr == DEPTH-1) begin
                        wr_toggle_f = ~wr_toggle_f;
                    end
                    wr_ptr      = wr_ptr + 1;
                    wr_ptr_gray = {wr_ptr[3],wr_ptr[3:1] ^ wr_ptr[2:0]};

                end
            end

        end

    end




    always @(posedge rd_clk_i) begin
        if (rst_i != 1) begin
            rd_error_o = 0;


            if (rd_en_i == 1) begin
                if (empty_o == 1) begin
                    rd_error_o = 1;
                end
                else begin
                    rdata_o = memory[rd_ptr];
                    if (rd_ptr == DEPTH-1) begin
                        rd_toggle_f = ~rd_toggle_f;
                    end
                    rd_ptr      = rd_ptr + 1;
                    rd_ptr_gray = {rd_ptr[3],rd_ptr[3:1]^rd_ptr[2:0]};

                end
            end
        end

    end




    always @(*) begin
        empty_o = 0;
        full_o  = 0;


        if (wr_ptr_gray == rd_ptr_gray_wr_clk) begin
            if (wr_toggle_f != rd_toggle_f_wr_clk) full_o = 1;
        end

        if (wr_ptr_gray_rd_clk == rd_ptr_gray) begin
            if (wr_toggle_f_rd_clk == rd_toggle_f) empty_o = 1;
        end



    end



    always @(posedge rd_clk_i) begin
        wr_ptr_gray_rd_clk <= wr_ptr_gray;
        wr_toggle_f_rd_clk <= wr_toggle_f;
    end


    always @(posedge wr_clk_i) begin
        rd_ptr_gray_wr_clk <= rd_ptr_gray;
        rd_toggle_f_wr_clk <= rd_toggle_f;
    end

endmodule

`timescale 1ns / 1ps





















module Control(
    input      [6: 0] opcode,
    input      [2: 0] func3,
    input      [6: 0] func7,
    output reg [2: 0] ExtOp,    
    output reg [2: 0] Branch,   
    output reg        MemRead,  

    output reg        MemWrite, 
    output reg [3: 0] ALUsrc,    
    output reg        ALUAsrc,  
    output reg [1: 0] ALUBsrc,  

    output reg        MemToReg, 
    output reg        RegWrite  
    );


    always @(*) begin
        ExtOp = 3'b000;   
        RegWrite = 0;
        Branch = 3'b000;
        MemToReg = 0;
        MemWrite = 0;
        MemRead = 0;
        ALUAsrc = 0;      
        ALUBsrc = 2'b00;  
        ALUsrc = 4'b0000;  
        case(opcode[6: 2])
        5'b01101: begin          
            ExtOp = 3'b001;
            RegWrite = 1;
            ALUBsrc = 2'b01;  
            ALUsrc = 4'b0011;     
        end
        5'b00101: begin           
            ExtOp = 3'b001; 
            RegWrite = 1;
            ALUAsrc = 1;      
            ALUBsrc = 2'b01;  
            ALUsrc = 4'b0000;     
        end
        5'b01100: begin           
            case(func3)
            3'b000: begin   
                case(func7[5]) 
                1: begin      
                    RegWrite = 1;
                    ALUsrc = 4'b1000;     
                end
                0: begin      
                    RegWrite = 1;
                    ALUsrc = 4'b0000;     
                end
                endcase
            end
            3'b100: begin   
                RegWrite = 1;
                ALUsrc = 4'b0100;     
            end
            3'b110: begin   
                RegWrite = 1;
                ALUsrc = 4'b0110;     
            end
            3'b111: begin   
                RegWrite = 1;
                ALUsrc = 4'b0111;     
            end
            default: begin
                RegWrite = 0;
                ALUsrc = 4'b0000;   
            end
            endcase
        end
        5'b00100: begin           
            case(func3)
            3'b000: begin    
                RegWrite = 1;
                ALUBsrc = 2'b01;
                ALUsrc = 4'b0000;   
            end
            3'b001: begin    
                RegWrite = 1;
                ALUBsrc = 2'b01;
                ALUsrc = 4'b0001;   
            end
            3'b101: begin
                case(func7[5])
                1: begin     
                    RegWrite = 1;
                    ALUBsrc = 2'b01;
                    ALUsrc = 4'b1101;   
                end
                0: begin     
                    RegWrite = 1;
                    ALUBsrc = 2'b01;
                    ALUsrc = 4'b0101;    
                end
                endcase
            end
            default: begin
                RegWrite = 0;
                ALUBsrc = 2'b00;
                ALUsrc = 4'b0000;
            end
            endcase
        end
        5'b00000: begin           
            ExtOp = 3'b000;
            RegWrite = 1;
            MemWrite = 0;         

            MemRead = 1;   
            MemToReg = 1;
            ALUBsrc = 2'b01;
            ALUsrc = 4'b0000;     
        end 
        5'b01000: begin           
            ExtOp = 3'b010;
            RegWrite = 0;         
            MemWrite = 1;
            MemToReg = 0;        
            ALUBsrc = 2'b01;
            ALUsrc = 4'b0000;     
        end
        5'b11000: begin           
            case(func3)
            3'b000: begin      
                ExtOp = 3'b011;
                Branch = 3'b100;
                ALUsrc = 4'b0010;    
            end
            3'b100: begin      
                ExtOp = 3'b011;
                Branch = 3'b110;
                ALUsrc = 4'b0010;    
            end
            3'b110: begin      
                ExtOp = 3'b011;
                Branch = 3'b110;
                ALUsrc = 4'b1010;     
            end
            default: begin
                ExtOp = 3'b000;
                Branch = 3'b000;
                ALUsrc = 4'b0000;
            end
            endcase
        end
        5'b11011: begin           
            ExtOp = 3'b100;
            RegWrite = 1;
            Branch = 3'b001;
            ALUAsrc = 1;
            ALUBsrc = 2'b10;
            ALUsrc = 4'b0000;     
        end
        5'b11001: begin           
            ExtOp = 3'b000;
            RegWrite = 1;
            Branch = 3'b010;
            ALUAsrc = 1;
            ALUBsrc = 2'b10;
            ALUsrc = 4'b0000;      
        end
        default: begin
        end
        endcase
    end

endmodule

