    localparam BASE_ADDR = 3;  
    localparam COLON = 10;
    localparam ROW_NUM = 24;

    localparam CLK_BASE_ADDR = 59544; 

    reg IM_WEN_w, IM_WEN_r;
    reg e_sec_w, e_sec_r;               
    reg [2:0]  state_w, state_r;
    reg [2:0]  s_cnt_r, s_cnt_w;        
    reg [15:0] b_cnt_r, b_cnt_w;        
    reg [2:0]  cnt5_r, cnt5_w;          
    reg [19:0] addr_r, addr_w;          
    reg [8:0]  ch_addr_r, ch_addr_w;    
    reg [23:0] time_w, time_r;          
    reg [19:0] FB_addr_w, FB_addr_r;
    reg [2:0]  p_num_w, p_num_r;        
    reg [19:0] p_addr_w, p_addr_r;      
    reg [1:0]  p_size_w, p_size_r;      
    reg [1:0]  photo_id_w, photo_id_r;  
    reg [11:0] bitmap_w, bitmap_r;      
    reg [2:0]  char_cnt_w, char_cnt_r;  
    reg [3:0]  bit_cnt_w, bit_cnt_r;    
    reg [4:0]  row_cnt_w, row_cnt_r;    

    reg [15:0] output_id_w, output_id_r;        


    reg [9:0] red_w, red_r;
    reg [9:0] green_w, green_r;
    reg [9:0] blue_w, blue_r;

    reg [3:0] char_sel;
    reg  first_w, first_r;    


    wire [15:0] addr_128_0, addr_128_1, addr_128_2, addr_128_3;
    wire [17:0] addr_512_0, addr_512_1, addr_512_2, addr_512_3;
    wire [6:0]  row_128, col_128;               
    wire [3:0]  hr1, hr0, min1, min0, sec1, sec0;

    assign sec1 = (time_r[7:0]< 8'd10)? 0:
                  (time_r[7:0]< 8'd20)? 1:
                  (time_r[7:0]< 8'd30)? 2:
                  (time_r[7:0]< 8'd40)? 3:
                  (time_r[7:0]< 8'd50)? 4:
                  (time_r[7:0]< 8'd60)? 5: 6; 
    assign sec0 = time_r[7:0] - 10*sec1;

    assign min1 = (time_r[15:8]< 8'd10)? 0:
                  (time_r[15:8]< 8'd20)? 1:
                  (time_r[15:8]< 8'd30)? 2:
                  (time_r[15:8]< 8'd40)? 3:
                  (time_r[15:8]< 8'd50)? 4:
                  (time_r[15:8]< 8'd60)? 5: 6; 
    assign min0 = time_r[15:8] - 10*min1;

    assign hr1 = (time_r[23:16]< 8'd10)? 0:
                 (time_r[23:16]< 8'd20)? 1:
                 (time_r[23:16]< 8'd30)? 2: 3; 
    assign hr0 = time_r[23:16] - 10*hr1;


    assign row_128 = (b_cnt_r[14:8]==7'd127)? b_cnt_r[14:8]: b_cnt_r[14:8] + 1'b1;
    assign col_128 = (b_cnt_r[6:0]==7'd127)? b_cnt_r[6:0]: b_cnt_r[6:0] + 1'b1;

    assign addr_128_0 = {b_cnt_r[14:8], b_cnt_r[6:0]};  
    assign addr_128_1 = {b_cnt_r[14:8], col_128};       
    assign addr_128_2 = {row_128, b_cnt_r[6:0]};        
    assign addr_128_3 = {row_128, col_128};             


    assign addr_512_0 = {output_id_r[15:8], 1'b0, output_id_r[7:0], 1'b0};
    assign addr_512_1 = {output_id_r[15:8], 1'b0, output_id_r[7:0], 1'b1};
    assign addr_512_2 = {output_id_r[15:8], 1'b1, output_id_r[7:0], 1'b0};
    assign addr_512_3 = {output_id_r[15:8], 1'b1, output_id_r[7:0], 1'b1};

    assign IM_A = addr_r;
    assign CR_A = ch_addr_r;
    assign IM_D = (IM_WEN_r)? 24'b0: {red_r[9:2], green_r[9:2], blue_r[9:2]};
    assign IM_WEN = IM_WEN_r;

    always@(*) begin
        state_w = state_r;
        addr_w = addr_r;
        time_w = time_r;
        ch_addr_w = ch_addr_r;
        FB_addr_w = FB_addr_r;
        p_num_w = p_num_r;
        p_addr_w = p_addr_r;
        p_size_w = p_size_r;
        IM_WEN_w = IM_WEN_r;
        red_w = red_r;
        green_w = green_r;
        blue_w = blue_r;
        photo_id_w = photo_id_r;
        e_sec_w = e_sec_r;
        bitmap_w = bitmap_r;
        char_cnt_w = char_cnt_r;
        bit_cnt_w = bit_cnt_r;
        row_cnt_w = row_cnt_r;
        first_w = first_r;
        char_sel = 4'b0;




        if (state_r == UPDATE_CLK || state_r == WAIT) begin
            output_id_w = output_id_r;
        end else begin
            if (cnt5_r==3'd0) begin
                output_id_w = (b_cnt_r[7])? {b_cnt_r[14:0], 1'b0} : {b_cnt_r[14:0], 1'b1};
            end else begin
                output_id_w = (b_cnt_r[7])? {b_cnt_r[14:0], 1'b1} : {b_cnt_r[14:0], 1'b0};
            end
        end


        if (s_cnt_r < 3'd5) begin
            s_cnt_w = s_cnt_r + 1'b1;
            b_cnt_w = b_cnt_r;
        end else begin
            s_cnt_w = 3'd1;
            b_cnt_w = (b_cnt_r == 16'd39999)? 16'd0: b_cnt_r + 1'b1;
        end


        if (b_cnt_r == 16'd39999 && s_cnt_r==3'd5) begin
            cnt5_w = (cnt5_r == 3'd4)? 3'd0: cnt5_r + 1'b1;
        end else begin
            cnt5_w = cnt5_r;
        end








        if (~first_r && s_cnt_r==3'd1 && ((e_sec_r && b_cnt_r==16'd0 && cnt5_r==3'd0) || (e_sec_r && b_cnt_r==16'd39999 && cnt5_r==3'd4))) begin
            if (time_r[7:0] == 8'd59) begin             
                time_w[7:0] = 8'd0;
                if (time_r[15:8] == 8'd59) begin        
                    time_w[15:8] = 8'd0;
                    if (time_r[23:16] == 8'd23) begin   
                        time_w[23:16] = 8'd0;
                    end else begin
                        time_w[23:16] = time_r[23:16] + 1'b1;
                    end
                end else begin
                    time_w[15:8] = time_r[15:8] + 1'b1;
                end
            end else begin
                time_w[7:0] = time_r[7:0] + 1'b1;
            end
        end else begin
            time_w = time_r;
        end


        if (cnt5_r == 3'd4 && b_cnt_r==16'd39999 && s_cnt_r==3'd5) begin
            e_sec_w = ~e_sec_r;
        end else begin
            e_sec_w = e_sec_r;
        end

        case(state_r)
            INIT: begin
                addr_w = addr_r + 1'b1;
                case(s_cnt_r)
                    3'd1: time_w = IM_Q;
                    3'd2: FB_addr_w = IM_Q[19:0];
                    3'd3: begin
                        p_num_w = IM_Q[2:0];
                        state_w = READ_HD;
                    end
                    default: begin
                    end
                endcase
            end

            READ_HD: begin
                if (s_cnt_r >= 3'd4) begin
                    if (!addr_r[0]) begin 
                        addr_w = addr_r + 1'b1;
                        p_addr_w = IM_Q[19:0];
                    end else begin       
                        if (IM_Q[7]) begin
                            p_size_w = 2'b01; 
                            addr_w = p_addr_r;
                            state_w = DUMMY;
                        end else if (IM_Q[8]) begin
                            p_size_w = 2'b10; 
                            addr_w = p_addr_r + 1'b1;
                            state_w = TRAN;
                        end else if (IM_Q[9]) begin
                            p_size_w = 2'b11; 
                            addr_w = p_addr_r + 2'd2;
                            state_w = DUMMY;
                        end
                    end
                end else begin
                    if (s_cnt_r==3'd3) begin
                        addr_w = addr_r + 1'b1;
                    end
                    state_w = state_r;
                end
            end

            TRAN: begin 
                if (b_cnt_r < HALF_TRAN) begin
                    if (output_id_r[7:0] < 8'd152 || output_id_r[15:8] < 8'd232) begin
                        case(p_size_r)
                            2'b01: begin  
                                case(s_cnt_r)
                                    3'd1: begin  
                                        red_w = IM_Q[23:16];
                                        green_w = IM_Q[15:8];
                                        blue_w = IM_Q[7:0];
                                        IM_WEN_w = 1'b1;
                                        if (b_cnt_r[6:0]==7'd0 && b_cnt_r[15:7]!=9'd0) begin
                                            if (cnt5_r==3'd0) begin
                                                addr_w = (output_id_r[8])? 
                                                         p_addr_r + addr_128_1:
                                                         p_addr_r + addr_128_0;
                                            end else begin
                                                addr_w = (output_id_r[8])? 
                                                         p_addr_r + addr_128_0:
                                                         p_addr_r + addr_128_1;
                                            end
                                        end else begin
                                            if (output_id_r[0]) begin  
                                                addr_w =  p_addr_r + addr_128_1;
                                            end else begin
                                                addr_w =  p_addr_r + addr_128_0;
                                            end
                                        end
                                    end
                                    3'd2: begin 
                                        if (b_cnt_r ==16'b0) begin
                                            red_w = IM_Q[23:16];                                                                                        
                                            green_w = IM_Q[15:8];
                                            blue_w = IM_Q[7:0];
                                        end else begin
                                            red_w = red_r; 
                                            green_w = green_r;
                                            blue_w = blue_r;
                                        end

                                        if (output_id_r[8]) 
                                            addr_w = p_addr_r + addr_128_2;
                                        else
                                            addr_w = p_addr_r + addr_128_0;
                                    end
                                    3'd3: begin
                                        red_w = red_r + IM_Q[23:16];
                                        green_w = green_r + IM_Q[15:8];
                                        blue_w = blue_r + IM_Q[7:0];

                                        if (output_id_r[0] && output_id_r[8]) 
                                            addr_w = p_addr_r + addr_128_3;
                                        else begin
                                            if (output_id_r[0]) 
                                                addr_w = p_addr_r + addr_128_1;
                                            else if (output_id_r[8]) 
                                                addr_w = p_addr_r + addr_128_2;
                                            else    
                                                addr_w = p_addr_r + addr_128_0;
                                        end
                                    end
                                    3'd4: begin
                                        red_w = red_r + IM_Q[23:16];
                                        green_w = green_r + IM_Q[15:8];
                                        blue_w = blue_r + IM_Q[7:0];
                                        if (b_cnt_r[7:0]==8'd127) begin
                                            addr_w = p_addr_r + addr_128_0 + 1'b1 - 8'd128;
                                        end else begin
                                            addr_w = p_addr_r + addr_128_0 + 1'b1;
                                        end
                                    end
                                    3'd5: begin
                                        red_w = red_r + IM_Q[23:16];
                                        green_w = green_r + IM_Q[15:8];
                                        blue_w = blue_r + IM_Q[7:0];
                                        IM_WEN_w = 1'b0;
                                        addr_w = FB_addr_r + output_id_r;
                                    end
                                    default: begin
                                    end
                                endcase
                            end
                            2'b10: begin 
                                case(s_cnt_r)
                                    3'd2: begin
                                        addr_w = p_addr_r + output_id_r;
                                    end
                                    3'd4: begin
                                        red_w = {IM_Q[23:16], 2'b0};
                                        green_w = {IM_Q[15:8], 2'b0};
                                        blue_w = {IM_Q[7:0], 2'b0};
                                        IM_WEN_w = 1'b0;
                                        addr_w = FB_addr_r + output_id_r;
                                    end
                                    default: begin
                                        IM_WEN_w = 1'b1;
                                    end
                                endcase
                            end
                            2'b11: begin 
                                case(s_cnt_r)
                                    3'd1: begin 
                                        IM_WEN_w = 1'b1;
                                        if ((b_cnt_r[6:0]==7'd0) && (b_cnt_r[15:7]!=9'd0)) begin
                                            if (cnt5_r == 3'd0) begin
                                                addr_w = (b_cnt_r[7])? 
                                                         p_addr_r + addr_512_1 + 3'd2 + 10'd512:
                                                         p_addr_r + addr_512_1 + 3'd6 + 10'd512;
                                            end else begin
                                                addr_w = (b_cnt_r[7])? 
                                                         p_addr_r + addr_512_1 + 3'd6 + 10'd512:
                                                         p_addr_r + addr_512_1 + 3'd2 + 10'd512;
                                            end
                                        end else begin
                                            addr_w = p_addr_r + addr_512_1 + 3'd4;
                                        end
                                        red_w = IM_Q[23:16];
                                        green_w = IM_Q[15:8];
                                        blue_w = IM_Q[7:0];
                                    end
                                    3'd2: begin 
                                        addr_w = p_addr_r + addr_512_2;
                                        if (b_cnt_r==16'b0) begin
                                            red_w = IM_Q[23:16];
                                            green_w = IM_Q[15:8];
                                            blue_w = IM_Q[7:0];
                                        end else begin
                                            red_w = red_r;
                                            green_w = green_r;
                                            blue_w = blue_r;
                                        end
                                    end
                                    3'd3: begin
                                        addr_w = p_addr_r + addr_512_3;
                                        red_w = red_r + IM_Q[23:16];
                                        green_w = green_r + IM_Q[15:8];
                                        blue_w = blue_r + IM_Q[7:0];
                                    end
                                    3'd4: begin

                                        if (b_cnt_r[6:0]==7'd127) begin
                                            if (cnt5_r == 3'd0) begin
                                                addr_w = (b_cnt_r[7])? 
                                                         p_addr_r + addr_512_0 + 3'd6 + 10'd512:
                                                         p_addr_r + addr_512_0 + 3'd2 + 10'd512;
                                            end else begin
                                                addr_w = (b_cnt_r[7])? 
                                                         p_addr_r + addr_512_0 + 3'd2 + 10'd512:
                                                         p_addr_r + addr_512_0 + 3'd6 + 10'd512;
                                            end
                                        end else begin
                                            addr_w = p_addr_r + addr_512_0 + 3'd4;
                                        end

                                        red_w = red_r + IM_Q[23:16];
                                        green_w = green_r + IM_Q[15:8];
                                        blue_w = blue_r + IM_Q[7:0];
                                    end
                                    3'd5: begin 
                                        IM_WEN_w = 1'b0;
                                        addr_w = FB_addr_r + output_id_r;
                                        red_w = red_r + IM_Q[23:16];
                                        green_w = green_r + IM_Q[15:8];
                                        blue_w = blue_r + IM_Q[7:0];
                                    end
                                    default: begin
                                    end
                                endcase
                            end
                            default: begin
                            end
                        endcase
                    end else begin
                        if (p_size_r==2'b11) begin
                            case(s_cnt_r)
                                3'd1: begin
                                    IM_WEN_w = 1'b1;
                                    if ((b_cnt_r[6:0]==7'd0) && (b_cnt_r[15:7]!=9'd0)) begin
                                        if (cnt5_r == 3'd0) begin
                                            addr_w = (b_cnt_r[7])? 
                                                     p_addr_r + addr_512_1 + 3'd2 + 10'd512:
                                                     p_addr_r + addr_512_1 + 3'd6 + 10'd512;
                                        end else begin
                                            addr_w = (b_cnt_r[7])? 
                                                     p_addr_r + addr_512_1 + 3'd6 + 10'd512:
                                                     p_addr_r + addr_512_1 + 3'd2 + 10'd512;
                                        end
                                    end else begin
                                        addr_w = p_addr_r + addr_512_1 + 3'd4;
                                    end
                                    red_w = IM_Q[23:16];
                                    green_w = IM_Q[15:8];
                                    blue_w = IM_Q[7:0];
                                end
                                3'd4: begin
                                    if (b_cnt_r[6:0]==7'd127) begin
                                        if (cnt5_r == 3'd0) begin
                                            addr_w = (b_cnt_r[7])? 
                                                     p_addr_r + addr_512_0 + 3'd6 + 10'd512:
                                                     p_addr_r + addr_512_0 + 3'd2 + 10'd512;
                                        end else begin
                                            addr_w = (b_cnt_r[7])? 
                                                     p_addr_r + addr_512_0 + 3'd2 + 10'd512:
                                                     p_addr_r + addr_512_0 + 3'd6 + 10'd512;
                                        end
                                    end else begin
                                        addr_w = p_addr_r + addr_512_0 + 3'd4;
                                    end
                                end
                                default: begin
                                    addr_w = addr_r;
                                end
                            endcase
                        end else if (p_size_r==2'b01) begin
                            case(s_cnt_r)
                                3'd1: begin
                                    red_w = IM_Q[23:16];
                                    green_w = IM_Q[15:8];
                                    blue_w = IM_Q[7:0];
                                    IM_WEN_w = 1'b1;
                                    if (b_cnt_r[6:0]==7'd0 && b_cnt_r[15:7]!=9'd0) begin
                                        if (cnt5_r==3'd0) begin
                                            addr_w = (output_id_r[8])? 
                                                     p_addr_r + addr_128_1:
                                                     p_addr_r + addr_128_0;
                                        end else begin
                                            addr_w = (output_id_r[8])? 
                                                     p_addr_r + addr_128_0:
                                                     p_addr_r + addr_128_1;
                                        end
                                    end else begin
                                        if (output_id_r[0]) begin  
                                            addr_w =  p_addr_r + addr_128_1;
                                        end else begin
                                            addr_w =  p_addr_r + addr_128_0;
                                        end
                                    end
                                end
                                3'd4: begin
                                    if (b_cnt_r[7:0]==8'd127) begin
                                        addr_w = p_addr_r + addr_128_0 + 1'b1 - 8'd128;
                                    end else begin
                                        addr_w = p_addr_r + addr_128_0 + 1'b1;
                                    end
                                end
                                default: begin
                                    addr_w = addr_r;
                                end
                            endcase
                        end
                    end
                end else begin
                    IM_WEN_w = 1'b1;
                    state_w = UPDATE_CLK;
                    ch_addr_w = ROW_NUM*hr1;
                    bit_cnt_w = 4'd0;
                    row_cnt_w = 5'd0;
                    char_cnt_w = 3'd0;
                end
            end
            UPDATE_CLK: begin

                if  (bit_cnt_r==4'd12 && row_cnt_r==5'd23) begin
                    state_w = (char_cnt_r==3'd7)? WAIT: state_r;
                end

                if (bit_cnt_r == 4'd13) begin
                    addr_w = addr_r;
                    IM_WEN_w = 1'b1;
                end else begin
                    addr_w = FB_addr_r + CLK_BASE_ADDR + char_cnt_r*13 + row_cnt_r*256 + bit_cnt_r;
                    IM_WEN_w = 1'b0;
                end

                case(char_cnt_r)
                    3'd0: char_sel = (row_cnt_r==5'd23)? hr0: hr1;
                    3'd1: char_sel = (row_cnt_r==5'd23)? COLON: hr0; 
                    3'd2: char_sel = (row_cnt_r==5'd23)? min1:COLON; 
                    3'd3: char_sel = (row_cnt_r==5'd23)? min0: min1; 
                    3'd4: char_sel = (row_cnt_r==5'd23)? COLON: min0; 
                    3'd5: char_sel = (row_cnt_r==5'd23)? sec1: COLON; 
                    3'd6: char_sel = (row_cnt_r==5'd23)? sec0: sec1; 
                    3'd7: char_sel = (row_cnt_r==5'd23)? hr1: sec0; 
                endcase

                bit_cnt_w = bit_cnt_r + 1'b1;
                if (bit_cnt_r == 4'd0) begin
                    bitmap_w = CR_Q[11:0];
                    red_w = (CR_Q[12])? 10'd1023: 10'd0;
                    green_w = (CR_Q[12])? 10'd1023: 10'd0;
                    blue_w = (CR_Q[12])? 10'd1023: 10'd0;
                end else begin
                    if (bit_cnt_r == 4'd13) begin
                        if (row_cnt_r == 5'd23) begin
                            row_cnt_w = 5'd0;
                            char_cnt_w = (char_cnt_r==3'd7)? 3'd0: char_cnt_r + 1'b1;
                        end else begin
                            row_cnt_w = row_cnt_r + 1'b1;
                        end
                        bit_cnt_w = 4'd0;
                    end else if (bit_cnt_r == 4'd12) begin
                        if (row_cnt_r == 5'd23) begin
                            ch_addr_w = ROW_NUM*char_sel;
                        end else begin
                            ch_addr_w = ROW_NUM*char_sel + row_cnt_r + 1'b1;
                        end
                    end

                    bitmap_w = {bitmap_r[10:0], bitmap_r[11]};
                    red_w = (bitmap_r[11])? 10'd1023: 10'd0;
                    green_w = (bitmap_r[11])? 10'd1023: 10'd0;
                    blue_w = (bitmap_r[11])? 10'd1023: 10'd0;
                end

            end
            WAIT: begin
                IM_WEN_w = 1'b1;
                first_w = 1'b0;
                if (cnt5_r==3'd0 && b_cnt_r == 16'd39999 && s_cnt_r==3'd5) begin
                    case(p_size_r)
                        2'b01: begin                
                            addr_w = p_addr_r;
                            state_w = DUMMY;
                        end
                        2'b10: begin
                            addr_w = p_addr_r;      
                            state_w = TRAN;
                        end
                        2'b11: begin                
                            addr_w = p_addr_r;
                            state_w = DUMMY;
                        end
                    endcase
                end else if (cnt5_r==3'd4 && b_cnt_r==16'd39998 && s_cnt_r==3'd5) begin
                    if (e_sec_r) begin
                        state_w = UPDATE_CLK;
                    end else begin
                        state_w = READ_HD;
                        if (photo_id_r == p_num_r-1'b1) begin
                            addr_w = BASE_ADDR;
                            photo_id_w = 2'd0;
                        end else begin
                            addr_w = BASE_ADDR + 2*(photo_id_r + 1'b1);
                            photo_id_w = photo_id_r + 1'b1;
                        end
                    end
                end
            end
            DUMMY: begin
                state_w = TRAN;
                if (p_size_r==2'b11) begin
                    addr_w = (cnt5_r==3'd0)? p_addr_r+2'd3: p_addr_r+2'd1;
                    red_w = 10'b0;
                    green_w = 10'b0;
                    blue_w = 10'b0;
                end else if (p_size_r==2'b01) begin
                    addr_w = (cnt5_r==3'd0)? p_addr_r+2'd1: p_addr_r;
                    red_w = 10'b0;
                    green_w = 10'b0;
                    blue_w = 10'b0;
                end
            end
        endcase
    end

    always@(posedge clk or posedge reset) begin
        if (reset) begin
            IM_WEN_r <= 1'b1;
            s_cnt_r <= 3'b0;
            b_cnt_r <= 16'hffff;
            cnt5_r <= 3'b0;
            state_r <= INIT;
            addr_r <= 20'b0;
            time_r <= 24'b0;
            ch_addr_r <= 9'b0;
            FB_addr_r <= 20'b0;
            p_num_r <= 3'b0;
            p_addr_r <= 20'b0;
            p_size_r <= 2'b0;
            red_r <= 10'b0;
            green_r <= 10'b0;
            blue_r <= 10'b0;
            output_id_r <= 16'b0;
            photo_id_r <= 2'b0;
            e_sec_r <= 1'b1;
            bitmap_r <= 12'b0;
            char_cnt_r <= 3'b0;
            bit_cnt_r <= 4'b0;
            row_cnt_r <= 5'b0;
            first_r <= 1'b1;

        end else begin
            IM_WEN_r <= IM_WEN_w;
            s_cnt_r <= s_cnt_w;
            b_cnt_r <= b_cnt_w;
            cnt5_r <= cnt5_w;
            state_r <= state_w;
            addr_r <= addr_w;
            time_r <= time_w;
            ch_addr_r <= ch_addr_w;
            FB_addr_r <= FB_addr_w;
            p_num_r <= p_num_w;
            p_addr_r <= p_addr_w;
            p_size_r <= p_size_w;
            red_r <= red_w;
            green_r <= green_w;
            blue_r <= blue_w;
            output_id_r <= output_id_w;
            photo_id_r <= photo_id_w;
            e_sec_r <= e_sec_w;
            bitmap_r <= bitmap_w;
            char_cnt_r <= char_cnt_w;
            bit_cnt_r <= bit_cnt_w;
            row_cnt_r <= row_cnt_w;
            first_r <= first_w;
        end
    end

endmodule

module b01 (
	input clock, 
	input  line1, 
	input line2,
	input reset,

	output reg outp,
	output reg overflw
);

reg [2:0] stato;


parameter   a = 3'b0;
parameter   b = 3'b001;
parameter   c = 3'b010;
parameter   e = 3'b011;
parameter   f = 3'b100;
parameter   g = 3'b101;
parameter wf0 = 3'b110;
parameter wf1 = 3'b111;

always@(posedge clock)
    if(reset==1'b1) 
		begin
			stato <= a;
			outp <= 1'b0;
			overflw<=1'b0;
		end
    else 
		case(stato)
		a:
			begin
				if(line1 == 1'b1 && line2==1'b1) begin
					stato <= f;
				end
				else begin
					stato <= b ;
					end
				outp <= line1 | line2;
				overflw <= 1'b0;
			end
		e:
			begin
				if(line1 == 1'b1 && line2==1'b1 ) begin
					stato <= f;
				end
				else begin
					stato <= b ;
				end
				outp <= line1 | line2;
				overflw <= 1'b1;
			end
        b:   
			begin
                if(line1 == 1'b1 && line2 == 1'b1) begin
					stato <= g ;
				end
                else begin 
                    stato <= c;
				end
				outp <= line1 | line2;
				overflw <= 1'b0 ;
			end
        f:
			begin
                if( line1 == 1'b1 || line2 == 1'b1) begin
                    stato <= g;
				end
                else begin
                    stato <= c;
				end
				outp <= ~(line1 ^ line2);
				overflw <= 1'b0 ;
			end
        c:  
			begin
                if(line1 == 1'b1 && line2 == 1'b1 ) begin
                    stato <= wf1;
				end
                else begin
                    stato <= wf0;
				end
				outp <= line1 | line2;
				overflw <= 1'b0 ;
			end
        g: 
			begin
                if( line1 == 1'b1 || line2 ==1'b1) begin
					stato <= wf1;
				end
                else begin
					stato <= wf0;
            	end
				outp <= ~(line1 | line2);
				overflw <= 1'b0 ;
			end
        wf0:
			begin
                if( line1==1'b1 && line2==1'b1 ) begin
                    stato <= e;
				end
                else begin
                    stato <= a;
				end
				outp <= line1 | line2;
				overflw <= 1'b0 ;
			end
        wf1:
			begin
                if( line1==1'b1 || line2==1'b1 ) begin
                    stato <= e;
				end
                else begin
                    stato <= a;
				end
				outp <= ~(line1 | line2);
				overflw <= 1'b0 ;
			end
        endcase

endmodule

`timescale 1ns / 1ps

module fir 
#(  parameter pADDR_WIDTH = 12,
    parameter pDATA_WIDTH = 32,
    parameter Tape_Num    = 11
)
(

    output  wire                     awready,
    output  wire                     wready,
    input   wire                     awvalid,
    input   wire [(pADDR_WIDTH-1):0] awaddr,
    input   wire                     wvalid,
    input   wire [(pDATA_WIDTH-1):0] wdata,


    output  wire                     arready,
    input   wire                     rready,
    input   wire                     arvalid,
    input   wire [(pADDR_WIDTH-1):0] araddr,
    output  reg                      rvalid,
    output  reg  [(pDATA_WIDTH-1):0] rdata,


    input   wire                     ss_tvalid, 
    input   wire [(pDATA_WIDTH-1):0] ss_tdata, 
    input   wire                     ss_tlast, 
    output  reg                      ss_tready, 


    input   wire                     sm_tready, 
    output  wire                     sm_tvalid, 
    output  wire  [(pDATA_WIDTH-1):0]sm_tdata, 
    output  wire                     sm_tlast, 


    output  reg [3:0]               tap_WE,
    output  wire                    tap_EN,
    output  reg [(pDATA_WIDTH-1):0] tap_Di,
    output  reg [(pADDR_WIDTH-1):0] tap_A,
    input   wire signed [(pDATA_WIDTH-1):0] tap_Do,


    output  reg  [3:0]               data_WE,
    output  reg                      data_EN,
    output  reg  [(pDATA_WIDTH-1):0] data_Di,
    output  reg  [(pADDR_WIDTH-1):0] data_A,
    input   wire [(pDATA_WIDTH-1):0] data_Do,

    input   wire                     axis_clk,
    input   wire                     axis_rst_n

);


localparam S_IDLE = 3'b000; 
localparam S_GET  = 3'b001; 
localparam S_CAL  = 3'b010; 
localparam S_OUT  = 3'b011; 

localparam AR_IDLE = 2'b00; 
localparam AR_DATA = 2'b01; 
localparam AR_CMD  = 2'b10; 

localparam AW_IDLE = 2'b00; 
localparam AW_DATA = 2'b01; 
localparam AW_CMD  = 2'b10; 



reg  signed[(pDATA_WIDTH-1):0] acc_reg;
wire signed[(pDATA_WIDTH-1):0] mul_result;
wire signed [(pDATA_WIDTH-1):0] h_coeff, x_data;
reg [(pDATA_WIDTH-1):0]temp_sdata;
reg [3:0] coe_cnt,cnt;
reg [3:0] coe_point;
reg eof;
reg [2:0]ap_flag, ap_flag_n;

reg [6:0]addr_temp;
reg [2:0]n_state, c_state;
reg [1:0]axir_n, axir_c;
reg [1:0]axiw_n, axiw_c;


	always@(posedge axis_clk, negedge axis_rst_n) begin
		if(!axis_rst_n)
			ap_flag <= 3'b100;
		else
			ap_flag <= ap_flag_n;
	end 

	always@(*) begin
		if(axiw_c == AW_CMD && wvalid)
			ap_flag_n = wdata;
		else if(ss_tready)
			ap_flag_n = 3'b000;
		else if(c_state == S_OUT && sm_tready && sm_tvalid)
			ap_flag_n = 3'b110;
		else if(c_state == S_IDLE && axir_c == AR_CMD && rready && rvalid)
			ap_flag_n = 3'b100;
		else
			ap_flag_n = ap_flag;
	end




	always@(posedge axis_clk, negedge axis_rst_n) begin
		if(!axis_rst_n)
			c_state <= S_IDLE;
		else
			c_state <= n_state;
	end 

	always@(*) begin
		case(c_state)
		S_IDLE: if(ap_flag == 3'b001)   n_state = S_GET;
				else		   		    n_state = S_IDLE;
		S_GET:  n_state = S_CAL;
		S_CAL:  if(coe_cnt == 10) begin
					if(eof == 1)
						n_state = S_OUT;
					else
						n_state = S_GET;
				end 
				else 	 n_state = S_CAL;
		S_OUT:  if(sm_tready && sm_tvalid)
					n_state = S_IDLE;
				else
					n_state = S_OUT;
		default: n_state = S_IDLE;
		endcase
	end



	always@(posedge axis_clk, negedge axis_rst_n) begin
		if(!axis_rst_n)
			axir_c <= AR_IDLE;
		else
			axir_c <= axir_n;
	end 

	always@(*) begin
		case(axir_c)
		AR_IDLE: if(arvalid && arready) 
					if(araddr == 0)
						axir_n = AR_CMD;
					else
						axir_n = AR_DATA;
				 else		 axir_n = AR_IDLE;
		AR_DATA: if(rready && rvalid) axir_n = AR_IDLE;
				 else		axir_n = AR_DATA;
		AR_CMD:  if(rready && rvalid) axir_n = AR_IDLE;
				 else		axir_n = AR_CMD;
		default: axir_n = AR_IDLE;
		endcase
	end



	always@(posedge axis_clk, negedge axis_rst_n) begin
		if(!axis_rst_n)
			axiw_c <= AW_IDLE;
		else
			axiw_c <= axiw_n;
	end 

	always@(*) begin
		case(axiw_c)
		AW_IDLE: if(awvalid && awvalid) 
					if(awaddr == 0)
						axiw_n = AW_CMD;
					else
						axiw_n = AW_DATA;
				 else		 axiw_n = AW_IDLE;
		AW_DATA: if(wready && wvalid) axiw_n = AW_IDLE;
				 else		axiw_n = AW_DATA;
		AW_CMD:  if(wready && wvalid) axiw_n = AW_IDLE;
				 else		axiw_n = AW_CMD;
		default: axiw_n = AW_IDLE;
		endcase
	end


	always@(posedge axis_clk, negedge axis_rst_n) begin
		if(!axis_rst_n)
			eof <= 1'b0;
		else
			if(c_state == S_OUT)
				eof <= 1'b0;
			else if(c_state == S_GET && ss_tlast == 1'b1)	
				eof <= 1'b1;
			else
				eof <= eof;
	end


	assign x_data = (coe_cnt == 0)? temp_sdata : data_Do;
	assign mul_result = tap_Do * x_data;
	always@(posedge axis_clk, negedge axis_rst_n) begin
		if(!axis_rst_n)
			acc_reg <= 0;
		else
			if(c_state == S_CAL)
				if(coe_cnt < cnt)
					acc_reg <= acc_reg + mul_result;
				else
					acc_reg <=acc_reg;
			else if(c_state == S_GET)
				acc_reg <= 0;
	end

	always@(posedge axis_clk, negedge axis_rst_n) begin
		if(!axis_rst_n)
			coe_cnt <= 0;
		else if(c_state == S_GET)
			coe_cnt <= 0;
		else if(c_state == S_CAL)
			coe_cnt <= coe_cnt + 1;
	end 

	always@(posedge axis_clk, negedge axis_rst_n) begin
		if(!axis_rst_n)
			cnt <= 0;
		else begin
			if(c_state == S_GET)
				if(cnt < 'd11)
					cnt <= cnt + 1;
				else
					cnt <= cnt;
			else if(c_state == S_IDLE)
				cnt <= 0;
		end
	end 

	always@(posedge axis_clk, negedge axis_rst_n) begin
		if(!axis_rst_n)
			coe_point <= 0;
		else begin
			if(c_state == S_IDLE)
				coe_point <= 0;
			else
				if(c_state == S_CAL && coe_cnt == 'd10)
					if(coe_point == 'd10)
						coe_point <= 0;
					else 
						coe_point <= coe_point + 1;

		end
	end 



	always@(posedge axis_clk, negedge axis_rst_n) begin
		if(!axis_rst_n)
			addr_temp <= 0;
		else if(axiw_c == AW_IDLE && awvalid)
			addr_temp <= awaddr;
		else if(axir_c == AR_IDLE && arvalid)
			addr_temp <= araddr;
		else
			addr_temp <= addr_temp;

	end 

	assign awready = (!axis_rst_n)? 1'b0:awvalid;
    assign  wready = (!axis_rst_n)? 1'b0:(axiw_c == AW_IDLE)?1'b0:1'b1;








	always@(posedge axis_clk, negedge axis_rst_n) begin
		if(!axis_rst_n)
			rvalid <= 0;
		else begin
			rvalid <= rready;
		end
	end 

	assign arready = (!axis_rst_n)? 1'b0:arvalid;

	always@(*) begin
		if(!axis_rst_n)begin
			rdata = 32'b0;
		end else begin
			case(axir_c)
			AR_IDLE: rdata = 32'b0;
			AR_DATA: rdata = tap_Do;
			AW_CMD:  rdata = ap_flag;
			default: rdata = 32'b0;
			endcase
		end
	end




	always@(posedge axis_clk, negedge axis_rst_n) begin
		if(!axis_rst_n)
			temp_sdata <= 0;
		else begin
			if(c_state == S_GET)
				temp_sdata <= ss_tdata;
		end
	end


	always@(*) begin
		if(!axis_rst_n)begin
			ss_tready = 1'b0;
		end else begin
			case(c_state)
			S_GET:	 ss_tready = 1'b1;
			default: ss_tready = 1'b0;
			endcase
		end
	end



	assign sm_tvalid = (!axis_rst_n)? 1'b0:( (c_state == S_GET && cnt >0) ||  (c_state == S_OUT && eof))? 1'b1: 1'b0;
	assign sm_tlast = (!axis_rst_n)? 1'b0:((c_state == S_GET && cnt >0)  || (c_state == S_OUT) )? eof: 1'b0;

	reg [(pDATA_WIDTH-1):0] temp_smdata;

	always@(posedge axis_clk, negedge axis_rst_n) begin
		if(!axis_rst_n)
			temp_smdata <= 0;
		else begin
			if(coe_cnt == 4'd10 && c_state == S_CAL)
				temp_smdata <= acc_reg;
			else
				temp_smdata <= 0;
		end
	end

	assign sm_tdata = temp_smdata;


	assign tap_EN = 1'b1;

	always@(*) begin
		if(!axis_rst_n)
			tap_WE = 4'b0;
		else if(axiw_c == AW_DATA && wvalid)
			tap_WE = 4'b1111;
		else
			tap_WE = 4'b0;
	end
	wire [3:0]temp_tap;
	assign temp_tap = 12'd9 - coe_cnt;
	always@(*) begin
		if(!axis_rst_n)begin
			tap_A = 12'b0;
		end else begin
			case(c_state)
			S_IDLE:  tap_A = addr_temp-12'h20;
			S_GET: 	 tap_A = {12'd10,2'd0};
			S_CAL: 	 tap_A = {temp_tap,2'd0};
			default: tap_A = 12'b0;
			endcase
		end
	end

	always@(*) begin
		if(!axis_rst_n)
			tap_Di = 32'b0;
		else if(axiw_c == AW_DATA && wvalid)
			tap_Di = wdata;
		else
			tap_Di = 32'b0;
	end








	always@(*) begin
		if(!axis_rst_n)begin
			data_EN = 1'b0;
		end else begin
			case(c_state)
			S_GET:	 data_EN = 1'b1;
			S_CAL:	 data_EN = 1'b1;
			default: data_EN = 1'b0;
			endcase
		end
	end
	always@(*) begin
		if(!axis_rst_n)begin
			data_WE = 4'b0;
		end else begin
			case(c_state)
			S_GET:   data_WE = 4'b1111;
			default: data_WE = 4'b0;
			endcase
		end
	end
	wire [4:0] temp_add, temp_sub,result;
	assign temp_add = coe_point - coe_cnt + 'd10;
	assign temp_sub = coe_point - coe_cnt - 'd1;
	assign result = (temp_sub[4])? temp_add : temp_sub ;
	always@(*) begin
		if(!axis_rst_n)begin
			data_A = 12'b0;
		end else begin
			case(c_state)
			S_GET:   data_A = {coe_point,2'd0};
			S_CAL:	 data_A = {result,2'd0};
			default: data_A = 12'b0;
			endcase
		end
	end

	always@(*) begin
		if(!axis_rst_n)begin
			data_Di = 32'b0;
		end else begin
			case(c_state)
			S_GET:	 data_Di = ss_tdata;
			default: data_Di = 32'b0;
			endcase
		end
	end



endmodule

module ADDRgen #(
    parameter R = 5,
    parameter N = 32
) (
    input i_clk,
    input i_rst,
    input i_en,
    output reg o_sel_wing,
    output reg [R-2:0] o_a0,  
    output reg [R-2:0] o_a1   
);


localparam s_0 = 2'b00; 
localparam s_1 = 2'b01; 
localparam s_2 = 2'b10;
reg [1:0] r_ps; 
reg [R-2:0] r_bcnt;
reg [3:0] r_ccnt;
wire [R-2:0] w_a0;
wire [R-2:0] w_a1;


ADDRgen_element #(.i(0), .R(5)) ADDRgen_element_a0(
.i_b1(r_bcnt[0]),
.i_b0(1'b0),
.i_c(r_ccnt),
.i_s(^r_bcnt),
.o_a0(w_a0[0]),
.o_a1(w_a1[0]) 
);
ADDRgen_element #(.i(1), .R(5)) ADDRgen_element_a1(
.i_b1(r_bcnt[1]),
.i_b0(r_bcnt[0]),
.i_c(r_ccnt),
.i_s(^r_bcnt),
.o_a0(w_a0[1]),
.o_a1(w_a1[1]) 
);
ADDRgen_element #(.i(2), .R(5)) ADDRgen_element_a2(
.i_b1(r_bcnt[2]),
.i_b0(r_bcnt[1]),
.i_c(r_ccnt),
.i_s(^r_bcnt),
.o_a0(w_a0[2]),
.o_a1(w_a1[2]) 
);
ADDRgen_element #(.i(3), .R(5)) ADDRgen_element_a3(
.i_b1(r_bcnt[3]),
.i_b0(r_bcnt[2]),
.i_c(r_ccnt),
.i_s(^r_bcnt),
.o_a0(w_a0[3]),
.o_a1(w_a1[3]) 
);

always @(posedge i_clk) begin
    if(i_rst) begin
        o_a0 <= 0;
        o_a1 <= 0;
        r_ps <= s_0;
        r_bcnt <= 0;
        r_ccnt <= 0;
        o_sel_wing <= 0;
    end
    else begin
        case (r_ps)
            s_0 : 
            begin
                if(i_en) r_ps <= s_1;
                else r_ps <= s_0;
            end
            s_1 :
            begin
                r_ps <= s_2;
                o_a0 <= w_a1;
                o_a1 <= w_a0;
                o_sel_wing <= ^r_bcnt;
                if(r_bcnt == N/2-1) begin
                    if(r_ccnt == R-1) begin
                        r_bcnt <= 0;
                        r_ccnt <= 0;
                    end
                    else begin
                        r_bcnt <= 0;
                        r_ccnt <= r_ccnt + 1;
                    end
                end
                else r_bcnt <= r_bcnt + 1;
            end
            s_2 :
            begin
                r_ps <= s_0;
            end
        endcase
    end
end
endmodule

module ADDRgen_element #(
    parameter i = 0,
    parameter R = 5
) (
    input i_b1,   
    input i_b0,   
    input [3:0] i_c,
    input i_s,    
    output o_a0,  
    output o_a1   
);

wire w_wsel;
wire w_bsel;
wire w_b;
wire w_w1, w_w0;

assign w_wsel = (i_c == R-1-i) ? 1 : 0;     
assign w_bsel = (i_c < R-1-i) ? 1 : 0;      

barrel_shifter u_barrel_shifter(
    .s(i_s),
    .w1(w_w1),
    .w0(w_w0)
);
bwMUX bMUX(
    .in1(i_b1),
    .in2(i_b0),
    .sel(w_bsel),
    .out(w_b)
);
bwMUX wMUX0(
    .in1(w_w0),
    .in2(w_b),
    .sel(w_wsel),
    .out(o_a0)
);
bwMUX wMUX1(
    .in1(w_w1),
    .in2(w_b),
    .sel(w_wsel),
    .out(o_a1)
);
endmodule

module barrel_shifter (
    input s,
    output w1, w0
);
    assign  w1 = s ? 1'b1 : 1'b0;
    assign  w0 = s ? 1'b0 : 1'b1;
endmodule

module bwMUX
(
    input in1,
    input in2,  
    input sel,
    output out
);
assign out = sel ? in1 : in2;
endmodule

module uart_rx
#(
    parameter RTX_EXTERNAL_OVERRIDE = "NO"
)
(
	input clk_i, rst_i,

	input rx_i,
	output reg rx_done_tick_o,
	output reg [7:0] dout_bo,

	output reg locked_o,
	output reg [28:0] bitperiod_o
);

localparam ST_NOSYNC 			= 4'h0;
localparam ST_NOSYNC_WAIT1_1 	= 4'h1;
localparam ST_NOSYNC_WAIT0_2 	= 4'h2;
localparam ST_NOSYNC_WAIT1_3 	= 4'h3;
localparam ST_NOSYNC_WAIT0_4 	= 4'h4;
localparam ST_NOSYNC_WAIT1_5 	= 4'h5;
localparam ST_NOSYNC_WAIT0_6 	= 4'h6;
localparam ST_NOSYNC_WAIT1_7 	= 4'h7;
localparam ST_NOSYNC_WAIT0_8 	= 4'h8;
localparam ST_NOSYNC_WAIT_STOP 	= 4'h9;
localparam ST_SYNC 				= 4'hA;
localparam ST_SYNC_WAIT_START 	= 4'hB;
localparam ST_SYNC_RX_DATA 		= 4'hC;
localparam ST_SYNC_WAIT_STOP 	= 4'hD;

reg [4:0] 	state;
reg [31:0] 	clk_counter;
reg [2:0]	bit_counter;

reg rx_buf;
always @(posedge clk_i)
	begin
	if (rst_i) rx_buf <= 1'b1;
	else rx_buf <= rx_i;
	end

always @(posedge clk_i)
	begin
	if (rst_i)
		begin
		state <= ST_NOSYNC;
		clk_counter <= 32'h0;
		bit_counter <= 3'h0;
		locked_o <= 1'b0;
		bitperiod_o <= 32'h0;
		rx_done_tick_o <= 1'b0;
		dout_bo <= 8'h0;
		end
	else 
		begin

		if (RTX_EXTERNAL_OVERRIDE == "NO") rx_done_tick_o <= 1'b0;

		case (state)

			ST_NOSYNC:
				begin
				if (rx_buf == 1'b0) state <= ST_NOSYNC_WAIT1_1;
				end

			ST_NOSYNC_WAIT1_1:
				begin
				if (rx_buf == 1'b1) state <= ST_NOSYNC_WAIT0_2;
				end

			ST_NOSYNC_WAIT0_2:
				begin
				if (rx_buf == 1'b0) state <= ST_NOSYNC_WAIT1_3;
				clk_counter <= clk_counter + 32'h1;
				end

			ST_NOSYNC_WAIT1_3:
				begin
				if (rx_buf == 1'b1) state <= ST_NOSYNC_WAIT0_4;
				clk_counter <= clk_counter + 32'h1;
				end

			ST_NOSYNC_WAIT0_4:
				begin
				if (rx_buf == 1'b0) state <= ST_NOSYNC_WAIT1_5;
				clk_counter <= clk_counter + 32'h1;
				end

			ST_NOSYNC_WAIT1_5:
				begin
				if (rx_buf == 1'b1) state <= ST_NOSYNC_WAIT0_6;
				clk_counter <= clk_counter + 32'h1;
				end

			ST_NOSYNC_WAIT0_6:
				begin
				if (rx_buf == 1'b0) state <= ST_NOSYNC_WAIT1_7;
				clk_counter <= clk_counter + 32'h1;
				end

			ST_NOSYNC_WAIT1_7:
				begin
				if (rx_buf == 1'b1) state <= ST_NOSYNC_WAIT0_8;
				clk_counter <= clk_counter + 32'h1;
				end

			ST_NOSYNC_WAIT0_8:
				begin
				if (rx_buf == 1'b0) state <= ST_NOSYNC_WAIT_STOP;
				clk_counter <= clk_counter + 32'h1;
				end

			ST_NOSYNC_WAIT_STOP:
				begin
				if (rx_buf == 1'b1)
					begin
					state <= ST_SYNC;
					locked_o <= 1'b1;
					bitperiod_o <= clk_counter[31:3];		
					dout_bo <= 32'h55;
					rx_done_tick_o <= 1'b1;
					end
				clk_counter <= clk_counter + 32'h1;
				end

			ST_SYNC:
				begin
				if (rx_buf == 1'b0)
					begin
					state <= ST_SYNC_WAIT_START;
					clk_counter <= 32'h0;
					end
				end

			ST_SYNC_WAIT_START:
				begin
				clk_counter <= clk_counter + 32'h1;
				if (clk_counter == {4'h0, bitperiod_o[28:1]})
					begin
					state <= ST_SYNC_RX_DATA;
					clk_counter <= 32'h0;
					bit_counter <= 3'h0;
					end
				end

			ST_SYNC_RX_DATA:
				begin
				clk_counter <= clk_counter + 32'h1;
				if (clk_counter == {3'h0, bitperiod_o})
					begin
					dout_bo <= {rx_buf, dout_bo[7:1]};
					clk_counter <= 32'h0;
					bit_counter <= bit_counter + 3'h1;
					if (bit_counter == 3'h7)
						begin
						rx_done_tick_o <= 1'b1;
						state <= ST_SYNC_WAIT_STOP;
						end
					end
				end

			ST_SYNC_WAIT_STOP:
				begin
				if (rx_buf == 1'b1) state <= ST_SYNC;
				end

		endcase

		end
	end

endmodule

module Extensor(Controle, ConstanteIn, ConstanteOut);

	input Controle; 
	input [15:0] ConstanteIn;
	output reg [31:0] ConstanteOut; 


	always @(Controle or ConstanteIn)	begin	
		case(Controle)
			1'b0: begin  							
				ConstanteOut[31:16] =  {16{ConstanteIn[15]}};
				ConstanteOut[15:0] = ConstanteIn[15:0];
			end

			1'b1: begin 							
				ConstanteOut[31:12] =  {20{ConstanteIn[11]}};
				ConstanteOut[11:0] = ConstanteIn[11:0];
			end 

		endcase
	end
endmodule

module half_addr(X,Y,S,C);
   input X,Y;
   output S,C;

   wire S;
   wire C;

   assign S=X^Y;
   assign C=X&Y;
endmodule

module full_addr(a,b,sum,cin,carry);
  input[1:0] a,b;
  input cin;
  output [1:0] sum;
  output carry;

  wire c0,c1,c2,c3,c4;
  wire s0,s1;

  half_addr H1 (a[0],b[0],s0,c0);
  half_addr H2 (s0,cin,sum[0],c1);           
  or G1 (c2,c1,c0);
  half_addr H3 (a[1],b[1],s1,c3);   
  half_addr H4 (s1,c2,sum[1],c4);            
  or G2 (carry,c3,c4);
endmodule

module qspi_driver(
	output                  O_qspi_clk          , 
	output reg              O_qspi_cs           , 
	inout                   IO_qspi_io0         , 
	inout                   IO_qspi_io1         , 
	inout                   IO_qspi_io2         , 
	inout                   IO_qspi_io3         , 

	input                   I_rst_n             , 

	input                   I_clk_25M           , 
	input       [4:0]       I_cmd_type          , 
	input       [7:0]       I_cmd_code          , 
	input       [23:0]      I_qspi_addr         , 
	input       [15:0]      I_status_reg        , 
	input       [7:0]       I_test_vec          , 

	output reg              O_done_sig          , 
	output reg  [7:0]       O_read_data         , 
	output reg              O_read_byte_valid   , 
	output reg  [3:0]       O_qspi_state          
);


parameter   C_IDLE            =   4'b0000  ; 
parameter   C_SEND_CMD        =   4'b0001  ; 
parameter   C_SEND_ADDR       =   4'b0010  ; 
parameter   C_READ_WAIT       =   4'b0011  ; 
parameter   C_WRITE_DATA      =   4'b0100  ; 
parameter   C_WRITE_STATE_REG =   4'b0101  ; 
parameter   C_WRITE_DATA_QUAD =   4'b0110  ; 
parameter   C_DUMMY           =   4'b0111  ; 
parameter   C_READ_WAIT_QUAD  =   4'b1000  ; 
parameter   C_FINISH_DONE     =   4'b1001  ; 



reg         R_qspi_io0          ;
reg         R_qspi_io1          ;
reg         R_qspi_io2          ;
reg         R_qspi_io3          ;          
reg         R_qspi_io0_out_en   ;
reg         R_qspi_io1_out_en   ;
reg         R_qspi_io2_out_en   ;
reg         R_qspi_io3_out_en   ;

reg         [7:0]   R_read_data_reg     ; 
reg                 R_qspi_clk_en       ; 
reg                 R_data_come_single  ; 
reg                 R_data_come_quad    ; 

reg         [7:0]   R_cmd_reg           ; 
reg         [23:0]  R_address_reg       ; 
reg         [15:0]  R_status_reg        ; 

reg         [7:0]   R_write_bits_cnt    ; 
reg         [8:0]   R_write_bytes_cnt   ; 
reg         [7:0]   R_read_bits_cnt     ; 
reg         [8:0]   R_read_bytes_cnt    ; 
reg         [8:0]   R_read_bytes_num    ; 
reg                 R_read_finish       ; 




assign O_qspi_clk = R_qspi_clk_en ? I_clk_25M : 0   ; 



assign IO_qspi_io0     =   R_qspi_io0_out_en ? R_qspi_io0 : 1'bz ;                
assign IO_qspi_io1     =   R_qspi_io1_out_en ? R_qspi_io1 : 1'bz ;                
assign IO_qspi_io2     =   R_qspi_io2_out_en ? R_qspi_io2 : 1'bz ;                
assign IO_qspi_io3     =   R_qspi_io3_out_en ? R_qspi_io3 : 1'bz ; 



always @(negedge I_clk_25M or negedge I_rst_n)
begin
    if(!I_rst_n)
        begin
            O_qspi_cs           <=  1'b1   ;        
            O_qspi_state        <=  C_IDLE ;
            R_cmd_reg           <=  0      ;
            R_address_reg       <=  0      ;
            R_qspi_clk_en       <=  1'b0   ;  
            R_write_bits_cnt    <=  0      ;
            R_write_bytes_cnt   <=  0      ;
            R_read_bytes_num    <=  0      ;    
            R_address_reg       <=  0      ;
            O_done_sig          <=  1'b0   ;
            R_data_come_single  <=  1'b0   ;           
            R_data_come_quad      <=  1'b0   ;           
        end
    else
        begin
            case(O_qspi_state)
                C_IDLE:  
                    begin                              
                        R_qspi_clk_en          <=   1'b0         ;
                        O_qspi_cs              <=   1'b1         ;
                        R_qspi_io0             <=   1'b0         ;    
                        R_cmd_reg              <=   I_cmd_code   ;
                        R_address_reg          <=   I_qspi_addr  ;
                        R_status_reg           <=   I_status_reg ;
                        O_done_sig             <=   1'b0         ;
                        R_qspi_io3_out_en   <=   1'b0         ; 
                        R_qspi_io2_out_en   <=   1'b0         ; 
                        R_qspi_io1_out_en   <=   1'b0         ; 
                        R_qspi_io0_out_en   <=   1'b0         ; 
                        if(I_cmd_type[4] == 1'b1) 
                            begin                
                                O_qspi_state        <=  C_SEND_CMD  ;
                                R_write_bits_cnt    <=  7           ;        
                                R_write_bytes_cnt   <=  0           ;
                                R_read_bytes_num    <=  0           ;                    
                            end
                    end
                C_SEND_CMD: 
                    begin
                        R_qspi_io0_out_en   <=  1'b1    ; 
                        R_qspi_clk_en       <=  1'b1    ; 
                        O_qspi_cs           <=  1'b0    ; 
                        if(R_write_bits_cnt > 0) 
                            begin                           
                                R_qspi_io0            <=  R_cmd_reg[R_write_bits_cnt] ;         
                                R_write_bits_cnt       <=  R_write_bits_cnt-1'b1       ;
                            end                            
                        else 
                            begin                                 
                                R_qspi_io0 <=  R_cmd_reg[0]    ;
                                if ((I_cmd_type[3:0] == 4'b0001) | (I_cmd_type[3:0] == 4'b0100)) 
                                    begin    
                                        O_qspi_state    <=  C_FINISH_DONE   ;
                                    end
								else if (I_cmd_type[3:0] == 4'b0000) 
                                    begin    
                                        O_qspi_state        <=  C_READ_WAIT ;
                                        R_write_bits_cnt    <=  7           ;
                                        R_read_bytes_num    <=  21          ;
									end	
                                else if (I_cmd_type[3:0] == 4'b0011) 
                                    begin    
                                        O_qspi_state        <=  C_READ_WAIT ;
                                        R_write_bits_cnt    <=  7           ;
                                        R_read_bytes_num    <=  1           ;
                                    end
								else if (I_cmd_type[3:0] == 4'b1010) 
                                    begin    
                                        O_qspi_state        <=  C_READ_WAIT ;
                                        R_write_bits_cnt    <=  7           ;
                                        R_read_bytes_num    <=  2           ;
                                    end		
                                else if( (I_cmd_type[3:0] == 4'b0010) ||  
                                         (I_cmd_type[3:0] == 4'b0101) ||  
                                         (I_cmd_type[3:0] == 4'b0111) ||  
                                         (I_cmd_type[3:0] == 4'b1000) ||  
                                         (I_cmd_type[3:0] == 4'b1001)     
                                        ) 
                                    begin                          
                                        O_qspi_state        <=  C_SEND_ADDR ;
                                        R_write_bits_cnt    <=  23          ; 
                                    end
                                else if (I_cmd_type[3:0] == 4'b0110) 
                                    begin    
                                        O_qspi_state        <=  C_WRITE_STATE_REG   ;
                                        R_write_bits_cnt    <=  15                  ;
                                    end 
                            end
                    end
                C_WRITE_STATE_REG   :
                    begin
                        R_qspi_io0_out_en   <=  1'b1    ;   
                        if(R_write_bits_cnt > 0)  
                            begin                           
                                R_qspi_io0         <=  R_status_reg[R_write_bits_cnt] ;   
                                R_write_bits_cnt   <=  R_write_bits_cnt    -   1      ;    
                            end                                 
                        else 
                            begin                                        
                                R_qspi_io0      <=  R_status_reg[0]    ;   
                                O_qspi_state    <=  C_FINISH_DONE      ;                                          
                            end                            
                    end 
                C_SEND_ADDR: 
                    begin
                        R_qspi_io0_out_en   <=  1'b1    ;
                        if(R_write_bits_cnt > 0)  
                            begin                                 
                                R_qspi_io0            <=  R_address_reg[R_write_bits_cnt] ; 
                                R_write_bits_cnt       <=  R_write_bits_cnt    -   1       ;    
                            end                                 
                        else 
                            begin 
                                R_qspi_io0 <=  R_address_reg[0]    ;   
                                if(I_cmd_type[3:0] == 4'b0010) 
                                    begin  
                                        O_qspi_state <= C_FINISH_DONE   ;    
                                    end
                                else if (I_cmd_type[3:0] == 4'b0101) 
                                    begin                              
                                        O_qspi_state        <=  C_WRITE_DATA    ;
                                        R_write_bits_cnt    <=  7               ;                       
                                    end                                                        
                                else if (I_cmd_type[3:0] == 4'b0111) 
                                    begin
                                        O_qspi_state        <=  C_READ_WAIT     ;
                                        R_read_bytes_num    <=  256             ;   
                                    end 
                                else if (I_cmd_type[3:0] == 4'b1000) 
                                    begin   
                                        O_qspi_state        <=  C_WRITE_DATA_QUAD   ;
                                        R_write_bits_cnt    <=  7                   ;                       
                                    end 
                                else if (I_cmd_type[3:0] == 4'b1001) 
                                    begin   
                                        O_qspi_state        <=  C_DUMMY         ;
                                        R_read_bytes_num    <=  256             ; 
                                        R_write_bits_cnt    <=  9               ; 
                                    end 
                            end
                    end 
                C_DUMMY:  
                    begin  
                        R_qspi_io3_out_en   <=  1'b0            ; 
                        R_qspi_io2_out_en   <=  1'b0            ; 
                        R_qspi_io1_out_en   <=  1'b0            ; 
                        R_qspi_io0_out_en   <=  1'b0            ; 
                        if(R_write_bits_cnt > 0)    
                            R_write_bits_cnt    <=  R_write_bits_cnt - 1 ;                                    
                        else 
                            O_qspi_state        <=  C_READ_WAIT_QUAD     ;                                          
                    end   
                C_READ_WAIT: 
                    begin
                        if(R_read_finish)  
                            begin
                                O_qspi_state        <=  C_FINISH_DONE   ;
                                R_data_come_single  <=  1'b0            ;
                            end
                        else
                            begin
                                R_data_come_single  <=  1'b1            ; 
                                R_qspi_io1_out_en   <=  1'b0            ;
                            end
                    end
                C_READ_WAIT_QUAD: 
                    begin
                        if(R_read_finish)  
                            begin
                                O_qspi_state        <=  C_FINISH_DONE   ;
                                R_data_come_quad    <=  1'b0            ;
                            end
                        else
                            R_data_come_quad        <=  1'b1            ;
                    end
                C_WRITE_DATA: 
                    begin
                        if(R_write_bytes_cnt < 1) 
                            begin                       
                                if(R_write_bits_cnt > 0) 
                                    begin                           
                                        R_qspi_io0             <=  I_test_vec[R_write_bits_cnt] ; 
                                        R_write_bits_cnt    <=  R_write_bits_cnt  - 1'b1    ;                        
                                    end                 
                                else 
                                    begin                                 
                                        R_qspi_io0             <=  I_test_vec[0]                ; 
                                        R_write_bits_cnt    <=  7                           ;
                                        R_write_bytes_cnt   <=  R_write_bytes_cnt + 1'b1    ;
                                    end
                            end
                        else 
                            begin
                                O_qspi_state    <=  C_FINISH_DONE   ;
                                R_qspi_clk_en   <=  1'b0            ;
                            end
                    end
                C_WRITE_DATA_QUAD    :
                    begin
                        R_qspi_io0_out_en   <=  1'b1    ;   
                        R_qspi_io1_out_en   <=  1'b1    ;   
                        R_qspi_io2_out_en   <=  1'b1    ;   
                        R_qspi_io3_out_en   <=  1'b1    ;   
                        if(R_write_bytes_cnt == 9'd256)
                            begin
                                O_qspi_state   <=  C_FINISH_DONE    ;    
                                R_qspi_clk_en  <=  1'b0             ; 
                            end 
                        else
                            begin      
                                if(R_write_bits_cnt == 8'd3)
                                    begin
                                        R_write_bytes_cnt   <=  R_write_bytes_cnt + 1'b1         ;
                                        R_write_bits_cnt    <=  8'd7                             ;
                                        R_qspi_io3          <=  I_test_vec[3]                     ; 
                                        R_qspi_io2          <=  I_test_vec[2]                     ; 
                                        R_qspi_io1          <=  I_test_vec[1]                     ; 
                                        R_qspi_io0          <=  I_test_vec[0]                     ; 
                                    end
                                else
                                    begin
                                        R_write_bits_cnt    <=  R_write_bits_cnt - 4            ;
                                        R_qspi_io3          <=  I_test_vec[R_write_bits_cnt - 0] ; 
                                        R_qspi_io2          <=  I_test_vec[R_write_bits_cnt - 1] ; 
                                        R_qspi_io1          <=  I_test_vec[R_write_bits_cnt - 2] ; 
                                        R_qspi_io0          <=  I_test_vec[R_write_bits_cnt - 3] ; 
                                    end 
                            end                                            
                    end 
                C_FINISH_DONE:
                    begin
                        O_qspi_cs           <=  1'b1    ;
                        R_qspi_io0          <=  1'b0    ;
                        R_qspi_clk_en       <=  1'b0    ;
                        O_done_sig          <=  1'b1    ;
                        R_qspi_io3_out_en   <=  1'b0    ; 
                        R_qspi_io2_out_en   <=  1'b0    ; 
                        R_qspi_io1_out_en   <=  1'b0    ; 
                        R_qspi_io0_out_en   <=  1'b0    ; 
                        R_data_come_single  <=  1'b0    ;
                        R_data_come_quad    <=  1'b0    ;
                        O_qspi_state        <=  C_IDLE  ;
                    end
                default:O_qspi_state    <=  C_IDLE      ;
            endcase         
        end
end




always @(posedge I_clk_25M)
begin
    if(!I_rst_n)
        begin
            R_read_bytes_cnt    <=  0       ;
            R_read_bits_cnt     <=  0       ;
            R_read_finish       <=  1'b0    ;
            O_read_byte_valid   <=  1'b0    ;
            R_read_data_reg     <=  0       ;
            O_read_data         <=  0       ;
        end
    else if(R_data_come_single)   
        begin
            if(R_read_bytes_cnt < R_read_bytes_num) 
                begin            
                    if(R_read_bits_cnt < 7)  
                        begin                         
                            O_read_byte_valid   <=  1'b0                               ;
                            R_read_data_reg     <=  {R_read_data_reg[6:0],IO_qspi_io1} ;
                            R_read_bits_cnt     <=  R_read_bits_cnt +   1'b1           ;
                        end
                    else  
                        begin
                            O_read_byte_valid   <=  1'b1                               ;  
                            O_read_data         <=  {R_read_data_reg[6:0],IO_qspi_io1} ;  
                            R_read_bits_cnt     <=  0                                  ;
                            R_read_bytes_cnt    <=  R_read_bytes_cnt    +   1'b1       ;
                        end
                end                               
            else 
                begin 
                    R_read_bytes_cnt    <=  0       ;
                    R_read_finish       <=  1'b1    ;
                    O_read_byte_valid   <=  1'b0    ;
                end
        end 
    else if(R_data_come_quad)   
        begin
            if(R_read_bytes_cnt < R_read_bytes_num) 
                begin  
                    if(R_read_bits_cnt < 8'd1)
                        begin
                            O_read_byte_valid       <=  1'b0                    ;
                            R_read_data_reg         <=  {R_read_data_reg[3:0],IO_qspi_io3,IO_qspi_io2,IO_qspi_io1,IO_qspi_io0};
                            R_read_bits_cnt         <=  R_read_bits_cnt + 1     ; 
                        end
                    else    
                        begin
                            O_read_byte_valid       <=  1'b1                    ;
                            O_read_data             <=  {R_read_data_reg[3:0],IO_qspi_io3,IO_qspi_io2,IO_qspi_io1,IO_qspi_io0};  
                            R_read_bits_cnt         <=  0                       ;
                            R_read_bytes_cnt        <=  R_read_bytes_cnt + 1'b1 ;     
                        end
                end                               
            else 
                begin 
                    R_read_bytes_cnt    <=  0       ;
                    R_read_finish       <=  1'b1    ;
                    O_read_byte_valid   <=  1'b0    ;
                end
        end
    else 
        begin
            R_read_bytes_cnt    <=  0       ;
            R_read_bits_cnt     <=  0       ;
            R_read_finish       <=  1'b0    ;
            O_read_byte_valid   <=  1'b0    ;
            R_read_data_reg     <=  0       ;
        end
end         


endmodule

module arp_rx
  #(

    parameter BOARD_MAC = 48'h00_11_22_33_44_55,  

    parameter BOARD_IP = {8'd192,8'd168,8'd1,8'd10}      
    )
   (
    input                clk        , 
    input                rst_n      , 

    input                gmii_rx_dv , 
    input        [7:0]   gmii_rxd   , 
    output  reg          arp_rx_done, 
    output  reg          arp_rx_type, 
    output  reg  [47:0]  src_mac    , 
    output  reg  [31:0]  src_ip       
    );


localparam  st_idle     = 5'b0_0001; 
localparam  st_preamble = 5'b0_0010; 
localparam  st_eth_head = 5'b0_0100; 
localparam  st_arp_data = 5'b0_1000; 
localparam  st_rx_end   = 5'b1_0000; 

localparam  ETH_TPYE = 16'h0806;     


reg    [4:0]   cur_state ;
reg    [4:0]   next_state;

reg            skip_en   ; 
reg            error_en  ; 
reg    [4:0]   cnt       ; 
reg    [47:0]  des_mac_t ; 
reg    [31:0]  des_ip_t  ; 
reg    [47:0]  src_mac_t ; 
reg    [31:0]  src_ip_t  ; 
reg    [15:0]  eth_type  ; 
reg    [15:0]  op_data   ; 






always @(posedge clk or negedge rst_n) begin
    if(!rst_n)
        cur_state <= st_idle;  
    else
        cur_state <= next_state;
end


always @(*) begin
    next_state = st_idle;
    case(cur_state)
        st_idle : begin                     
            if(skip_en) 
                next_state = st_preamble;
            else
                next_state = st_idle;    
        end
        st_preamble : begin                 
            if(skip_en) 
                next_state = st_eth_head;
            else if(error_en) 
                next_state = st_rx_end;    
            else
                next_state = st_preamble;   
        end
        st_eth_head : begin                 
            if(skip_en) 
                next_state = st_arp_data;
            else if(error_en) 
                next_state = st_rx_end;
            else
                next_state = st_eth_head;   
        end  
        st_arp_data : begin                  
            if(skip_en)
                next_state = st_rx_end;
            else if(error_en)
                next_state = st_rx_end;
            else
                next_state = st_arp_data;   
        end                  
        st_rx_end : begin                   
            if(skip_en)
                next_state = st_idle;
            else
                next_state = st_rx_end;          
        end
        default : next_state = st_idle;
    endcase                                          
end    


always @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        skip_en <= 1'b0;
        error_en <= 1'b0;
        cnt <= 5'd0;
        des_mac_t <= 48'd0;
        des_ip_t <= 32'd0;
        src_mac_t <= 48'd0;
        src_ip_t <= 32'd0;        
        eth_type <= 16'd0;
        op_data <= 16'd0;
        arp_rx_done <= 1'b0;
        arp_rx_type <= 1'b0;
        src_mac <= 48'd0;
        src_ip <= 32'd0;
    end
    else begin
        skip_en <= 1'b0;
        error_en <= 1'b0;  
        arp_rx_done <= 1'b0;
        case(next_state)
            st_idle : begin                                  
                if((gmii_rx_dv == 1'b1) && (gmii_rxd == 8'h55)) 
                    skip_en <= 1'b1;
            end
            st_preamble : begin
                if(gmii_rx_dv) begin                         
                    cnt <= cnt + 5'd1;
                    if((cnt < 5'd6) && (gmii_rxd != 8'h55))  
                        error_en <= 1'b1;
                    else if(cnt==5'd6) begin
                        cnt <= 5'd0;
                        if(gmii_rxd==8'hd5)                  
                            skip_en <= 1'b1;
                        else
                            error_en <= 1'b1;    
                    end  
                end  
            end
            st_eth_head : begin
                if(gmii_rx_dv) begin
                    cnt <= cnt + 5'b1;
                    if(cnt < 5'd6) 
                        des_mac_t <= {des_mac_t[39:0],gmii_rxd};
                    else if(cnt == 5'd6) begin

                        if((des_mac_t != BOARD_MAC)
                            && (des_mac_t != 48'hff_ff_ff_ff_ff_ff))           
                            error_en <= 1'b1;
                    end
                    else if(cnt == 5'd12) 
                        eth_type[15:8] <= gmii_rxd;          
                    else if(cnt == 5'd13) begin
                        eth_type[7:0] <= gmii_rxd;
                        cnt <= 5'd0;
                        if(eth_type[15:8] == ETH_TPYE[15:8]  
                            && gmii_rxd == ETH_TPYE[7:0])
                            skip_en <= 1'b1; 
                        else
                            error_en <= 1'b1;                       
                    end        
                end  
            end
            st_arp_data : begin
                if(gmii_rx_dv) begin
                    cnt <= cnt + 5'd1;
                    if(cnt == 5'd6) 
                        op_data[15:8] <= gmii_rxd;           
                    else if(cnt == 5'd7)
                        op_data[7:0] <= gmii_rxd;
                    else if(cnt >= 5'd8 && cnt < 5'd14)      
                        src_mac_t <= {src_mac_t[39:0],gmii_rxd};
                    else if(cnt >= 5'd14 && cnt < 5'd18)     
                        src_ip_t<= {src_ip_t[23:0],gmii_rxd};
                    else if(cnt >= 5'd24 && cnt < 5'd28)     
                        des_ip_t <= {des_ip_t[23:0],gmii_rxd};
                    else if(cnt == 5'd28) begin
                        cnt <= 5'd0;
                        if(des_ip_t == BOARD_IP) begin       
                            if((op_data == 16'd1) || (op_data == 16'd2)) begin
                                skip_en <= 1'b1;
                                arp_rx_done <= 1'b1;
                                src_mac <= src_mac_t;
                                src_ip <= src_ip_t;
                                src_mac_t <= 48'd0;
                                src_ip_t <= 32'd0;
                                des_mac_t <= 48'd0;
                                des_ip_t <= 32'd0;
                                if(op_data == 16'd1)         
                                    arp_rx_type <= 1'b0;     
                                else
                                    arp_rx_type <= 1'b1;     
                            end
                            else
                                error_en <= 1'b1;
                        end 
                        else
                            error_en <= 1'b1;
                    end
                end                                
            end
            st_rx_end : begin     
                cnt <= 5'd0;

                if(gmii_rx_dv == 1'b0 && skip_en == 1'b0)
                    skip_en <= 1'b1; 
            end    
            default : ;
        endcase                                                        
    end
end

endmodule

module spi(
div_clk,
rst_n,
sclk,
spiste,
spisimo,
spisomi,
spi_done,
tx_data,
rx_data,
wr_en,
rd_en,
flag,
stage_rst
);
input flag;
input div_clk;
input rst_n;
input spisomi;
input wr_en;
input rd_en;
input stage_rst;
input [7:0]tx_data;
output reg spi_done;
output reg sclk;
output reg spisimo;
output reg spiste;
output reg [7:0] rx_data;
reg [3:0]spi_count;

always @(posedge div_clk or negedge rst_n)
	begin
	if(!rst_n)
		begin
		spi_count <= 4'b0;
		spi_done <= 1'b0;
		rx_data <= 8'b0;
		sclk <= 1'b0;
		spiste <= 1'b1;
		spisimo <= 1'b0;
		end
	else if (stage_rst)
		begin
		spi_count <= 4'b0;
		spi_done <= 1'b0;
		rx_data <= 8'b0;
		sclk <= 1'b0;
		spiste <= 1'b1;
		spisimo <= 1'b0;
		end
	else if (wr_en)
		begin
			spiste <= 1'b0;
			case(spi_count)
				4'd1,4'd3,4'd5,4'd7,
				4'd9,4'd11,4'd13:
					begin
						sclk <= 1'b1;
						spi_count <= spi_count + 1'b1;
						spi_done <= 1'b0;
					end
				4'd0:
					begin
						sclk <= 1'b0;
						spi_count <= spi_count +1'b1;
						spisimo <= tx_data[7];
						spi_done <= 1'b0;
					end
				4'd2:
					begin
						sclk <= 1'b0;
						spi_count <= spi_count +1'b1;
						spisimo <= tx_data[6];
						spi_done <= 1'b0;
					end
				4'd4:
					begin
						sclk <= 1'b0;
						spi_count <= spi_count +1'b1;
						spisimo <= tx_data[5];
						spi_done <= 1'b0;
					end
				4'd6:
					begin
						sclk <= 1'b0;
						spi_count <= spi_count +1'b1;
						spisimo <= tx_data[4];
						spi_done <= 1'b0;
					end
				4'd8:
					begin
						sclk <= 1'b0;
						spi_count <= spi_count +1'b1;
						spisimo <= tx_data[3];
						spi_done <= 1'b0;
					end
				4'd10:
					begin
						sclk <= 1'b0;
						spi_count <= spi_count +1'b1;
						spisimo <= tx_data[2];
						spi_done <= 1'b0;
					end
				4'd12:
					begin
						sclk <= 1'b0;
						spi_count <= spi_count +1'b1;
						spisimo <= tx_data[1];
						spi_done <= 1'b0;
					end
				4'd14:
					begin
						sclk <= 1'b0;
						spi_count <= spi_count +1'b1;
						spisimo <= tx_data[0];
						spi_done <= 1'b1;
					end
				4'd15:
					begin
						sclk <= 1'b1;
						spi_count <= spi_count +1'b1;
						spi_done <= 1'b0;
					end
			endcase
		end
	else if (rd_en)
		begin
		spiste <= 1'b0;
			case(spi_count)
				4'd0,4'd2,4'd4,4'd6,
				4'd8,4'd10,4'd12,4'd14:
					begin
						sclk <= 1'b0;
						spi_count <= spi_count + 1'b1;
						spi_done <= 1'b0;
					end
				4'd1:
					begin
						sclk <= 1'b1;
						spi_count <= spi_count +1'b1;
						rx_data[7] <= spisomi;
						spi_done <= 1'b0;
					end
				4'd3:
					begin
						sclk <= 1'b1;
						spi_count <= spi_count +1'b1;
						rx_data[6] <= spisomi;
						spi_done <= 1'b0;
					end
				4'd5:
					begin
						sclk <= 1'b1;
						spi_count <= spi_count +1'b1;
						rx_data[5] <= spisomi;
						spi_done <= 1'b0;
					end
				4'd7:
					begin
						sclk <= 1'b1;
						spi_count <= spi_count +1'b1;
						rx_data[4] <= spisomi;
						spi_done <= 1'b0;
					end
				4'd9:
					begin
						sclk <= 1'b1;
						spi_count <= spi_count +1'b1;
						rx_data[3] <= spisomi;
						spi_done <= 1'b0;
					end
				4'd11:
					begin
						sclk <= 1'b1;
						spi_count <= spi_count +1'b1;
						rx_data[2] <= spisomi;
						spi_done <= 1'b0;
					end
				4'd13:
					begin
						sclk <= 1'b1;
						spi_count <= spi_count +1'b1;
						rx_data[1] <= spisomi;
						spi_done <= 1'b0;
					end
				4'd15:
					begin
						sclk <= 1'b1;
						spi_count <= 4'b0;
						rx_data[0] <= spisomi;
						spi_done <= 1'b1;
					end
			endcase
		end				
	else if (flag)
		begin
			spi_count <= 4'b0;
			rx_data <= 8'b0;
			spi_done <= 1'b0;
			sclk <= 1'b0;
			spiste <= 1'b0;
			spisimo <= 1'b0;
		end
	else
		begin
		spi_count <= 4'b0;
			rx_data <= 8'b0;
			spi_done <= 1'b0;
			sclk <= 1'b0;
			spiste <= 1'b1;
			spisimo <= 1'b0;
		end	
	end	
endmodule

`timescale 1ns / 1ps



















module spi_tr8(	
						input clk,
						input reset,
						input dummy,
						input start_out,
						input rnw,
						input [12:0] div_rate,
						input [3:0] dummy_clks,
						input [1:0] mode,
						input [7:0] din, 
						output reg [7:0] dout, 
						output reg done,
						output reg done_for_wr,
						output [3:0] dq_t_delayed,


						output reg c, 
						output reg s, 
						output reg [3:0] dq_o, 
						output reg [3:0] dq_t, 
						input [3:0] dq_i); 



wire dq_0_cmb;
wire dq_1_cmb;
wire dq_2_cmb;
wire dq_3_cmb;
wire c_cmb;
wire [3:0] dq_o_cmb;
wire [3:0] dq_t_cmb;
wire [7:0] dload_out;

wire activate_c;
wire s_dly;
reg s_delayed;

reg [13:0] count_c;
reg [3:0] count_dummy;
reg [3:0] count_send;
reg [3:0] count_read;

reg [2:0] state;
reg [2:0] next;
reg [1:0] state_clk;
reg [1:0] next_clk;
reg [1:0] stare;
reg [1:0] urm;
reg [1:0] cstate;
reg [1:0] nstate;

reg [2:0] state_delayed;

reg [7:0] dreg_out;
reg [7:0] dload_in;

wire pos_c;
wire poss_c;

wire trigger_edge;
wire [1:0] a;
wire [1:0] b;

wire done_for_dout;
reg done_dly;
reg done_dly2;

reg [3:0] dq_t_delay;
reg [3:0] dq_t_delay2;

wire start;
reg start_mode2_div_rate2;
reg start_mode2_div_rate2_buf;
reg signal_start;




parameter idle				= 3'b000,
			 idle_wait		= 3'b001,
			 send_dummy		= 3'b011,
			 send_data		= 3'b010,
			 read_data		= 3'b110;


parameter idle_clk 		= 2'b00,
			 gen_clk  		= 2'b01;


parameter got 				= 2'b00,
			 buc     		= 2'b01,
			 sfarsit			= 2'b11;


parameter trig_start		= 2'b00,
			 trig_posedge	= 2'b01,
			 preend_event 	= 2'b11,
			 end_event 		= 2'b10;




assign dload_out = (mode == 2'b00) ? din : 
						 (mode == 2'b01) ? {din[7],din[5],din[3],din[1],din[6],din[4],din[2],din[0]} : 
						 (mode == 2'b10) ? {din[7],din[3],din[6],din[2],din[5],din[1],din[4],din[0]} : 1'b1; 

assign dq_0_cmb = (mode == 2'b00) ? dreg_out[7] : 
						(mode == 2'b01) ? dreg_out[3] : 
						(mode == 2'b10) ? dreg_out[1] : 1'b1; 

assign dq_1_cmb = (mode == 2'b00) ? 1'b1 : 
						(mode == 2'b01) ? dreg_out[7] : 
						(mode == 2'b10) ? dreg_out[3] : 1'b1; 

assign dq_2_cmb = (mode == 2'b00) ? 1'b1 : 
						(mode == 2'b01) ? 1'b1 : 
						(mode == 2'b10) ? dreg_out[5] : 1'b1; 

assign dq_3_cmb = (mode == 2'b00) ? 1'b1 : 
						(mode == 2'b01) ? 1'b1 : 
						(mode == 2'b10) ? dreg_out[7] : 1'b1; 





assign pos_c = (!s && (count_c == ((div_rate/2) - 1))) ? 1'b1 : 1'b0;





assign poss_c = (count_c == (div_rate - 1)) ? 1'b1 : 1'b0;





assign c_cmb = (s || !activate_c || reset) ? 1'b1 : 
               ((state != idle) && (count_c >= ((div_rate/2) - 1)) && 
					(count_c < (div_rate - 1))) ? 1'b1 : 1'b0;

always @(posedge clk)
begin
	c <= c_cmb;
end





assign dq_o_cmb = (state == send_dummy) ? 4'bzzzz : {dq_3_cmb,dq_2_cmb,dq_1_cmb,dq_0_cmb};

always @ (posedge clk)
begin
	if (poss_c)
		dq_o <= dq_o_cmb;
end





assign dq_t_cmb = (state == read_data) ? 4'b1111 : 4'b0000;

always @ (posedge clk)
begin
	if (poss_c)
		dq_t <= dq_t_cmb;
end





assign s_dly = (state == idle) ? 1'b1 : 1'b0;

always @ (posedge clk)
begin
	s <= s_dly;
end



assign a = (div_rate <= 13'd2) ? 2'b10 : 2'b01;
assign b = (div_rate <= 13'd4) ? 2'b10 : 2'b01;

assign trigger_edge = (div_rate == 13'd4) ? poss_c : pos_c;





always @ (posedge clk)
begin
	if (reset)
		state_clk <= idle_clk;
	else
		state_clk <= next_clk;
end





assign activate_c = (state_clk == gen_clk) ? 1'b1 : 1'b0;

always @ *
begin
	next_clk = state_clk;
	case (state_clk)
		idle_clk:if (pos_c)
						next_clk = gen_clk;
					else
						next_clk = idle_clk;
		gen_clk:	if (s)
						next_clk = idle_clk;
					else
						next_clk = gen_clk;
	endcase
end





always @ (posedge clk)
begin
	if (reset || s || (count_c == (div_rate - 1)))
		count_c <= 14'b00000000000000;
	else
		count_c <= count_c + 14'b00000000000001;
end





always @ (posedge clk)
begin
	if (reset)
		state <= idle;
	else
		state <= next;
end





always @ *
begin
	next = state;
	case (state)
		idle:			begin
							if (start_out && dummy)
								next = send_dummy;
							else if (start_out && rnw)
								next = read_data;
							else if (start_out && !rnw)
								next = send_data;
							else
								next = idle;
						end

		idle_wait:  begin
							if (poss_c)
								next = idle;
							else
								next = idle_wait;
						end

		send_dummy:	begin
							if (!start_out && done_dly)
								next = idle_wait;
							else if (start_out && rnw)
								next = read_data;
							else if (start_out && !rnw)
								next = send_data;
							else
								next = send_dummy;
						end

		send_data:	begin
							if (start_out && dummy)
								next = send_dummy;
							else if (start_out && rnw)
								next = read_data;
							else if (!start_out && done_dly)
								next = idle_wait;
							else
								next = send_data;
						end

		read_data:	begin
							if (start && dummy)
								next = send_dummy;
							else if (start && !rnw)
								next = send_data;
							else if (!start && done_dly)
								next = idle_wait;
							else
								next = read_data;
						end
	endcase
end





always @ (posedge clk)
begin
	if ((state == read_data) && pos_c && dq_t)
		case (mode)
			2'b00:	dload_in <= {dload_in[6:0],dq_i[1]}; 
			2'b01:	dload_in <= {dload_in[6:4],dq_i[1],dload_in[2:0],dq_i[0]}; 
			2'b10:	dload_in <= {dload_in[6],dq_i[3],dload_in[4],dq_i[2],dload_in[2],dq_i[1],
								 dload_in[0],dq_i[0]}; 
		endcase
end





always @ (posedge clk)
begin
	if (reset || (count_dummy == dummy_clks + 1))
		count_dummy <= 4'b0000;
	else if ((state == send_dummy) && pos_c)
		count_dummy <= count_dummy + 4'b0001;
end





always @ (posedge clk)
begin
	if (start)
		case (mode)
			2'b00: count_send <= 4'b1000;
			2'b01: count_send <= 4'b0100;
			2'b10: count_send <= 4'b0010;
		endcase
	else if (reset)
		count_send <= 4'b0000;
	else if ((state == send_data) && pos_c)
		count_send <= count_send - 4'b0001;
end





always @ (posedge clk)
begin
	if (start)
		dreg_out <= dload_out;
	else if ((state == send_data) && pos_c)
		dreg_out <= dreg_out << 1;
end





always @ (posedge clk)
begin
	if (start)
		case (mode)
			2'b00: count_read <= 4'b1000;
			2'b01: count_read <= 4'b0100;
			2'b10: count_read <= 4'b0010;
		endcase
	else if ((state == read_data) && pos_c && dq_t)
		count_read <= count_read - 4'b0001;
	else if (reset)
		count_read <= 4'b0000;
end





always @ (posedge clk)
begin
	if (done_for_dout && (state_delayed == read_data))
		case (mode)
			2'b00: dout <= dload_in; 
			2'b01: dout <= {dload_in[7], dload_in[3], dload_in[6], dload_in[2], dload_in[5], 
								 dload_in[1], dload_in[4], dload_in[0]}; 
			2'b10: dout <= {dload_in[7], dload_in[5], dload_in[3], dload_in[1], dload_in[6], 
								 dload_in[4], dload_in[2], dload_in[0]}; 
		endcase	
end

assign done_for_dout = (div_rate <= 13'd2) ? done_dly2 : done_dly;





always @ (posedge clk)
begin
	if ((pos_c && (count_dummy == (dummy_clks - b)) && (state == send_dummy)) ||
		 (trigger_edge && (count_send == a) && (state == send_data)) ||
		 (pos_c && (count_read == a) && (state == read_data)))
		done <= 1'b1;
	else
		done <= 1'b0;
end





always @ (posedge clk)
begin
	if (pos_c)
		state_delayed <= state;
end





always @ (posedge clk)
begin
	done_dly <= done;
	done_dly2 <= done_dly;
end





assign dq_t_delayed = (div_rate <= 13'd2) ? dq_t_delay2 : dq_t_delay;

always @ (posedge clk)
begin
	if (poss_c)
		begin
			dq_t_delay <= dq_t;
			dq_t_delay2 <= dq_t_delay;
		end
end





always @ (posedge clk)
begin
	if (reset)
		begin
			stare <= got;
			cstate <= trig_start;
		end
	else
		begin
			stare <= urm;
			cstate <= nstate;
		end
end



always @ *
begin
	urm = stare;
	case (stare)
		got:	if (done)
					urm = buc;
				else
					urm = got;
		buc:	if (poss_c)
					urm = sfarsit;
				else
					urm = buc;
		sfarsit:	urm = got;
	endcase
end





always @ *
begin
	nstate = cstate;
	case (cstate)
		trig_start:	if (start_out && s)
							nstate = trig_posedge;
						else
							nstate = trig_start;
		trig_posedge:	if (pos_c)
								nstate = preend_event;
							else
								nstate = trig_posedge;
		preend_event:	nstate = trig_start;
	endcase
end





assign start = (s_delayed && (div_rate <= 13'd2) && ((mode == 2'b10) || (mode == 2'b01))) ? 
					 start_mode2_div_rate2 : (!s) ? (signal_start | start_out) : 1'b0;

always @ (posedge clk)
begin
	s_delayed <= s;
end



always @ (posedge clk)
begin
	start_mode2_div_rate2_buf <= start_out;
	start_mode2_div_rate2 <= start_mode2_div_rate2_buf;
end



always @ (posedge clk)
begin
	if (nstate == preend_event)
		signal_start <= 1'b1;
	else
		signal_start <= 1'b0;
end





always @ (posedge clk)
begin
	if (stare == sfarsit)
		done_for_wr <= 1'b1;
	else
		done_for_wr <= 1'b0;
end



endmodule

module top_module(sum,cout,result,a,b,cin);
parameter N = 16;
parameter Q =4;
input [N-1:0]a;
input [N-1:0]b;
input cin;
output [N-1:0]sum;
output cout;
output [N:0]result;

wire [N-1:0]p;
wire [N-1:0]g;
wire [N:0]g_0;

assign g_0[0] = cin;

genvar i;
    generate
        for(i=0;i<N;i=i+1)
            begin:generate_nbit_Bitwise
                Bitwise_PG b0(p[i],g[i],a[i],b[i]);
            end
    endgenerate

genvar j;
    generate
        for(j=0;j<N/2;j=j+Q)
            begin:carry_generator
                carry_gen c0(g_0[j+Q:j+1],p[j+Q-1:j],g[j+Q-1:j]);
            end
    endgenerate

genvar l;
    generate
        for(l=N/2;l<N;l=l+Q)
            begin:carry_accurate
                carry_accurate c1(g_0[l+Q:l+1],p[l+Q-1:l],g[l+Q-1:l],g_0[l]);
            end
    endgenerate

genvar k;
    generate
        for(k=0;k<N;k=k+Q)
            begin:sum_generaator
                sum_gen s0(sum[k+Q-1:k],p[k+Q-1:k],g[k+Q-1:k],g_0[k+Q-1:k]);
            end
   endgenerate

assign cout = g_0[N];
assign result = {cout,sum};
endmodule

module sum_gen(sum,p,g,g_0);
parameter Q = 4;
input [Q-1:0]p;
input [Q-1:0]g;
input [Q-1:0]g_0;
output [Q-1:0]sum;

genvar i;
    generate
        for(i=0;i<Q;i=i+1)
            begin:sum_gen
                assign sum[i]=p[i]^g_0[i];
            end
    endgenerate

endmodule

module carry_gen(cout,p,g);
parameter Q = 4;
input [Q-1:0]p;
input [Q-1:0]g;
output [Q-1:0]cout;
wire [Q:0]g_0;
assign g_0[0] = 0;

genvar i;
    generate
        for(i=0;i<Q;i=i+1)
            begin:generate_nbit_Bitwise
                Groupwise_PG g0(g_0[i+1],g[i],p[i],g_0[i]);
            end
    endgenerate

assign cout = g_0[Q:1];
endmodule

module carry_accurate(cout,p,g,cin);
parameter Q = 4;
input [Q-1:0]p;
input [Q-1:0]g;
input cin;
output [Q-1:0]cout;
wire [Q:0]g_0;
assign g_0[0] = cin;

genvar i;
    generate
        for(i=0;i<Q;i=i+1)
            begin:generate_nbit_Bitwise
                Groupwise_PG g0(g_0[i+1],g[i],p[i],g_0[i]);
            end
    endgenerate

assign cout = g_0[Q:1];
endmodule

module Bitwise_PG(
	output p,
	output g,
	input a,
	input b
    );
	assign p = a ^ b;
	assign g = a & b;

endmodule

module Groupwise_PG(	
	output g_1,
	input g,
	input p,
	input g_0
	);

	wire inter;
	assign inter = p & g_0;
	assign g_1 = g | inter;
endmodule

module CL_code_lit(input wire clk,rst_n,
                   input wire enb,
                   input wire[115:0] litTree,
                   input wire[7:0] litCode,
                   input wire[3:0] len_in,
                   output wire fin_lit,
                   output wire[4:0] litSymb,
                   output wire[4:0] litCount);

    parameter IDLE = 4'b0000;
    parameter Len1 = 4'b0001;
    parameter Len2 = 4'b0010;
    parameter Len3 = 4'b0011;
    parameter Len4 = 4'b0100;
    parameter Len5 = 4'b0101;
    parameter Len6 = 4'b0110;
    parameter Len7 = 4'b0111;
    parameter Len8 = 4'b1000;
    parameter Fin  = 4'b1001;
    reg[3:0] curr_state,next_state;

    reg[4:0] litCode_reg[255:0],litCode_count[8:1];
    reg[7:0] code,next_code;
    reg[3:0] len;
    reg[4:0] pos;
    reg pos_enb;

    wire[3:0] litTree_wap[28:0];
    wire match,pos_end;



    always @(posedge clk) begin
        if(!rst_n)begin
            curr_state <= IDLE;
        end
        else begin
            curr_state <= next_state;
        end
    end

    always @(*) begin
        case(curr_state)
            IDLE:begin
                if(enb)begin
                    next_state = Len1;
                    len        = 4'd0;
                    pos_enb    = 1'b0;
                end
                else begin
                    next_state = IDLE;
                    len        = 4'd0;
                    pos_enb    = 1'b0;
                end
            end
            Len1:begin
                if(pos_end)begin
                    next_state = Len2;
                    len        = 4'd1;
                    pos_enb    = 1'b1;
                end
                else begin
                    next_state = Len1;
                    len        = 4'd1;
                    pos_enb    = 1'b1;
                end
            end
            Len2:begin
                if(pos_end)begin
                    next_state = Len3;
                    len        = 4'd2;
                    pos_enb    = 1'b1;
                end
                else begin
                    next_state = Len2;
                    len        = 4'd2;
                    pos_enb    = 1'b1;
                end
            end
            Len3:begin
                if(pos_end)begin
                    next_state = Len4;
                    len        = 4'd3;
                    pos_enb    = 1'b1;
                end
                else begin
                    next_state = Len3;
                    len        = 4'd3;
                    pos_enb    = 1'b1;
                end
            end
            Len4:begin
                if(pos_end)begin
                    next_state = Len5;
                    len        = 4'd4;
                    pos_enb    = 1'b1;
                end
                else begin
                    next_state = Len4;
                    len        = 4'd4;
                    pos_enb    = 1'b1;
                end
            end
            Len5:begin
                if(pos_end)begin
                    next_state = Len6;
                    len        = 4'd5;
                    pos_enb    = 1'b1;
                end
                else begin
                    next_state = Len5;
                    len        = 4'd5;
                    pos_enb    = 1'b1;
                end
            end
            Len6:begin
                if(pos_end)begin
                    next_state = Len7;
                    len        = 4'd6;
                    pos_enb    = 1'b1;
                end
                else begin
                    next_state = Len6;
                    len        = 4'd6;
                    pos_enb    = 1'b1;
                end
            end
            Len7:begin
                if(pos_end)begin
                    next_state = Len8;
                    len        = 4'd7;
                    pos_enb    = 1'b1;
                end
                else begin
                    next_state = Len7;
                    len        = 4'd7;
                    pos_enb    = 1'b1;
                end
            end
            Len8:begin
                if(pos_end)begin
                    next_state = Fin;
                    len        = 4'd8;
                    pos_enb    = 1'b1;
                end
                else begin
                    next_state = Len8;
                    len        = 4'd8;
                    pos_enb    = 1'b1;
                end
            end
            Fin:begin
                next_state = Fin;
                len        = 4'd0;
                pos_enb    = 1'b0;
            end
            default:begin
                next_state = IDLE;
                len        = 4'd0;
                pos_enb    = 1'b0;
            end
        endcase
    end



    always @(posedge clk) begin
        if(!rst_n)begin
            pos <= 5'b0;
        end
        else if(pos_enb) begin
            if(pos_end) pos <= 5'b0;
            else pos <= pos + 1'b1;
        end
    end

    always @(posedge clk) begin
        if(pos_enb&match) litCode_reg[code] <= pos;
    end

    always @(posedge clk) begin
        if(!rst_n)begin
            litCode_count[1] <= 5'b0;
            litCode_count[2] <= 5'b0;
            litCode_count[3] <= 5'b0;
            litCode_count[4] <= 5'b0;
            litCode_count[5] <= 5'b0;
            litCode_count[6] <= 5'b0;
            litCode_count[7] <= 5'b0;
            litCode_count[8] <= 5'b0;
        end
        else begin
            litCode_count[len] <= litCode_count[len] + ((pos_enb&match)?1'b1:1'b0);
        end
    end

    always @(posedge clk) begin
        if(!rst_n)begin
            code <= 8'b0;
        end
        else if(pos_enb)begin
            code <= next_code;
        end
    end



    always @(*) begin
        case({pos_end,match})
            2'b00: next_code = code;
            2'b01: next_code = code + 1'b1;
            2'b10: next_code = code << 1;
            2'b11: next_code = (code + 1'b1) << 1;
            default: next_code = code;
        endcase
    end


    assign litSymb = litCode_reg[litCode];
    assign fin_lit = curr_state == Fin;
    assign litCount = ((len_in>=4'd1)&(len_in<=4'd8))?litCode_count[len_in]:5'b0;

    assign match = litTree_wap[pos] == len;
    assign pos_end = pos == 5'd28;

    assign {litTree_wap[28],litTree_wap[27],litTree_wap[26],litTree_wap[25],
            litTree_wap[24],litTree_wap[23],litTree_wap[22],litTree_wap[21],
            litTree_wap[20],litTree_wap[19],litTree_wap[18],litTree_wap[17],
            litTree_wap[16],litTree_wap[15],litTree_wap[14],litTree_wap[13],
            litTree_wap[12],litTree_wap[11],litTree_wap[10],litTree_wap[9],
            litTree_wap[8], litTree_wap[7], litTree_wap[6], litTree_wap[5],
            litTree_wap[4], litTree_wap[3], litTree_wap[2], litTree_wap[1],
            litTree_wap[0]}  = litTree;

endmodule

module score(
	input rst,
	input clk22,
	input shot_reimu,
	input shot_enm,
	input shot_boss,
	input gamestart,
	input [6:0]enmhp1,
	input [6:0]enmhp2,
	input [6:0]enmhp3,
	input [6:0]enmhp4,
	input [9:0]bosshp,
	output reg [3:0]score0,
	output reg [3:0]score1,
	output reg [3:0]score2,
	output reg [3:0]score3 
	);

	wire count0, count1, count2, count3;

	assign count0 = (score0 > 4'b1001);
	assign count1 = (score1 > 4'b1001);
	assign count2 = (score2 > 4'b1001);
	assign count3 = (score3 > 4'b1001);

	reg [3:0] nt_score0;
	reg [3:0] nt_score1;
	reg [3:0] nt_score2;
	reg [3:0] nt_score3;
	reg [3:0] enm;
	reg [3:0] nt_enm;
	reg boss, nt_boss;

	always@(posedge clk22)
	begin
		if(rst||gamestart)
		begin
		    enm <= 4'b0000;
			boss <= 1'b0;
			score0 <= 4'b0000;
			score1 <= 4'b0000;
			score2 <= 4'b0000;
			score3 <= 4'b0000;
		end
		else
		begin
		    enm <= nt_enm;
			boss <= nt_boss;
			score0 <= nt_score0;
			score1 <= nt_score1;
			score2 <= nt_score2;
			score3 <= nt_score3;
		end
	end

    always@(*)
    begin
        if(enmhp1 == 7'd0)
        begin
            nt_enm[0] = 1'b1;
        end
        else
        begin
            nt_enm[0] = 1'b0;
        end
        if(enmhp2 == 7'd0)
        begin
            nt_enm[1] = 1'b1;
        end
        else
        begin
            nt_enm[1] = 1'b0;
        end
        if(enmhp3 == 7'd0)
        begin
            nt_enm[2] = 1'b1;
        end
        else
        begin
            nt_enm[2] = 1'b0;
        end
        if(enmhp4 == 7'd0)
        begin
            nt_enm[3] = 1'b1;
        end
        else
        begin
            nt_enm[3] = 1'b0;
        end

		if(bosshp == 10'd0)
		begin
			nt_boss = 1'b1;
		end
		else
		begin
			nt_boss = 1'b0;
		end
    end

	always@(*)
	begin
		if(shot_reimu)
		begin
		    nt_score0 = 4'b0000;
		end
		else if(shot_enm || shot_boss)
		begin
			nt_score0 = score0 + 4'b0001;
		end
		else if(count0)
		begin
			nt_score0 = score0 - 4'b1010;
		end
		else
		begin
		    nt_score0 = score0;
		end

		if(shot_reimu)
		begin
		    nt_score1 = 4'b0000;
		end
		else if(count0)
		begin
		    nt_score1 = score1 + 4'b0001;
		end
		else if(count1)
		begin
		    nt_score1 = score1 - 4'b1010;
		end
		else
		begin
		    nt_score1 = score1;
		end

		if(shot_reimu)
		begin
		    nt_score2 = 4'b0000;
		end
		else if((enmhp1 == 7'd0 && !enm[0]) || (enmhp2 == 7'd0 && !enm[1]) || (enmhp3 == 7'd0 && !enm[2]) || (enmhp4 == 7'd0 && !enm[3]) || count1)
		begin
			nt_score2 = score2 + 4'b0001;
		end
		else if(count2)
		begin
		    nt_score2 = score2 - 4'b1010;
		end
		else
		begin
		    nt_score2 = score2;
		end

		if(shot_reimu)
		begin
		    nt_score3 = 4'b0000;
		end
		else if((bosshp == 10'd0 && !boss) || count2)
		begin
			nt_score3 = score3 + 4'b0001;
		end
		else if(count3)
		begin
		    nt_score3 = 4'b1001;
		end
		else
		begin
			nt_score3 = score3;
	    end
	 end
endmodule

module updown_counter(clk_i, rst_i, mode_i, count_o);
  input clk_i, rst_i, mode_i;
  output reg [2:0] count_o;
  reg direction;

  always @(posedge clk_i or posedge rst_i) begin
    if (rst_i) begin
      count_o <= 0; 
      direction <= 1; 
    end else begin
      if (mode_i)
        direction <= ~direction; 

      if (direction)
        count_o <= count_o + 1; 
      else
        count_o <= count_o - 1; 
    end
  end
endmodule

