module contador_fecha(
    input clk, reset,
    input boton_u, boton_d, cambiar_fecha,
    input [7:0] dias, mes, year,
    input [1:0] pos_x,
    output [7:0] dias_out, mes_out, year_out
    );

reg [7:0] count_dias, count_mes, count_year;
reg state_boton_u, state_boton_d;

always @ (posedge clk, posedge reset)
begin
if (reset)
begin
    count_dias = 8'h01;
    count_mes = 8'h01;
    count_year = 8'h00;
    state_boton_u = 0;
    state_boton_d = 0;
end
else
begin
    if (~cambiar_fecha)
    begin
        count_dias = dias;
        count_mes = mes;
        count_year = year;
    end
    else
    begin
        if (boton_u)
        begin
            state_boton_u = 1;
        end
        if (boton_d)
        begin
            state_boton_d = 1;
        end
        if (~boton_u & state_boton_u & (pos_x == 0))
        begin
            if (count_dias == 8'h9 | count_dias == 8'h19 | count_dias == 8'h29 )
            begin
                count_dias = count_dias + 8'h07;
                state_boton_u = 0;
            end
            else if (count_dias == 8'h31)
            begin
                count_dias = 8'h01;
                state_boton_u = 0;
            end
            else
            begin
                count_dias = count_dias + 1;
                state_boton_u = 0;
            end
        end
        if (~boton_d & state_boton_d & (pos_x == 0))
        begin
            if (count_dias == 8'h10 | count_dias == 8'h20 | count_dias == 8'h30 )
            begin
                count_dias = count_dias - 8'h07;
                state_boton_d = 0;
            end
            else if (count_dias == 8'h01)
            begin
                count_dias = 8'h31;
                state_boton_u = 0;
            end
            else
            begin
                count_dias = count_dias - 1;
                state_boton_u = 0;
            end
        end
        if (~boton_u & state_boton_u & (pos_x == 1))
        begin
            if (count_mes == 8'h9 )
            begin
                count_mes = count_mes + 8'h07;
                state_boton_u = 0;
            end
            else if (count_mes == 8'h12)
            begin
                count_mes = 8'h01;
                state_boton_u = 0;
            end
            else
            begin
                count_mes = count_mes + 1;
                state_boton_u = 0;
            end
        end
        if (~boton_d & state_boton_d & (pos_x == 1))
        begin
            if (count_mes == 8'h10)
            begin
                count_mes = count_mes - 8'h07;
                state_boton_d = 0;
            end
            else if (count_mes == 8'h01)
            begin
                count_mes = 8'h12;
                state_boton_u = 0;
            end
            else
            begin
                count_mes = count_mes - 1;
                state_boton_u = 0;
            end
        end
        if (~boton_u & state_boton_u & (pos_x == 2))
        begin
            if (count_year == 8'h09 | count_year == 8'h19 | count_year == 8'h29 | count_year == 8'h39 |
                count_year == 8'h49 | count_year == 8'h59 | count_year == 8'h69 | count_year == 8'h79 | count_year == 8'h89)
            begin
                count_year = count_year + 8'h07;
                state_boton_u = 0;
            end
            else if (count_year == 8'h99)
            begin
                count_year = 8'h00;
                state_boton_u = 0;
            end
            else
            begin
                count_year = count_year + 1;
                state_boton_u = 0;
            end
        end
        if (~boton_d & state_boton_d & (pos_x == 2))
        begin
            if (count_year == 8'h10 | count_year == 8'h20 | count_year == 8'h30 | count_year == 8'h40 |
                count_year == 8'h50 | count_year == 8'h60 | count_year == 8'h70 | count_year == 8'h80 | count_year == 8'h90)
            begin
                count_year = count_year - 8'h07;
                state_boton_d = 0;
            end
            else if (count_year == 8'h00)
            begin
                count_year = 8'h99;
                state_boton_u = 0;
            end
            else
            begin
                count_year = count_year - 1;
                state_boton_u = 0;
            end
        end
    end
end
end

assign dias_out = count_dias;
assign mes_out = count_mes;
assign year_out = count_year;

endmodule

module gamecontroller(clk, rst, mode, update, timeout2sec, rain, reqlfsr, req2sec, allowgt, raout1, raout2, raout3, raout4, raout5, segen);
input clk, rst, mode, update, timeout2sec;
input [3:0]rain;
output reg reqlfsr, req2sec, allowgt, segen;
output reg [3:0]raout1, raout2, raout3, raout4, raout5;
parameter init=0, start=1, request1=2, waitc1=4, load1=3, request2=5, waitc2=7, load2=6, request3=8, waitc3=10, load3=9, request4=11, waitc4=13, 
load4=12, request5=14, waitc5=16, load5=15, stop=17;
reg [4:0]state;
always @(posedge clk)
  begin
    if(rst==0)
      begin
        state<=init;
      end
    else
      begin
        case(state)
          init:
            begin
              reqlfsr<=0;
              req2sec<=0;
              allowgt<=0;
              segen<=0;
              raout1<=4'h0;
              raout2<=4'h0;
              raout3<=4'h0;
              raout4<=4'h0;
              raout5<=4'h0;
              if(mode==1)
                begin
                  state<=start;
                end
              else
                begin
                  state<=init;
                end
            end
          start:
            begin
              if(update==1)
                begin
                  allowgt<=0;
                  state<=request1;
                end
              else
                begin
                  state<=start;
                end
            end
          request1:
            begin
              reqlfsr=1'b1;
              segen<=1;
              req2sec<=1;
              state<=load1;
            end
          load1:
            begin
              reqlfsr<=1'b0;
              state<=waitc1;
            end
          waitc1:
            begin
              reqlfsr<=1'b0;
              raout1<=rain;
              if(timeout2sec==1)
                begin
                  req2sec<=0;
                  state<=request2;
                end
              else
                begin
                  state<=waitc1;
                end
            end
          request2:
            begin
              reqlfsr=1'b1;
              segen<=1;
              req2sec<=1;
              state<=load2;
            end
         load2:
            begin
              reqlfsr<=1'b0;
              state<=waitc2;
            end
          waitc2:
            begin
              reqlfsr<=1'b0;
              raout2<=rain;
              if(timeout2sec==1)
                begin
                  req2sec<=0;
                  state<=request3;
                end
              else
                begin
                  state<=waitc2;
                end
            end
          request3:
            begin
              reqlfsr=1'b1;
              segen<=1;
              req2sec<=1;
              state<=load3;
            end
         load3:
            begin
              reqlfsr<=1'b0;
              state<=waitc3;
            end
          waitc3:
            begin
              reqlfsr<=1'b0;
              raout3<=rain;
              if(timeout2sec==1)
                begin
                  req2sec<=0;
                  state<=request4;
                end
              else
                begin
                  state<=waitc3;
                end
            end
          request4:
            begin
              reqlfsr=1'b1;
              segen<=1;
              req2sec<=1;
              state<=load4;
            end
          load4:
            begin
              reqlfsr<=1'b0;
              state<=waitc4;
            end
          waitc4:
            begin
              reqlfsr<=1'b0;
              raout4<=rain;
              if(timeout2sec==1)
                begin
                  req2sec<=0;
                  state<=request5;
                end
              else
                begin
                  state<=waitc4;
                end
            end
          request5:
            begin
              reqlfsr=1'b1;
              segen<=1;
              req2sec<=1;
              state<=load5;
            end
          load5:
            begin
              reqlfsr<=1'b0;
              state<=waitc5;
            end
          waitc5:
            begin
              reqlfsr<=1'b0;
              raout5<=rain;
              if(timeout2sec==1)
                begin
                  req2sec<=0;
                  state<=stop;
                end
              else
                begin
                  state<=waitc5;
                end
            end
          stop:
            begin
              allowgt<=1;
              segen<=0;
              state<=start;
            end
          default:
            begin
              state<=init;
            end
        endcase
      end
  end
endmodule

module lab4(LEDR, HEX0, HEX1,HEX2,HEX3, HEX4, HEX5, SW, KEY);
