module Control_RX
(
	input in,
	input [8:0]shift_out,
	input clk,
	input reset,
	input clear,

	output shift,
	output load,
	output [8:0]value,
	output done


);

localparam INIT = 11;
localparam START = 12;
localparam READ_0 = 0;
localparam READ_1 = 1;
localparam READ_2 = 2;
localparam READ_3 = 3;
localparam READ_4 = 4;
localparam READ_5 = 5;
localparam READ_6 = 6;
localparam READ_7 = 7;
localparam READ_PARITY = 8;
localparam FINISH = 9;
localparam CLEAR = 10;

reg shift_reg;
reg load_reg;
reg [8:0]value_reg;
reg done_reg;

reg [3:0]cicles;
reg [3:0] state = 9;

always@(posedge clk or negedge reset) begin
	if(reset == 1'b0)
	begin
		state <= INIT;
		cicles <= 4'b0000;
	end
	else
	begin
		case(state)
			INIT:
			begin
				cicles <= 4'b0000;
				if(in == 0)
					state <= START;
				else
					state <= INIT;
			end			
			START:
			begin
				cicles <= cicles + 4'b0001;
				if(cicles == 4'b1111)
				begin
					cicles <= 4'b0000;
					state <= READ_0;
				end
				else
					state <= START;	
			end

			READ_0:
			begin
				cicles <= cicles + 4'b0001;
				if(cicles == 4'b1111)
				begin
					cicles <= 4'b0000;
					state <= READ_1;
				end
				else
					state <= READ_0;	
			end

			READ_1:
