				begin
					cicles <= 4'b0000;
					state <= READ_5;
				end
				else
					state <= READ_4;	
			end

			READ_5:
			begin
				cicles <= cicles + 4'b0001;
				if(cicles == 4'b1111)
				begin
					cicles <= 4'b0000;
					state <= READ_6;
				end
				else
					state <= READ_5;	
			end

			READ_6:
			begin
				cicles <= cicles + 4'b0001;
				if(cicles == 4'b1111)
				begin
					cicles <= 4'b0000;
					state <= READ_7;
				end
				else
					state <= READ_6;	
			end

			READ_7:
			begin
				cicles <= cicles + 4'b0001;
				if(cicles == 4'b1111)
				begin
					cicles <= 4'b0000;
					state <= READ_PARITY;
				end
				else
					state <= READ_7;	
			end

			READ_PARITY:
			begin
				cicles <= cicles + 4'b0001;
				if(cicles == 4'b1111)
				begin
					cicles <= 4'b0000;
					state <= FINISH;
				end
				else
					state <= READ_PARITY;
			end

			FINISH:
			begin
				cicles <= 4'b0000;
				if(in == 0)
					state <= START;
				else
				begin
					if(clear == 1)
						state <= CLEAR;
					else
						state <= FINISH;
				end
			end

			CLEAR:
			begin
				cicles <= 4'b0000;
				if(in == 0)
					state <= START;
				else
					state <= CLEAR;
			end

			default:
				state <= INIT;
		endcase
	end
end

