                            txpcdata<=zz5[7:0];
                        end
                        'd6: begin
                            txpcdata<=zz6[7:0];
                        end
                        'd7: begin
                            txpcdata<=zz7[7:0];
                        end
                        default:   ;
                    endcase
                    if (clkcount != 14'b11000010010000) begin
                        clkcount<=clkcount+1;
                    end
                    if(clkcount == 14'b11000010010000)begin
                        clkcount<=0;
                        bitcount<= 0;

                        if(txflag === 7)begin
                            txflag<=0;
                            starttx<=0;

                        end else begin
                            txflag <= txflag+1;
                        end

                    end

                end

            end




        end

    end

endmodule

module LZ77_Encoder(clk,reset,chardata,valid,encode,finish,offset,match_len,char_nxt);

input 				clk;
input 				reset;
input 		[7:0] 	chardata;
output reg 			valid;
output  			encode;
output reg 			finish;
output reg 	[3:0] 	offset;
output reg 	[2:0] 	match_len;
output reg 	[7:0] 	char_nxt;


reg			[1:0]	current_state, next_state;
reg			[11:0]	counter;
reg			[2:0]	search_index;
reg			[1:0]	lookahead_index;
reg			[3:0]	str_buffer	[2047:0];
reg			[3:0]	search_buffer	[6:0];

wire				equal	[2:0];
wire		[11:0]	current_encode_len;
wire		[1:0]	curr_lookahead_index;
wire		[3:0]	match_char [1:0];

parameter [1:0] IN=2'b00, ENCODE=2'b01, ENCODE_OUT=2'b10, SHIFT_ENCODE=2'b11;

integer i;

assign	encode = 1'b1;


assign	match_char[0] = search_buffer[search_index];
assign	match_char[1] = (search_index >= 1) ? search_buffer[search_index-1] : str_buffer[search_index];

assign	equal[0] = (search_index <= 6) ? (match_char[0]==str_buffer[0]) ? 1'b1 : 1'b0 : 1'b0;
assign	equal[1] = (search_index <= 6) ? (match_char[1]==str_buffer[1]) ? equal[0] : 1'b0 : 1'b0;
assign	equal[2] = 1'b0;


assign	current_encode_len = counter+match_len+1;
assign	curr_lookahead_index = lookahead_index+1;


always @(posedge clk or posedge reset)
begin
	if(reset)
	begin
		current_state <= IN;
		counter <= 12'd0;
		search_index <= 3'd0;
		lookahead_index <= 2'd0;
		valid <= 1'b0;
		finish <= 1'b0;
		offset <= 4'd0;
		match_len <= 3'd0;
		char_nxt <= 8'd0;

		search_buffer[0] <= 4'd0;
		search_buffer[1] <= 4'd0;
		search_buffer[2] <= 4'd0;
		search_buffer[3] <= 4'd0;
		search_buffer[4] <= 4'd0;
		search_buffer[5] <= 4'd0;
		search_buffer[6] <= 4'd0;
	end
	else
	begin
		current_state <= next_state;

		case(current_state)
			IN:
			begin
				str_buffer[counter] <= chardata[3:0];
				counter <= (counter==2047) ? 0 : counter+1;
			end
			ENCODE:
			begin
				if(equal[match_len]==1 && search_index < counter && current_encode_len <= 2048)
				begin
					char_nxt <= str_buffer[curr_lookahead_index];
					match_len <= match_len+1;
					offset <= search_index;

					lookahead_index <= curr_lookahead_index;
				end
				else
				begin
					search_index <= (search_index==7) ? 0 : search_index-1;
				end
			end
			ENCODE_OUT:
			begin
				valid <= 1;


				char_nxt <= (current_encode_len==2049) ? 8'h24 : (match_len==0) ? str_buffer[0] : char_nxt;
				counter <= current_encode_len;
			end
			SHIFT_ENCODE:
			begin
				finish <= (counter==2049) ? 1 : 0;
				offset <= 0;
				valid <= 0;
				match_len <= 0;
				search_index <= 6;
				lookahead_index <= (lookahead_index==0) ? 0 : lookahead_index-1;

				search_buffer[6] <= search_buffer[5];
				search_buffer[5] <= search_buffer[4];
				search_buffer[4] <= search_buffer[3];
				search_buffer[3] <= search_buffer[2];
				search_buffer[2] <= search_buffer[1];
				search_buffer[1] <= search_buffer[0];
				search_buffer[0] <= str_buffer[0];

				for (i=0; i<2047; i=i+1) begin
					str_buffer[i] <= str_buffer[i+1];
				end
			end
		endcase
	end
end



always @(*)
begin
	case(current_state)
		IN:
		begin
			next_state = (counter==2047) ? ENCODE : IN;
		end
		ENCODE:
		begin

			next_state = (search_index==7 || match_len==2) ? ENCODE_OUT : ENCODE;
		end
		ENCODE_OUT:
		begin
			next_state = SHIFT_ENCODE;
		end
		SHIFT_ENCODE:
		begin
			next_state = (lookahead_index==0) ? ENCODE : SHIFT_ENCODE;
		end
		default:
		begin
			next_state = IN;
		end
	endcase
end


endmodule

module arbitro_1(
    input clk,
    input almost_full0,
    input almost_full1,
    input almost_full2,
    input almost_full3,
    input empty0,
    input empty1,
    input empty2,
    input empty3,
    input wire[1:0] dest,
    input valid_0,
    input valid_1,
    input valid_2,
    input valid_3,
    input [3:0] state,
    output reg pop0,
    output reg pop1,
    output reg pop2,
    output reg pop3,
    output reg push0,
    output reg push1,
    output reg push2,
    output reg push3
);
reg [2:0] contador0;
reg [2:0] contador1;
reg [2:0] contador2;
reg [2:0] contador3;


always@(*)begin
  pop0=0;
  pop1=0;
  pop2=0;
  pop3=0;
    if(state == 4'b0001)begin
        pop0=0;
        pop1=0;
        pop2=0;
        pop3=0;
    end else begin
      if (almost_full0 == 1 || almost_full1 == 1 || almost_full2 == 1 || almost_full3 == 1) begin
        pop0=0;
        pop1=0;
        pop2=0;
        pop3=0;
      end else
      if (contador0 < 4 && empty0 == 0) begin
        pop0 = 1;
      end else
      if (contador1 < 3 && empty1 == 0) begin
        pop1 = 1;
      end else
      if (contador2 < 2 && empty2 == 0) begin
        pop2 = 1;
      end else
      if (contador3 < 1 && empty3 == 0) begin
        pop3 = 1;
      end
    end
end

always@(*)begin
    push0=0;
    push1=0;
    push2=0;
    push3=0;
    if (almost_full0 == 1 || almost_full1 == 1 || almost_full2 == 1 || almost_full3 == 1) begin
      push0=0;
      push1=0;
      push2=0;
      push3=0;
    end else
     if (dest == 0 && valid_0 == 1 ) begin
       push0 = 1;
     end else
     if (dest == 1 && valid_1 == 1 ) begin
       push1 = 1;
     end else
     if (dest == 2 && valid_2 == 1) begin
       push2 = 1;
     end else
     if (dest == 3 && valid_3 == 1) begin
       push3 = 1;
     end
end

always@(posedge clk)begin
    if (state == 4'b0001 ) begin
      contador0 <= 0;
      contador1 <= 0;
      contador2 <= 0;
      contador3 <= 0;

    end else begin
      if (pop0 == 1) begin
        contador0 = contador0 + 1;
        contador3 = 0;
      end else
      if (pop1 == 1) begin
        contador1 = contador1 + 1;
      end
      if (pop2 == 1) begin
        contador2 = contador2 + 1;
      end
      if (pop3 == 1) begin
        contador3 = contador3 + 1;
        contador1 = 0;
        contador2 = 0;
        contador0 = 0;
      end
    end
end

endmodule

