						writeEnable = 1'b1;
						readEnable = 1'b0;
					end
					JUMP: begin
						muxPC = 2'd0;
						muxData = 2'd0;
						muxOperand = 1'b1;
						controALU = 3'd1;
						writeEnable = 1'b1;
						readEnable = 1'b0;
					end
					BEQ: begin
						muxPC = 2'd0;
						muxData = 2'd0;
						muxOperand = 1'b1;
						controALU = 3'd1;
						writeEnable = 1'b1;
						readEnable = 1'b0;
					end
					BGT: begin
						muxPC = 2'd0;
						muxData = 2'd0;
						muxOperand = 1'b1;
						controALU = 3'd1;
						writeEnable = 1'b1;
						readEnable = 1'b0;
					end
					BGE: begin
						muxPC = 2'd0;
						muxData = 2'd0;
						muxOperand = 1'b1;
						controALU = 3'd1;
						writeEnable = 1'b1;
						readEnable = 1'b0;
					end
					BLT: begin
						muxPC = 2'd0;
						muxData = 2'd0;
						muxOperand = 1'b1;
						controALU = 3'd1;
						writeEnable = 1'b1;
						readEnable = 1'b0;
					end
					BLE: begin
						muxPC = 2'd0;
						muxData = 2'd0;
						muxOperand = 1'b1;
						controALU = 3'd1;
						writeEnable = 1'b1;
						readEnable = 1'b0;
					end
					BNE: begin
						muxPC = 2'd0;
						muxData = 2'd0;
						muxOperand = 1'b1;
						controALU = 3'd1;
						writeEnable = 1'b1;
						readEnable = 1'b0;
					end
					MOVE: begin
						muxPC = 2'd0;
						muxData = 2'd0;
						muxOperand = 1'b1;
						controALU = 3'd1;
						writeEnable = 1'b1;
						readEnable = 1'b0;
					end
					NOP: begin
						muxPC = 2'd0;
						muxData = 2'd0;
						muxOperand = 1'b1;
						controALU = 3'd1;
						writeEnable = 1'b1;
						readEnable = 1'b0;
					end
					HLT: begin
						muxPC = 2'd0;
						muxData = 2'd0;
						muxOperand = 1'b1;
						controALU = 3'd1;
						writeEnable = 1'b1;
						readEnable = 1'b0;
					end
					IN: begin
						muxPC = 2'd0;
						muxData = 2'd0;
						muxOperand = 1'b1;
						controALU = 3'd1;
						writeEnable = 1'b1;
						readEnable = 1'b0;
					end
					OUT: begin
						muxPC = 2'd0;
						muxData = 2'd0;
						muxOperand = 1'b1;
						controALU = 3'd1;
						writeEnable = 1'b1;
						readEnable = 1'b0;
					end
					default: begin
						muxPC = 2'd0;
						muxData = 2'd0;
						muxOperand = 1'b1;
						controALU = 3'd1;
						writeEnable = 1'b1;
						readEnable = 1'b0;
					end
				endcase
			end
			default: begin
				muxPC = 2'd0;
				muxData = 2'd0;
				muxOperand = 1'b1;
				controALU = 3'd1;
				writeEnable = 1'b1;
				readEnable = 1'b0;
			end
		endcase
	end

endmodule

module jhonson_counter(
