    input n_rst,
    output reg [3:0] out
);

always @(posedge clk or negedge n_rst) begin
    if(!n_rst)
        out <= 4'b0000;
    else
        out <= {out[2:0], ~out[3]};
end


endmodule

module LFSR_Timer_1ms(rst, clk, enable, out_1ms);
	input clk, rst, enable;
	reg [15:0] LFSR;
	output reg out_1ms;

	parameter 	CYCLE50K 	= 16'b0100001011001110,
			INIT		= 16'b1111111111111111;

	always @(posedge clk, negedge rst)
	begin
		if(rst == 0)
		begin
			LFSR <= INIT;
			out_1ms <= 0;
		end
		else	begin
			if(enable)	begin
				if(LFSR == CYCLE50K)	begin
					out_1ms <= 1;
					LFSR <= INIT;
				end
				else	begin
					LFSR[0] <= LFSR[1] ^ LFSR[2] ^ LFSR[4] ^ LFSR[15];
					LFSR[15:1] <= LFSR[14:0];
					out_1ms <= 0;
				end
			end
			else	begin
				LFSR <= INIT;
				out_1ms <= 0;
			end
		end
	end
endmodule

module EXE_MEM_REG(
	clk, reset_n,
	flush, EXE_MEM_REG_Write,
	MemRead_EXE, MemWrite_EXE,
	MemtoReg_EXE, RegWrite_EXE,
	rd_EXE, pc_EXE,
	ALU_Result_EXE, write_data_EXE,
	MemRead_MEM, MemWrite_MEM,
	MemtoReg_MEM, RegWrite_MEM,
	rd_MEM, pc_MEM,
	ALU_Result_MEM, write_data_MEM
);

	input clk, reset_n;
	input flush, EXE_MEM_REG_Write;


	input [3:0] MemRead_EXE, MemWrite_EXE; 


	input [1:0] MemtoReg_EXE;
	input RegWrite_EXE;
	input [4:0] rd_EXE;
	input [14:0] pc_EXE;


	input [31:0] ALU_Result_EXE;
	input [31:0] write_data_EXE;


	output reg [3:0] MemRead_MEM, MemWrite_MEM; 


	output reg [1:0] MemtoReg_MEM;
	output reg RegWrite_MEM;
	output reg [4:0] rd_MEM;
	output reg [14:0] pc_MEM;


	output reg [31:0] ALU_Result_MEM;
	output reg [31:0] write_data_MEM;

	always @(posedge clk) begin
		if (reset_n || flush) begin
			MemRead_MEM <= 0;
			MemWrite_MEM <= 0;
			MemtoReg_MEM <= 0;
			RegWrite_MEM <= 0;
			rd_MEM <= 0;
			pc_MEM <= 0;
			ALU_Result_MEM <= 0;
			write_data_MEM <= 0;
		end 

		else if (EXE_MEM_REG_Write) begin
			MemRead_MEM <= MemRead_EXE;
			MemWrite_MEM <= MemWrite_EXE;
			MemtoReg_MEM <= MemtoReg_EXE;
			RegWrite_MEM <= RegWrite_EXE;
			rd_MEM <= rd_EXE;
			pc_MEM <= pc_EXE;
			ALU_Result_MEM <= ALU_Result_EXE;
			write_data_MEM <= write_data_EXE;
		end
	end

endmodule

`timescale 1ns / 1ps

module ControllerIO(
Opcode,Function_opcode,Jr,RegDST,ALUSrc,RegWrite,MemWrite,Branch,
nBranch,Jmp,Jal,I_format,Sftmd,ALUOp,Alu_resultHigh,MemorIOtoReg,MemRead,IORead,IOWrite
);
input [5:0] Opcode;
input [5:0] Function_opcode;
output Jr;
output RegDST;
output ALUSrc;
output RegWrite;
output MemWrite;
output Branch;
output nBranch;
output Jmp;
output Jal;
output I_format;
output Sftmd;
output [1:0]ALUOp;

input[21:0] Alu_resultHigh; 
output MemorIOtoReg;
output MemRead; 
output IORead; 
output IOWrite; 

assign Jr =((Function_opcode==6'b001000)&&(Opcode==6'b000000)) ? 1'b1 : 1'b0;
assign Jal=(Opcode==6'b000011) ? 1'b1 : 1'b0;
assign Jmp=(Opcode==6'b000010) ? 1'b1 : 1'b0;


wire R_type=(Opcode==6'b0)?1'b1:1'b0;
wire J_type=(Jr||Jal||Jmp)?1'b1:1'b0;
wire I_type=(R_type||J_type)?1'b0:1'b1;


wire beq=(Opcode==6'b000100)? 1'b1 : 1'b0;
wire bne=(Opcode==6'b000101)? 1'b1 : 1'b0;
wire lw=(Opcode==6'b100011)? 1'b1 : 1'b0;
wire sw=(Opcode==6'b101011)? 1'b1 : 1'b0;

wire beqorbne=beq||bne;
wire RorI=R_type||I_format;

assign I_format=I_type&&(!(beq||bne||lw||sw));
assign ALUOp={RorI,beqorbne};
assign Branch=beq;
assign nBranch=bne;
assign RegDST=R_type;
assign Sftmd = (((Function_opcode==6'b000000)||(Function_opcode==6'b000010)
||(Function_opcode==6'b000011)||(Function_opcode==6'b000100)
||(Function_opcode==6'b000110)||(Function_opcode==6'b000111))
&& R_type)? 1'b1:1'b0;
assign ALUSrc=(I_type && ! beq && !bne )?1'b1 :1'b0;

assign RegWrite = (R_type || lw || Jal || I_format) && !(Jr) ; 
assign MemWrite = ((sw==1) && (Alu_resultHigh[21:0] != 22'h3FFFFF)) ? 1'b1:1'b0;
assign MemRead = ((lw==1) && (Alu_resultHigh[21:0] != 22'h3FFFFF)) ? 1'b1:1'b0;
assign IORead = ((lw==1) && (Alu_resultHigh[21:0] == 22'h3FFFFF)) ? 1'b1:1'b0;
assign IOWrite = ((sw==1) && (Alu_resultHigh[21:0] == 22'h3FFFFF)) ? 1'b1:1'b0;


assign MemorIOtoReg = IORead || MemRead ;
endmodule

module I2c 
(wr_i2c, cmd, din, dvsr, clk, rst, sda_in, dout, ack, ready, done_tick, sda_out, scl);
input wr_i2c;
input  [2:0] cmd;
input  [7:0] din;
input  [15:0] dvsr;
input clk;
input rst;
input sda_in;
output wire [7:0] dout;
output wire ack;
output reg ready;
output reg done_tick;
output reg sda_out;
output reg scl;

reg [3:0] current_state;
reg [3:0] next_state;
reg [15:0] counter;
reg counter_rst;
reg [4:0] bit_cnt;
reg bit_done;
reg [8:0] tx_reg;
reg [8:0] rx_reg;
reg [8:0] tx_next;
reg [8:0] rx_next;
reg       READ_DONE;


parameter IDLE      =  0;
parameter START_1   =  1;
parameter START_2   =  2;
parameter HOLD      =  3;
parameter DATA_1    =  4;
parameter DATA_2    =  5;
parameter DATA_3    =  6;
parameter DATA_4    =  7;
parameter ACK_1     =  8;
parameter ACK_2     =  9;
parameter ACK_3     =  10;
parameter ACK_4     =  11;
parameter STOP_1    =  12;
parameter STOP_2    =  13;

parameter START_CMD   = 0;
parameter WR_CMD      = 1;
parameter RD_CMD      = 2;
parameter STOP_CMD    = 3;


wire [15:0] qutr;
wire [15:0] half;
assign qutr = dvsr;
assign half = qutr<<1;
assign ack  = cmd == WR_CMD ? sda_in:1;
assign dout = READ_DONE ? rx_reg[8:1]:0;




always @(posedge clk or negedge rst) 
begin
    if(!rst)
    begin
        tx_reg <= 9'b0;
        rx_reg <= 9'b0;
    end
    else
    begin
        tx_reg <= tx_next;
        rx_reg <= rx_next;
    end
end


always @(posedge clk or negedge rst) 
begin
    if(!rst)
        counter <= 0;
    else if (counter_rst)
        counter <= 0;
    else 
        counter <= counter + 1;
end


always @(posedge clk or negedge rst) 
begin
    if(!rst) 
        bit_cnt <= 0; 
    else if (bit_cnt == 9)
        bit_cnt <= 0;
    else if (bit_done)
        bit_cnt <= bit_cnt + 1;  
    else
        bit_cnt <= bit_cnt;
end

always @(posedge clk or negedge rst) 
begin
    if(!rst) 
        current_state <= IDLE; 
    else 
        current_state <= next_state;  
end

always @(*)
begin
    case(current_state)
    IDLE: 
    begin
        if(cmd == START_CMD && wr_i2c)
        begin
            next_state = START_1;
        end
        else
        begin
            next_state = IDLE;
        end

        sda_out      = 1'b1;
        scl          = 1'b1;
        ready        = 1'b1;
        counter_rst  = 1'b1;
        bit_done     = 1'b0;
        tx_next      = tx_reg;
        rx_next      = rx_reg;
        done_tick    = 1'b0;
        READ_DONE    = 1'b0;

    end   

    START_1: 
    begin
        if(counter == half)
        begin
            next_state = START_2;
            counter_rst = 1'b1;
        end
        else
        begin
            next_state = START_1;
            counter_rst = 1'b0;
        end

        sda_out    = 1'b0;
        scl        = 1'b1;
        ready      = 1'b0; 
        bit_done   = 1'b0;
        tx_next    = tx_reg;
        rx_next    = rx_reg;
        done_tick  = 1'b0;
        READ_DONE    = 1'b0;

    end 

    START_2: 
    begin
        if(counter == half)
        begin 
            next_state = HOLD;
            counter_rst = 1'b1;
        end
        else
        begin
            next_state = START_2;
            counter_rst = 1'b0;
        end
        sda_out      = 1'b0;
        scl          = 1'b0;
        ready        = 1'b0; 
        bit_done     = 1'b0;
        tx_next      = tx_reg;
        rx_next      = rx_reg;
        done_tick    = 1'b0;
        READ_DONE    = 1'b0;

    end 
    HOLD: 
    begin
        if(cmd == WR_CMD)
        begin
            next_state  = DATA_1;
            tx_next     = {din,1'b0};
        end
        else if (cmd == RD_CMD)
        begin
            next_state = DATA_1;
            tx_next = tx_reg;
        end
        else if (cmd == STOP_CMD)
        begin
            next_state = STOP_1;
            tx_next = tx_reg;
        end
        else
        begin
            next_state = HOLD;
            tx_next = tx_reg;
        end

        sda_out     = 1'b0;
        scl         = 1'b0;
        ready       = 1'b1; 
        bit_done    = 1'b0;
        counter_rst = 1'b1;
        rx_next     = rx_reg;
        done_tick   = 1'b0;
        READ_DONE    = 1'b0;
    end 
    DATA_1: 
    begin
        if(counter == qutr)
        begin
            next_state = DATA_2;
            counter_rst = 1'b1;
        end
        else
        begin
            next_state = DATA_1;
            counter_rst = 1'b0;
        end

        if(cmd == RD_CMD)
        sda_out  = 1'hz;
        else
        begin
        sda_out  = tx_reg[8];
        end

        scl         = 1'b0;
        ready       = 1'b0; 
        bit_done    = 1'b0;
        tx_next     = tx_reg;
        rx_next     = rx_reg;
        done_tick   = 1'b0;
        READ_DONE    = 1'b0;
    end 
    DATA_2: 
    begin
        if(counter == qutr)
        begin
            next_state  = DATA_3;
            counter_rst = 1'b1;
            rx_next     = {rx_reg[7:0],sda_in};
        end
        else
        begin
            next_state  = DATA_2;
            counter_rst = 1'b0;
            rx_next     = rx_reg;
        end

        if(cmd == RD_CMD)
        sda_out  = 1'hz;
        else
        begin
        sda_out  = tx_reg[8];
        end

        scl         = 1'b1;
        ready       = 1'b0; 
        bit_done    = 1'b0;
        tx_next     = tx_reg;
        done_tick   = 1'b0;
        READ_DONE    = 1'b0;
    end 
    DATA_3: 
    begin
        if(counter == qutr)
        begin
            next_state  = DATA_4;
            counter_rst = 1'b1;
        end
        else
        begin
            next_state  = DATA_3;
            counter_rst = 1'b0;
        end

        if(cmd == RD_CMD)
        sda_out  = 1'hz;
        else
        begin
        sda_out  = tx_reg[8];
        end

        scl         = 1'b1;
        ready       = 1'b0; 
        bit_done    = 1'b0;
        tx_next     = tx_reg;
        rx_next     = rx_reg;
        done_tick   = 1'b0;
        READ_DONE    = 1'b0;
    end 
    DATA_4: 
    begin
        if (counter == qutr && bit_cnt == 8)
        begin
            next_state  = ACK_1;
            tx_next     = tx_reg;
            counter_rst = 1'b1;
            bit_done    = 1'b1;
        end
        else if(counter == qutr && bit_cnt != 8)
        begin
            next_state  = DATA_1;
            tx_next     = {tx_reg[7:0],1'b0};
            counter_rst = 1'b1;
            bit_done    = 1'b1;

        end
        else
        begin
            tx_next     = tx_reg;
            next_state  = DATA_4;
            counter_rst = 1'b0;
            bit_done    = 1'b0; 

        end

        if(cmd == RD_CMD)
        sda_out  = 1'hz;
        else
        begin
        sda_out  = tx_reg[8];
        end

        scl         = 1'b0;
        ready       = 1'b0;
        rx_next     = rx_reg; 
        done_tick   = 1'b0;
        READ_DONE    = 1'b0;

    end 
    ACK_1: 
    begin
        if(counter == qutr)
        begin
            next_state  = ACK_2;
            counter_rst = 1'b1;
        end
        else
        begin
            next_state  = ACK_1;
            counter_rst = 1'b0;
        end

        if(cmd == WR_CMD)
        sda_out  = 1'hz;
        else
        begin
        sda_out  = 1'b0;
        end

        scl         = 1'b0;
        bit_done    = 1'b0;
        ready       = 1'b0; 
        done_tick   = 1'b0;
        tx_next     = tx_reg;
        rx_next     = rx_reg;
        READ_DONE    = 1'b0;
    end
    ACK_2: 
    begin
        if(counter == qutr)
        begin
            next_state  = ACK_3;
            counter_rst = 1'b1;
        end
        else
        begin
            next_state  = ACK_2;
            counter_rst = 1'b0;
        end

        if(cmd == WR_CMD)
        sda_out  = 1'hz;
        else
        begin
        sda_out  = 1'b0;
        end

        scl         = 1'b1;
        bit_done    = 1'b0;
        ready       = 1'b0; 
        done_tick   = 1'b0;
        tx_next     = tx_reg;
        rx_next     = rx_reg;
        READ_DONE    = 1'b0;
    end
    ACK_3: 
    begin
        if(counter == qutr)
        begin
            next_state  = ACK_4;
            counter_rst = 1'b1;
        end
        else
        begin
            next_state  = ACK_3;
            counter_rst = 1'b0;
        end

        if(cmd == WR_CMD)
        sda_out  = 1'hz;
        else
        begin
        sda_out  = 1'b0;
        end

        scl         = 1'b1;
        bit_done    = 1'b0;
        ready       = 1'b0; 
        done_tick   = 1'b0;
        tx_next     = tx_reg;
        rx_next     = rx_reg;
        READ_DONE    = 1'b0;
    end
    ACK_4: 
    begin
        if(counter == qutr)
        begin
            next_state  = HOLD;
            counter_rst = 1'b1;
            done_tick   = 1'b1;
        end
        else
        begin
            next_state  = ACK_4;
            counter_rst = 1'b0;
            done_tick   = 1'b0;
        end

        if(cmd == WR_CMD)
        begin
        sda_out  = 1'hz;
        READ_DONE   = 1'b0;
        end
        else
        begin
        sda_out    = 1'b0;
        READ_DONE   = 1'b1;
        end

        scl         = 1'b0;
        bit_done    = 1'b0;
        ready       = 1'b0; 
        tx_next     = tx_reg;
        rx_next     = rx_reg;
    end
    STOP_1: 
    begin
        if(counter == half)
        begin
            next_state  = STOP_2;
            counter_rst = 1'b1;
        end
        else
        begin
            next_state  = STOP_1;
            counter_rst = 1'b0;
        end
        sda_out     = 1'b0;
        scl         = 1'b1;
        ready       = 1'b0; 
        bit_done    = 1'b0;
        tx_next     = tx_reg;
        rx_next     = rx_reg;
        done_tick   = 1'b0;
        READ_DONE   = 1'b0;
    end   
    STOP_2: 
    begin
        if(counter == half)
        begin
            next_state = IDLE;
            counter_rst = 1'b1;
        end
        else
        begin
            next_state = STOP_2;
            counter_rst = 1'b0;
        end
        sda_out     = 1'b1;
        scl         = 1'b1;
        ready       = 1'b0; 
        bit_done    = 1'b0;
        tx_next     = tx_reg;
        rx_next     = rx_reg;
        done_tick   = 1'b0;
        READ_DONE   = 1'b0;
    end  
    default:  
    begin
        next_state  = IDLE;
        sda_out     = 1'b1;
        scl         = 1'b1;
        ready       = 1'b0; 
        bit_done    = 1'b0;
        tx_next     = tx_reg;
        rx_next     = rx_reg;
        done_tick   = 1'b0;
        READ_DONE   = 1'b0;
        counter_rst = 1'b1;
    end 
    endcase
end
endmodule

