    output wire[4:0]    o_vram_yoffset
);

reg r_busy;     
assign t_busy=r_busy;
reg r_done;     
assign t_done=r_done;

reg[4:0] r_y_offset;    
reg[6:0] r_line_cnt;    
reg[7:0] r_A;        
assign t_A=r_A;
wire t_DRA = i_dev_KZ[0];
wire t_KZS = i_dev_KZ[6];
wire t_KZC = i_dev_KZ[7];
reg r_WANC;
reg r_SHOW;
reg[7:0] r_CHAR;

