assign o_dev_ZT = {r_done, r_busy};
assign o_dev_DMs = DEV_DMs;

wire t_CHAR_BS = (r_A == 8'd8) | (r_A == 8'd25);
wire t_CHAR_LF = (r_A == 8'd10);
wire t_CHAR_NULL = (r_A == 8'd0) | (r_A == 8'd7) | (r_A == 8'd19) | (r_A == 8'd23) | (r_A == 8'd26);
assign o_vram_ce = r_SHOW;
assign o_vram_we = r_SHOW;
assign o_vram_data = {TTO_COLOR, r_CHAR};
assign o_vram_addr = {r_line_cnt, TTO_Y};
assign o_vram_yoffset = r_y_offset;

reg r_LINE_CLEAN;
reg r_LINE_FEED;
reg[3:0] r_STATE;


localparam  STATE_IDLE             = 4'd0; 
localparam  STATE_START_T1         = 4'd1; 
localparam  STATE_START_T2         = 4'd2; 
localparam  STATE_PUTCHAR_START    = 4'd3; 
localparam  STATE_PUTCHAR_T1       = 4'd4; 
localparam  STATE_PUTCHAR_T2       = 4'd5; 
localparam  STATE_PUTCHAR_T3       = 4'd6; 
localparam  STATE_PUTCHAR_DONE     = 4'd7; 
localparam  STATE_LINEFEED_START   = 4'd8; 
localparam  STATE_LINEFEED_DONE    = 4'd9; 
localparam  STATE_LINECLEAN_START  = 4'd10; 
localparam  STATE_LINECLEAN_DONE   = 4'd11; 
localparam  STATE_DONE             = 4'd12; 


always @(posedge i_dev_ZZ0 or posedge t_DRA) begin
    if (i_dev_ZZ0) r_A <= 16'b0;
    else if (t_DRA) r_A <= i_dev_SR[7:0];
    else r_A <= r_A;
end


wire t_set_done = (t_KZS & r_done) | (r_WANC & !r_done);
wire t_rst_done = i_dev_ZZ0 | (t_KZC & r_done);
always @(posedge t_rst_done or posedge t_set_done) begin
    if (t_rst_done) r_done <= 1'b0;
    else if (r_done) r_done <= 1'b0;
    else r_done <= 1'b1;
end


wire t_busy_clk = (t_KZS & !r_busy) | (t_KZC & r_busy) | (r_WANC & r_busy);
always @(posedge t_busy_clk or posedge i_dev_ZZ0) begin
    if (i_dev_ZZ0) r_busy <= 1'b0;
    else if (r_busy) r_busy <= 1'b0;
    else r_busy <= 1'b1;
end 

always @(posedge i_vram_clk or posedge i_dev_ZZ0) begin
    if (i_dev_ZZ0) begin
        r_STATE <= STATE_IDLE;
        r_line_cnt <= 5'd0;
        r_LINE_CLEAN <= 0;
        r_LINE_FEED <= 0;
        r_SHOW <= 0;
        r_WANC <= 0;
        r_CHAR <= 8'd0;
        r_y_offset <= 5'd0;
    end
    else begin
        case (r_STATE) 
        STATE_IDLE: 
            if ((r_busy == 1) & (r_done == 0)) r_STATE <= STATE_START_T1;
            else begin
                r_STATE <= STATE_IDLE;
                r_WANC <= 0;
            end
        STATE_START_T1: 
            r_STATE <= STATE_START_T2;
        STATE_START_T2:  begin
                if (t_CHAR_NULL) 
                    r_STATE <= STATE_DONE;
                else if (t_CHAR_BS) begin
                    if (r_line_cnt != 0) r_line_cnt = r_line_cnt - 5'd1;
                    r_STATE <= STATE_DONE;
                end
                else if (r_line_cnt == TTO_LINE_MAX) begin
                    r_LINE_CLEAN <= 1;
                    r_STATE <= STATE_LINECLEAN_START;
                end
                else if (t_CHAR_LF) begin
                    r_LINE_FEED <= 1;
                    r_STATE <= STATE_LINEFEED_START;
                end
                else begin
                    r_CHAR <= r_A;
                    r_STATE <= STATE_PUTCHAR_START;
                end
            end
        STATE_LINECLEAN_START: begin
                r_CHAR <= TTO_SPACE;
                r_y_offset <= r_y_offset + 1;
                r_line_cnt <= 5'd0;
                r_STATE <= STATE_PUTCHAR_START;
            end
        STATE_LINEFEED_START: begin
                r_CHAR <= TTO_SPACE;
                r_STATE <= STATE_PUTCHAR_START;
            end    
        STATE_PUTCHAR_START: begin
            r_STATE <= STATE_PUTCHAR_T1;
            r_SHOW <= 1'b1;
        end
        STATE_PUTCHAR_T1: begin
            r_STATE <= STATE_PUTCHAR_T2;
        end
        STATE_PUTCHAR_T2: begin
            r_STATE <= STATE_PUTCHAR_T3;
        end
        STATE_PUTCHAR_T3: begin
            r_STATE <= STATE_PUTCHAR_DONE;
            r_SHOW <= 1'b0;
        end
        STATE_PUTCHAR_DONE: begin
            r_line_cnt <= r_line_cnt + 1;
            if (r_LINE_FEED) 
                r_STATE <= STATE_LINEFEED_DONE;
            else if (r_LINE_CLEAN)
                r_STATE <= STATE_LINECLEAN_DONE;
            else r_STATE <= STATE_DONE; 
        end
        STATE_LINEFEED_DONE: begin
            if (r_line_cnt == TTO_LINE_MAX) begin
                r_LINE_FEED <= 0;
                r_LINE_CLEAN <= 1;
                r_STATE <= STATE_LINECLEAN_START; 
            end
            else r_STATE <= STATE_PUTCHAR_START;
        end
        STATE_LINECLEAN_DONE: begin
            if (r_line_cnt == TTO_LINE_MAX) begin
                r_line_cnt <= 5'd0;
                r_LINE_CLEAN <= 0;
                r_STATE <= STATE_DONE;
            end
            else r_STATE <= STATE_PUTCHAR_START;
        end
        STATE_DONE: begin
            r_STATE <= STATE_IDLE;
            r_WANC <= 1;
        end
        endcase
    end
end

endmodule

module led_ctrl (
    input   wire            i_clk,
    input   wire            i_res_n,

    input   wire            i_tx_d1,
    input   wire            i_tx_err,
    input   wire            i_rx_d1,
    input   wire            i_rx_err,

    output  wire            o_tx_led_red,
    output  wire            o_tx_led_gr,
    output  wire            o_rx_led_red,
    output  wire            o_rx_led_gr
);


    reg     [25:0]  r_cnt_boot;
    reg     [ 1:0]  r_boot_st;
    wire            w_cnt_max_boot = (r_cnt_boot == 26'd59999999);
    always @(posedge i_clk or negedge i_res_n) begin
        if (~i_res_n) begin
            r_cnt_boot <= 26'd0;
            r_boot_st <= 2'd0;
        end else begin
            if (w_cnt_max_boot) begin
                r_cnt_boot <= 26'd0;
                if (r_boot_st != 2'b11) begin
                    r_boot_st <= r_boot_st + 2'd1;
                end
            end else begin
                r_cnt_boot <= r_cnt_boot + 26'd1;
            end
        end
    end


    reg     [23:0]  r_cnt_flash;
    wire            w_cnt_max_flash = (r_cnt_flash == 24'd11999999);
    reg             r_flash_en;
    always @(posedge i_clk or negedge i_res_n) begin
        if (~i_res_n) begin
            r_cnt_flash <= 24'd0;
            r_flash_en <= 1'b0;
        end else begin
            if (w_cnt_max_flash) begin
                r_cnt_flash <= 24'd0;
                r_flash_en <= ~r_flash_en;
            end else begin
                r_cnt_flash <= r_cnt_flash + 24'd1;
            end
        end
    end

    assign o_tx_led_red =   (r_boot_st == 2'd0) ? 1'b1 :
                            (r_boot_st == 2'd1) ? 1'b0 :
                            (i_tx_err) ? r_flash_en :
                            1'b1;

    assign o_tx_led_gr =    (r_boot_st == 2'd0) ? 1'b1 :
                            (r_boot_st == 2'd1) ? 1'b0 :
                            i_tx_d1;

    assign o_rx_led_red =   (r_boot_st == 2'd0) ? 1'b1 :
                            (r_boot_st == 2'd1) ? 1'b0 :
                            (i_rx_err) ? r_flash_en :
                            1'b1;

    assign o_rx_led_gr =    (r_boot_st == 2'd0) ? 1'b1 :
                            (r_boot_st == 2'd1) ? 1'b0 :
                            i_rx_d1;

endmodule

`timescale 1ns / 1ps
module decoder_4_to_16(
	input [3:0]RegAdd,
	input WE,
	output reg [15:0]Out
    );

always @(*) begin
	if(WE == 0)
		Out = 0;
	else begin
		case(RegAdd)
			4'b0000: Out = 1;
			4'b0001: Out = 2;
			4'b0010: Out = 4;
			4'b0011: Out = 8;
			4'b0100: Out = 16;
			4'b0101: Out = 32;
			4'b0110: Out = 64;
			4'b0111: Out = 128;
			4'b1000: Out = 256;
			4'b1001: Out = 512;
			4'b1010: Out = 1024;
			4'b1011: Out = 2048;
			4'b1100: Out = 4096;
			4'b1101: Out = 8192;
			4'b1110: Out = 16384;
			4'b1111: Out = 32768;
		endcase
	end
end

endmodule

`timescale 1ns / 1ps

module KeyBoard_detection(
    input clk,
    input rst,
    input ps2_clk,
    input ps2_data, 
    output reg  [23:0] key  
    );

    reg [23:0] out;
    reg ps2_clk_r1,ps2_clk_r2; 
    wire ps2_clk_neg; 
    reg [3:0] ps2_clk_cnt; 

 always@(posedge clk or posedge rst) begin    
   if(rst)       
      ps2_clk_r1  <= 1'b1;   
   else        
      ps2_clk_r1  <= ps2_clk;     
 end 

 always@(posedge clk or posedge rst) begin     
    if(rst)        
        ps2_clk_r2  <= 1'b1;     
    else 
        ps2_clk_r2  <= ps2_clk_r1;
    end 

  assign ps2_clk_neg = (~ps2_clk_r1)&&(ps2_clk_r2);   

  always@(posedge clk or posedge rst) begin    
   if(rst)         
     ps2_clk_cnt <= 4'd0;    
   else if(ps2_clk_neg) begin         
     if(ps2_clk_cnt>=4'd10)            
       ps2_clk_cnt <= 4'd0;       
      else             
       ps2_clk_cnt <= ps2_clk_cnt + 4'd1;     
       end 
    end 


    always@(posedge clk or posedge rst) begin     
       if(rst)begin
        key <= 24'h0;        
        out   <= 24'h0;     
       end 
       else if(ps2_clk_neg)     
         begin        
           if((ps2_clk_cnt>=1)&&(ps2_clk_cnt<=8))            
             out <= { ps2_data,out[23:1]};
           if(ps2_clk_cnt==4'd9)
             key<=out; 
         end 
     end  

endmodule

module control(i_instrCode, 
               o_regDst,
               o_jump, 
               o_beq,
			         o_bne,
               o_memToReg,
               o_aluOp,
               o_memWrite,
               o_aluSrc_op2,
               o_regWrite,
               o_extOp,
               o_unknown_command
               );

localparam OP_RTYPE = 6'h0, OP_ADDI = 6'h8, OP_ADDIU = 6'h9;
localparam OP_LUI = 6'b001111, OP_ORI = 6'b001101, OP_XORI = 6'b001110;
localparam OP_ANDI = 6'b001100;
localparam OP_LW = 6'h23, OP_SW = 6'h2B;
localparam OP_BEQ = 6'h4, OP_J = 6'h2, OP_BNE = 6'h5;  
localparam OP_COP0 = 6'b010000;

input         [5:0]  i_instrCode; 
output    reg        o_regDst;
output    reg        o_jump; 
output    reg        o_beq;
output	  reg        o_bne;
output    reg        o_memToReg;
output    reg [5:0]  o_aluOp;
output    reg        o_memWrite;
output    reg        o_aluSrc_op2;
output    reg        o_regWrite;
output    reg        o_extOp;
output    reg        o_unknown_command;

always @(i_instrCode) begin
  o_regDst          = 1'b0;
  o_regWrite        = 1'b0;
  o_aluSrc_op2      = 1'b0;
  o_bne             = 1'b0;
  o_beq             = 1'b0;
  o_jump            = 1'b0;
  o_memWrite        = 1'b0;
  o_memToReg        = 1'b0;
  o_aluOp           = i_instrCode;
  o_extOp           = 1'b0;
  o_unknown_command = 1'b0;

    case(i_instrCode)
      OP_RTYPE: 
        begin
          o_regDst       = 1'b1;
		      o_regWrite     = 1'b1;
      	end
      OP_ADDI:
      	begin
		      o_regWrite    = 1'b1;
      		o_aluSrc_op2  = 1'b1;
      		o_extOp       = 1'b1;
      	end
      OP_ADDIU:
        begin
          o_regWrite    = 1'b1;
          o_aluSrc_op2  = 1'b1;
          o_extOp       = 1'b1;
        end
      OP_LUI:
        begin
          o_regWrite    = 1'b1;
          o_aluSrc_op2  = 1'b1;
        end
      OP_ORI:
        begin
          o_regWrite    = 1'b1;
          o_aluSrc_op2  = 1'b1;
        end
      OP_XORI:
        begin
          o_regWrite    = 1'b1;
          o_aluSrc_op2  = 1'b1;
        end
      OP_ANDI:
        begin
          o_regWrite    = 1'b1;
          o_aluSrc_op2  = 1'b1;
        end
  	  OP_LW:
	      begin
      		o_regWrite    = 1'b1;
      		o_aluSrc_op2  = 1'b1;
      		o_memToReg    = 1'b1;
      		o_extOp       = 1'b1;
      	end
  	  OP_SW:
	      begin
      		o_aluSrc_op2  = 1'b1;
      		o_memWrite    = 1'b1;
      		o_extOp       = 1'b1;
      	end
  	  OP_J:
	     	begin
      		o_jump	      = 1'b1;
      	end
  	  OP_BEQ:
      	begin
      		o_beq         = 1'b1;
      	end
      OP_BNE:
      	begin
			    o_bne	        = 1'b1;
      	end
      OP_COP0:
        begin
          o_regWrite    = 1'b1;
        end
      default:
        begin
          o_unknown_command = 1'b1;
        end
  	endcase
  end	
endmodule

