module Ctrl(

    input                   sys_clk         ,
    input                   sys_rst_n       ,

    input           [31:0]  data1_in        ,   
    input           [31:0]  data2_in        ,   
    input           [31:0]  plus_result_in  ,   
    input           [31:0]  multi_result_in ,   
    input           [31:0]  div_result_in   ,   
    output  reg     [31:0]  data1_out       ,   
    output  reg     [31:0]  data2_out       ,   
    output  reg     [31:0]  result_out      ,   

    input           [1:0]   opcode          ,   
    input                   trig            ,
    input                   plus_vld_in     ,   
    input                   multi_vld_in    ,
    input                   div_vld_in      ,
    output  reg             sel_plus        ,   
    output  reg             sel_multi       ,   
    output  reg             sel_div         ,
    output  reg             op_plus         ,   
    output  reg             work            ,   
    output  reg             result_vld          
);


localparam          IDLE    =   4'b0001,
                    PLUS    =   4'b0010,
                    MULTI   =   4'b0100,
                    DIV     =   4'b1000;

reg             [3:0]       next_state;
reg             [3:0]       state;



always@(posedge sys_clk or negedge sys_rst_n) begin
    if(~sys_rst_n) begin
        state   <=  4'b0;
    end
    else begin
        state   <=  next_state;
    end
end

always@(*) begin
    case(state)
        IDLE: begin
            if(trig) begin
                case(opcode)
                    2'b00:  next_state  =   PLUS;
                    2'b01:  next_state  =   PLUS;
                    2'b10:  next_state  =   MULTI;
                    2'b11:  next_state  =   DIV;
                    default:next_state  =   IDLE;       
                endcase
            end
            else begin
                next_state  =   IDLE;
            end
        end
        PLUS:   next_state  =   (plus_vld_in)   ?   IDLE    :   PLUS;  
        MULTI:  next_state  =   (multi_vld_in)  ?   IDLE    :   MULTI;  
        DIV:    next_state  =   (div_vld_in)    ?   IDLE    :   DIV;
        default:next_state  =   IDLE;
    endcase
end



always@(posedge sys_clk or negedge sys_rst_n) begin
    if(~sys_rst_n) begin
        sel_plus    <=  1'b0;
        sel_multi   <=  1'b0;
        sel_div     <=  1'b0;
        op_plus     <=  1'b0;
        data1_out   <=  32'b0;
        data2_out   <=  32'b0;
    end
    else if(state == IDLE && trig) begin
        data1_out   <=  data1_in;
        data2_out   <=  data2_in;
        op_plus     <=  opcode[0];

        case(opcode)
            2'b00:  {sel_plus, sel_multi, sel_div}  <=  3'b100;
            2'b01:  {sel_plus, sel_multi, sel_div}  <=  3'b100;
            2'b10:  {sel_plus, sel_multi, sel_div}  <=  3'b010;
            2'b11:  {sel_plus, sel_multi, sel_div}  <=  3'b001;
            default:{sel_plus, sel_multi, sel_div}  <=  3'b000;
        endcase
    end
    else begin
        sel_plus    <=  1'b0;
        sel_multi   <=  1'b0;
        sel_div     <=  1'b0;
        op_plus     <=  1'b0;
        data1_out   <=  32'b0;
        data2_out   <=  32'b0;
    end
end



always@(posedge sys_clk or negedge sys_rst_n) begin
    if(~sys_rst_n) begin
        result_out  <=  32'b0;      
    end
    else begin
        if(state != IDLE) begin
            if(plus_vld_in) begin
                result_out  <=  plus_result_in; 
            end
            else if(multi_vld_in) begin
                result_out  <=  multi_result_in;
            end
            else if(div_vld_in) begin
                result_out  <=  div_result_in;
            end
            else begin
                result_out  <=  result_out;
            end
        end
        else begin
            result_out  <=  result_out;
        end
    end
end

always@(posedge sys_clk or negedge sys_rst_n) begin
    if(~sys_rst_n) begin
        result_vld  <=  1'b0;       
    end
    else if(state != IDLE) begin
        result_vld  <=  plus_vld_in | multi_vld_in | div_vld_in;
    end
    else begin
        result_vld  <=  1'b0;
    end
end



always@(posedge sys_clk or negedge sys_rst_n) begin
    if(~sys_rst_n) begin
        work            <=  1'b0;
    end
    else if(state == IDLE && trig) begin
        work            <=  1'b1;
    end
    else if(state != IDLE && (plus_vld_in | multi_vld_in | div_vld_in)) begin
        work            <=  1'b0;
    end
    else begin
        work            <=  work;
    end
end

endmodule

module LPC_Peri (

  input  wire        lclk         , 
  input  wire        lreset_n     , 
  input  wire        lframe_n     , 
  inout  wire [ 3:0] lad_in       , 

  output reg [ 3:0]  lpc_data_out , 

  output reg         lpc_en       , 
  input  wire        addr_hit     , 
  output reg [15:0]  lpc_addr     , 
  input  wire [ 7:0] din          , 
  output reg  [ 7:0] lpc_data_in  , 
  output reg         io_rden_sm   ,
  output reg         io_wren_sm   ,
  inout int_serirq,					
  input [7:0] serirq                
);

reg [ 4:0] current_state;
reg lad_in_dir;

`define IDLE             5'h00
`define START            5'h01
`define IO_RD            5'h02
`define IO_RD_ADDR_LCLK1 5'h03
`define IO_RD_ADDR_LCLK2 5'h04
`define IO_RD_ADDR_LCLK3 5'h05
`define IO_RD_ADDR_LCLK4 5'h06
`define IO_RD_TAR_LCLK1  5'h07
`define IO_RD_TAR_LCLK2  5'h08
`define IO_RD_SYNC       5'h09
`define IO_RD_DATA_LCLK1 5'h0B
`define IO_RD_DATA_LCLK2 5'h0C
`define IO_WR            5'h0D
`define IO_WR_ADDR_LCLK1 5'h0E
`define IO_WR_ADDR_LCLK2 5'h0F
`define IO_WR_ADDR_LCLK3 5'h10
`define IO_WR_ADDR_LCLK4 5'h11
`define IO_WR_DATA_LCLK1 5'h12
`define IO_WR_DATA_LCLK2 5'h13
`define IO_WR_TAR_LCLK1  5'h14
`define IO_WR_TAR_LCLK2  5'h15
`define IO_WR_SYNC       5'h16

assign lad_in = lad_in_dir ? lpc_data_out : 4'bzzzz;


always @ (posedge lclk or negedge lreset_n) begin
  if (~lreset_n) begin
    current_state <= `IDLE;
    lpc_addr <= 0;
    io_rden_sm <= 0;
	io_wren_sm <= 0;
    lad_in_dir <= 0;
    lpc_data_in <= 0;
    lpc_en <= 0;
  end
  else begin
    case (current_state)
      `IDLE: begin
        lpc_addr <= 0;
        io_rden_sm <= 0;
		io_wren_sm <= 0;
        lad_in_dir <= 0;
        lpc_data_in <= 0;
        lpc_en <= 0;
        if ((lframe_n == 1'b0) && (lad_in == 4'h0))
          current_state <= `START;
        else
          current_state <= `IDLE;
      end
      `START: begin
        if((lframe_n == 1'b1) && (lad_in == 4'h0))
          current_state <= `IO_RD;
        else if((lframe_n == 1'b1) && (lad_in == 4'h2))
          current_state <= `IO_WR;
        else if((lframe_n == 1'b0) && (lad_in == 4'h0))
          current_state <= `START;
        else
          current_state <= `IDLE;
      end


      `IO_RD: begin
        if(lframe_n == 1'b1) begin
          lpc_addr[15:12] <= lad_in;
          current_state <= `IO_RD_ADDR_LCLK1;
        end
        else
          current_state <= `IDLE;
      end
      `IO_RD_ADDR_LCLK1: begin
        if(lframe_n == 1'b1) begin
          lpc_addr[11:8] <= lad_in;
          current_state <= `IO_RD_ADDR_LCLK2;
        end
        else
          current_state <= `IDLE;
      end
      `IO_RD_ADDR_LCLK2: begin
        if(lframe_n == 1'b1) begin
          lpc_addr[7:4] <= lad_in;
          current_state <= `IO_RD_ADDR_LCLK3;
        end
        else
          current_state <= `IDLE;
      end
      `IO_RD_ADDR_LCLK3: begin
        if(lframe_n == 1'b1) begin
          lpc_addr[3:0] <= lad_in;
          current_state <= `IO_RD_ADDR_LCLK4;
        end
        else
          current_state <= `IDLE;
      end
      `IO_RD_ADDR_LCLK4: begin
        if((lframe_n == 1'b1)&&(lad_in == 4'hf)) begin
          current_state <= `IO_RD_TAR_LCLK1;
          io_rden_sm <= 1;
          lpc_en <= 1;
        end
        else begin
          current_state <= `IDLE;
          io_rden_sm <= 0;
          lpc_en <= 0;
        end
      end
      `IO_RD_TAR_LCLK1: begin
        if((lframe_n == 1'b1)&&(addr_hit == 1'b1)) begin
          current_state <= `IO_RD_TAR_LCLK2;
          lad_in_dir <= 1;
          lpc_data_out <= 4'b0000;
        end
        else begin
          current_state <= `IDLE;
          lad_in_dir <= 0;
          lpc_data_out <= 0;
        end
      end
      `IO_RD_TAR_LCLK2: begin
        if(lframe_n == 1'b1) begin
          current_state <= `IO_RD_SYNC;
          lad_in_dir <= 1;
          lpc_data_out <= din[3:0];
        end
        else begin
          current_state <= `IDLE;
          lad_in_dir <= 0;
          lpc_data_out <= 0;
        end
      end
      `IO_RD_SYNC: begin
        if(lframe_n == 1'b1) begin
          current_state <= `IO_RD_DATA_LCLK1;
          lad_in_dir <= 1;
          lpc_data_out <= din[7:4];
        end
        else begin
          current_state <= `IDLE;
          lad_in_dir <= 0;
          lpc_data_out <= 0;
        end
      end
      `IO_RD_DATA_LCLK1: begin
        if(lframe_n == 1'b1) begin
          current_state <= `IO_RD_DATA_LCLK2;
          lad_in_dir <= 1;
          lpc_data_out <= 4'b1111;
        end
        else begin
          current_state <= `IDLE;
          lad_in_dir <= 0;
          lpc_data_out <= 0;
        end
      end
      `IO_RD_DATA_LCLK2: begin
          current_state <= `IDLE;
          lad_in_dir <= 0;
          lpc_data_out <= 0;
          lpc_en <= 0;
      end


      `IO_WR: begin
        if(lframe_n == 1'b1) begin
          lpc_addr[15:12] <= lad_in;
          current_state <= `IO_WR_ADDR_LCLK1;
        end
        else
          current_state <= `IDLE;
      end
      `IO_WR_ADDR_LCLK1: begin
        if(lframe_n == 1'b1) begin
          lpc_addr[11:8] <= lad_in;
          current_state <= `IO_WR_ADDR_LCLK2;
        end
        else
          current_state <= `IDLE;
      end
      `IO_WR_ADDR_LCLK2: begin
        if(lframe_n == 1'b1) begin
          lpc_addr[7:4] <= lad_in;
          current_state <= `IO_WR_ADDR_LCLK3;
        end
        else
          current_state <= `IDLE;
      end
      `IO_WR_ADDR_LCLK3: begin
        if(lframe_n == 1'b1) begin
          lpc_addr[3:0] <= lad_in;
          current_state <= `IO_WR_ADDR_LCLK4;
        end
        else
          current_state <= `IDLE;
      end
      `IO_WR_ADDR_LCLK4: begin
        if(lframe_n == 1'b1) begin
          current_state <= `IO_WR_DATA_LCLK1;
          lpc_data_in[3:0] <= lad_in;
        end
        else begin
          current_state <= `IDLE;
          lpc_data_in <= 0;
        end
      end
      `IO_WR_DATA_LCLK1: begin
        if(lframe_n == 1'b1) begin
          current_state <= `IO_WR_DATA_LCLK2;
          lpc_data_in[7:4] <= lad_in;
        end
        else begin
          current_state <= `IDLE;
          lpc_data_in <= 0;
        end
      end
      `IO_WR_DATA_LCLK2: begin
        if((lframe_n == 1'b1)&&(lad_in == 4'hf)) begin
          current_state <= `IO_WR_TAR_LCLK1;
          io_wren_sm <= 1;
          lpc_en <= 1;
        end
        else begin
          current_state <= `IDLE;
          io_wren_sm <= 0;
          lpc_en <= 0;
        end
      end
      `IO_WR_TAR_LCLK1: begin
        if((lframe_n == 1'b1)&&(addr_hit == 1'b1)) begin
          current_state <= `IO_WR_TAR_LCLK2;
          lad_in_dir <= 1;
          lpc_data_out <= 4'b0000;
        end
        else begin
          current_state <= `IDLE;
          lad_in_dir <= 0;
          lpc_data_out <= 0;
        end
      end
      `IO_WR_TAR_LCLK2: begin
        if(lframe_n == 1'b1) begin
          current_state <= `IO_WR_SYNC;
          lad_in_dir <= 1;
          lpc_data_out <= 4'b1111;
        end
        else begin
          current_state <= `IDLE;
          lad_in_dir <= 0;
          lpc_data_out <= 0;
        end
      end
      `IO_WR_SYNC: begin
        lad_in_dir <= 0;
        lpc_data_out <= 0;
        lpc_en <= 0;
        current_state <= `IDLE;
      end
      default: begin
        lpc_addr <= 0;
        io_rden_sm <= 0;
		io_wren_sm <= 0;
        lad_in_dir <= 0;
        lpc_data_in <= 0;
        lpc_en <= 0;
        current_state <= `IDLE;
      end
	endcase
  end
end


reg [5:0] serirq_cnt;
reg [3:0] serirq_shift; 
reg [1:0] irq_state;
wire serirq_dir;
wire serirq_data;

`define IRQIDLE          2'b00
`define IRQSTART         2'b01
`define IRQDOING         2'b10

assign int_serirq = serirq_dir ? ~serirq_data : 1'bz;
assign serirq_data = ((serirq_cnt == 6'h02) && serirq[0])				
					|| ((serirq_cnt == 6'h05) && serirq[1])				
					|| ((serirq_cnt == 6'h08) && serirq[2])				
					|| ((serirq_cnt == 6'h0b) && serirq[3])				
					|| ((serirq_cnt == 6'h0e) && serirq[4])				

					|| ((serirq_cnt == 6'h11) && serirq[5])				
					|| ((serirq_cnt == 6'h14) && serirq[6])				
					|| ((serirq_cnt == 6'h17) && serirq[7]);			

assign serirq_dir = (((serirq_cnt == 6'h02) || (serirq_cnt == 6'h03)) && serirq[0])			
					|| (((serirq_cnt == 6'h05) || (serirq_cnt == 6'h06)) && serirq[1])		
					|| (((serirq_cnt == 6'h08) || (serirq_cnt == 6'h09)) && serirq[2])		
					|| (((serirq_cnt == 6'h0b) || (serirq_cnt == 6'h0c)) && serirq[3])		
					|| (((serirq_cnt == 6'h0e) || (serirq_cnt == 6'h0f)) && serirq[4])		

					|| (((serirq_cnt == 6'h11) || (serirq_cnt == 6'h12)) && serirq[5])		
					|| (((serirq_cnt == 6'h14) || (serirq_cnt == 6'h15)) && serirq[6])		
					|| (((serirq_cnt == 6'h17) || (serirq_cnt == 6'h18)) && serirq[7]);		

always @ (posedge lclk or negedge lreset_n) begin
	if (~lreset_n) begin
		irq_state <= `IRQIDLE;
		serirq_cnt <= 0;
		serirq_shift <= 4'b1111;
	end
	else begin
		case (irq_state)
			`IRQIDLE: begin
				serirq_cnt <= 0;
				serirq_shift <= 4'b1111;
				irq_state <= `IRQSTART;
			end
			`IRQSTART: begin
				serirq_shift[0] <= int_serirq;
				serirq_shift[3:1] <= serirq_shift[2:0];
				if({serirq_shift, int_serirq}== 5'b0_0001) begin
					irq_state <= `IRQDOING;
					serirq_cnt <= 2; 
				end
				else begin
					irq_state <= irq_state;
					serirq_cnt <= 0;
				end
			end
			`IRQDOING: begin
				serirq_cnt <= serirq_cnt + 1;
				if(serirq_cnt <= 62)
					irq_state <= irq_state;
				else
					irq_state <= `IRQIDLE;
			end
			default: begin
				serirq_cnt <= 0;
				serirq_shift <= 4'b1111;
				irq_state <= `IRQSTART;
			end
		endcase
	end
end

endmodule

module FSM (
        input   wire                CLK,
        input   wire                RST_n,


        input   wire                start,
        output  reg                 done,


        input   wire                done_vec,
        output  reg                 valid_vec,


        output  reg                 valid_regfile,
        output  reg     [1:0]       opr_regfile,


        input   wire                done_rot1,
        input   wire                done_rot2,
        input   wire                done_rot3,
        output  reg                 valid_rot1,
        output  reg                 valid_rot2,
        output  reg                 valid_rot3,


        output  reg                 valid_transpose,
        output  reg                 start_transpose,


        input   wire                done_inverse,
        output  reg                 valid_inverse,
        output  reg                 start_inverse,


        input   wire                done_mul,
        output  reg                 valid_mul
    );


    localparam  [2:0]   IDLE             = 3'b000,
                        VEC_START        = 3'b001,
                        VEC_ROT_BUSY     = 3'b011,
                        ROT_LAST_UPDATE  = 3'b010,
                        VEC_INVERSE      = 3'b110,
                        MUL_READY        = 3'b111,
                        MUL_BUSY         = 3'b101;


    reg     [2:0]   curr_state, next_state;


    reg     [3:0]   count;


    reg             clear_counter, increment_counter;




    reg             valid_vec_reg;
    reg             valid_rot1_reg;
    reg             valid_rot2_reg;
    reg             valid_rot3_reg;
    reg             valid_transpose_reg;
    reg             valid_mul_reg;
    reg             valid_inverse_reg;

    always @(posedge CLK or negedge RST_n) begin

        if(!RST_n) begin


            curr_state <= IDLE;
        end
        else begin


            curr_state <= next_state;
        end
    end

    always @(*) begin




        valid_vec_reg = 1'b0;
        valid_rot1_reg = 1'b0;
        valid_rot2_reg = 1'b0;
        valid_rot3_reg = 1'b0;
        valid_transpose_reg = 1'b0;
        valid_mul_reg = 1'b0;
        valid_inverse_reg = 1'b0;


        done = 1'b0;


        opr_regfile = 'b0;
        valid_regfile = 1'b0;


        start_transpose = 1'b0;


        start_inverse = 1'b0;


        clear_counter = 1'b0;
        increment_counter = 1'b0;


        case (curr_state)
            IDLE: begin

                if(start) begin


                    next_state = VEC_START;
                end
                else begin


                    next_state = IDLE;
                end


                opr_regfile = 'b01;

                if(start) begin


                    valid_vec_reg = 1'b1;



                    valid_regfile = 1'b1;
                end
                else begin


                    valid_vec_reg = 1'b0;


                    valid_regfile = 1'b0;
                end
            end
            VEC_START: begin

                if(done_vec) begin


                    next_state = VEC_ROT_BUSY;
                end
                else begin


                    next_state = VEC_START;
                end


                opr_regfile = 'b01;

                if(done_vec) begin


                    valid_vec_reg = 1'b1;
                    valid_rot1_reg = 1'b1;
                    valid_rot2_reg = 1'b1;
                    valid_rot3_reg = 1'b1;


                    valid_regfile = 1'b1;


                    clear_counter = 1'b1;
                end
                else begin


                    valid_vec_reg = 1'b0;
                    valid_rot1_reg = 1'b0;
                    valid_rot2_reg = 1'b0;
                    valid_rot3_reg = 1'b0;


                    valid_regfile = 1'b0;


                    clear_counter = 1'b0;
                end
            end
            VEC_ROT_BUSY: begin

                if(count == 'b11) begin


                    next_state = ROT_LAST_UPDATE;
                end
                else begin


                    next_state = VEC_ROT_BUSY;
                end


                opr_regfile = 'b01;

                if(done_vec || (done_rot1 && done_rot2) || done_rot3) begin

                    if(count == 'b0) begin


                        valid_rot3_reg = 1'b1;
                    end
                    else begin


                        valid_rot3_reg = 1'b0;
                    end

                    if((count == 'b1)) begin


                        valid_vec_reg = 1'b1;
                    end
                    else begin


                        valid_vec_reg = 1'b0;
                    end

                    if((count != 'b1)) begin


                        valid_rot1_reg = 1'b1;
                        valid_rot2_reg = 1'b1;
                    end
                    else begin


                        valid_rot1_reg = 1'b0;
                        valid_rot2_reg = 1'b0;
                    end

                    if(((count == 'b0) || (count == 'b1)) && (done_rot1 && done_rot2)) begin


                        valid_transpose_reg = 1'b1;
                    end
                    else begin


                        valid_transpose_reg = 1'b0;
                    end


                    valid_regfile = 1'b1;


                    increment_counter = 1'b1;
                end
                else begin


                    valid_vec_reg = 1'b0;
                    valid_rot1_reg = 1'b0;
                    valid_rot2_reg = 1'b0;
                    valid_rot3_reg = 1'b0;


                    valid_transpose_reg = 1'b0;


                    valid_regfile = 1'b0;


                    increment_counter = 1'b0;
                end
            end
            ROT_LAST_UPDATE: begin

                if(done_rot1 && done_rot2) begin


                    next_state = VEC_INVERSE;
                end
                else begin


                    next_state = ROT_LAST_UPDATE;
                end


                opr_regfile = 'b01;

                if(done_rot1 && done_rot2) begin


                    valid_transpose_reg = 1'b1;


                    valid_regfile = 1'b1;


                    valid_inverse_reg = 1'b1;


                    clear_counter = 1'b1;
                end
                else begin


                    valid_transpose_reg = 1'b0;


                    valid_regfile = 1'b0;


                    valid_inverse_reg = 1'b0;


                    clear_counter = 1'b0;
                end
            end
            VEC_INVERSE: begin

                if(count == 'b11) begin


                    next_state = MUL_READY;
                end
                else begin


                    next_state = VEC_INVERSE;
                end


                opr_regfile = 'b10;

                if(done_inverse) begin

                    if(count != 'b10) begin


                        valid_inverse_reg = 1'b1;


                        valid_regfile = 1'b1;
                    end
                    else begin


                        valid_inverse_reg = 1'b0;


                        valid_regfile = 1'b0;
                    end


                    increment_counter = 1'b1;
                end
                else begin


                    valid_inverse_reg = 1'b0;


                    valid_regfile = 1'b0;


                    increment_counter = 1'b0;
                end

                if(count == 'b11) begin


                    clear_counter = 1'b1;
                end
                else begin


                    clear_counter = 1'b0;
                end
            end
            MUL_READY: begin

                if(count == 'b1000) begin


                    next_state = MUL_BUSY;
                end
                else begin


                    next_state = MUL_READY;
                end


                increment_counter = 1'b1;


                start_transpose = 1'b1;


                start_inverse = 1'b1;


                valid_mul_reg = 1'b1;


                if(count == 'b1000) begin


                    clear_counter = 'b1;
                end
                else begin


                    clear_counter = 'b0;
                end
            end
            MUL_BUSY: begin

                if(count == 'b1000) begin


                    next_state = IDLE;
                end
                else begin


                    next_state = MUL_BUSY;
                end

                if(done_mul) begin


                    done = 1'b1;


                    increment_counter = 'b1;
                end
                else begin


                    done = 1'b0;


                    increment_counter = 'b0;
                end
            end
            default: begin


                next_state = IDLE;
            end
        endcase
    end

    always @(posedge CLK or negedge RST_n) begin

        if (!RST_n) begin


            valid_vec <= 'b0;
            valid_rot1 <= 'b0;
            valid_rot1 <= 'b0;
            valid_rot1 <= 'b0;
            valid_transpose <= 'b0;
            valid_mul <= 'b0;
            valid_inverse <= 'b0;
        end else begin


            valid_vec <= valid_vec_reg;
            valid_rot1 <= valid_rot1_reg;
            valid_rot2 <= valid_rot2_reg;
            valid_rot3 <= valid_rot3_reg;
            valid_transpose <= valid_transpose_reg;
            valid_mul <= valid_mul_reg;
            valid_inverse <= valid_inverse_reg;
        end
    end
    always @(posedge CLK or negedge RST_n) begin

        if(!RST_n) begin


            count <= 'b0;
        end
        else if (clear_counter) begin


            count <= 'b0;
        end
        else if (increment_counter) begin


            count <= count + 'b1;
        end
    end


endmodule

module CONTROLLER #(parameter flit_width=16, MAX_Packet_NUM=8)
(
input    wire                        clk,
input    wire                        rst,
input    wire                        Arb_valid,
input    wire    [1:0]               SEL_VC,
input    wire                        VC_selected,
input    wire    [flit_width-1:0]    read_O,
input    wire                        VC_ANSWER,
input    wire                        SW_ANSWER,
input    wire                        ROUTE_DONE,
input    wire   [2:0]                DIRECTION,
output   reg                         ready,
output   reg    [3:0]                Route_info,
output   reg                         Start_route,
output   reg    [4:0]                Vc_request,
output   reg                         valid_vc_req,
output   reg    [2:0]                Sw_request,
output   reg                         Valid_sw_req,
output   reg                         clear
);



localparam IDLE           =3'b000,
           FLIT_STORE     =3'b001,
			  TYPE_SELECTION =3'b010,
			  ROUTING        =3'b011,
			  ASK_VC         =3'b100,
			  ASK_SW         =3'b101,
			  DONE           =3'b110;




wire  [2:0] 	           sequance_num;
reg   [flit_width-1:0]    Flit_mem;
reg   [2:0]               mem_comb;
reg   [2:0]               current_state,
                          next_state;

reg   [2:0]               route_mem [MAX_Packet_NUM-1:0] ;




assign sequance_num = Flit_mem[6:4];			  



 always @ (posedge clk or negedge rst)
   begin
	   if(!rst)
		  begin
		    route_mem[0]<=3'b0;
			 route_mem[1]<=3'b0;
			 route_mem[2]<=3'b0;
			 route_mem[3]<=3'b0;
			 route_mem[4]<=3'b0;
			 route_mem[5]<=3'b0;
			 route_mem[6]<=3'b0;
			 route_mem[7]<=3'b0;
		  end
		else
		   route_mem[sequance_num] <= mem_comb;
	end






always@(posedge clk or negedge rst)
  begin
     if(!rst)
	    current_state<= IDLE;
		else
		 current_state <= next_state;
  end



always@(*)
  begin
    case(current_state)
	   IDLE           :begin
		                   if(Arb_valid)
								    next_state = FLIT_STORE;
								 else
								    next_state = IDLE;
		                end
		FLIT_STORE     :begin
		                   if(VC_selected)
								   next_state = TYPE_SELECTION; 
								 else
								   next_state = FLIT_STORE;
		                end
		TYPE_SELECTION :begin
		                   if(Flit_mem[3:2]==2'b00)
								   next_state = ROUTING;
								 else
		                     next_state = ASK_VC;
		                end
		ROUTING        :begin
		                   if(ROUTE_DONE)
								   next_state = ASK_VC;
								 else
		                     next_state = ROUTING;
		                end
		ASK_VC         :begin
		                   if(VC_ANSWER)
								   next_state = ASK_SW;
								 else
		                     next_state = ASK_VC;
		                end 
		ASK_SW         :begin
		                   if(SW_ANSWER)
								   next_state = DONE;
								 else
		                     next_state = ASK_SW;
		                end
		DONE           :begin
		                   if(Arb_valid)
								    next_state = FLIT_STORE;
								 else
								    next_state = IDLE;
		                end
		default        :begin
		                      next_state = IDLE;
		                end

	 endcase
  end



always@(*)
  begin
    ready                    = 1'b0;
	 Start_route              = 1'b0;
	 valid_vc_req             = 1'b0;
	 Valid_sw_req             = 1'b0;
	 clear                    = 1'b0;
	 Flit_mem                 = read_O;
	 Route_info               = Flit_mem[10:7];
	 mem_comb                 = route_mem[sequance_num];
	 Vc_request               = {route_mem[sequance_num],SEL_VC};
	 Sw_request               = route_mem[sequance_num];

    case(current_state)
	   IDLE           :begin
		                  ready= 1'b1;
		                end
		FLIT_STORE     :begin
		                   if(VC_selected) 
								   Flit_mem = read_O;
								 else
								   Flit_mem = read_O;
		                end
		TYPE_SELECTION :begin
		                   if(Flit_mem[3:2]==2'b00)              
								   begin
									  Route_info = Flit_mem[10:7];
									  Start_route = 1'b1;
									end
								 else if(Flit_mem[3:2]==2'b01)         
		                      begin
									   Vc_request = {route_mem[sequance_num],SEL_VC};  
										valid_vc_req = 1'b1;
										Start_route = 1'b0;
									 end
								    begin
									   Vc_request = {route_mem[sequance_num],SEL_VC}; 
										valid_vc_req = 1'b1;
										Start_route = 1'b0;

									 end
		                end
		ROUTING        :begin
		                   if(ROUTE_DONE)
								   begin
									  Start_route = 1'b0;
									  Vc_request = {DIRECTION,SEL_VC};
									  valid_vc_req = 1'b1;
									  mem_comb = DIRECTION;  
									end
								 else
								   begin
									  Start_route = 1'b1;
									  Route_info = Flit_mem[10:7];
									  valid_vc_req = 1'b0;
									end
		                end
		ASK_VC         :begin
		                   if(VC_ANSWER)
								   begin
								      Sw_request = route_mem[sequance_num];
										Valid_sw_req = 1'b1;
									   valid_vc_req = 1'b0;

									end
							    else	
								   begin
									   Vc_request = {route_mem[sequance_num],SEL_VC};
									   valid_vc_req = 1'b1;
								   end	

		                end 
		ASK_SW         :begin
		                   if(SW_ANSWER)
								   begin
									   Valid_sw_req = 1'b0;
									end
								 else
								   begin
									   Sw_request = route_mem[sequance_num];
										Valid_sw_req = 1'b1;
									end
		                end
		DONE           :begin
		                     clear = 1'b1;
								   ready = 1'b1;	
		                   if(Flit_mem[3:2]==2'b10)              
								   mem_comb = 3'b0;
								 else
								   mem_comb = route_mem[sequance_num];	
		                end
		default        :begin
                         ready                    = 1'b0;
	                      Start_route              = 1'b0;
	                      valid_vc_req             = 1'b0;
	                      Valid_sw_req             = 1'b0;
	                      clear                    = 1'b0;
	                      Flit_mem                 = read_O;
	                      Route_info               = Flit_mem[10:7];
	                      mem_comb                 = route_mem[sequance_num];
	                      Vc_request               = {route_mem[sequance_num],SEL_VC};
	                      Sw_request               = route_mem[sequance_num];
	                      Valid_sw_req             = 1'b0;		
		                end

	 endcase
  end



endmodule

`timescale 1ns / 1ps



















module mem_addr_generator(
    input rst,
    input clk,
    input down_velocity,next_picture_delay,
    input [1:0] level,
    input [4:0] key_alphabet,
    input [7:0] random,
    input [9:0] h_cnt,
    input [9:0] v_cnt,
    output reg [4:0] life,
    output reg [9:0] point,
    output reg [15:0] pixel_addr
    );

wire [2:0] column;

reg [4:0] tmp_life;
reg [9:0] tmp_point;
reg [3:0] tmp_step;
wire [9:0] tmp_point_equal;
wire [4:0] alphabet; 
reg [2:0] entering_column; 
reg [4:0] entering_alphabet;
reg [2:0] column_1st,column_2nd,column_3rd,column_4th,column_5th,column_6th;
reg [4:0] alphabet_1st,alphabet_2nd,alphabet_3rd,alphabet_4th,alphabet_5th,alphabet_6th,alphabet_7th;
reg [3:0] step;
reg [4:0] tmp_alphabet_7th;

reg fsm_out,state,tmp_state;
reg [4:0] present_alphabet_4th,present_alphabet_5th;    
wire [4:0] last_alphabet_4th,last_alphabet_5th;    



assign column = random [2:0] ;     
assign alphabet = random [7:3] ;

always@(negedge next_picture_delay or posedge rst)
if(rst)
begin
    entering_column <= 3'd0;
    entering_alphabet <= 5'd0;
end
else
begin
    entering_column <= column ;
    entering_alphabet <= alphabet ;         
end



always@(posedge next_picture_delay or posedge rst)
if(rst)
begin
    column_1st <= 3'd5 ;
    alphabet_1st <= 5'd18 ;
end    
else
begin
if((entering_alphabet>26))
begin
    column_1st <= entering_column;
    alphabet_1st <= entering_alphabet - 5'd26;
end
else 
begin
    column_1st <= entering_column ;
    alphabet_1st <= entering_alphabet ;    
end 
end   

always@(posedge next_picture_delay or posedge rst)
if(rst)
begin
    column_2nd <= 3'd3 ;
    alphabet_2nd <= 5'd21 ;
end    
else
begin
    column_2nd <= column_1st ;
    alphabet_2nd <= alphabet_1st ;
end   

always@(posedge next_picture_delay or posedge rst)
if(rst)
begin
    column_3rd <= 3'd6 ;
    alphabet_3rd <= 5'd13 ;
end    
else
begin
    column_3rd <= column_2nd ;
    alphabet_3rd <= alphabet_2nd ;
end    

always@(posedge next_picture_delay or posedge rst)
if(rst)
begin
    column_4th <= 3'd5 ;
    alphabet_4th <= 5'd4 ;
end    
else
begin
    column_4th <= column_3rd ;
    alphabet_4th <= alphabet_3rd ;
end

always@(posedge next_picture_delay or posedge rst)
if(rst)
begin
    column_5th <= 3'd0 ;
    alphabet_5th <= 5'd0 ;
end    
else
begin
    column_5th <= column_4th ;
    alphabet_5th <= alphabet_4th ;
end    

always@(posedge next_picture_delay or posedge rst)
if(rst)
begin
    column_6th <= 3'd0 ;
    alphabet_6th <= 5'd0 ;
end    
else
begin
    column_6th <= column_5th ;
    alphabet_6th <= alphabet_5th ;
end



assign last_alphabet_4th = alphabet_4th;

always@(posedge down_velocity or posedge rst)
if(rst)
    present_alphabet_4th <= 0;
else
    present_alphabet_4th <= last_alphabet_4th;

assign last_alphabet_5th = alphabet_5th;

always@(posedge down_velocity or posedge rst)
if(rst)
    present_alphabet_5th <= 0;
else
    present_alphabet_5th <= last_alphabet_5th;

always@*
case(state)
1'b0:
begin
    fsm_out=0;
    if(key_alphabet==alphabet_6th)
        tmp_state =1;
    else
        tmp_state =0;
end
1'b1:
begin
fsm_out=1;
    if(present_alphabet_5th!=last_alphabet_5th||present_alphabet_4th!=last_alphabet_4th)
        tmp_state =0;
    else
        tmp_state =1;
end
endcase


always@( posedge clk or posedge rst)
if(rst)
    state <= 0;
else
    state <= tmp_state;


always @* begin
    if(life==5'd0)
    begin
        tmp_point = point;
        tmp_life = 5'd0;
    end
    else
        if(key_alphabet == alphabet_6th||alphabet_6th==5'd0)
        begin
            tmp_point = point + (2 * level + 1);
            tmp_life = life; 
        end
        else
        begin
            tmp_life = life -1;
            tmp_point = point;
        end
end
always @(posedge next_picture_delay or posedge rst) begin
    if(rst)
    begin
        point <= 10'b0;
        life <= 5'd16;
    end
    else
    begin
        point <= tmp_point;
        life <= tmp_life;
    end
end

always@*
if(step>=4'd9)
    tmp_step = 0;
else
    tmp_step = step +1;

always@(posedge down_velocity or posedge rst)
if(rst)
    step <= 4'd0;
else
    step <= tmp_step;




always@*
if((life==5'd0))
begin
if((h_cnt>=220)&&(h_cnt<270)&&(v_cnt>=190)&&(v_cnt<240))    
    pixel_addr= 6*2500+((v_cnt-190)*50+(h_cnt-220));
else if((h_cnt>=270)&&(h_cnt<320)&&(v_cnt>=190)&&(v_cnt<240))    
    pixel_addr= ((v_cnt-190)*50+(h_cnt-270));
else if((h_cnt>=320)&&(h_cnt<370)&&(v_cnt>=190)&&(v_cnt<240))    
    pixel_addr= 12*2500+((v_cnt-190)*50+(h_cnt-320));
else if((h_cnt>=370)&&(h_cnt<420)&&(v_cnt>=190)&&(v_cnt<240))    
        pixel_addr= 4*2500+((v_cnt-190)*50+(h_cnt-370)); 
else if((h_cnt>=220)&&(h_cnt<270)&&(v_cnt>=240)&&(v_cnt<290))    
        pixel_addr= 14*2500+((v_cnt-240)*50+(h_cnt-220));
else if((h_cnt>=270)&&(h_cnt<320)&&(v_cnt>=240)&&(v_cnt<290))    
        pixel_addr= 21*2500+((v_cnt-240)*50+(h_cnt-270));                   
else if((h_cnt>=320)&&(h_cnt<370)&&(v_cnt>=240)&&(v_cnt<290))    
        pixel_addr= 4*2500+((v_cnt-240)*50+(h_cnt-320));
else if((h_cnt>=370)&&(h_cnt<420)&&(v_cnt>=240)&&(v_cnt<290))    
        pixel_addr= 17*2500+((v_cnt-240)*50+(h_cnt-370));
else
    pixel_addr=1;                                            
end
else
begin
if((h_cnt<120)&&(v_cnt>=250)&&(v_cnt<350)||(h_cnt>=520)&&(v_cnt>=250)&&(v_cnt<350))
    pixel_addr = 0; 
else if((h_cnt>=(column_1st*50+120))&&(h_cnt<(column_1st*50+170))&&(v_cnt>=(step*5))&&(v_cnt<(step*5+50)))
begin
    if(alphabet_1st==5'd0)
        pixel_addr = 1;
    else
        pixel_addr = (alphabet_1st-1)*2500+((v_cnt-5*step)*50+(h_cnt-120-column_1st*50));
end
else if((h_cnt>=(column_2nd*50+120))&&(h_cnt<(column_2nd*50+170))&&(v_cnt>=(50+step*5))&&(v_cnt<(step*5+100)))
begin
    if(alphabet_2nd==5'd0)
        pixel_addr = 1;
    else
        pixel_addr = (alphabet_2nd-1)*2500+((v_cnt-5*step-50)*50+(h_cnt-120-column_2nd*50));
end
else if((h_cnt>=(column_3rd*50+120))&&(h_cnt<(column_3rd*50+170))&&(v_cnt>=(100+step*5))&&(v_cnt<(step*5+150)))
begin
    if(alphabet_3rd==5'd0)
        pixel_addr = 1;
    else
        pixel_addr = (alphabet_3rd-1)*2500+((v_cnt-5*step-100)*50+(h_cnt-120-column_3rd*50));
end
else if((h_cnt>=(column_4th*50+120))&&(h_cnt<(column_4th*50+170))&&(v_cnt>=(150+step*5))&&(v_cnt<(step*5+200)))
begin
    if(alphabet_4th==5'd0)
        pixel_addr = 1;
    else
        pixel_addr = (alphabet_4th-1)*2500+((v_cnt-5*step-150)*50+(h_cnt-120-column_4th*50));
end
else if((h_cnt>=(column_5th*50+120))&&(h_cnt<(column_5th*50+170))&&(v_cnt>=(200+step*5))&&(v_cnt<(step*5+250)))
begin
    if(alphabet_5th==5'd0)
        pixel_addr = 1;
    else
        pixel_addr = (alphabet_5th-1)*2500+((v_cnt-5*step-200)*50+(h_cnt-120-column_5th*50));
end
else if((h_cnt>=(column_6th*50+120))&&(h_cnt<(column_6th*50+170))&&(v_cnt>=(250+step*5))&&(v_cnt<(step*5+300)))
begin
    if(alphabet_6th==5'd0||fsm_out)
        pixel_addr = 1;
    else
        pixel_addr = (alphabet_6th-1)*2500+((v_cnt-5*step-250)*50+(h_cnt-120-column_6th*50));
end
else
    pixel_addr = 1; 
end

endmodule

