module PID(
	input i_Clk,
	input [13:0]number_of_pulses,
	input [4:0]SW,
	input PID_timer,
	output reset_nop_0,
	input reset,
	output [13:0]signal_dc,
	input [35:0] KP,
	input [35:0] KI,
	input [35:0] KD


);

	reg reset_nop;
	assign reset_nop_0 = reset_nop;

	reg [2:0]PID_STATE;
	reg [35:0]sample_data;
	wire [35:0]mult_out_0, mult_out_1, mult_out_2, mult_out_3;
	reg [35:0]mult_out_0_reg, mult_out_1_reg, mult_out_2_reg, mult_out_3_reg;
	wire [71:0]mult_step_0, mult_step_1, mult_step_2, mult_step_3;
	reg [35:0]current_speed, desired_speed;
	reg [35:0]e_speed ,e_speed_pre, e_speed_sum, e_speed_de, pwm_pulse;
	reg [13:0]dc_out;




	parameter	WAIT_TIME = 3'd0,
				CALCULATE_PWM_0 = 3'd1,
				CALCULATE_PWM_1 = 3'd2,
				CALCULATE_PWM_2 = 3'd3,
				CALCULATE_PWM_3 = 3'd4,
				CALCULATE_PWM_4 = 3'd5,
				CALCULATE_PWM_5 = 3'd6,
				LIMIT_CHECK = 3'd7;

	parameter 	FP_36_9_d10 = 36'b1010_000_000_000;




	assign signal_dc = dc_out;

	always@(posedge i_Clk) 
	begin	
		case(PID_STATE)
			WAIT_TIME: begin
				if(reset)begin
					PID_STATE <= WAIT_TIME;	
					reset_nop <= 1'b1;					
					e_speed_pre <= 0;
					e_speed <= 0;
					e_speed_sum <= 0;
					pwm_pulse <= 0;
					dc_out <= 0;
				end
				else if(PID_timer)begin
					sample_data <= {1'b0, 12'b0, number_of_pulses, 9'b0};
					desired_speed <= {1'b0, 21'b0, SW[4:0], 9'b0};
					reset_nop <= 1'b1;
					PID_STATE <= CALCULATE_PWM_0;
				end
				else begin
					reset_nop <= 1'b0;
					PID_STATE <= WAIT_TIME;
					dc_out <= pwm_pulse[22:9];
				end
			end
			CALCULATE_PWM_0: begin
				mult_out_0_reg <= mult_out_0;
				PID_STATE <= CALCULATE_PWM_1;
			end
			CALCULATE_PWM_1: begin
				current_speed <= mult_out_0_reg >>  9;
				PID_STATE <= CALCULATE_PWM_2;
			end
			CALCULATE_PWM_2: begin
				e_speed <= desired_speed - current_speed;
				PID_STATE <= CALCULATE_PWM_3;
			end
			CALCULATE_PWM_3: begin
				mult_out_1_reg <= mult_out_1;
				mult_out_2_reg <= mult_out_2;
				e_speed_de <= (e_speed - e_speed_pre);
				PID_STATE <= CALCULATE_PWM_4;
			end
			CALCULATE_PWM_4: begin
				mult_out_3_reg <= mult_out_3;
				pwm_pulse <= mult_out_2_reg + mult_out_1_reg;
				PID_STATE <= CALCULATE_PWM_5;
			end
			CALCULATE_PWM_5: begin
				pwm_pulse <= pwm_pulse + mult_out_3_reg;
				e_speed_pre <= e_speed;  				
				e_speed_sum <= e_speed_sum + e_speed; 	
				PID_STATE <= LIMIT_CHECK;
			end
			LIMIT_CHECK: begin
				if(pwm_pulse[22:9] > 14'd10_000) begin
					pwm_pulse[22:9] <= 14'd10_000;
				end
				PID_STATE <= WAIT_TIME;
			end
			default: begin
				PID_STATE <= WAIT_TIME;
			end
		endcase
	end

	assign mult_step_0 = $signed(sample_data) * $signed(FP_36_9_d10);
	assign mult_out_0 = {mult_step_0[71], mult_step_0[43:9]};

	assign mult_step_1 = $signed(e_speed) * $signed(KP);
	assign mult_out_1 = {mult_step_1[71], mult_step_1[43:9]};

	assign mult_step_2 = $signed(e_speed_sum) * $signed(KI);
	assign mult_out_2 = {mult_step_2[71], mult_step_2[43:9]};

	assign mult_step_3 = $signed(e_speed_de) * $signed(KD);
	assign mult_out_3 = {mult_step_3[71], mult_step_3[43:9]};



endmodule

module Zicsr (
    input  wire          clk,
    input  wire          reset,

    input  wire  [11:0]  index,
    input  wire  [31:0]  data,
    input  wire  [1:0]   opcode,
    input  wire          mret,

    input  wire          exception,
    input  wire  [3:0]   exceptionType,
    input  wire  [31:0]  exceptionPC,

    input  wire          NMI,
    input  wire          timerInterrupt,
    input  wire  [15:0]  externalInterrupts,
    input  wire          stalled,

    output reg           interrupt_reg,
    output reg   [31:0]  csrData,
    output wire  [31:0]  nextPC
);


localparam  MSTATUS   = 12'h300,
            MISA      = 12'h301,
            MIE       = 12'h304,
            MTVEC     = 12'h305,
            MSCRATCH  = 12'h340,
            MEPC      = 12'h341,
            MCAUSE    = 12'h342,
            MTVAL     = 12'h343,
            MIP       = 12'h344,
            MVENDORID = 12'hF11,
            MARCHID   = 12'hF12,
            MIMPID    = 12'hF13,
            MHARTID   = 12'hF14;




localparam  mie_MSIE = 3,
            mie_MTIE = 7,
            mie_MEIE = 11;


localparam  mstatus_MIE = 3,
            mstatus_MPIE = 7;

localparam  RW = 2'b01,
            RS = 2'b10,
            RC = 2'b11;

reg     [31:0]  mstatus, mie, mtvec, mepc, mcause, mtval, mip, mscratch;
reg     [31:0]  mstatus_c, mie_c, mtvec_c, mepc_c, mcause_c, mtval_c, mip_c, mscratch_c;

wire    [31:0]  mvendorid, marchid, mimpid, mhartid;
wire    [31:0]  misa;

reg  NMI_reg, NMI_return;
reg interrupt;
reg  [4:0] currentInterrupt, currentInterrupt_reg;
integer i;

always @ (*) begin
    if (mstatus[mstatus_MIE]) begin
        if (|externalInterrupts & mie[mie_MEIE]) begin
            interrupt = 1;
            currentInterrupt = 31;
            for (i = 31; i >= 16; i = i - 1) begin
                if ((externalInterrupts[i-16] == 1'b1) && mie[i]) begin
                    currentInterrupt = i;
                end
            end
        end
        else if (mip[mie_MSIE] & mie[mie_MSIE]) begin
            interrupt = 1;
            currentInterrupt = 3;
        end
        else if (timerInterrupt & mie[mie_MTIE]) begin
            interrupt = 1;
            currentInterrupt = 7;
        end
        else begin
            interrupt = 0;
            currentInterrupt = 0;
        end
    end
    else begin
        interrupt = 0;
        currentInterrupt = 0;
    end 
end

always @ (posedge clk or negedge reset) begin
    if (!reset) begin
        interrupt_reg <= 0;
        currentInterrupt_reg <= 0;
        NMI_reg <= 0;
        NMI_return <= 1;
    end
    else begin
        interrupt_reg <= ((NMI & NMI_return) | interrupt);
        currentInterrupt_reg <= currentInterrupt;

        NMI_reg <= NMI & NMI_return;
        if (NMI)
            NMI_return <= 0;
        if (mret) 
            NMI_return <= 1;        
    end
end


always @ (*) begin

    mstatus_c = {19'b0, 2'b11, 3'b0, mstatus[mstatus_MPIE], 3'b0, mstatus[mstatus_MIE], 3'b0}; 

    mie_c = mie;
    mip_c = mip;    
    mscratch_c = mscratch;
    mtvec_c = mtvec;
    mtval_c = mtval;
    mcause_c = mcause;
    mepc_c = mepc;
    mtval_c = mtval;

    case (index)
        MSTATUS     :   begin
                            csrData = mstatus; 
                        end

        MISA        :   begin
                            csrData = misa;
                        end

        MIE         :   begin
                            csrData = {mie[31:16], 4'b0, mie[mie_MEIE], 3'b0, mie[mie_MTIE], 3'b0, mie[mie_MSIE], 3'b0};
                        end

        MTVEC       :   begin
                            csrData = mtvec; 
                        end

        MSCRATCH    :   begin
                            csrData = mscratch;
                        end

        MEPC        :   begin
                            csrData = mepc;  
                        end

        MCAUSE      :   begin
                            csrData = mcause;  
                        end

        MTVAL       :   begin
                            csrData = mtval;  
                        end

        MIP         :   begin
                            csrData = mip;  
                        end

        MVENDORID   :   begin
                            csrData = mvendorid;
                        end

        MARCHID     :   begin
                            csrData = marchid;  
                        end

        MIMPID      :   begin
                            csrData = mimpid;
                        end

        MHARTID     :   begin
                            csrData = mhartid;
                        end

        default     :   begin
                            csrData = 32'b0;
                        end
        endcase

    if (mret | NMI_reg | exception | interrupt_reg) begin
        if (mret) begin
            mstatus_c[mstatus_MIE]  = mstatus[mstatus_MPIE];
            mstatus_c[mstatus_MPIE] = 1'b1;

            mip_c = mip;
            if (NMI_reg)
                mip_c[0] = 0;
            else if (interrupt_reg) 
                mip_c[currentInterrupt_reg] = 0;
            else
                mip_c = mip;
        end
        else if (NMI_reg && ~stalled) begin
            if (~stalled) begin
                mepc_c = {exceptionPC[31:2], 2'b0};
                mtval_c = 32'b0;

                mstatus_c[mstatus_MPIE] = mstatus[mstatus_MIE];
                mstatus_c[mstatus_MIE] = 1'b0;

                mip_c[0] = 1;
            end
            else begin
                mepc_c = mepc;
                mtval_c = mtval;
                mstatus_c = mstatus;
                mip_c = mip;
            end
            mcause_c[31] = 1;
            mcause_c[30:0] = 0;
        end
        else if (interrupt_reg) begin
            if (~stalled) begin
                mepc_c = {exceptionPC[31:2], 2'b0};
                mtval_c = 32'b0;

                mstatus_c[mstatus_MPIE] = mstatus[mstatus_MIE];
                mstatus_c[mstatus_MIE] = 1'b0;

                mip_c[currentInterrupt_reg] = 1;
            end
            else begin
                mepc_c = mepc;
                mtval_c = mtval;
                mstatus_c = mstatus;
                mip_c = mip;
            end
            mcause_c[31] = 1;
            mcause_c[30:0] = currentInterrupt_reg;
        end
        else begin
            if (~stalled) begin
                mepc_c = {exceptionPC[31:2], 2'b0};
                mtval_c = 32'b0;
            end
            else begin
                mepc_c = mepc;
                mtval_c = mtval;
            end
            mcause_c[31] = 0;
            mcause_c[30:0] = exceptionType;
        end
    end


    else if (|opcode) begin
        case (index)
        MSTATUS     :   begin
                            csrData = mstatus;
                            case (opcode)
                                RW      : mstatus_c = data;
                                RS      : mstatus_c = mstatus_c | data;
                                RC      : mstatus_c = mstatus_c & ~data;
                                default : mstatus_c = mstatus;
                            endcase    
                        end

        MISA        :   begin
                            csrData = misa;
                        end

        MIE         :   begin
                            csrData = {mie[31:16], 4'b0, mie[mie_MEIE], 3'b0, mie[mie_MTIE], 3'b0, mie[mie_MSIE], 3'b0};
                            case (opcode)
                                RW      : mie_c = data;
                                RS      : mie_c = mie_c | data;
                                RC      : mie_c = mie_c & ~data;
                                default : mie_c = mie;
                            endcase    
                        end

        MTVEC       :   begin
                            csrData = mtvec;
                            case (opcode)
                                RW      : mtvec_c = data;
                                RS      : mtvec_c = mtvec_c | data;
                                RC      : mtvec_c = mtvec_c & ~data;
                                default : mtvec_c = mtvec;
                            endcase    
                        end

        MSCRATCH    :   begin
                            csrData = mscratch;
                            case (opcode)
                                RW      : mscratch_c = data;
                                RS      : mscratch_c = mscratch_c | data;
                                RC      : mscratch_c = mscratch_c & ~data;
                                default : mscratch_c = mscratch;
                            endcase    
                        end

        MEPC        :   begin
                            csrData = mepc;
                            case (opcode)
                                RW      : mepc_c[31:2] = data[31:2];
                                RS      : mepc_c[31:2] = mepc_c[31:2] | data[31:2];
                                RC      : mepc_c[31:2] = mepc_c[31:2] & ~data[31:2];
                                default : mepc_c[31:2] = mepc[31:2];
                            endcase    
                        end

        MCAUSE      :   begin
                            csrData = mcause;
                            case (opcode)
                                RW      : mcause_c = data;
                                RS      : mcause_c = mcause_c | data;
                                RC      : mcause_c = mcause_c & ~data;
                                default : mcause_c = mcause;
                            endcase    
                        end

        MTVAL       :   begin
                            csrData = mtval;
                            case (opcode)
                                RW      : mtval_c = data;
                                RS      : mtval_c = mtval_c | data;
                                RC      : mtval_c = mtval_c & ~data;
                                default : mtval_c = mtval;
                            endcase    
                        end

        MIP         :   begin
                            csrData = mip;
                            mip_c = mip;
                            case (opcode)
                                RW      : mip_c[mie_MSIE] = data[mie_MSIE];
                                RS      : mip_c[mie_MSIE] = mip_c[mie_MSIE] | data[mie_MSIE];
                                RC      : mip_c[mie_MSIE] = mip_c[mie_MSIE] & ~data[mie_MSIE];
                                default : mip_c = mip;
                            endcase    
                        end

        MVENDORID   :   begin
                            csrData = mvendorid;
                        end

        MARCHID     :   begin
                            csrData = marchid;  
                        end

        MIMPID      :   begin
                            csrData = mimpid;
                        end

        MHARTID     :   begin
                            csrData = mhartid;
                        end

        default     :   begin
                            csrData = 32'b0;
                        end
        endcase
    end

    else begin
        mstatus_c = {19'b0, 2'b11, 3'b0, mstatus[mstatus_MPIE], 3'b0, mstatus[mstatus_MIE], 3'b0};  

        mie_c = mie;
        mip_c = mip;    
        mscratch_c = mscratch;
        mtvec_c = mtvec;
        mtval_c = mtval;
        mcause_c = mcause;
        mepc_c = mepc;
        mtval_c = mtval;
        csrData = 0;
    end


end 

always @ (posedge clk or negedge reset) begin
    if (!reset) begin
        mstatus <= 0;
        mie <= 0;
        mtvec[31:2] <= 30'h3C00;
        mtvec[1:0] <= 2'b01;    
        mepc <= 0;
        mcause <= 0;
        mtval <= 0;
        mip <= 0;
        mscratch <= 0;
    end
    else begin
        mstatus <= mstatus_c;
        mie <= mie_c;
        mtvec <= mtvec_c;
        mepc <= mepc_c;
        mcause <= mcause_c;
        mtval <= mtval_c;
        mip <= mip_c;
        mscratch <= mscratch_c;
    end
end


assign nextPC = (mcause_c[31]) ? ({mtvec[31:2], 2'b0} + (mcause_c[4:0] << 2)) : {mtvec[31:2], 2'b0};


assign misa = 32'b0 | (1 << 30) | (1 << 8) | (1 << 12);
assign mvendorid = 32'b0;
assign marchid = 32'b0;
assign mhartid = 32'b0;
assign mimpid = {31'b0, 1'b1};


endmodule

`define MATHr 7'b0110011
`define MATHi 7'b0010011
`define MATHWi 7'b0011011
`define MATHWr 7'b0111011
`define JALr  7'b1100111
`define JAL   7'b1101111
`define BRANCH 7'b1100011
`define LUI   7'b0110111
`define AUIPC 7'b0010111
`define SW    7'b0100011
`define LW    7'b0000011
`define CSR   7'b1110011

`define ALU_ADD 4'b0000
`define ALU_SUB 4'b0001
`define ALU_AND 4'b0010
`define ALU_OR 4'b0011
`define ALU_XOR 4'b0100
`define ALU_SLT 4'b0101
`define ALU_SLTU 4'b0110
`define ALU_SLL 4'b0111
`define ALU_SRL 4'b1000
`define ALU_SRA 4'b1001
`define ALU_ADDW 4'b1010
`define ALU_SUBW 4'b1011
`define ALU_SLLW 4'b1100
`define ALU_SRLW 4'b1101
`define ALU_SRAW 4'b1110


module Inst_Controller (
    input [31:0] inst,
    output [21:0] decode,
    output reg csr_write,
    output reg [1:0] trap,
    output reg wb_src
);

    reg we_reg, npl_sel, we_mem;
    reg [1:0] alu_asel, alu_bsel, wb_sel;
    reg [3:0] alu_op;
    reg [2:0] immgen_op, bralu_op, memdata_width;

    wire [6:0] opcode = inst[6:0];
    wire [2:0] funct3 = inst[14:12];
    wire funct7_5 = inst[30];
    wire [4:0] rs1 = inst[19:15];
    initial begin
        we_mem = 0;
        we_reg = 0;
        npl_sel = 0;
        alu_asel = 0;
        alu_bsel = 0;
        wb_sel = 0;
        alu_op = 0;
        immgen_op = 0;
        bralu_op = 0;
        memdata_width = 0;
        csr_write = 0;
        trap = 0;
        wb_src = 0;
    end
    always @(*) begin
        case (opcode) 
            `MATHr: begin
                we_reg = 1;
                npl_sel = 0;
                we_mem = 0;
                immgen_op = 0;
                case (funct3)
                    3'b000: alu_op = funct7_5 == 0 ? `ALU_ADD : `ALU_SUB;
                    3'b001: alu_op = `ALU_SLL;
                    3'b010: alu_op = `ALU_SLT;
                    3'b011: alu_op = `ALU_SLTU;
                    3'b100: alu_op = `ALU_XOR;
                    3'b101: alu_op = funct7_5 == 0 ? `ALU_SRL : `ALU_SRA;
                    3'b110: alu_op = `ALU_OR;
                    3'b111: alu_op = `ALU_AND;
                    default: alu_op = 4'bx;
                endcase
                bralu_op = 0;
                alu_asel = 2'b01;
                alu_bsel = 2'b01;
                wb_sel = 2'b01;
                memdata_width = 3'b0;
            end
            `MATHi: begin
                we_reg = 1;
                npl_sel = 0;
                we_mem = 0;
                immgen_op = 3'b001;
                case (funct3)
                    3'b000: alu_op = `ALU_ADD;
                    3'b001: alu_op = `ALU_SLL;
                    3'b010: alu_op = `ALU_SLT;
                    3'b011: alu_op = `ALU_SLTU;
                    3'b100: alu_op = `ALU_XOR;
                    3'b101: alu_op = funct7_5 == 0 ? `ALU_SRL : `ALU_SRA;
                    3'b110: alu_op = `ALU_OR;
                    3'b111: alu_op = `ALU_AND;
                    default: alu_op = 4'bx;
                endcase
                bralu_op = 0;
                alu_asel = 2'b01;
                alu_bsel = 2'b10;
                wb_sel = 2'b01;
                memdata_width = 0;
            end
            `MATHWr: begin
                we_reg = 1;
                npl_sel = 0;
                we_mem = 0;
                immgen_op = 3'b000;
                case (funct3)
                    3'b000: alu_op = funct7_5 == 0 ? `ALU_ADDW : `ALU_SUBW;
                    3'b001: alu_op = `ALU_SLLW;
                    3'b101: alu_op = funct7_5 == 0 ? `ALU_SRLW : `ALU_SRAW;
                    default: alu_op = 4'bx;
                endcase
                bralu_op = 0;
                alu_asel = 2'b01;
                alu_bsel = 2'b01;
                wb_sel = 2'b01;
                memdata_width = 0;
            end
            `MATHWi: begin
                we_reg = 1;
                npl_sel = 0;
                we_mem = 0;
                immgen_op = 3'b001;
                case (funct3)
                    3'b000: alu_op = `ALU_ADDW;
                    3'b001: alu_op = `ALU_SLLW;
                    3'b101: alu_op = funct7_5 == 0 ? `ALU_SRLW : `ALU_SRAW;
                    default: alu_op = 4'bx;
                endcase
                bralu_op = 0;
                alu_asel = 2'b01;
                alu_bsel = 2'b10;
                wb_sel = 2'b01;
                memdata_width = 0;
            end
            `JALr: begin
                we_reg = 1;
                npl_sel = 1;
                we_mem = 0;
                immgen_op = 3'b001;
                alu_op = `ALU_ADD;
                bralu_op = 0;
                alu_asel = 2'b01;
                alu_bsel = 2'b10;
                wb_sel = 2'b11;
                memdata_width = 0;
            end
            `JAL: begin
                we_reg = 1;
                npl_sel = 1;
                we_mem = 0;
                immgen_op = 3'b101;
                alu_op = `ALU_ADD;
                bralu_op = 0;
                alu_asel = 2'b10;
                alu_bsel = 2'b10;
                wb_sel = 2'b11;
                memdata_width = 0;
            end
            `BRANCH: begin
                we_reg = 0;
                npl_sel = 1;
                we_mem = 0;
                immgen_op = 3'b011;
                alu_op = `ALU_ADD;
                case (funct3)
                    3'b000: bralu_op = 3'b001;
                    3'b001: bralu_op = 3'b010;
                    3'b100: bralu_op = 3'b011;
                    3'b101: bralu_op = 3'b100;
                    3'b110: bralu_op = 3'b101;
                    3'b111: bralu_op = 3'b110;
                    default: bralu_op = 3'bx;
                endcase
                alu_asel = 2'b10;
                alu_bsel = 2'b10;
                wb_sel = 2'b01;
                memdata_width = 0;
            end
            `LUI: begin
                we_reg = 1;
                npl_sel = 0;
                we_mem = 0;
                immgen_op = 3'b100;
                alu_op = `ALU_ADD;
                bralu_op = 0;
                alu_asel = 2'b00;
                alu_bsel = 2'b10;
                wb_sel = 2'b01;
                memdata_width = 0;
            end
            `AUIPC: begin
                we_reg = 1;
                npl_sel = 0;
                we_mem = 0;
                immgen_op = 3'b100;
                alu_op = `ALU_ADD;
                bralu_op = 0;
                alu_asel = 2'b10;
                alu_bsel = 2'b10;
                wb_sel = 2'b01;
                memdata_width = 0;
            end
            `SW: begin
                we_reg = 0;
                npl_sel = 0;
                we_mem = 1;
                immgen_op = 3'b010;
                alu_op = `ALU_ADD;
                bralu_op = 0;
                alu_asel = 2'b01;
                alu_bsel = 2'b10;
                wb_sel = 2'b00;
                memdata_width = funct3 == 3'b011 ? 3'b001 :
                                funct3 == 3'b010 ? 3'b010 :
                                funct3 == 3'b001 ? 3'b011 :
                                funct3 == 3'b000 ? 3'b100 :
                                3'bx;
            end
            `LW: begin
                we_reg = 1;
                npl_sel = 0;
                we_mem = 0;
                immgen_op = 3'b001;
                alu_op = `ALU_ADD;
                bralu_op = 0;
                alu_asel = 2'b01;
                alu_bsel = 2'b10;
                wb_sel = 2'b10;
                memdata_width = funct3 == 3'b000 ? 3'b100 :
                                funct3 == 3'b001 ? 3'b011 :
                                funct3 == 3'b010 ? 3'b010 :
                                funct3 == 3'b011 ? 3'b001 :
                                funct3 == 3'b100 ? 3'b111 :
                                funct3 == 3'b101 ? 3'b110 :
                                funct3 == 3'b110 ? 3'b101 :
                                3'bx;
            end
            `CSR: begin
                we_reg = 1;
                npl_sel = 0;
                we_mem = 0;
                immgen_op = 3'b110;
                case(funct3) 
                    3'b001: begin
                        alu_op = `ALU_ADD;
                        alu_asel = 2'b01;
                        alu_bsel = 2'b0;
                        wb_src = 1;
                        csr_write = rs1 == 5'b0 ? 0 : 1;
                    end
                    3'b010: begin
                        alu_op = `ALU_OR;
                        alu_asel = 2'b01;
                        alu_bsel = 2'b11;
                        wb_src = 1;
                        csr_write = rs1 == 5'b0 ? 0 : 1;
                    end
                    3'b011: begin
                        alu_op = `ALU_XOR;
                        alu_asel = 2'b01;
                        alu_bsel = 2'b11;
                        wb_src = 1;
                        csr_write = rs1 == 5'b0 ? 0 : 1;
                    end
                    3'b101: begin
                        alu_op = `ALU_ADD;
                        alu_asel = 2'b11;
                        wb_src = 1;
                        alu_bsel = 2'b0;
                        csr_write = rs1 == 5'b0 ? 0 : 1;
                    end
                    3'b110: begin
                        alu_op = `ALU_OR;
                        alu_asel = 2'b11;
                        wb_src = 1;
                        alu_bsel = 2'b11;
                        csr_write = rs1 == 5'b0 ? 0 : 1;
                    end
                    3'b111: begin
                        alu_op = `ALU_XOR;
                        alu_asel = 2'b11;
                        wb_src = 1;
                        alu_bsel = 2'b11;
                        csr_write = rs1 == 5'b0 ? 0 : 1;
                    end
                    3'b000: begin
                        case (inst[31:20]) 
                            12'b000000000000: begin
                                trap = 2'b11; 

                                csr_write = 1;
                            end
                            12'b001100000010: begin
                                trap = 2'b10;

                                csr_write = 1;
                            end
                            12'b000100000010: begin
                                trap = 2'b01;
                                csr_write = 1;

                            end
                            default: begin
                                trap = 2'b00;

                            end
                        endcase
                    end
                    default: begin

                    end
                endcase
                bralu_op = 0;
                wb_sel = 2'b10;
                memdata_width = 3'b001;
            end
            default: begin
                we_mem = 0;
                we_reg = 0;
                npl_sel = 0;
                alu_asel = 0;
                alu_bsel = 0;
                wb_sel = 0;
                alu_op = 0;
                immgen_op = 0;
                bralu_op = 0;
                memdata_width = 0;
                csr_write = 0;
                trap = 0;
                wb_src = 0;
            end
        endcase
    end
    assign decode = { we_reg, we_mem, npl_sel, immgen_op, alu_op, bralu_op, alu_asel, alu_bsel, wb_sel, memdata_width };
endmodule

module FFTTheta_R2 #(
	parameter bw_fftp = 4,
	parameter bw_stage	= 2 		
)
(
	input Clock,Reset,Start,
	output reg[bw_fftp-2:0] Theta,
	output [bw_stage-1:0] Stage,
	output reg Busy,End
);

	localparam bw_stagep1 = bw_stage+1;	
	localparam bw_theta	= bw_fftp-1; 
	localparam bw_count = bw_theta+bw_stagep1;



	reg [bw_count-1:0] Count,DCount,Mask;
	reg [bw_theta-1:0] GenThetaCount;
	reg rCSens,rDummy,rEnd,rGenThetaCountReset;


	wire [bw_theta-1:0] PreTheta;
	wire [bw_stagep1-1:0] wStage 	= Count[bw_count-1:bw_theta];
	assign Stage					= wStage[bw_stage-1:0];
	wire [bw_stagep1-1:0] wDStage	= DCount[bw_count-1:bw_theta];
	wire CSens						= |({1'b0,DCount}&Mask);

	wire wGenThetaCountReset		= wDStage != wStage;
	wire wGenThetaCountUp			= rCSens != CSens;
	wire wEnd						= (wStage == bw_fftp);

	generate
		genvar i;
		for(i=0;i<bw_theta;i=i+1) begin :br
			assign PreTheta[i] = GenThetaCount[bw_theta-1-i];
		end
	endgenerate	

	always@(posedge Clock or posedge Reset) begin
		if(Reset)begin
			{
				Theta,Count,rCSens,DCount,
				GenThetaCount,rGenThetaCountReset,
				rDummy ,Busy,End,rEnd
			}			<=	1'b0;
			Mask		<=	1<<(bw_theta);
		end else begin
			if(Start)
				Busy	<= 1'b1;
			else if (rEnd)
				Busy	<= 1'b0;

			if(End) begin
				Count	<= 1'b0;
				rDummy	<= 1'b0;
			end else if(Busy)
				{Count,rDummy}	<= {Count,rDummy} + 1'b1;	

			if(Start)
				rEnd	<= 1'b0;
			else
				rEnd <= wEnd;

			if(rEnd && !Busy)
				End <= 1'b0;
			else if(rEnd)
				End <= 1'b1;

			Theta		<= PreTheta;

			rGenThetaCountReset	<= wGenThetaCountReset;

			if(End)
				DCount	<= 1'b0;
			else
				DCount	<= Count;	

			rCSens	<= CSens;

			if(rGenThetaCountReset)
				GenThetaCount	<= 1'b0;
			else if(wGenThetaCountUp)
				GenThetaCount	<= GenThetaCount+1;					

			if(Start)
				Mask	<= 1<<(bw_theta);
			else if(Count[bw_theta] != DCount[bw_theta])
				Mask	<= Mask>>1;
		end
	end
endmodule

