module muxer(
    input clock,
    input reset,
    input [3:0] fourth,
    input [3:0] third,
    input [3:0] second,
    input [3:0] first,
    output a_m,
    output b_m,
    output c_m,
    output d_m,
    output e_m,
    output f_m,
    output g_m,
    output dp_m,
    output [3:0] an_m
    );



localparam N = 18;

reg [N-1:0]count; 

always @ (posedge clock or posedge reset)
 begin
  if (reset)
   count <= 0;
  else
   count <= count + 1;
 end

reg [3:0]sseg; 
reg [3:0]an_temp; 
reg reg_dp;
always @ (*)
 begin
  case(count[N-1:N-2]) 

   2'b00 :
    begin
     sseg = first;
     an_temp = 4'b1110;
     reg_dp = 1'b1;
    end

   2'b01:
    begin
     sseg = second;
     an_temp = 4'b1101;
     reg_dp = 1'b1;
    end

   2'b10:
    begin
     sseg = third;
     an_temp = 4'b1011;
     reg_dp = 1'b1;
    end

   2'b11:
    begin
     sseg = fourth;
     an_temp = 4'b0111;
     reg_dp = 1'b0;
    end
  endcase
 end
assign an_m = an_temp;

reg [6:0] sseg_temp;
always @ (*)
 begin
  case(sseg)
   4'd0 : sseg_temp = 7'b1000000; 
   4'd1 : sseg_temp = 7'b1111001; 
   4'd2 : sseg_temp = 7'b0100100; 
   4'd3 : sseg_temp = 7'b0110000; 
   4'd4 : sseg_temp = 7'b0011001; 
   4'd5 : sseg_temp = 7'b0010010; 
   4'd6 : sseg_temp = 7'b0000010; 
   4'd7 : sseg_temp = 7'b1111000; 
   4'd8 : sseg_temp = 7'b0000000; 
   4'd9 : sseg_temp = 7'b0010000; 
   4'd10 : sseg_temp = 7'b0111111; 
   4'd11 : sseg_temp = 7'b0111111; 
   default : sseg_temp = 7'b0111111; 
  endcase
 end
assign {g_m, f_m, e_m, d_m, c_m, b_m, a_m} = sseg_temp;
assign dp_m = reg_dp;

endmodule

module    UART_REG_IF(
    clk,
    rst_,

    paddr_i,
    pwdata_i,
    psel_i,
    penable_i,
    pwrite_i,

    st_error,
    p_error,
    rx_fifo_rempty,
    rx_fifo_cnt,
    rx_data,

    tx_fifo_wfull,
    tx_fifo_cnt,

    uart_int_o,

    prdata_o,

    st_check,
    p_error_ack,
    st_error_ack,
    rxrst,

    stop_bit,
    two_tx_delay,
    tx_data,
    txrst,

    check,
    parity,
    rx_fifo_rinc,
    tx_fifo_winc,
    baud_div
);
input           clk;                
input           rst_;               
input  [31:0]   paddr_i;            
input  [31:0]   pwdata_i;           
input           psel_i;             
input           penable_i;          
input           pwrite_i;           
input           st_error;       
input           p_error;        
input           rx_fifo_rempty;     
input  [4:0]    rx_fifo_cnt;        
input  [7:0]    rx_data;            
input           tx_fifo_wfull;      
input  [4:0]    tx_fifo_cnt;        

output          uart_int_o;          
output [31:0]   prdata_o;            
output          st_check;            
output          p_error_ack;         
output          st_error_ack;        
output          rxrst;               
output          stop_bit;            
output [3:0]    two_tx_delay;        
output [7:0]    tx_data;             
output          txrst;               
output          check;               
output          parity;              
output          rx_fifo_rinc;        
output          tx_fifo_winc;        
output [9:0]    baud_div;            


reg             uart_int_o;
reg  [31:0]     prdata_o;
reg             st_check;
reg             p_error_ack;
reg             st_error_ack;
reg             rxrst;
reg             stop_bit;
reg  [3:0]      two_tx_delay;
reg  [7:0]      tx_data;
reg             txrst;
reg             check;
reg             parity;
reg  [9:0]      baud_div;
reg             rx_fifo_rinc;        
reg             tx_fifo_winc;        
reg  [31:0]     uart_tx;             
reg  [31:0]     uart_rx;             
reg  [31:0]     uart_baud;           
reg  [31:0]     uart_conf;           
reg  [31:0]     uart_rxtrig;         
reg  [31:0]     uart_txtrig;         
reg  [31:0]     uart_delay;          
reg  [31:0]     uart_status;         
reg  [31:0]     uart_rxfifo_stat;    
reg  [31:0]     uart_txfifo_stat;    
reg             state;               
reg  [1:0]      state_en;            
reg             rx_state;            
reg             tx_state;            

reg             uart_status3_delay1;
reg             uart_status3_delay2;
wire             neg_uart_status3;

reg             uart_status2_delay1;
reg             uart_status2_delay2;
wire             neg_uart_status2;

reg             st_error_syn1;
reg             st_error_syn2;
reg             st_error_syn3;
wire            st_error_syn;

reg             p_error_syn1;
reg             p_error_syn2;
reg             p_error_syn3;
wire            p_error_syn;

wire [3:0] paddr ;

assign paddr = paddr_i[5:2] ;


always@(posedge clk or negedge rst_) begin
    if(!rst_) begin
        uart_status3_delay1 <= 1'b0;
        uart_status3_delay2 <= 1'b0;
    end
    else begin
        uart_status3_delay1 <= uart_status[3];
        uart_status3_delay2 <= uart_status3_delay1;
    end
end
assign  neg_uart_status3 = (!uart_status3_delay1) && uart_status3_delay2;


always@(posedge clk or negedge rst_) begin
    if(!rst_) begin
        uart_status2_delay1 <= 1'b0;
        uart_status2_delay2 <= 1'b0;
    end
    else begin
        uart_status2_delay1 <= uart_status[2];
        uart_status2_delay2 <= uart_status2_delay1;
    end
end
assign  neg_uart_status2 = (!uart_status2_delay1) && uart_status2_delay2;


always@(posedge clk or negedge rst_) begin
    if(!rst_) begin
        p_error_syn1 <= 1'b0;
        p_error_syn2 <= 1'b0;
        p_error_syn3 <= 1'b0;
    end
    else begin
        p_error_syn1 <= p_error;
        p_error_syn2 <= p_error_syn1;
        p_error_syn3 <= p_error_syn2;
    end
end
assign  p_error_syn = p_error_syn2 && (!p_error_syn3);


always@(posedge clk or negedge rst_) begin
    if(!rst_) begin
        st_error_syn1 <= 1'b0;
        st_error_syn2 <= 1'b0;
        st_error_syn3 <= 1'b0;
    end
    else begin
        st_error_syn1 <= st_error;
        st_error_syn2 <= st_error_syn1;
        st_error_syn3 <= st_error_syn2;
    end
end
assign  st_error_syn = st_error_syn2 && (!st_error_syn3);


always@(posedge clk or negedge rst_) begin
    if(!rst_) begin
        uart_tx     <= 32'h0;
        uart_baud   <= 32'hf152;
        uart_conf   <= 32'h34;
        uart_rxtrig <= 32'h1;
        uart_txtrig <= 32'h0;
        uart_delay  <= 32'h2;
    end
    else begin

        if(psel_i && penable_i && pwrite_i) begin
            case(paddr)
            4'h0:
                uart_tx     <= pwdata_i;
            4'h2:
                uart_baud   <= pwdata_i;
            4'h3:
                uart_conf   <= pwdata_i;
            4'h4:
                uart_rxtrig <= pwdata_i;
            4'h5:
                uart_txtrig <= pwdata_i;
            4'h6:
                uart_delay  <= pwdata_i;
            endcase
        end
    end
end


always@(posedge clk or negedge rst_) begin
    if(!rst_) begin
        prdata_o <= 32'h0;
    end
    else begin

        if(psel_i && (!penable_i) && (!pwrite_i)) begin
            case(paddr)
            4'h0:
                prdata_o <= uart_tx;
            4'h1:
                prdata_o <= uart_rx;
            4'h2:
                prdata_o <= uart_baud;
            4'h3:
                prdata_o <= uart_conf;
            4'h4:
                prdata_o <= uart_rxtrig;
            4'h5:
                prdata_o <= uart_txtrig;
            4'h6:
                prdata_o <= uart_delay;
            4'h7:
                prdata_o <= uart_status;
            4'h8:
                prdata_o <= uart_rxfifo_stat;
            4'h9:
                prdata_o <= uart_txfifo_stat;
            endcase
        end
    end
end



always@(posedge clk or negedge rst_) begin
    if(!rst_) begin
        uart_rxfifo_stat <= 32'h0;
        uart_txfifo_stat <= 32'h0;
    end
    else begin
        uart_rxfifo_stat <= {27'b0,rx_fifo_cnt};
        uart_txfifo_stat <= {27'b0,tx_fifo_cnt};
    end
end


always@(posedge clk or negedge rst_) begin
    if(!rst_) begin
        rx_fifo_rinc <= 1'b0;
        state        <= 1'b0;
    end
    else begin
        case(state)
        1'b0: begin


            if(psel_i && (!penable_i)&&(!pwrite_i)&&(paddr==4'h7)) begin
                if(uart_status[1] && !rx_fifo_rempty) begin
                    rx_fifo_rinc <= 1'b1;
                    state        <= 1'b1;
                end
            end
            if(psel_i &&(!penable_i)&&(!pwrite_i)&&(paddr==4'h1)) begin
                rx_fifo_rinc <= 1'b1;
                state        <= 1'b1;
            end
        end
        1'b1: begin
            rx_fifo_rinc <= 1'b0;
            state        <= 1'b0;
        end
        endcase
    end
end

always@(posedge clk or negedge rst_) begin
    if(!rst_) begin
        tx_fifo_winc <= 1'b0;
        state_en     <= 2'b0;
    end
    else begin
        case(state_en)
        2'b0: begin

            if(psel_i && penable_i && pwrite_i && (paddr==4'h0)) begin
                state_en <= 2'b01;
            end
        end
        2'b01: begin
            state_en     <= 2'b10;
            tx_fifo_winc <= 1'b1;
        end
        2'b10: begin
            tx_fifo_winc <= 1'b0;
            state_en     <= 2'b0;
        end
        endcase
    end
end


always@(posedge clk or negedge rst_) begin
    if(!rst_) begin
        p_error_ack  <= 1'b0;
        st_error_ack <= 1'b0;
        uart_status  <= 32'h0;
        rx_state     <= 1'b0;
        tx_state     <= 1'b0;
    end
    else begin
        if(st_error_syn) begin
            uart_status[3]   <= 1'b1;
        end
        else begin
            if(neg_uart_status3) begin
                st_error_ack <= 1'b1;
            end
            else begin
                if(!st_error_syn2) begin
                    st_error_ack <= 1'b0;
                end
            end
        end
        if(p_error_syn) begin
            uart_status[2]   <= 1'b1;
        end
        else begin
            if(neg_uart_status2) begin
                p_error_ack  <= 1'b1;
            end
            else begin
                if(!p_error_syn2) begin
                    p_error_ack  <= 1'b0;
                end
            end
        end


        case(rx_state)
        1'b0: begin
            if(rx_fifo_cnt == (uart_rxtrig[3:0] - 1'b1)) begin
                rx_state      <= 1'b1;
            end
            else begin
                rx_state      <= 1'b0;
            end
        end
        1'b1: begin
            if(rx_fifo_cnt == uart_rxtrig[3:0]) begin
                uart_status[1] <= 1'b1;
                rx_state       <= 1'b0;
            end
            else begin
                rx_state       <= 1'b1;
            end
        end
        endcase


        case(tx_state)
        1'b0: begin
            if(tx_fifo_cnt == (uart_txtrig[3:0] + 1'b1)) begin
                tx_state       <= 1'b1;
            end
            else begin
                tx_state       <= 1'b0;
            end
        end
        1'b1: begin
            if(tx_fifo_cnt == uart_txtrig[3:0]) begin
                uart_status[0] <= 1'b1;
                tx_state       <= 1'b0;
            end
            else begin
                tx_state       <= 1'b1;
            end
        end
        endcase

        if(psel_i && penable_i && pwrite_i && (paddr==4'h7)) begin
            uart_status <= uart_status & (~pwdata_i);
        end
    end
end


always @(posedge clk or negedge rst_) begin
    if(!rst_) begin
	      uart_int_o <= 1'b0;
		end
	  else begin
	      if(|uart_status[3:0]) begin
            uart_int_o <= 1'b1;
        end
		    else begin
            uart_int_o <= 1'b0;
        end
		end
end


always@(posedge clk or negedge rst_) begin
    if(!rst_) begin
        uart_rx <= 8'h0;
    end
    else begin
        uart_rx <= {24'b0,rx_data};
    end
end



always@(posedge clk or negedge rst_) begin
    if(!rst_) begin
        tx_data   <= 8'h0;
        baud_div  <= 10'h152;
        rxrst     <= 1'b0;
        txrst     <= 1'b0;
        st_check  <= 1'b0;
        stop_bit  <= 1'b0;
        parity    <= 1'b0;
        check     <= 1'b0;
        two_tx_delay <= 4'h2;
    end
    else begin
        tx_data   <= uart_tx[7:0];
        baud_div  <= uart_baud[9:0];
        rxrst     <= uart_conf[15];
        txrst     <= uart_conf[14];
        st_check  <= uart_conf[3];
        stop_bit  <= uart_conf[2];
        parity    <= uart_conf[1];
        check     <= uart_conf[0];
        two_tx_delay <= uart_delay[3:0];
    end
end

endmodule

