parameter zero = 0;
parameter one = 1;
parameter two = 2;
parameter three = 3;
always @(posedge clock, posedge reset) begin 


    if((reset == 1'b1)) begin
      s = 1'b0;
      speaker <= 1'b0;
      counterP4 <= 0;
      end else begin
      if(play == 1'b1) begin
         case(sound)
            zero : begin
               if(counterP4 > RED_TONE) begin
                  s =  ~s;
                  speaker <= s;
                  counterP4 <= 0;
               end
               else begin
                  counterP4 <= counterP4 + 1;
               end
            end
            one : begin
               if(counterP4 > GREEN_TONE) begin
                  s =  ~s;
                  speaker <= s;
                  counterP4 <= 0;
               end
               else begin
                  counterP4 <= counterP4 + 1;
               end
            end
            two : begin
               if(counterP4 > YELLOW_TONE) begin
                  s =  ~s;
                  speaker <= s;
                  counterP4 <= 0;
               end
               else begin
                  counterP4 <= counterP4 + 1;
               end
            end
            three : begin
               if(counterP4 > BLUE_TONE) begin
                  s =  ~s;
                  speaker <= s;
                  counterP4 <= 0;
               end
               else begin
                  counterP4 <= counterP4 + 1;
               end
            end
            S_WIN : begin
               if(counterP4 > WIN_TONE) begin
                  s =  ~s;
                  speaker <= s;
                  counterP4 <= 0;
               end
               else begin
                  counterP4 <= counterP4 + 1;
               end
            end
            S_LOSS : begin
               if(counterP4 > ERROR_TONE) begin
                  s =  ~s;
                  speaker <= s;
                  counterP4 <= 0;
               end
               else begin
                  counterP4 <= counterP4 + 1;
               end
            end
            default : begin
               counterP4 <= 0;
            end
         endcase
      end
      else begin
         counterP4 <= 0;
         speaker <= 1'b0;
      end
   end
end

always @(posedge clock, posedge reset) begin


    if((reset == 1'b1)) begin
      count_P3 <= 0;
      num <= 0;
      end else begin
      count_P3 = (count_P3 + 1) % (2 ** COD_COLOR);


      num <= count_P3;
   end
end


always @(posedge clock, posedge reset) begin 


    if(reset == 1'b1) begin
      data_out <= 0;
      for (mar=0; mar <= SIZE_MEM - 1; mar = mar + 1) begin
         memory[mar] <= 0;
      end
      end else begin
      data_out <= memory[address];
      if(wr == 1'b1) begin
         memory[address] <= data_in;
      end
   end
end

always @(posedge clock, posedge reset) begin


    if((reset == 1'b1)) begin
      nloss <= LED_OFF;
      nl <= {4{LED_OFF}};
      play <= PLAY_OFF;
      wr <= 1'b0;
      scan <= 0;
      max <= 0;
      ind <= 0;
      timebase <= 0;
      countP1 <= 0;
      sound <= 0;
      address <= 0;
      data_in <= 0;
      gamma <= G0;
      end 

      else begin
	if(start == 1'b1) begin 

		   nloss <= LED_OFF;
            nl <= {4{LED_OFF}};
            play <= PLAY_OFF;
            wr <= 1'b0;
            max <= 0;
            timebase <= COUNT_SEQ;
            gamma <= G2;
	end else


      case(gamma)
         G0 : begin
            gamma <= G0;
         end
		 G1 : begin 
            nloss <= LED_OFF;
            nl <= {4{LED_OFF}};
            play <= PLAY_OFF;
            wr <= 1'b0;
            max <= 0;
            timebase <= COUNT_SEQ;
            gamma <= G2;
         end
         G2 : begin
            scan <= 0;
            wr <= 1'b1;
            address <= max;
            data_in <= num;
            gamma <= G3;
         end
         G3 : begin
            wr <= 1'b0;
            address <= scan;
            gamma <= G4;
         end
         G4 : begin
            gamma <= G5;
         end
         G5 : begin
            nl[data_out] <= LED_ON;
            countP1 <= timebase;
            play <= PLAY_ON;
            sound <= data_out;
            gamma <= G6;
         end
         G6 : begin
            if(countP1 == 0) begin
               nl <= {4{LED_OFF}};
               play <= PLAY_OFF;
               countP1 <= timebase;
               gamma <= G7;
            end
            else begin
               countP1 <= countP1 - 1;
               gamma <= G6;
            end
         end
         G7 : begin
            if(countP1 == 0) begin
               if(scan != max) begin
                  scan <= scan + 1;
                  gamma <= G3;
               end
               else begin
                  scan <= 0;
                  gamma <= G8;
               end
            end
            else begin
               countP1 <= countP1 - 1;
               gamma <= G7;
            end
         end
         G8 : begin
            countP1 <= COUNT_KEY;
            address <= scan;
            gamma <= G9;
         end
         G9 : begin
            gamma <= G10;
         end
         G10 : begin
            if(countP1 == 0) begin
               nloss <= LED_ON;
               max <= 0;
               gamma <= K0;
            end
            else begin
               countP1 <= countP1 - 1;
               if(k[0] == KEY_ON) begin
                  ind <= 0;
                  sound <= 0;
                  play <= PLAY_ON;
                  countP1 <= timebase;
                  if((data_out == 0)) begin
                     gamma <= G10a;
                  end
                  else begin
                     nloss <= LED_ON;
                     gamma <= Ea;
                  end
               end
               else if(k[1] == KEY_ON) begin
                  ind <= 1;
                  sound <= 1;
                  play <= PLAY_ON;
                  countP1 <= timebase;
                  if((data_out == 1)) begin
                     gamma <= G10a;
                  end
                  else begin
                     nloss <= LED_ON;
                     gamma <= Ea;
                  end
               end
               else if(k[2] == KEY_ON) begin
                  ind <= 2;
                  sound <= 2;
                  play <= PLAY_ON;
                  countP1 <= timebase;
                  if((data_out == 2)) begin
                     gamma <= G10a;
                  end
                  else begin
                     nloss <= LED_ON;
                     gamma <= Ea;
                  end
               end
               else if(k[3] == KEY_ON) begin
                  ind <= 3;
                  sound <= 3;
                  play <= PLAY_ON;
                  countP1 <= timebase;
                  if((data_out == 3)) begin
                     gamma <= G10a;
                  end
                  else begin
                     nloss <= LED_ON;
                     gamma <= Ea;
                  end
               end
               else begin
                  gamma <= G10;
               end
            end
         end
         G10a : begin
            nl[ind] <= LED_ON;
            gamma <= G11;
         end
         G11 : begin
            if(countP1 == 0) begin
               nl <= {4{LED_OFF}};
               play <= PLAY_OFF;
               countP1 <= timebase;

               gamma <= G12;

            end
            else begin
               countP1 <= countP1 - 1;

               gamma <= G11;

            end
         end
         G12 : begin
            if(countP1 == 0) begin

               if(scan != max) begin

                  scan <= scan + 1;

                  gamma <= G8;

               end
               else if(max != (SIZE_MEM - 1)) begin

                  max <= max + 1;

                  timebase <= timebase - DEC_SEQ;

                  gamma <= G2;

               end
               else begin
                  play <= PLAY_ON;

                  sound <= S_WIN;

                  countP1 <= COUNT_FIN;

                  gamma <= W0;

               end
            end
            else begin
               countP1 <= countP1 - 1;

               gamma <= G12;

            end
         end
         Ea : begin
            nl[ind] <= LED_ON;

            gamma <= E0;

         end
         E0 : begin
            if(countP1 == 0) begin

               nl <= {4{LED_OFF}};

               play <= PLAY_OFF;

               countP1 <= timebase;

               gamma <= E1;

            end
            else begin
               countP1 <= countP1 - 1;

               gamma <= E0;

            end
         end
         E1 : begin
            if(countP1 == 0) begin

               max <= 0;

               gamma <= K0;

            end
            else begin
               countP1 <= countP1 - 1;

               gamma <= E1;

            end
         end
         K0 : begin
            address <= max;

            gamma <= K1;

         end
         K1 : begin

            gamma <= K2;

         end
         K2 : begin
            nl[data_out] <= LED_ON;

            play <= PLAY_ON;

            sound <= data_out;

            countP1 <= timebase;

            gamma <= K3;

         end
         K3 : begin
            if(countP1 == 0) begin

               nl <= {4{LED_OFF}};

               play <= PLAY_OFF;

               countP1 <= timebase;

               gamma <= K4;

            end
            else begin
               countP1 <= countP1 - 1;

               gamma <= K3;

            end
         end
         K4 : begin
            if(countP1 == 0) begin

               if(max != scan) begin

                  max <= max + 1;

                  gamma <= K0;

               end
               else begin
                  nl[data_out] <= LED_ON;

                  play <= PLAY_ON;

                  sound <= S_LOSS;

                  countP1 <= COUNT_FIN;

                  gamma <= K5;

               end
            end
            else begin
               countP1 <= countP1 - 1;

               gamma <= K4;

            end
         end
         K5 : begin
            if(countP1 == 0) begin

               nl <= {4{LED_OFF}};

               play <= PLAY_OFF;

               countP1 <= COUNT_FIN;

               gamma <= K6;

            end
            else begin
               countP1 <= countP1 - 1;

               gamma <= K5;

            end
         end
         K6 : begin
            if(countP1 == 0) begin

               nl[data_out] <= LED_ON;

               play <= PLAY_ON;

               sound <= S_LOSS;

               countP1 <= COUNT_FIN;

               gamma <= K5;

            end
            else begin
               countP1 <= countP1 - 1;

               gamma <= K6;

            end
         end
         W0 : begin
            if(countP1 == 0) begin

               nl <= {4{LED_ON}};

               play <= PLAY_OFF;

               countP1 <= COUNT_FIN;

               gamma <= W1;

            end
            else begin
               countP1 <= countP1 - 1;

               gamma <= W0;

            end
         end
         W1 : begin
            if(countP1 == 0) begin

               nl <= {4{LED_OFF}};

               play <= PLAY_ON;

               sound <= S_WIN;

               countP1 <= COUNT_FIN;

               gamma <= W0;

            end
            else begin
               countP1 <= countP1 - 1;

               gamma <= W1;

            end
         end
      endcase
   end
end


